import { createCanvas } from "./CanvasUtils";

const TEXTURE_SIZE = 64; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Get visual texture. 
     */
    public getTexture(type: 'SHARD' | 'RUBBLE' | 'SPIKE' | 'SPARK' | 'SLASH' | 'CRACKS' | 'RING' | 'GLOW' | 'MAGIC_CIRCLE' | 'DUST' | 'PEBBLE' | 'ATMOSPHERE' | 'GENERIC_DEBUG' | 'SMOKE_PUFF', color: string): HTMLCanvasElement {
        // Alias mapping
        if (type === 'DUST' || type === 'PEBBLE') return this.getTexture('RUBBLE', color);
        if (type === 'RING') return this.getTexture('SHOCKWAVE_RING' as any, color); 

        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const texture = this.bakeProjectile(visual, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;

        ctx.translate(cx, cy);

        // Intensified Glow / Halo for volumetric feel
        ctx.shadowColor = color;
        ctx.shadowBlur = 20;

        if (visual === 'ARROW') {
            ctx.fillStyle = '#fff';
            ctx.strokeStyle = color;
            ctx.lineWidth = 3; // Thicker

            // Shaft
            ctx.beginPath();
            ctx.moveTo(-40, 0); ctx.lineTo(30, 0);
            ctx.stroke();

            // Head (Glowing Core)
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(30, 0); ctx.lineTo(15, -8); ctx.lineTo(15, 8); ctx.closePath();
            ctx.fill();

            // Energy Trail
            const grad = ctx.createLinearGradient(-60, 0, 0, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(1, color);
            ctx.strokeStyle = grad;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(-60, 0); ctx.lineTo(-40, 0); ctx.stroke();
        }
        else if (visual === 'BOLT') {
            // Energy Bolt - Teardrop with hot core
            const grad = ctx.createLinearGradient(-40, 0, 40, 0);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.2, color);
            grad.addColorStop(0.8, '#fff');
            grad.addColorStop(1, '#fff');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(-50, 0);
            ctx.quadraticCurveTo(0, 12, 40, 0); // Fatter body
            ctx.quadraticCurveTo(0, -12, -50, 0);
            ctx.fill();

            // Core line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(-20, 0); ctx.lineTo(35, 0); ctx.stroke();
        }
        else if (visual === 'FIREBALL') {
            // Core
            const grad = ctx.createRadialGradient(-10, 0, 0, -10, 0, 35);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(-10, 0, 35, 0, Math.PI*2); ctx.fill();

            // Turbulent sparks
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 5;
            for(let i=0; i<8; i++) {
                ctx.beginPath();
                const sx = -20 - Math.random() * 40;
                const sy = (Math.random()-0.5) * 25;
                const s = Math.random() * 3;
                ctx.arc(sx, sy, s, 0, Math.PI*2);
                ctx.fill();
            }
        }
        else if (visual === 'BOMB') {
            // Dark Matter Bomb
            const grad = ctx.createRadialGradient(0, 0, 5, 0, 0, 20);
            grad.addColorStop(0, '#4b5563'); // Gray core
            grad.addColorStop(0.8, '#000');    // Black body
            grad.addColorStop(1, color);       // Rim light

            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 5, 20, 0, Math.PI*2); ctx.fill();

            // Fuse Spark
            ctx.shadowColor = '#fbbf24';
            ctx.shadowBlur = 10;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(10, -5, 4, 0, Math.PI*2); ctx.fill();
        }
        else if (visual === 'SLASH') {
            // Crescent Wave - Sharp edge, faded trail
            const grad = ctx.createLinearGradient(0, -40, 0, 40);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');

            ctx.strokeStyle = grad;
            ctx.lineWidth = 6;
            ctx.lineCap = 'round';
            ctx.shadowBlur = 20;

            ctx.beginPath();
            ctx.arc(-10, 0, 40, -Math.PI/2.5, Math.PI/2.5);
            ctx.stroke();

            // Inner hot edge
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.shadowBlur = 5;
            ctx.beginPath();
            ctx.arc(-8, 0, 40, -Math.PI/2.5, Math.PI/2.5);
            ctx.stroke();
        }
        else {
            // Generic Orb - Volumetric
            const grad = ctx.createRadialGradient(0, 0, 2, 0, 0, 15);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement {
        return this.getTexture('ATMOSPHERE', color);
    }

    public generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    public generateFogCloud(color: string): HTMLCanvasElement {
        // High quality fog with noise simulation via radial steps
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const w = 128, h = 64;

        // Elliptical gradient for volume
        const grad = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w/2);
        grad.addColorStop(0, color); // Dense center
        grad.addColorStop(0.6, color.replace(')', ', 0.4)').replace('rgb', 'rgba')); 
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.ellipse(w/2, h/2, w/2, h/2, 0, 0, Math.PI*2);
        ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;

        // Force ISO perspective in texture
        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); 

        const grad = ctx.createRadialGradient(0, 0, 20, 0, 0, 60);
        grad.addColorStop(0, 'rgba(255,255,255,0.8)');
        grad.addColorStop(0.2, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, 60, 0, Math.PI*2); ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateHexFog(color: string): HTMLCanvasElement {
        const key = `HEX_FOG_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 128);
        const cx = 64, cy = 64;
        const size = 50;

        // Volumetric Hexagon
        // Use a radial gradient clipped to a hex shape for soft edges
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, size);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent'); // Soft falloff

        ctx.fillStyle = grad;

        ctx.beginPath();
        for(let i=0; i<6; i++) {
            const angle = (Math.PI/6 + Math.PI/4) + i * Math.PI/3;
            const x = cx + Math.cos(angle) * size;
            const y = cy + Math.sin(angle) * size;
            if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
        }
        ctx.closePath();
        ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    // =========================================================================================
    // 🔨 VOLUMETRIC TEXTURE BAKING
    // =========================================================================================

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 2;

        ctx.translate(CENTER, CENTER);

        if (type === 'GENERIC_DEBUG') {
            ctx.fillStyle = '#ff00ff';
            ctx.fillRect(-r, -r, r*2, r*2);
            return canvas;
        }

        // 1. VOLUMETRIC GLOWS & ATMOSPHERICS
        // Used for: GLOW, ATMOSPHERE, SMOKE_PUFF
        if (type === 'ATMOSPHERE' || type === 'GLOW' || type === 'SMOKE_PUFF') {
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);

            if (type === 'SMOKE_PUFF') {
                // Smoke is denser in middle, fluffy edges
                grad.addColorStop(0, color); 
                grad.addColorStop(0.4, color);
                grad.addColorStop(1, 'transparent');
            } else {
                // Atmosphere is super soft, hot core
                grad.addColorStop(0, '#ffffff'); // Hot core
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, 'transparent');
            }

            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            return canvas;
        }

        // 2. HARD DEBRIS (Physical)
        // Used for: RUBBLE, SHARD, ROCK, CHIP
        if (type === 'SHARD' || type === 'RUBBLE' || type === 'ROCK' || type === 'CHIP') {
            // Generate an irregular polygon for natural look
            ctx.fillStyle = color;
            ctx.beginPath();
            const points = 5 + Math.floor(Math.random() * 3);
            for(let i=0; i<points; i++) {
                const angle = (i / points) * Math.PI * 2;
                const dist = r * (0.5 + Math.random() * 0.5);
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                if (i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.fill();

            // Highlight facet (Fake 3D)
            ctx.fillStyle = 'rgba(255,255,255,0.3)';
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(r*0.5, -r*0.5);
            ctx.lineTo(-r*0.5, -r*0.5);
            ctx.closePath();
            ctx.fill();

            // Shadow facet
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(r*0.5, r*0.5);
            ctx.lineTo(-r*0.5, r*0.5);
            ctx.closePath();
            ctx.fill();

            return canvas;
        }

        // 3. ENERGETIC BURSTS
        // Used for: SPIKE, SPARK, STAR
        if (type === 'SPIKE' || type === 'SPARK') {
            ctx.fillStyle = color;
            ctx.beginPath();

            // 4-Point Star (Diamond Flash)
            const w = type === 'SPARK' ? r * 0.2 : r * 0.4;
            ctx.moveTo(0, -r); 
            ctx.quadraticCurveTo(0, 0, w, 0);
            ctx.quadraticCurveTo(0, 0, 0, r);
            ctx.quadraticCurveTo(0, 0, -w, 0);
            ctx.quadraticCurveTo(0, 0, 0, -r);
            ctx.fill();

            // White hot core
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.8;
            ctx.beginPath();
            ctx.moveTo(0, -r*0.5); 
            ctx.lineTo(w*0.5, 0);
            ctx.lineTo(0, r*0.5);
            ctx.lineTo(-w*0.5, 0);
            ctx.fill();

            return canvas;
        }

        // 4. RINGS & WAVES
        if (type === 'SHOCKWAVE' as any || type === 'SHOCKWAVE_RING' as any || type === 'RING') {
            // Soft Ring with gradient stroke
            const grad = ctx.createRadialGradient(0, 0, r * 0.7, 0, 0, r);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath(); 
            ctx.arc(0, 0, r, 0, Math.PI*2); 
            ctx.arc(0, 0, r * 0.6, 0, Math.PI*2, true); // Hollow
            ctx.fill();

            // Inner bright rim
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.stroke();

            return canvas;
        }

        // 5. CRACKS (Ground Fissures)
        if (type === 'CRACKS') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round'; 
            ctx.lineJoin = 'round';

            const branches = 3;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2;
                ctx.beginPath();
                ctx.moveTo(0, 0);

                // Jagged line
                let cx = 0, cy = 0;
                const len = r;
                const cx1 = Math.cos(angle) * len * 0.4 + (Math.random()-0.5)*10;
                const cy1 = Math.sin(angle) * len * 0.4 + (Math.random()-0.5)*10;
                ctx.lineTo(cx1, cy1);

                const cx2 = Math.cos(angle) * len;
                const cy2 = Math.sin(angle) * len;
                ctx.lineTo(cx2, cy2);

                ctx.stroke();
            }
            return canvas;
        }

        // 6. MAGIC CIRCLE (Geometric)
        if (type === 'MAGIC_CIRCLE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.shadowColor = color;
            ctx.shadowBlur = 5;

            ctx.beginPath(); 
            ctx.arc(0, 0, r * 0.9, 0, Math.PI*2);
            ctx.stroke();

            // Inner Square
            ctx.beginPath();
            const s = r * 0.6;
            ctx.rect(-s, -s, s*2, s*2);
            ctx.stroke();

            // Rotated Square
            ctx.save();
            ctx.rotate(Math.PI/4);
            ctx.beginPath(); ctx.rect(-s, -s, s*2, s*2); ctx.stroke();
            ctx.restore();

            return canvas;
        }

        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { Particle } from "../state";
import { ISO_SCALE_Y } from "../../../../constants";
import { SurfaceAssets } from "../../../graphics/SurfaceAssets";
import { PROCEDURAL_VISUALS, PillarVisualDef, DomainVisualDef, HexVisualDef, GridVisualDef, DEFAULT_PILLAR_CONFIG, DEFAULT_DOMAIN_CONFIG, DEFAULT_GRID_CONFIG } from "../../../../data/vfx/procedural_visuals";

// Helper for hex tracing (used by procedural beams)
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS_X: number[] = [];
const HEX_CORNERS_Y: number[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS_X.push(Math.cos(angle));
    HEX_CORNERS_Y.push(Math.sin(angle));
}
function traceHexagonFast(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    ctx.moveTo(HEX_CORNERS_X[0] * r, HEX_CORNERS_Y[0] * r);
    for (let i = 1; i < 6; i++) ctx.lineTo(HEX_CORNERS_X[i] * r, HEX_CORNERS_Y[i] * r);
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean) {
        ctx.save();
        ctx.translate(drawX, drawY);

        const now = Date.now() / 1000;

        // --- 1. PERSPECTIVE CORRECTION (THE 2.5D RULE) ---
        // Ground-planar effects must be squashed to match the isometric grid.
        // This is non-negotiable for depth perception.
        const isGroundEffect = ['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'DOMAIN', 'MAGIC_CIRCLE'].includes(p.type);

        if (isGroundEffect) {
            ctx.scale(1, ISO_SCALE_Y); // Flatten vertical axis
        }

        ctx.rotate(p.rotation);

        // --- 2. BLEND MODES & COMPOSITION ---
        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            // Smart defaults based on material type
            if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'CHIP'].includes(p.type)) {
                 ctx.globalCompositeOperation = 'source-over'; // Solid matter
            } else if (['SMOKE', 'SMOKE_PUFF', 'ATMOSPHERE'].includes(p.type)) {
                 ctx.globalCompositeOperation = 'screen';      // Volumetric gas
            } else {
                 ctx.globalCompositeOperation = 'screen';      // Light/Energy (safer than lighter)
            }
        }

        // --- 3. RENDERING ---

        // A. TEXTURE BASED (High Quality Pre-baked)
        if (p.image) {
            this.drawTexture(ctx, p.image, p.size, progress, p.type);
        } 
        else if (p.texture) {
            this.drawTexture(ctx, p.texture, p.size, progress, p.type);
        }
        else {
            // B. PROCEDURAL COMPLEX SHAPES
            if (['BEAM', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'GRID_FIELD', 'DOMAIN', 'DEATH_RAY'].includes(p.type)) {
                this.drawProcedural(ctx, p, progress, isChaos, now);
            }
            // C. GENERIC SHAPES (Using cached textures from VFXFactory is preferred over raw ctx calls)
            else {
                // Determine scale animation
                let scale = 1.0;
                let alpha = 1.0 - progress;

                if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
                    scale = 0.2 + progress * 2.0; // Expands outward
                    alpha = 1.0 - Math.pow(progress, 2); // Fades out non-linearly
                } else if (p.type === 'SMOKE' || p.type === 'ATMOSPHERE') {
                    scale = 0.5 + progress * 1.5; // Expands slowly
                    alpha = (1.0 - progress) * 0.6; // Low opacity for gas
                } else {
                    scale = 1.0 - Math.pow(progress, 2); // Shrinks
                }

                ctx.globalAlpha = Math.max(0, Math.min(1, alpha));

                // PHYSICAL OBJECT SHADOWS
                if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD'].includes(p.type)) {
                    // Draw Drop Shadow manually for 2.5D depth
                    ctx.save();
                    ctx.translate(0, p.size * 0.5); // Shadow offset
                    ctx.scale(1, 0.5); // Flatten shadow
                    ctx.globalCompositeOperation = 'multiply';
                    ctx.globalAlpha = 0.4 * alpha;
                    ctx.fillStyle = '#000';
                    ctx.beginPath(); ctx.arc(0, 0, p.size * scale * 0.8, 0, Math.PI*2); ctx.fill();
                    ctx.restore();
                }

                // Render Geometry (Diamond/Rect for physicals, Texture for others is implied via p.image usually)
                // If no p.image, we fallback to drawing shapes, but we try to use cached factory textures implicitly
                // by forcing the system to have loaded them in `VFXPlayer` or `VFXFactory`.
                // However, `p.image` isn't always set in simple emitters. 

                // DIRECT DRAWING FALLBACK (If no baked texture in particle)
                if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'CHIP'].includes(p.type)) {
                    const s = p.size * scale;
                    ctx.fillStyle = p.color;
                    ctx.beginPath();
                    // Irregular shard shape
                    ctx.moveTo(-s, -s*0.5);
                    ctx.lineTo(s*0.5, -s);
                    ctx.lineTo(s, s*0.5);
                    ctx.lineTo(-s*0.5, s);
                    ctx.closePath();
                    ctx.fill();

                    // Highlight facet
                    ctx.fillStyle = 'rgba(255,255,255,0.3)';
                    ctx.beginPath(); ctx.moveTo(-s, -s*0.5); ctx.lineTo(0,0); ctx.lineTo(-s*0.5, s); ctx.fill();
                } 
                else if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
                    const s = p.size * scale;
                    ctx.beginPath();
                    ctx.arc(0, 0, s, 0, Math.PI * 2);
                    ctx.lineWidth = (p.size * 0.2) * (1-progress); // Thins out
                    ctx.strokeStyle = p.color;
                    ctx.stroke();
                }
                else {
                    // Generic Glow/Spark (Fallback to Circle with Gradient)
                    const s = p.size * scale;
                    const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, s);
                    grad.addColorStop(0, '#fff');
                    grad.addColorStop(0.3, p.color);
                    grad.addColorStop(1, 'transparent');
                    ctx.fillStyle = grad;
                    ctx.beginPath(); ctx.arc(0, 0, s, 0, Math.PI * 2); ctx.fill();
                }
            }
        }

        ctx.restore();
    },

    drawTexture(ctx: CanvasRenderingContext2D, img: HTMLCanvasElement, baseSize: number, progress: number, type: string) {
        let scale = 1.0;
        let alpha = 1.0 - progress;

        if (type === 'SHOCKWAVE' || type === 'RING') {
            scale = 0.5 + progress * 2.0;
            alpha = 1.0 - Math.pow(progress, 3);
        } else if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            scale = 0.8 + progress * 1.2;
            alpha = (1.0 - progress) * 0.5; // Transparent gas
        } else {
            scale = 1.0 - Math.pow(progress, 2);
        }

        const drawSize = baseSize * scale;
        ctx.globalAlpha = Math.max(0, Math.min(1, alpha));
        ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
    },

    drawProcedural(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean, now: number) {

        if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
             if (p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.targetX;
                const dy = p.targetY; 

                // Soft Core
                ctx.beginPath();
                ctx.moveTo(0,0);
                ctx.lineTo(dx, dy - (p.targetZ || 0));
                ctx.strokeStyle = p.color;
                ctx.lineWidth = p.size * (1-progress) * 1.5; // Wider soft glow
                ctx.lineCap = 'round';
                ctx.shadowColor = p.color;
                ctx.shadowBlur = 15;
                ctx.globalCompositeOperation = 'screen';
                ctx.stroke();

                // Bright White Inner
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = p.size * (1-progress) * 0.4;
                ctx.shadowBlur = 0;
                ctx.stroke();
             }
        }
        else if (p.type === 'HEX_BEAM' || p.type === 'GIANT_HEX') {
            // Apply 2.5D Scale
            ctx.scale(1, ISO_SCALE_Y);
            if (p.type === 'GIANT_HEX') ctx.rotate(p.rotation);

            ctx.globalCompositeOperation = 'screen';

            // Volumetric Fill
            const grad = ctx.createRadialGradient(0,0,0,0,0,p.size);
            grad.addColorStop(0, p.color); // Hot center
            grad.addColorStop(0.8, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = (1 - progress) * 0.8;
            traceHexagonFast(ctx, p.size); ctx.fill();

            // Inner Edge
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            traceHexagonFast(ctx, p.size * 0.9); ctx.stroke();
        }
        else if (p.type === 'PILLAR') {
            const rawDef = PROCEDURAL_VISUALS[p.style || ''] || DEFAULT_PILLAR_CONFIG;
            const def = rawDef as PillarVisualDef;
            const h = def.height || 1200; 
            const width = p.size * (1 - progress * 0.5) * (def.widthScale || 1.0);

            ctx.save();
            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            // Volumetric Cylinder Gradient (Left to Right) to simulate 3D form
            const cylinderGrad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
            cylinderGrad.addColorStop(0, p.color); // Edge
            cylinderGrad.addColorStop(0.5, '#ffffff'); // Highlights
            cylinderGrad.addColorStop(1, p.color); // Edge

            // Vertical Fade
            const verticalMask = ctx.createLinearGradient(0, 0, 0, -h);
            verticalMask.addColorStop(0, 'rgba(255,255,255,1)');
            verticalMask.addColorStop(1, 'rgba(255,255,255,0)');

            ctx.fillStyle = cylinderGrad;
            ctx.globalAlpha = (1 - progress) * 0.8;

            // Draw rect (Pillar body)
            ctx.fillRect(-width/2, -h, width, h);

            // Base Ring (Impact point)
            if (def.hasBaseRing) {
                ctx.scale(1, ISO_SCALE_Y);
                const ringGrad = ctx.createRadialGradient(0,0, width*0.5, 0,0, width*1.2);
                ringGrad.addColorStop(0, 'transparent');
                ringGrad.addColorStop(0.5, p.color);
                ringGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = ringGrad;
                ctx.beginPath(); ctx.arc(0, 0, width*1.5, 0, Math.PI*2); ctx.fill();
            }
            ctx.restore();
        }
        else if (p.type === 'DOMAIN') {
            // Ensure flat projection
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 

            const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.7, p.color); // Colored rim
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.4 * (1 - progress);
            ctx.globalCompositeOperation = 'screen';
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();

            // Bright Rim
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.2;
            ctx.beginPath(); ctx.arc(0, 0, r * 0.9, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// --- PRECOMPUTED GEOMETRY ---
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_COS: number[] = [];
const HEX_SIN: number[] = [];

for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_COS.push(Math.cos(angle));
    HEX_SIN.push(Math.sin(angle));
}

export const GEOMETRY = {
    HEX_COS,
    HEX_SIN,
    START_ANGLE
};

export const SurfaceAssets = {

    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
        ctx.beginPath();
        const startX = x + radius * HEX_COS[0];
        const startY = y + radius * HEX_SIN[0] * ISO_SCALE_Y;
        ctx.moveTo(startX, startY);

        for (let i = 1; i < 6; i++) {
            const vx = x + radius * HEX_COS[i];
            const vy = y + radius * HEX_SIN[i] * ISO_SCALE_Y;
            ctx.lineTo(vx, vy);
        }
        ctx.closePath();
    },

    /**
     * NEW: Volumetric Hexagon
     * Renders a soft, glowing pillar base or fog pool.
     */
    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        // We use the "ATMOSPHERE" texture which is a perfect soft radial glow
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; // Oversize slightly for bleed

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); // Flatten to ground plane

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';

        // Draw the soft fog texture
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        // Optional: Draw a second smaller, brighter core
        ctx.globalAlpha = opacity * 0.5;
        const coreSize = size * 0.6;
        ctx.drawImage(texture, -coreSize/2, -coreSize/2, coreSize, coreSize);

        ctx.restore();
    },

    /**
     * NEW: Hex Ripple (Volumetric Ring)
     */
    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        // Soft glow for the line
        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        this.traceHex(ctx, x, y, radius);
        ctx.stroke();

        // Secondary white hot core
        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = opacity * 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        const r = HEX_SIZE * 0.9;

        // 1. Base Liquid Shape (Wobbly)
        ctx.beginPath();
        const segments = 12; 
        for (let i = 0; i <= segments; i++) {
            const theta = (i / segments) * Math.PI * 2;
            // More organic noise
            const noise = Math.sin(theta * 4 + time) * 3 + Math.cos(theta * 2 - time * 1.5) * 2; 
            const px = Math.cos(theta) * (r + noise);
            const py = Math.sin(theta) * (r + noise);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();

        // 2. Deep Base
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.8 * intensity;
        ctx.fill();

        // 3. Surface Ripples (Darker)
        ctx.globalCompositeOperation = 'multiply';
        ctx.beginPath();
        const rippleX = Math.sin(time) * 5;
        const rippleY = Math.cos(time * 0.8) * 5;
        ctx.ellipse(rippleX, rippleY, r * 0.6, r * 0.5, time*0.1, 0, Math.PI * 2);
        ctx.fill();

        // 4. Specular Highlights (Bubbles/Reflection)
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.5;

        const bX = Math.cos(time * 1.5) * r * 0.4;
        const bY = Math.sin(time * 1.5) * r * 0.4;
        ctx.beginPath(); ctx.ellipse(bX, bY, 6, 3, 0, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        // Use the factory generated cloud texture for better performance & look
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.0;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.15; // Very subtle

        const puffs = 3;
        for(let i=0; i<puffs; i++) {
            const angle = time * 0.2 + (i * Math.PI * 2 / puffs);
            const dist = 12 + Math.sin(time + i) * 6;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            // Breathe
            const pulse = 1.0 + Math.sin(time * 1.5 + i) * 0.1;
            const pSize = size * 0.5 * pulse;

            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }

        // Center Core
        ctx.globalAlpha = 0.2;
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;

        const staticRot = (x + y) * 0.1; // Consistent rotation based on position
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity;

        const visibleFaces = [5, 0, 1]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;

            const x1 = x + HEX_SIZE * HEX_COS[i];
            const y1 = HEX_SIZE * HEX_SIN[i] * ISO_SCALE_Y; 

            const x2 = x + HEX_SIZE * HEX_COS[j];
            const y2 = HEX_SIZE * HEX_SIN[j] * ISO_SCALE_Y; 

            // Gradient for 3D depth
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); // Fade into ground

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, topY + y1);
            ctx.lineTo(x2, topY + y2);
            ctx.lineTo(x2, bottomY + y2);
            ctx.lineTo(x1, bottomY + y1);
            ctx.closePath();
            ctx.fill();

            // Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            ctx.stroke();
            ctx.globalAlpha = opacity;
        }

        // Top Cap
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        this.traceHex(ctx, x, topY, HEX_SIZE);
        ctx.fill();

        // Rim
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { GroundHazard } from "../../../types";
import { HAZARD_VISUALS } from "../../../data/vfx/hazard_visuals";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";

export const ZoneRenderer = {

    drawHazard(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        hazard: GroundHazard,
        globalTime: number
    ) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfaceAssets.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfaceAssets.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'FOG') {
            // Uses new Volumetric Smoke Puff texture internally
            SurfaceAssets.drawFog(ctx, x, y, def.primaryColor, globalTime * def.speed);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) SurfaceAssets.drawExtrusion(ctx, x, y, 8, def.primaryColor, 0.5);

            // Ground Crystal Glow
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Texture
            const texture = VFXFactory.getTexture('SHARD', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;

            // Draw scattered crystal shards on floor
            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 10;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-10, py-10, 20, 20);
            }

            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Dark Core
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();

            // Event Horizon Glow
            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.5, 0,0,HEX_SIZE);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

            // Rotating Accretion Disk
            ctx.rotate(globalTime * def.speed);
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 10]);
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    },

    /**
     * REFACTORED: Volumetric Hex Expansion
     * Draws a "Volume" of light that fills up the hex.
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visualTag: string, 
        progress: number, // 0.0 (Start) -> 1.0 (Ready)
        globalTime: number,
        dist: number,     // Distance from center of zone (in tiles)
        maxRadius: number // Radius of zone (in tiles)
    ) {
        const styleKey = (visualTag === 'ULT') ? 'ULT' : 
                         (visualTag === 'ACTIVE') ? 'ACTIVE' : 
                         (visualTag === 'AOE_WARNING') ? 'AOE_WARNING' : 'BASIC';

        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        const normDist = dist / Math.max(1, maxRadius);
        const wavePos = progress * 1.1; 

        const isInsideWave = wavePos >= normDist;
        const distToEdge = Math.abs(wavePos - normDist);
        const isEdge = distToEdge < 0.25; 

        const pulse = 1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1;

        // A. INNER VOLUME (The Fog)
        if (isInsideWave) {
            // Opacity ramps up as skill completes
            const fogOpacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);

            // Use improved volumetric renderer
            SurfaceAssets.drawVolumetricHex(ctx, x, y, size * 0.9, color, fogOpacity);
        }

        // B. EXPANDING EDGE (The Shockwave)
        if (isEdge) {
            const edgeIntensity = 1.0 - (distToEdge / 0.25); 
            const edgeOpacity = def.fillOpacityMax * edgeIntensity;
            const edgeWidth = (def.baseRingWidth || 3) * edgeIntensity * 1.5;

            // Draw thick, blurred hex stroke
            SurfaceAssets.drawHexRipple(ctx, x, y, size, color, edgeOpacity, edgeWidth);
        }

        // C. PERIMETER MARKER
        if (dist >= maxRadius - 0.5) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.4;

            ctx.strokeStyle = color;
            ctx.lineWidth = 1; 
            ctx.globalAlpha = borderAlpha;

            if (def.dashed) ctx.setLineDash([5, 5]);
            SurfaceAssets.traceHex(ctx, x, y, size);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { Team } from "../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { AssetManager } from "../../assets";
import { VFXFactory } from "../../graphics/VFXFactory";

/**
 * Draws the "Tether" for flying units.
 * Replaces old dashed line with a vertical energy beam gradient.
 */
export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.deathSpiritColor; 

    // Calculate ground point relative to current context (already translated to unit head)
    // Unit drawing context is at: physX, physY - physZ
    // So ground is at: 0, +physZ

    ctx.save();

    // Vertical Gradient Beam
    const grad = ctx.createLinearGradient(0, 0, 0, physZ);
    grad.addColorStop(0, 'rgba(0,0,0,0)'); // Fade at body
    grad.addColorStop(0.5, color);        // Brightest in middle
    grad.addColorStop(1, 'rgba(0,0,0,0)'); // Fade at ground

    ctx.globalAlpha = 0.3 + Math.sin(t * 5) * 0.1;
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;

    // Thin beam
    const w = 4;
    ctx.fillRect(-w/2, 0, w, physZ);

    // Ground anchor glow
    ctx.translate(0, physZ);
    ctx.scale(1, ISO_SCALE_Y); // Flatten for ISO

    const glow = VFXFactory.getTexture('GLOW', color);
    const sz = 32;
    ctx.drawImage(glow, -sz/2, -sz/2, sz, sz);

    ctx.restore();
}

/**
 * Draws jet/flight trails.
 * Replaces rotating hex lines with scaling glow sprites.
 */
export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.flightTrailColor;
    const glow = VFXFactory.getTexture('GLOW', color);

    ctx.save();
    ctx.translate(0, 10); 

    // Draw 2 oscillating thrusters
    for(let i = -1; i <= 1; i += 2) {
        ctx.save();
        const offsetX = i * 10;
        const pulse = Math.sin(t * 20 + i) * 0.2 + 0.8;

        ctx.translate(offsetX, 0);
        ctx.scale(0.5 * pulse, 1.0 * pulse);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -16, 0, 32, 48); // Stretch downwards
        ctx.restore();
    }

    ctx.restore();
}

/**
 * Draws casting indicator (Charging).
 * Replaces vector hexes with a rotating Ring Texture.
 */
export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -50); // Floating above head

    // 1. Vertical Ring (Halo)
    const ring = VFXFactory.getTexture('RING', color);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.8 * progress;

    ctx.save();
    ctx.scale(1, 0.4); // Flatten vertical halo
    ctx.rotate(t * 2);
    const size = 64 * (0.8 + progress * 0.2);
    ctx.drawImage(ring, -size/2, -size/2, size, size);
    ctx.restore();

    // 2. Core Glow
    const glow = VFXFactory.getTexture('GLOW', color);
    const coreSize = 32 * progress;
    ctx.drawImage(glow, -coreSize/2, -coreSize/2, coreSize, coreSize);

    ctx.restore();

    // 3. Ground Warning (AOE)
    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

/**
 * Draws AOE warning on caster.
 * Replaces stroke with expanding Shockwave texture.
 */
export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    // We are in Unit Space (centered on unit). We need to draw on the "ground" relative to unit.
    // However, drawCastingVFX calls this inside the body stack. 
    // To be correct, we should ideally draw this in the Ground Layer of UnitRenderer, but doing it here with offset works for now.

    // Actually, drawBodyElements has translated to (physX, physY - physZ). 
    // To draw on ground, we translate down by physZ. But we don't have physZ here easily.
    // Visual Hack: Draw it at feet (0,0 of unit body) and scale flat.

    const texture = VFXFactory.getTexture('SHOCKWAVE', color); 

    ctx.save();
    ctx.translate(0, 0); // Feet
    ctx.scale(1, ISO_SCALE_Y); // Flatten to ground

    const scale = (0.5 + progress * 1.5) * 3.0; // Expand outward

    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = (1 - progress) * 0.4; // Fade out as it expands

    const size = 64 * scale;
    ctx.drawImage(texture, -size/2, -size/2, size, size);

    ctx.restore();
}

/**
 * Draws Ultimate preparation.
 * Uses Magic Circle texture.
 */
export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;
    const texture = VFXFactory.getTexture('MAGIC_CIRCLE', color);

    ctx.save();
    ctx.translate(0, -60); 

    // Spin faster as it completes
    const rot = t * (2 + progress * 5);

    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.6 + progress * 0.4;

    // Back Circle
    ctx.save();
    ctx.scale(1, 0.4); // Flattened perspective
    ctx.rotate(rot);
    const size = 120;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();

    // Core glow (Rising energy)
    const glow = VFXFactory.getTexture('GLOW', color);
    ctx.globalAlpha = 0.5 * progress;
    ctx.scale(0.5, 1.5); // Vertical pillar feel
    ctx.drawImage(glow, -40, -40 - (progress * 50), 80, 80);

    ctx.restore();
}

/**
 * Draws the ground indicator for skills.
 * Uses Volumetric Hex from SurfaceAssets (Texture based).
 */
export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    // Note: Context is already translated to ground target position by caller (drawGroundElements)

    const pixelRadius = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = pixelRadius * progress;
    const opacity = 0.3 + Math.sin(t * 5) * 0.1;

    // Use Volumetric Draw (No Vectors!)
    SurfaceAssets.drawVolumetricHex(ctx, 0, 0, currentRadius, color, opacity);

    // Add a Ring at the edge for definition
    const ringSize = currentRadius * 2.5; 
    const ring = VFXFactory.getTexture('RING', color);

    ctx.save();
    ctx.scale(1, ISO_SCALE_Y); // ISO
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = opacity * 1.2;
    ctx.drawImage(ring, -ringSize/2, -ringSize/2, ringSize, ringSize);
    ctx.restore();
}

/**
 * Draws status icons overhead.
 * Uses textures for backgrounds.
 */
export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);

            // Background Glow
            const bg = VFXFactory.getTexture('GLOW', skill.color);
            ctx.globalAlpha = 0.6;
            ctx.globalCompositeOperation = 'screen';
            ctx.drawImage(bg, -30, -30, 60, 60);

            ctx.restore();
        }
    }
}

/**
 * Draws status effects (Stun, Silence, etc.)
 * Uses AssetManager icons.
 */
export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    let statusId = 'NONE';
    if (agent.banished) statusId = 'BANISH';
    else if (agent.stunTimer > 0) statusId = 'STUN';
    else if (agent.silenceTimer > 0) statusId = 'SILENCE';

    if (agent.visualStatus !== 'NONE') statusId = agent.visualStatus;

    const def = STATUS_VISUALS[statusId];
    if (!def || def.overheadType === 'NONE') return;

    ctx.save();
    if (agent.facing < 0) ctx.scale(-1, 1);

    // Position above head
    ctx.translate(0, Math.round(-80));

    if (def.overheadType === 'ICON' || def.overheadType === 'GHOST_FLOAT' || def.overheadType === 'BUBBLE_POP') {
        const bob = Math.sin(t * 4) * 5;
        ctx.translate(0, bob);

        const icon = AssetManager.getStatusIcon(statusId);
        if (icon) {
            const size = 32;
            // Shadow for readability
            ctx.shadowColor = 'rgba(0,0,0,0.8)';
            ctx.shadowBlur = 4;
            ctx.drawImage(icon, -size/2, -size/2, size, size);
            ctx.shadowBlur = 0;
        }
    } 

    ctx.restore();
}

import { ZoneRenderer } from "./ZoneRenderer";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

interface ZoneInfo {
    type: 'CAST';
    color: string;
    visual: string; // Skill visual tag
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face Y
        size: number,

        // State Props
        specialStatus: string | undefined, 
        zoneInfo: ZoneInfo | undefined,    

        // Lighting
        lightColor: string | null,
        lightIntensity: number,

        // Interactive
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        // Metadata
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        // --- LAYER 1: HAZARDS ---
        if (hazard) {
            ZoneRenderer.drawHazard(ctx, x, y, hazard, globalTime);
        }

        // --- LAYER 2: UNIT STATUS FLOOR TINT ---
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                // Use source-over for tinted glass look instead of additive
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                SurfaceAssets.traceHex(ctx, x, y, size);
                ctx.fill();
                ctx.restore();
            }
        }

        // --- LAYER 3: CAST ZONES (Volumetric) ---
        if (zoneInfo) {
            ZoneRenderer.drawZone(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // --- LAYER 4: DYNAMIC LIGHTING ---
        // Reduced intensity to prevent overexposure
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen'; // Screen is safer than lighter
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4); 
            ctx.fillStyle = lightColor;
            SurfaceAssets.traceHex(ctx, x, y, size);
            ctx.fill();
            ctx.restore();
        }

        // --- LAYER 5: INTERACTIVE UI HIGHLIGHTS ---
        if (isRange || isHover || hasUnit) {
            ctx.save();

            // Use 'screen' for light projection look instead of flat paint
            ctx.globalCompositeOperation = 'screen';

            // Valid Move/Skill Range
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                SurfaceAssets.traceHex(ctx, x, y, size);
                ctx.fill();

                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.5; 
                SurfaceAssets.traceHex(ctx, x, y, size);
                ctx.stroke();
            }

            // Mouse Hover - Bright Spotlight
            if (isHover) { 
                ctx.fillStyle = '#ffffff'; 
                ctx.globalAlpha = 0.2;
                SurfaceAssets.traceHex(ctx, x, y, size);
                ctx.fill(); 

                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8;
                SurfaceAssets.traceHex(ctx, x, y, size);
                ctx.stroke(); 
            }

            // Unit Position - Subtle selection ring
            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                SurfaceAssets.traceHex(ctx, x, y, size * 0.9);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { createCanvas } from "./CanvasUtils";

const TEXTURE_SIZE = 64; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Get visual texture. 
     */
    public getTexture(type: 'SHARD' | 'RUBBLE' | 'SPIKE' | 'SPARK' | 'SLASH' | 'CRACKS' | 'RING' | 'GLOW' | 'MAGIC_CIRCLE' | 'DUST' | 'PEBBLE' | 'ATMOSPHERE' | 'GENERIC_DEBUG' | 'SMOKE_PUFF' | 'SHOCKWAVE', color: string): HTMLCanvasElement {
        // Alias mapping
        if (type === 'DUST' || type === 'PEBBLE') return this.getTexture('RUBBLE', color);
        if (type === 'RING') return this.getTexture('SHOCKWAVE_RING' as any, color); 

        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const texture = this.bakeProjectile(visual, color);
        this.cache.set(key, texture);
        return texture;
    }

    private bakeProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;

        ctx.translate(cx, cy);

        // Intensified Glow / Halo for volumetric feel
        ctx.shadowColor = color;
        ctx.shadowBlur = 20;

        if (visual === 'ARROW') {
            ctx.fillStyle = '#fff';
            ctx.strokeStyle = color;
            ctx.lineWidth = 3; // Thicker

            // Shaft
            ctx.beginPath();
            ctx.moveTo(-40, 0); ctx.lineTo(30, 0);
            ctx.stroke();

            // Head (Glowing Core)
            ctx.fillStyle = '#fff';
            ctx.beginPath();
            ctx.moveTo(30, 0); ctx.lineTo(15, -8); ctx.lineTo(15, 8); ctx.closePath();
            ctx.fill();

            // Energy Trail
            const grad = ctx.createLinearGradient(-60, 0, 0, 0);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(1, color);
            ctx.strokeStyle = grad;
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(-60, 0); ctx.lineTo(-40, 0); ctx.stroke();
        }
        else if (visual === 'BOLT') {
            // Energy Bolt - Teardrop with hot core
            const grad = ctx.createLinearGradient(-40, 0, 40, 0);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.2, color);
            grad.addColorStop(0.8, '#fff');
            grad.addColorStop(1, '#fff');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(-50, 0);
            ctx.quadraticCurveTo(0, 12, 40, 0); // Fatter body
            ctx.quadraticCurveTo(0, -12, -50, 0);
            ctx.fill();

            // Core line
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.beginPath(); ctx.moveTo(-20, 0); ctx.lineTo(35, 0); ctx.stroke();
        }
        else if (visual === 'FIREBALL') {
            // Core
            const grad = ctx.createRadialGradient(-10, 0, 0, -10, 0, 35);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.3, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(-10, 0, 35, 0, Math.PI*2); ctx.fill();

            // Turbulent sparks
            ctx.fillStyle = '#fff';
            ctx.shadowBlur = 5;
            for(let i=0; i<8; i++) {
                ctx.beginPath();
                const sx = -20 - Math.random() * 40;
                const sy = (Math.random()-0.5) * 25;
                const s = Math.random() * 3;
                ctx.arc(sx, sy, s, 0, Math.PI*2);
                ctx.fill();
            }
        }
        else if (visual === 'BOMB') {
            // Dark Matter Bomb
            const grad = ctx.createRadialGradient(0, 0, 5, 0, 0, 20);
            grad.addColorStop(0, '#4b5563'); // Gray core
            grad.addColorStop(0.8, '#000');    // Black body
            grad.addColorStop(1, color);       // Rim light

            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 5, 20, 0, Math.PI*2); ctx.fill();

            // Fuse Spark
            ctx.shadowColor = '#fbbf24';
            ctx.shadowBlur = 10;
            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(10, -5, 4, 0, Math.PI*2); ctx.fill();
        }
        else if (visual === 'SLASH') {
            // Crescent Wave - Sharp edge, faded trail
            const grad = ctx.createLinearGradient(0, -40, 0, 40);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');

            ctx.strokeStyle = grad;
            ctx.lineWidth = 6;
            ctx.lineCap = 'round';
            ctx.shadowBlur = 20;

            ctx.beginPath();
            ctx.arc(-10, 0, 40, -Math.PI/2.5, Math.PI/2.5);
            ctx.stroke();

            // Inner hot edge
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.shadowBlur = 5;
            ctx.beginPath();
            ctx.arc(-8, 0, 40, -Math.PI/2.5, Math.PI/2.5);
            ctx.stroke();
        }
        else {
            // Generic Orb - Volumetric
            const grad = ctx.createRadialGradient(0, 0, 2, 0, 0, 15);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement {
        return this.getTexture('ATMOSPHERE', color);
    }

    public generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    public generateFogCloud(color: string): HTMLCanvasElement {
        // High quality fog with noise simulation via radial steps
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const w = 128, h = 64;

        // Elliptical gradient for volume
        const grad = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w/2);
        grad.addColorStop(0, color); // Dense center
        grad.addColorStop(0.6, color.replace(')', ', 0.4)').replace('rgb', 'rgba')); 
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.ellipse(w/2, h/2, w/2, h/2, 0, 0, Math.PI*2);
        ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;

        // Force ISO perspective in texture
        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); 

        const grad = ctx.createRadialGradient(0, 0, 20, 0, 0, 60);
        grad.addColorStop(0, 'rgba(255,255,255,0.8)');
        grad.addColorStop(0.2, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.arc(0, 0, 60, 0, Math.PI*2); ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateHexFog(color: string): HTMLCanvasElement {
        const key = `HEX_FOG_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 128);
        const cx = 64, cy = 64;
        const size = 50;

        // Volumetric Hexagon
        // Use a radial gradient clipped to a hex shape for soft edges
        const grad = ctx.createRadialGradient(cx, cy, 0, cx, cy, size);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent'); // Soft falloff

        ctx.fillStyle = grad;

        ctx.beginPath();
        for(let i=0; i<6; i++) {
            const angle = (Math.PI/6 + Math.PI/4) + i * Math.PI/3;
            const x = cx + Math.cos(angle) * size;
            const y = cy + Math.sin(angle) * size;
            if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y);
        }
        ctx.closePath();
        ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    // =========================================================================================
    // 🔨 VOLUMETRIC TEXTURE BAKING
    // =========================================================================================

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 2;

        ctx.translate(CENTER, CENTER);

        if (type === 'GENERIC_DEBUG') {
            ctx.fillStyle = '#ff00ff';
            ctx.fillRect(-r, -r, r*2, r*2);
            return canvas;
        }

        // 1. VOLUMETRIC GLOWS & ATMOSPHERICS
        // Used for: GLOW, ATMOSPHERE, SMOKE_PUFF
        if (type === 'ATMOSPHERE' || type === 'GLOW' || type === 'SMOKE_PUFF') {
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);

            if (type === 'SMOKE_PUFF') {
                // Smoke is denser in middle, fluffy edges
                grad.addColorStop(0, color); 
                grad.addColorStop(0.4, color);
                grad.addColorStop(1, 'transparent');
            } else {
                // Atmosphere is super soft, hot core
                grad.addColorStop(0, '#ffffff'); // Hot core
                grad.addColorStop(0.2, color);
                grad.addColorStop(1, 'transparent');
            }

            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill();
            return canvas;
        }

        // 2. HARD DEBRIS (Physical)
        // Used for: RUBBLE, SHARD, ROCK, CHIP
        if (type === 'SHARD' || type === 'RUBBLE' || type === 'ROCK' || type === 'CHIP') {
            // Generate an irregular polygon for natural look
            ctx.fillStyle = color;
            ctx.beginPath();
            const points = 5 + Math.floor(Math.random() * 3);
            for(let i=0; i<points; i++) {
                const angle = (i / points) * Math.PI * 2;
                const dist = r * (0.5 + Math.random() * 0.5);
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                if (i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
            }
            ctx.closePath();
            ctx.fill();

            // Highlight facet (Fake 3D)
            ctx.fillStyle = 'rgba(255,255,255,0.3)';
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(r*0.5, -r*0.5);
            ctx.lineTo(-r*0.5, -r*0.5);
            ctx.closePath();
            ctx.fill();

            // Shadow facet
            ctx.fillStyle = 'rgba(0,0,0,0.3)';
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(r*0.5, r*0.5);
            ctx.lineTo(-r*0.5, r*0.5);
            ctx.closePath();
            ctx.fill();

            return canvas;
        }

        // 3. ENERGETIC BURSTS
        // Used for: SPIKE, SPARK, STAR
        if (type === 'SPIKE' || type === 'SPARK') {
            ctx.fillStyle = color;
            ctx.beginPath();

            // 4-Point Star (Diamond Flash)
            const w = type === 'SPARK' ? r * 0.2 : r * 0.4;
            ctx.moveTo(0, -r); 
            ctx.quadraticCurveTo(0, 0, w, 0);
            ctx.quadraticCurveTo(0, 0, 0, r);
            ctx.quadraticCurveTo(0, 0, -w, 0);
            ctx.quadraticCurveTo(0, 0, 0, -r);
            ctx.fill();

            // White hot core
            ctx.fillStyle = '#fff';
            ctx.globalAlpha = 0.8;
            ctx.beginPath();
            ctx.moveTo(0, -r*0.5); 
            ctx.lineTo(w*0.5, 0);
            ctx.lineTo(0, r*0.5);
            ctx.lineTo(-w*0.5, 0);
            ctx.fill();

            return canvas;
        }

        // 4. RINGS & WAVES
        if (type === 'SHOCKWAVE' as any || type === 'SHOCKWAVE_RING' as any || type === 'RING') {
            // Soft Ring with gradient stroke
            const grad = ctx.createRadialGradient(0, 0, r * 0.7, 0, 0, r);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath(); 
            ctx.arc(0, 0, r, 0, Math.PI*2); 
            ctx.arc(0, 0, r * 0.6, 0, Math.PI*2, true); // Hollow
            ctx.fill();

            // Inner bright rim
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            ctx.beginPath(); ctx.arc(0, 0, r * 0.8, 0, Math.PI*2); ctx.stroke();

            return canvas;
        }

        // 5. CRACKS (Ground Fissures)
        if (type === 'CRACKS') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round'; 
            ctx.lineJoin = 'round';

            const branches = 3;
            for(let i=0; i<branches; i++) {
                const angle = (i / branches) * Math.PI * 2;
                ctx.beginPath();
                ctx.moveTo(0, 0);

                // Jagged line
                let cx = 0, cy = 0;
                const len = r;
                const cx1 = Math.cos(angle) * len * 0.4 + (Math.random()-0.5)*10;
                const cy1 = Math.sin(angle) * len * 0.4 + (Math.random()-0.5)*10;
                ctx.lineTo(cx1, cy1);

                const cx2 = Math.cos(angle) * len;
                const cy2 = Math.sin(angle) * len;
                ctx.lineTo(cx2, cy2);

                ctx.stroke();
            }
            return canvas;
        }

        // 6. MAGIC CIRCLE (Geometric)
        if (type === 'MAGIC_CIRCLE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.shadowColor = color;
            ctx.shadowBlur = 5;

            ctx.beginPath(); 
            ctx.arc(0, 0, r * 0.9, 0, Math.PI*2);
            ctx.stroke();

            // Inner Square
            ctx.beginPath();
            const s = r * 0.6;
            ctx.rect(-s, -s, s*2, s*2);
            ctx.stroke();

            // Rotated Square
            ctx.save();
            ctx.rotate(Math.PI/4);
            ctx.beginPath(); ctx.rect(-s, -s, s*2, s*2); ctx.stroke();
            ctx.restore();

            return canvas;
        }

        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// --- PRECOMPUTED GEOMETRY ---
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_COS: number[] = [];
const HEX_SIN: number[] = [];

for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_COS.push(Math.cos(angle));
    HEX_SIN.push(Math.sin(angle));
}

export const GEOMETRY = {
    HEX_COS,
    HEX_SIN,
    START_ANGLE
};

export const SurfaceAssets = {

    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
        ctx.beginPath();
        const startX = x + radius * HEX_COS[0];
        const startY = y + radius * HEX_SIN[0] * ISO_SCALE_Y;
        ctx.moveTo(startX, startY);

        for (let i = 1; i < 6; i++) {
            const vx = x + radius * HEX_COS[i];
            const vy = y + radius * HEX_SIN[i] * ISO_SCALE_Y;
            ctx.lineTo(vx, vy);
        }
        ctx.closePath();
    },

    /**
     * NEW: Volumetric Hexagon
     * Renders a soft, glowing pillar base or fog pool.
     */
    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        // We use the "ATMOSPHERE" texture which is a perfect soft radial glow
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; // Oversize slightly for bleed

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); // Flatten to ground plane

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';

        // Draw the soft fog texture
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        // Optional: Draw a second smaller, brighter core
        ctx.globalAlpha = opacity * 0.5;
        const coreSize = size * 0.6;
        ctx.drawImage(texture, -coreSize/2, -coreSize/2, coreSize, coreSize);

        ctx.restore();
    },

    /**
     * NEW: Hex Ripple (Volumetric Ring)
     */
    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        // Soft glow for the line
        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        this.traceHex(ctx, x, y, radius);
        ctx.stroke();

        // Secondary white hot core
        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = opacity * 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        const r = HEX_SIZE * 0.9;

        // 1. Base Liquid Shape (Wobbly)
        ctx.beginPath();
        const segments = 12; 
        for (let i = 0; i <= segments; i++) {
            const theta = (i / segments) * Math.PI * 2;
            // More organic noise
            const noise = Math.sin(theta * 4 + time) * 3 + Math.cos(theta * 2 - time * 1.5) * 2; 
            const px = Math.cos(theta) * (r + noise);
            const py = Math.sin(theta) * (r + noise);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();

        // 2. Deep Base
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.8 * intensity;
        ctx.fill();

        // 3. Surface Ripples (Darker)
        ctx.globalCompositeOperation = 'multiply';
        ctx.beginPath();
        const rippleX = Math.sin(time) * 5;
        const rippleY = Math.cos(time * 0.8) * 5;
        ctx.ellipse(rippleX, rippleY, r * 0.6, r * 0.5, time*0.1, 0, Math.PI * 2);
        ctx.fill();

        // 4. Specular Highlights (Bubbles/Reflection)
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.5;

        const bX = Math.cos(time * 1.5) * r * 0.4;
        const bY = Math.sin(time * 1.5) * r * 0.4;
        ctx.beginPath(); ctx.ellipse(bX, bY, 6, 3, 0, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        // Use the factory generated cloud texture for better performance & look
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.0;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.15; // Very subtle

        const puffs = 3;
        for(let i=0; i<puffs; i++) {
            const angle = time * 0.2 + (i * Math.PI * 2 / puffs);
            const dist = 12 + Math.sin(time + i) * 6;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            // Breathe
            const pulse = 1.0 + Math.sin(time * 1.5 + i) * 0.1;
            const pSize = size * 0.5 * pulse;

            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }

        // Center Core
        ctx.globalAlpha = 0.2;
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;

        const staticRot = (x + y) * 0.1; // Consistent rotation based on position
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity;

        const visibleFaces = [5, 0, 1]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;

            const x1 = x + HEX_SIZE * HEX_COS[i];
            const y1 = HEX_SIZE * HEX_SIN[i] * ISO_SCALE_Y; 

            const x2 = x + HEX_SIZE * HEX_COS[j];
            const y2 = HEX_SIZE * HEX_SIN[j] * ISO_SCALE_Y; 

            // Gradient for 3D depth
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); // Fade into ground

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, topY + y1);
            ctx.lineTo(x2, topY + y2);
            ctx.lineTo(x2, bottomY + y2);
            ctx.lineTo(x1, bottomY + y1);
            ctx.closePath();
            ctx.fill();

            // Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            ctx.stroke();
            ctx.globalAlpha = opacity;
        }

        // Top Cap
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        this.traceHex(ctx, x, topY, HEX_SIZE);
        ctx.fill();

        // Rim
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        // Simple deterministic random
        const rnd = (offset: number) => {
            const v = Math.sin(seed + offset) * 1000;
            return v - Math.floor(v);
        };

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;

                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             // Circuit lines
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            // Generic
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        ctx.restore();
    },
};

import { createCanvas } from "./CanvasUtils";

const TEXTURE_SIZE = 64; 
const CENTER = TEXTURE_SIZE / 2;

class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Get visual texture. 
     */
    public getTexture(type: 'SHARD' | 'RUBBLE' | 'SPIKE' | 'SPARK' | 'SLASH' | 'CRACKS' | 'RING' | 'GLOW' | 'MAGIC_CIRCLE' | 'DUST' | 'PEBBLE' | 'ATMOSPHERE' | 'GENERIC_DEBUG' | 'SMOKE_PUFF' | 'SHOCKWAVE' | 'HEX_HALO' | 'HEX_PRISM' | 'HEX_RUNE' | 'HEX_LOCK', color: string): HTMLCanvasElement {
        // Alias mapping for backward compatibility
        if (type === 'DUST' || type === 'PEBBLE') return this.getTexture('RUBBLE', color);
        if (type === 'RING' || type === 'SHOCKWAVE_RING' as any) return this.getTexture('SHOCKWAVE', color); 

        const key = `${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const texture = this.bakeTexture(type, color);
        this.cache.set(key, texture);
        return texture;
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const texture = this.bakeProjectile(visual, color);
        this.cache.set(key, texture);
        return texture;
    }

    // --- HEXAGON HELPER ---
    private drawHexPath(ctx: CanvasRenderingContext2D, x: number, y: number, r: number) {
        ctx.beginPath();
        for (let i = 0; i < 6; i++) {
            // Pointy Topped Hexagon (matches game grid)
            // Angle starts at -90deg (Top) or 30deg (Corner)? 
            // Game grid uses: angle = (Math.PI / 6 + Math.PI / 4) + i * Math.PI / 3;
            // But for pure icons, standard pointy top is usually -PI/6 (30 deg) offset?
            // Let's stick to standard math for icons: Point at top (-PI/2)
            const angle = (Math.PI / 3) * i - Math.PI / 6; 
            const px = x + Math.cos(angle) * r;
            const py = y + Math.sin(angle) * r;
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }

    private bakeProjectile(visual: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;

        ctx.translate(cx, cy);

        // Intensified Glow / Halo for volumetric feel
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        if (visual === 'ARROW') {
            ctx.fillStyle = '#fff';
            ctx.strokeStyle = color;
            ctx.lineWidth = 3; 

            // Hex-Tip Arrow
            ctx.beginPath();
            ctx.moveTo(-40, 0); ctx.lineTo(20, 0);
            ctx.stroke();

            ctx.fillStyle = '#fff';
            this.drawHexPath(ctx, 30, 0, 10);
            ctx.fill();
        }
        else if (visual === 'BOLT') {
            // Energy Bolt - Elongated Hex
            const grad = ctx.createLinearGradient(-40, 0, 40, 0);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, '#fff');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(-40, 0);
            ctx.lineTo(0, -10);
            ctx.lineTo(40, 0);
            ctx.lineTo(0, 10);
            ctx.fill();
        }
        else if (visual === 'FIREBALL') {
            // Hex Core Ball
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, 30);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.4, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            this.drawHexPath(ctx, 0, 0, 25);
            ctx.fill();
        }
        else if (visual === 'SLASH') {
            // Crescent Wave
            const grad = ctx.createLinearGradient(0, -40, 0, 40);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');

            ctx.strokeStyle = grad;
            ctx.lineWidth = 6;
            ctx.lineCap = 'round';
            ctx.shadowBlur = 20;

            ctx.beginPath();
            ctx.arc(-10, 0, 40, -Math.PI/2.5, Math.PI/2.5);
            ctx.stroke();
        }
        else {
            // Generic Orb
            const grad = ctx.createRadialGradient(0, 0, 2, 0, 0, 15);
            grad.addColorStop(0, '#fff');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
        }

        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement {
        return this.getTexture('ATMOSPHERE', color);
    }

    public generateCracks(color: string): HTMLCanvasElement {
        return this.getTexture('CRACKS', color);
    }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const w = 128, h = 64;

        const grad = ctx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w/2);
        grad.addColorStop(0, color); 
        grad.addColorStop(0.6, color.replace(')', ', 0.4)').replace('rgb', 'rgba')); 
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        ctx.beginPath();
        // Use multiple overlapping hexes to create a "cloud"
        this.drawHexPath(ctx, w/2, h/2, 30);
        ctx.fill();
        this.drawHexPath(ctx, w/2-20, h/2, 20);
        ctx.fill();
        this.drawHexPath(ctx, w/2+20, h/2, 20);
        ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;

        ctx.translate(cx, cy);
        ctx.scale(1, 0.58); 

        const grad = ctx.createRadialGradient(0, 0, 20, 0, 0, 60);
        grad.addColorStop(0, 'rgba(255,255,255,0.8)');
        grad.addColorStop(0.2, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        this.drawHexPath(ctx, 0, 0, 55); // Hex blast
        ctx.fill();

        this.cache.set(key, canvas);
        return canvas;
    }

    // =========================================================================================
    // 🔨 VOLUMETRIC TEXTURE BAKING (HEXAGON EDITION)
    // =========================================================================================

    private bakeTexture(type: string, color: string): HTMLCanvasElement {
        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;

        ctx.translate(CENTER, CENTER);

        // 1. ATMOSPHERICS (Soft Balls -> Soft Hexes)
        if (type === 'ATMOSPHERE' || type === 'GLOW' || type === 'SMOKE_PUFF') {
            const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
            if (type === 'SMOKE_PUFF') {
                grad.addColorStop(0, color); 
                grad.addColorStop(0.4, color);
                grad.addColorStop(1, 'transparent');
            } else {
                grad.addColorStop(0, '#ffffff'); // Hot core
                grad.addColorStop(0.3, color);
                grad.addColorStop(1, 'transparent');
            }

            ctx.fillStyle = grad;
            // Soft blurred hex instead of circle
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            this.drawHexPath(ctx, 0, 0, r * 0.8); 
            ctx.fill();
            return canvas;
        }

        // 2. HARD DEBRIS (Shards)
        if (type === 'SHARD' || type === 'RUBBLE' || type === 'ROCK' || type === 'CHIP') {
            ctx.fillStyle = color;
            this.drawHexPath(ctx, 0, 0, r * 0.6); // Mini hexes
            ctx.fill();

            // Highlight facet
            ctx.fillStyle = 'rgba(255,255,255,0.3)';
            ctx.beginPath();
            ctx.moveTo(0,0);
            ctx.lineTo(r*0.4, -r*0.4);
            ctx.lineTo(-r*0.4, -r*0.4);
            ctx.fill();

            return canvas;
        }

        // 3. ENERGETIC BURSTS (Spikes -> Hex Stars)
        if (type === 'SPIKE' || type === 'SPARK') {
            ctx.fillStyle = color;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;

            // 6-Point Star (Two triangles/Hex variant)
            ctx.beginPath();
            const w = type === 'SPARK' ? r * 0.3 : r * 0.5;
            for(let i=0; i<6; i++) {
                const angle = i * Math.PI/3;
                ctx.lineTo(Math.cos(angle)*r, Math.sin(angle)*r); // Tip
                ctx.lineTo(Math.cos(angle + Math.PI/6)*w, Math.sin(angle + Math.PI/6)*w); // Valley
            }
            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = '#fff';
            ctx.beginPath(); ctx.arc(0,0, w*0.5, 0, Math.PI*2); ctx.fill();

            return canvas;
        }

        // 4. RINGS & WAVES (Hex Rings)
        if (type === 'SHOCKWAVE' || type === 'SHOCKWAVE_RING' as any || type === 'RING') {
            const grad = ctx.createRadialGradient(0, 0, r * 0.5, 0, 0, r);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');

            ctx.strokeStyle = grad;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;

            this.drawHexPath(ctx, 0, 0, r * 0.8);
            ctx.stroke();

            // Inner thin line
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            ctx.shadowBlur = 0;
            this.drawHexPath(ctx, 0, 0, r * 0.6);
            ctx.stroke();

            return canvas;
        }

        // 5. MAGIC CIRCLE (Magic Hexagon)
        if (type === 'MAGIC_CIRCLE') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.shadowColor = color;
            ctx.shadowBlur = 8;

            this.drawHexPath(ctx, 0, 0, r * 0.9);
            ctx.stroke();

            // Inner Rotated Hex
            ctx.save();
            ctx.rotate(Math.PI/6);
            ctx.strokeStyle = 'rgba(255,255,255,0.5)';
            ctx.lineWidth = 1;
            this.drawHexPath(ctx, 0, 0, r * 0.6);
            ctx.stroke();
            ctx.restore();

            return canvas;
        }

        // 6. CC: HEX HALO (Stun)
        if (type === 'HEX_HALO') {
            // Bright thick ring with gaps
            ctx.strokeStyle = color;
            ctx.lineWidth = 4;
            ctx.shadowColor = color;
            ctx.shadowBlur = 15;
            ctx.lineCap = 'round';

            // Broken Hex
            ctx.beginPath();
            for(let i=0; i<6; i++) {
                const angle = (Math.PI / 3) * i - Math.PI / 6;
                const px = Math.cos(angle) * r * 0.8;
                const py = Math.sin(angle) * r * 0.8;
                // Draw only segments
                if (i % 2 === 0) {
                    ctx.moveTo(px, py);
                    const nextAngle = (Math.PI / 3) * (i+1) - Math.PI / 6;
                    ctx.lineTo(Math.cos(nextAngle)*r*0.8, Math.sin(nextAngle)*r*0.8);
                }
            }
            ctx.stroke();
            return canvas;
        }

        // 7. CC: HEX PRISM (Banish) - Vertical bars texture
        if (type === 'HEX_PRISM') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.5;

            // Vertical scanlines clipped to hex
            ctx.beginPath();
            this.drawHexPath(ctx, 0, 0, r);
            ctx.clip();

            const grad = ctx.createLinearGradient(0, -r, 0, r);
            grad.addColorStop(0, 'transparent');
            grad.addColorStop(0.5, color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.fillRect(-r, -r, r*2, r*2);

            // Scanlines
            ctx.fillStyle = 'rgba(255,255,255,0.3)';
            for(let y=-r; y<r; y+=4) {
                ctx.fillRect(-r, y, r*2, 1);
            }

            return canvas;
        }

        // 8. CC: HEX LOCK (Silence)
        if (type === 'HEX_LOCK' || type === 'HEX_RUNE') {
            ctx.fillStyle = color;
            ctx.shadowColor = color;
            ctx.shadowBlur = 5;

            this.drawHexPath(ctx, 0, 0, r * 0.8);
            ctx.fill();

            // Subtract inner "X" or Rune
            ctx.globalCompositeOperation = 'destination-out';
            ctx.lineWidth = 6;
            ctx.lineCap = 'round';
            ctx.beginPath();
            ctx.moveTo(-10, -10); ctx.lineTo(10, 10);
            ctx.moveTo(10, -10); ctx.lineTo(-10, 10);
            ctx.stroke();

            return canvas;
        }

        // Default Fallback
        ctx.fillStyle = '#ff00ff';
        ctx.fillRect(-10, -10, 20, 20);
        return canvas;
    }
}

export const VFXFactory = new VFXTextureCache();

import { Agent } from "../../game";
import { Team } from "../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
