}

/**
 * NEW: 3D WIREFRAME HEX PRISM CONSTRUCTION
 */
function draw3DHexPrism(ctx: CanvasRenderingContext2D, t: number, color: string, height: number, radius: number) {
    const startAngle = Math.PI / 6 + Math.PI / 4;
    const r = radius;

    ctx.save();
    ctx.globalCompositeOperation = 'screen';

    // Pulse line width
    const pulse = 1.5 + Math.sin(t * 5) * 0.5;
    ctx.lineWidth = pulse;
    ctx.strokeStyle = color;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    // Vertices Cache
    const topVerts: {x: number, y: number}[] = [];
    const botVerts: {x: number, y: number}[] = [];

    // Calculate Isometric Vertices
    for(let i=0; i<6; i++) {
        const angle = startAngle + i * Math.PI / 3 + t * 0.5; // Rotate slowly
        const x = Math.cos(angle) * r;
        const y = Math.sin(angle) * r * ISO_SCALE_Y; // Flatten

        topVerts.push({x: x, y: y - height});
        botVerts.push({x: x, y: y});
    }

    // Draw Connections (Verticals)
    ctx.globalAlpha = 0.4;
    ctx.beginPath();
    for(let i=0; i<6; i++) {
        ctx.moveTo(topVerts[i].x, topVerts[i].y);
        ctx.lineTo(botVerts[i].x, botVerts[i].y);
    }
    ctx.stroke();

    // Draw Top Ring
    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.moveTo(topVerts[0].x, topVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(topVerts[i].x, topVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    // Draw Bottom Ring
    ctx.beginPath();
    ctx.moveTo(botVerts[0].x, botVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(botVerts[i].x, botVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    // Fill Volume (Subtle)
    const grad = ctx.createLinearGradient(0, -height, 0, 0);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(0.5, color);
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalAlpha = 0.15;
    ctx.fillStyle = grad;
    ctx.fill(); // Fills bottom ring path implicitly

    // Draw Top Cap Fill
    ctx.beginPath();
    ctx.moveTo(topVerts[0].x, topVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(topVerts[i].x, topVerts[i].y);
    ctx.closePath();
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.1;
    ctx.fill();

    ctx.restore();
}

/**
 * REFACTORED: Volumetric CC Visualization
 */
export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    let statusId = 'NONE';
    if (agent.banished) statusId = 'BANISH';
    else if (agent.stunTimer > 0) statusId = 'STUN';
    else if (agent.silenceTimer > 0) statusId = 'SILENCE';
    else if (agent.visualStatus !== 'NONE') statusId = agent.visualStatus;

    if (statusId === 'NONE') return;

    // --- 1. BANISH / STASIS: 3D Holographic Prison ---
    if (statusId === 'BANISH' || statusId === 'STASIS') {
        const color = statusId === 'STASIS' ? '#facc15' : '#c084fc';

        ctx.save();
        // Shift to feet for 3D construction
        ctx.translate(0, 0); 

        draw3DHexPrism(ctx, t, color, 120, 40);

        ctx.restore();
        return;
    }

    // --- 2. STUN: Double Spinning Hex Halo ---
    if (statusId === 'STUN') {
        const color = '#facc15';
        const halo = VFXFactory.getTexture('HEX_HALO', color);

        ctx.save();
        ctx.translate(0, -90); // Above head

        const float = Math.sin(t * 8) * 5;
        ctx.translate(0, float);

        ctx.globalCompositeOperation = 'screen';

        // Inner fast ring
        ctx.save();
        ctx.scale(1, 0.4); 
        ctx.rotate(t * 6); 
        const size1 = 50;
        ctx.globalAlpha = 0.9;
        ctx.drawImage(halo, -size1/2, -size1/2, size1, size1);
        ctx.restore();

        // Outer slow ring (Counter rotate)
        ctx.save();
        ctx.scale(1, 0.4);
        ctx.rotate(-t * 2); 
        const size2 = 80;
        ctx.globalAlpha = 0.6;
        ctx.drawImage(halo, -size2/2, -size2/2, size2, size2);
        ctx.restore();

        ctx.restore();
        return;
    }

    // --- 3. SILENCE: Floating Lock Rune ---
    if (statusId === 'SILENCE') {
        const color = '#94a3b8';
        const lock = VFXFactory.getTexture('HEX_LOCK', color);

        ctx.save();
        ctx.translate(0, -100); 

        const float = Math.sin(t * 3) * 3;
        ctx.translate(0, float);

        ctx.globalCompositeOperation = 'source-over';
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;

        const size = 40;
        ctx.drawImage(lock, -size/2, -size/2, size, size);

        ctx.restore();
        return;
    }

    // --- 4. POLYMORPH / FROZEN (Model Overrides) ---
    if (statusId === 'FROZEN') {
        const glow = VFXFactory.getTexture('GLOW', '#bae6fd');
        ctx.save();
        ctx.translate(0, -40);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -50, -50, 100, 100);
        ctx.restore();
    }
}

import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";
import { VFXFactory } from "../../graphics/VFXFactory";

// Helper: Get random number from Range [min, max] or number
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};

// Helper: Pick random color
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};

export class VFXPlayer {

    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string) {
        const asset = VFX_REGISTRY[effectId];

        if (!asset) {
            // console.warn(`VFXPlayer: Asset '${effectId}' not found.`);
            return;
        }

        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride);
        }
    }

    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string) {
        const count = Math.floor(rnd(config.count));

        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();

            // 1. Position & Velocity Calculation based on Shape
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = cz;
            const speed = rnd(config.speed);

            if (config.shape === 'POINT') {
                // No offset
            } 
            else if (config.shape === 'BURST_DIR') {
                // Omnidirectional Sphere Burst
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);

                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); // Bias upwards slightly
            }
            else if (config.shape === 'CIRCLE') {
                // Flat ring burst
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;

                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }

            // 2. Properties
            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;

            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);

            p.size = rnd(config.size);

            // Color priority: Override > Config
            p.color = colorOverride || pickColor(config.colors);

            // Type Casting (Ensure string matches Particle internal type)
            p.type = config.particleType as any;

            // Apply Visual Style if defined
            if (config.visualStyle) p.style = config.visualStyle;

            // Optional Physics Overrides
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.vRotation) p.vRotation = rnd(config.vRotation);
            else p.vRotation = (Math.random() - 0.5) * 10; // Default gentle rotation

            if (config.blendMode) p.blendMode = config.blendMode;

            // --- CRITICAL FIX: HYDRATE TEXTURE ---
            // Force load the high-quality Hexagon texture immediately.
            // This prevents the renderer from using the fallback "White Square" vector.
            if (!p.image && !['PILLAR', 'BEAM', 'HEX_BEAM', 'GRID_FIELD', 'DOMAIN'].includes(p.type)) {
                // We cast p.type to any because the Factory accepts specific string literals
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }

            // Push to System
            system.state.particles.push(p);
        }
    }
}

import { Particle } from "../state";
import { ISO_SCALE_Y } from "../../../../constants";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../data/vfx/procedural_visuals";

// Helper for hex tracing (used by procedural beams)
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS_X: number[] = [];
const HEX_CORNERS_Y: number[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS_X.push(Math.cos(angle));
    HEX_CORNERS_Y.push(Math.sin(angle));
}
function traceHexagonFast(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    ctx.moveTo(HEX_CORNERS_X[0] * r, HEX_CORNERS_Y[0] * r);
    for (let i = 1; i < 6; i++) ctx.lineTo(HEX_CORNERS_X[i] * r, HEX_CORNERS_Y[i] * r);
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean) {
        ctx.save();
        ctx.translate(drawX, drawY);

        const now = Date.now() / 1000;

        // --- 1. PERSPECTIVE CORRECTION (THE 2.5D RULE) ---
        const isGroundEffect = ['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'DOMAIN', 'MAGIC_CIRCLE'].includes(p.type);
        if (isGroundEffect) {
            ctx.scale(1, ISO_SCALE_Y); 
        }

        ctx.rotate(p.rotation);

        // --- 2. BLEND MODES ---
        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'CHIP'].includes(p.type)) {
                 ctx.globalCompositeOperation = 'source-over'; 
            } else if (['SMOKE', 'SMOKE_PUFF', 'ATMOSPHERE'].includes(p.type)) {
                 ctx.globalCompositeOperation = 'screen';      
            } else {
                 ctx.globalCompositeOperation = 'screen';      
            }
        }

        // --- 3. RENDERING ---

        // A. PROCEDURAL COMPLEX SHAPES (Beams, Pillars, Domains)
        if (['BEAM', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'GRID_FIELD', 'DOMAIN', 'DEATH_RAY'].includes(p.type)) {
            this.drawProcedural(ctx, p, progress, isChaos, now);
        }
        // B. TEXTURE BASED (Everything else)
        else {
            // Safety Net: If image missing, try fetch one last time
            if (!p.image && !p.texture) {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }

            const img = p.image || p.texture;

            if (img) {
                this.drawTexture(ctx, img, p.size, progress, p.type);
            } else {
                // LAST RESORT: Simple Circle (No Squares allowed!)
                const s = p.size * (1 - progress);
                ctx.fillStyle = p.color;
                ctx.beginPath(); ctx.arc(0, 0, s, 0, Math.PI*2); ctx.fill();
            }
        }

        ctx.restore();
    },

    drawTexture(ctx: CanvasRenderingContext2D, img: HTMLCanvasElement, baseSize: number, progress: number, type: string) {
        let scale = 1.0;
        let alpha = 1.0 - progress;

        if (type === 'SHOCKWAVE' || type === 'RING') {
            scale = 0.5 + progress * 2.0;
            alpha = 1.0 - Math.pow(progress, 3);
        } else if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            scale = 0.8 + progress * 1.2;
            alpha = (1.0 - progress) * 0.5; 
        } else {
            scale = 1.0 - Math.pow(progress, 2);
        }

        const drawSize = baseSize * scale;
        ctx.globalAlpha = Math.max(0, Math.min(1, alpha));

        // Shadow for solid objects
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            // Draw a hex shadow instead of circle
            traceHexagonFast(ctx, drawSize * 0.5);
            ctx.fill();
            ctx.restore();
        }

        ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
    },

    drawProcedural(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean, now: number) {

        if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
             if (p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.targetX;
                const dy = p.targetY; 

                ctx.beginPath();
                ctx.moveTo(0,0);
                ctx.lineTo(dx, dy - (p.targetZ || 0));
                ctx.strokeStyle = p.color;
                ctx.lineWidth = p.size * (1-progress) * 1.5; 
                ctx.lineCap = 'round';
                ctx.shadowColor = p.color;
                ctx.shadowBlur = 15;
                ctx.globalCompositeOperation = 'screen';
                ctx.stroke();

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = p.size * (1-progress) * 0.4;
                ctx.shadowBlur = 0;
                ctx.stroke();
             }
        }
        else if (p.type === 'HEX_BEAM' || p.type === 'GIANT_HEX') {
            ctx.scale(1, ISO_SCALE_Y);
            // Spin effect
            if (p.vRotation) ctx.rotate(p.vRotation * now);

            ctx.globalCompositeOperation = 'screen';

            const grad = ctx.createRadialGradient(0,0,0,0,0,p.size);
            grad.addColorStop(0, p.color); 
            grad.addColorStop(0.8, p.color);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalAlpha = (1 - progress) * 0.8;
            traceHexagonFast(ctx, p.size); ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1 - progress;
            traceHexagonFast(ctx, p.size * 0.9); ctx.stroke();
        }
        else if (p.type === 'PILLAR') {
            // ... (Pillar logic remains valid)
            const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
            const def = rawDef as PillarVisualDef;
            const h = def.height || 1200; 
            const width = p.size * (1 - progress * 0.5) * (def.widthScale || 1.0);

            ctx.save();
            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            const cylinderGrad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
            cylinderGrad.addColorStop(0, p.color); 
            cylinderGrad.addColorStop(0.5, '#ffffff'); 
            cylinderGrad.addColorStop(1, p.color); 

            ctx.fillStyle = cylinderGrad;
            ctx.globalAlpha = (1 - progress) * 0.8;

            ctx.fillRect(-width/2, -h, width, h);

            if (def.hasBaseRing) {
                ctx.scale(1, ISO_SCALE_Y);
                const ringGrad = ctx.createRadialGradient(0,0, width*0.5, 0,0, width*1.2);
                ringGrad.addColorStop(0, 'transparent');
                ringGrad.addColorStop(0.5, p.color);
                ringGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = ringGrad;
                ctx.beginPath(); ctx.arc(0, 0, width*1.5, 0, Math.PI*2); ctx.fill();
            }
            ctx.restore();
        }
        else if (p.type === 'DOMAIN' || p.type === 'GRID_FIELD') {
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 

            const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.7, p.color); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.4 * (1 - progress);
            ctx.globalCompositeOperation = 'screen';
            // Use Hex shape for domains too!
            traceHexagonFast(ctx, r); ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.2;
            traceHexagonFast(ctx, r * 0.9); ctx.stroke();

            ctx.restore();
        }
    }
};

