export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.deathSpiritColor; 

    ctx.save();
    const grad = ctx.createLinearGradient(0, 0, 0, physZ);
    grad.addColorStop(0, 'rgba(0,0,0,0)'); 
    grad.addColorStop(0.5, color);        
    grad.addColorStop(1, 'rgba(0,0,0,0)'); 

    ctx.globalAlpha = 0.3 + Math.sin(t * 5) * 0.1;
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;

    const w = 4;
    ctx.fillRect(-w/2, 0, w, physZ);

    ctx.translate(0, physZ);
    ctx.scale(1, ISO_SCALE_Y); 

    const glow = VFXFactory.getTexture('GLOW', color);
    const sz = 32;
    ctx.drawImage(glow, -sz/2, -sz/2, sz, sz);

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.flightTrailColor;
    const glow = VFXFactory.getTexture('GLOW', color);

    ctx.save();
    ctx.translate(0, 10); 

    for(let i = -1; i <= 1; i += 2) {
        ctx.save();
        const offsetX = i * 10;
        const pulse = Math.sin(t * 20 + i) * 0.2 + 0.8;
        ctx.translate(offsetX, 0);
        ctx.scale(0.5 * pulse, 1.0 * pulse);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -16, 0, 32, 48); 
        ctx.restore();
    }
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -50); 

    const ring = VFXFactory.getTexture('HEX_HALO', color);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.8 * progress;

    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(t * 3); 
    const size = 64 * (0.8 + progress * 0.2);
    ctx.drawImage(ring, -size/2, -size/2, size, size);
    ctx.restore();

    const glow = VFXFactory.getTexture('GLOW', color);
    const coreSize = 32 * progress;
    ctx.drawImage(glow, -coreSize/2, -coreSize/2, coreSize, coreSize);

    ctx.restore();

    // If AOE, draw ground expansion
    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    // Large Ground Ripple
    const texture = VFXFactory.getTexture('SHOCKWAVE', color); 
    ctx.save();
    // Move to feet (ctx is currently at body center usually, depends on caller. 
    // Usually caller sets context to unit logical pos + physics. 
    // We want feet level. Logic: -BodyOffset?)
    // Actually drawAssembly translates to unit center.
    // Let's assume 0,0 is unit anchor.

    ctx.translate(0, UNIT_BODY_OFFSET); // Move down to feet level roughly
    ctx.scale(1, ISO_SCALE_Y); 

    // Scale up massively
    const scale = (0.5 + progress * 2.5) * 4.0; 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = (1 - progress) * 0.3; // Fade as it gets huge

    const size = 64 * scale;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // 1. Magic Circle (Spinning)
    const texture = VFXFactory.getTexture('MAGIC_CIRCLE', color);
    ctx.save();
    ctx.translate(0, -60); 
    const rot = t * (2 + progress * 5);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.6 + progress * 0.4;
    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(rot);
    const size = 120;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();

    // 2. Rising Energy
    const glow = VFXFactory.getTexture('GLOW', color);
    ctx.globalAlpha = 0.5 * progress;
    ctx.scale(0.5, 1.5); 
    ctx.drawImage(glow, -40, -40 - (progress * 50), 80, 80);
    ctx.restore();

    // 3. RESTORED: Domain Expansion (Ground Aura)
    // Moves to feet and expands a huge volumetric hex
    ctx.save();
    ctx.translate(0, 40); // Move to ground relative to center

    // Pulse expansion
    const domainSize = 200 * progress;
    SurfaceAssets.drawVolumetricHex(ctx, 0, 0, domainSize, color, 0.3 * progress);

    // Sharp Ring
    ctx.scale(1, ISO_SCALE_Y);
    ctx.beginPath();
    ctx.arc(0, 0, domainSize * 1.5, 0, Math.PI * 2);
    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.globalAlpha = 0.2 * progress;
    ctx.stroke();

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    const pixelRadius = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = pixelRadius * progress;
    const opacity = 0.3 + Math.sin(t * 5) * 0.1;

    SurfaceAssets.drawVolumetricHex(ctx, 0, 0, currentRadius, color, opacity);

    const ringSize = currentRadius * 2.5; 
    const ring = VFXFactory.getTexture('RING', color);

    ctx.save();
    ctx.scale(1, ISO_SCALE_Y); 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = opacity * 1.2;
    ctx.drawImage(ring, -ringSize/2, -ringSize/2, ringSize, ringSize);
    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);
            const bg = VFXFactory.getTexture('GLOW', skill.color);
            ctx.globalAlpha = 0.6;
            ctx.globalCompositeOperation = 'screen';
            ctx.drawImage(bg, -30, -30, 60, 60);
            ctx.restore();
        }
    }
}

function draw3DHexPrism(ctx: CanvasRenderingContext2D, t: number, color: string, height: number, radius: number) {
    const startAngle = Math.PI / 6 + Math.PI / 4;
    const r = radius;

    ctx.save();
    ctx.globalCompositeOperation = 'screen';

    // Animate width
    const pulse = 2 + Math.sin(t * 5) * 1.0;
    ctx.lineWidth = pulse;
    ctx.strokeStyle = color;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const topVerts: {x: number, y: number}[] = [];
    const botVerts: {x: number, y: number}[] = [];

    for(let i=0; i<6; i++) {
        const angle = startAngle + i * Math.PI / 3 + t * 0.5; 
        const x = Math.cos(angle) * r;
        const y = Math.sin(angle) * r * ISO_SCALE_Y;

        topVerts.push({x: x, y: y - height});
        botVerts.push({x: x, y: y});
    }

    ctx.globalAlpha = 0.4;
    ctx.beginPath();
    for(let i=0; i<6; i++) {
        ctx.moveTo(topVerts[i].x, topVerts[i].y);
        ctx.lineTo(botVerts[i].x, botVerts[i].y);
    }
    ctx.stroke();

    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.moveTo(topVerts[0].x, topVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(topVerts[i].x, topVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(botVerts[0].x, botVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(botVerts[i].x, botVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    const grad = ctx.createLinearGradient(0, -height, 0, 0);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(0.5, color);
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalAlpha = 0.2; // Increased visibility
    ctx.fillStyle = grad;
    ctx.fill();

    ctx.restore();
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    let statusId = 'NONE';
    if (agent.banished) statusId = 'BANISH';
    else if (agent.stunTimer > 0) statusId = 'STUN';
    else if (agent.silenceTimer > 0) statusId = 'SILENCE';
    else if (agent.visualStatus !== 'NONE') statusId = agent.visualStatus;

    if (statusId === 'NONE') return;

    if (statusId === 'BANISH' || statusId === 'STASIS') {
        const color = statusId === 'STASIS' ? '#facc15' : '#c084fc';
        ctx.save();
        ctx.translate(0, 0); 
        draw3DHexPrism(ctx, t, color, 120, 45); 
        ctx.restore();
        return;
    }

    if (statusId === 'STUN') {
        const color = '#facc15';
        const halo = VFXFactory.getTexture('HEX_HALO', color);
        ctx.save();
        ctx.translate(0, -90); 
        const float = Math.sin(t * 8) * 5;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'screen';
        ctx.save();
        ctx.scale(1, 0.4); 
        ctx.rotate(t * 6); 
        const size1 = 60; 
        ctx.globalAlpha = 1.0; 
        ctx.drawImage(halo, -size1/2, -size1/2, size1, size1);
        ctx.restore();
        ctx.save();
        ctx.scale(1, 0.4);
        ctx.rotate(-t * 2); 
        const size2 = 90; 
        ctx.globalAlpha = 0.7;
        ctx.drawImage(halo, -size2/2, -size2/2, size2, size2);
        ctx.restore();
        ctx.restore();
        return;
    }

    if (statusId === 'SILENCE') {
        const color = '#94a3b8';
        const lock = VFXFactory.getTexture('HEX_LOCK', color);
        ctx.save();
        ctx.translate(0, -100); 
        const float = Math.sin(t * 3) * 3;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'source-over';
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        const pulse = 1 + Math.sin(t * 5) * 0.1;
        const size = 48 * pulse; 
        ctx.drawImage(lock, -size/2, -size/2, size, size);
        ctx.restore();
        return;
    }

    if (statusId === 'FROZEN') {
        const glow = VFXFactory.getTexture('GLOW', '#bae6fd');
        ctx.save();
        ctx.translate(0, -40);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -50, -50, 100, 100);
        ctx.restore();
    }
}

import { GameEvent, Team, Role } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import { SpriteManager } from "../../sprites";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";

// Architects
import { UltArchitect } from "./UltArchitect";
import { SkillArchitect } from "./SkillArchitect";

interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        const groundZ = grid.getTerrainHeight(
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).q,
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).r,
            engine
        );

        if (!event.targetId) target.z = groundZ + 20;

        switch (event.type) {
            case 'VISUAL_SLASH':
                // Delegate to Skill Architect first if skill ID matches
                if (event.skill && SkillArchitect.play(event.skill.id, target, engine, vfx, grid, camera, event.sourceId)) {
                    return;
                }
                // Fallback
                if (event.sourceId && event.targetId) {
                    vfx.playBeam('SLASH_CONNECT', origin, target, event.color || '#fff', 0.2);
                }
                break;

            case 'VISUAL_BEAM':
                // Check Ult First
                if (event.skill && event.skill.tag === 'ULT') {
                     if (UltArchitect.play(event.skill.id, target, engine, vfx, grid, camera, event.sourceId)) return;
                }
                // Check Skill Second
                if (event.skill && SkillArchitect.play(event.skill.id, target, engine, vfx, grid, camera, event.sourceId)) return;

                // Fallback Generic
                vfx.playBeam('GENERIC_BEAM', origin, target, event.color || '#fff', 0.4);
                this.resolveImpact(event, engine, vfx, target, false); 
                break;

            case 'DAMAGE': 
                if (!event.skill?.projectileSpeed) {
                    this.resolveImpact(event, engine, vfx, target, true);
                }
                break;

            case 'PROJECTILE_HIT': 
                // Only play impact if not AOE (AOE handles its own impact via IMPACT_AOE event)
                if (event.skill?.type !== 'AOE') {
                    this.resolveImpact(event, engine, vfx, target, true);
                    camera.addTrauma(0.05); 
                } else {
                    // Small hit for AOE direct hit (redundant but adds juice)
                    vfx.playEffect('FX_HIT_GENERIC', event.pos.x, event.pos.y, groundZ + 5, event.skill?.color);
                }
                break;

            case 'IMPACT_AOE':
                this.handleAOE(event, engine, vfx, grid, camera, groundZ);
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    this.spawnUnitShatter(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
                }
                camera.addTrauma(0.1); 
                break;

            case 'SPAWN':
                vfx.playEffect('FX_TELEPORT', origin.x, origin.y, origin.z, event.color);
                break;

            case 'CAST_BREAK':
                // Standard Break
                vfx.playEffect('FX_CAST_BREAK', origin.x, origin.y, origin.z, event.color);

                // --- RESTORED: DOMAIN SHATTER FOR ULTS ---
                if (event.skill && event.skill.tag === 'ULT') {
                    // Spawn extra large shards to simulate the domain breaking
                    for(let i=0; i<8; i++) {
                        const p = vfx.state.getParticle();
                        p.x = origin.x + (Math.random()-0.5)*50;
                        p.y = origin.y + (Math.random()-0.5)*50;
                        p.z = origin.z + 50;
                        p.vx = (Math.random()-0.5) * 600;
                        p.vy = (Math.random()-0.5) * 600;
                        p.vz = 400 + Math.random() * 400;
                        p.life = 1.0; p.maxLife = 1.0;
                        p.color = event.color || '#fff';
                        p.size = 20 + Math.random() * 30; // Big chunks
                        p.type = 'SHARD'; 
                        p.gravity = 1500;
                        vfx.state.particles.push(p);
                    }
                    camera.addTrauma(0.4); // Significant impact for stopping an Ult
                } else {
                    camera.addTrauma(0.15); 
                }
                break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        if (!agent && !agentId) {
            const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
            agent = engine.getAgentAt(hex.q, hex.r);
        }

        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);
        return { x: defaultX, y: defaultY, z: terrainH };
    }

    private resolveImpact(event: GameEvent, engine: GameEngine, vfx: VFXSystem, target: Point3D, checkScript: boolean) {
        const skill = event.skill;
        const color = event.color || '#fff';

        // 1. Script Override (Ult or Skill)
        if (checkScript && skill) {
            if (skill.tag === 'ULT' && UltArchitect.play(skill.id, target, engine, vfx, engine.renderer!.grid, engine.renderer!.camera, event.sourceId)) return;
            if (SkillArchitect.play(skill.id, target, engine, vfx, engine.renderer!.grid, engine.renderer!.camera, event.sourceId)) return;
        }

        // 2. Data-Driven Override
        if (skill && skill.visualHitEffect && VFX_REGISTRY[skill.visualHitEffect]) {
            vfx.playEffect(skill.visualHitEffect, target.x, target.y, target.z, color);
            return;
        }

        // 3. Fallback to Generic
        vfx.playEffect('FX_HIT_GENERIC', target.x, target.y, target.z, color);
    }

    private handleAOE(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, camera: CameraSystem, groundZ: number) {
        if (!event.skill) return;
        const centerPt = { x: event.pos.x, y: event.pos.y, z: groundZ + 5 };

        // 1. Script Check
        if (UltArchitect.play(event.skill.id, centerPt, engine, vfx, grid, camera, event.sourceId)) return;
        if (SkillArchitect.play(event.skill.id, centerPt, engine, vfx, grid, camera, event.sourceId)) return;

        // 2. Default AOE Visuals
        this.resolveImpact(event, engine, vfx, centerPt, false);
        camera.addTrauma(0.2);
    }

    private spawnUnitShatter(system: VFXSystem, x: number, y: number, z: number, team: Team, role: Role, impulseX: number, impulseY: number) {
        // ... (Existing shatter logic remains good)
        const assets = SpriteManager.getUnitImages(role, team);
        const factionConfig = FACTION_VISUALS[team] || FACTION_VISUALS[Team.BLUE];

        const base = system.state.getParticle();
        base.x = x; base.y = y; base.z = z + 10;
        base.vx = impulseX * 0.8; base.vy = impulseY * 0.8; base.vz = 150 + Math.random() * 100;
        base.life = 2.0; base.maxLife = 2.0;
        base.color = '#fff'; base.size = 50; 
        base.type = 'SPRITE'; base.image = assets.base;
        base.vRotation = (Math.random() - 0.5) * 10;
        system.state.particles.push(base);

        const icon = system.state.getParticle();
        icon.x = x; icon.y = y; icon.z = z + 40; 
        icon.vx = impulseX * 1.2; icon.vy = impulseY * 1.2; icon.vz = 300 + Math.random() * 200;
        icon.life = 2.0; icon.maxLife = 2.0;
        icon.color = '#fff'; icon.size = 64; 
        icon.type = 'SPRITE'; icon.image = assets.icon;
        icon.vRotation = (Math.random() - 0.5) * 20; 
        system.state.particles.push(icon);

        const shardCount = 8;
        const colors = factionConfig.deathShatterColors;
        for(let i=0; i<shardCount; i++) {
            const p = system.state.getParticle();
            p.x = x + (Math.random()-0.5)*20; p.y = y + (Math.random()-0.5)*20; p.z = z + 30;
            const a = Math.random() * Math.PI * 2;
            const s = 150 + Math.random() * 250;
            p.vx = Math.cos(a)*s + impulseX*0.5; p.vy = Math.sin(a)*s + impulseY*0.5; p.vz = 250 + Math.random()*250; 
            p.life = 1.5; p.maxLife = 1.5;
            p.type = 'SHARD'; p.color = colors[Math.floor(Math.random() * colors.length)];
            p.size = 6 + Math.random()*8; 
            p.vRotation = (Math.random()-0.5)*30; 
            system.state.particles.push(p);
        }
    }
}

