            const bg = VFXFactory.getTexture('GLOW', skill.color);
            ctx.globalAlpha = 0.6;
            ctx.globalCompositeOperation = 'screen';
            ctx.drawImage(bg, -30, -30, 60, 60);
            ctx.restore();
        }
    }
}

function draw3DHexPrism(ctx: CanvasRenderingContext2D, t: number, color: string, height: number, radius: number) {
    const startAngle = Math.PI / 6 + Math.PI / 4;
    const r = radius;

    ctx.save();
    ctx.globalCompositeOperation = 'screen';

    // Animate width
    const pulse = 2 + Math.sin(t * 5) * 1.0;
    ctx.lineWidth = pulse;
    ctx.strokeStyle = color;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const topVerts: {x: number, y: number}[] = [];
    const botVerts: {x: number, y: number}[] = [];

    for(let i=0; i<6; i++) {
        const angle = startAngle + i * Math.PI / 3 + t * 0.5; 
        const x = Math.cos(angle) * r;
        const y = Math.sin(angle) * r * ISO_SCALE_Y;

        topVerts.push({x: x, y: y - height});
        botVerts.push({x: x, y: y});
    }

    ctx.globalAlpha = 0.4;
    ctx.beginPath();
    for(let i=0; i<6; i++) {
        ctx.moveTo(topVerts[i].x, topVerts[i].y);
        ctx.lineTo(botVerts[i].x, botVerts[i].y);
    }
    ctx.stroke();

    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.moveTo(topVerts[0].x, topVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(topVerts[i].x, topVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(botVerts[0].x, botVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(botVerts[i].x, botVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    const grad = ctx.createLinearGradient(0, -height, 0, 0);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(0.5, color);
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalAlpha = 0.2; // Increased visibility
    ctx.fillStyle = grad;
    ctx.fill();

    ctx.restore();
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    let statusId = 'NONE';
    if (agent.banished) statusId = 'BANISH';
    else if (agent.stunTimer > 0) statusId = 'STUN';
    else if (agent.silenceTimer > 0) statusId = 'SILENCE';
    else if (agent.visualStatus !== 'NONE') statusId = agent.visualStatus;

    if (statusId === 'NONE') return;

    if (statusId === 'BANISH' || statusId === 'STASIS') {
        const color = statusId === 'STASIS' ? '#facc15' : '#c084fc';
        ctx.save();
        ctx.translate(0, 0); 
        draw3DHexPrism(ctx, t, color, 120, 45); 
        ctx.restore();
        return;
    }

    if (statusId === 'STUN') {
        const color = '#facc15';
        const halo = VFXFactory.getTexture('HEX_HALO', color);
        ctx.save();
        ctx.translate(0, -90); 
        const float = Math.sin(t * 8) * 5;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'screen';
        ctx.save();
        ctx.scale(1, 0.4); 
        ctx.rotate(t * 6); 
        const size1 = 60; 
        ctx.globalAlpha = 1.0; 
        ctx.drawImage(halo, -size1/2, -size1/2, size1, size1);
        ctx.restore();
        ctx.save();
        ctx.scale(1, 0.4);
        ctx.rotate(-t * 2); 
        const size2 = 90; 
        ctx.globalAlpha = 0.7;
        ctx.drawImage(halo, -size2/2, -size2/2, size2, size2);
        ctx.restore();
        ctx.restore();
        return;
    }

    if (statusId === 'SILENCE') {
        const color = '#94a3b8';
        const lock = VFXFactory.getTexture('HEX_LOCK', color);
        ctx.save();
        ctx.translate(0, -100); 
        const float = Math.sin(t * 3) * 3;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'source-over';
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        const pulse = 1 + Math.sin(t * 5) * 0.1;
        const size = 48 * pulse; 
        ctx.drawImage(lock, -size/2, -size/2, size, size);
        ctx.restore();
        return;
    }

    if (statusId === 'FROZEN') {
        const glow = VFXFactory.getTexture('GLOW', '#bae6fd');
        ctx.save();
        ctx.translate(0, -40);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -50, -50, 100, 100);
        ctx.restore();
    }
}

export interface Particle {
    active: boolean; 

    // Position (World Space - Ground Plane)
    x: number;
    y: number;
    z: number; // Current visual Z (height offset)

    // Physics
    vx: number;
    vy: number;
    vz: number;

    rotation: number;     
    vRotation: number;    

    life: number;
    maxLife: number;
    color: string;
    size: number;

    // Added RUBBLE, SPIKE, DUST, ATMOSPHERE, GENERIC_DEBUG
    type: 'SPARK' | 'SMOKE' | 'GLOW' | 'DEBRIS' | 'SHARD' | 'BEAM' | 'SHOCKWAVE' | 'PILLAR' | 'DOMAIN' | 'SPRITE' | 'BLAST' | 'CHIP' | 'GRID_FIELD' | 'DEATH_RAY' | 'ROCK' | 'HEX_LOCK' | 'HEX_BEAM' | 'GIANT_HEX' | 'HEX_GLOW' | 'STREAK' | 'RING' | 'CRACKS' | 'PEBBLE' | 'RUBBLE' | 'SPIKE' | 'DUST' | 'ATMOSPHERE' | 'GENERIC_DEBUG';

    // 🎯 BEAM TARGETING (Explicit 3D Anchors)
    sx?: number; sy?: number; sz?: number; 
    tx?: number; ty?: number; tz?: number; 

    targetX?: number; 
    targetY?: number; 
    targetZ?: number; 

    style?: string; 
    delay?: number;
    image?: HTMLCanvasElement; 
    locked?: boolean; 
    drag?: number;
    gravity?: number; // Override default gravity    
    killAtTarget?: number; 
    texture?: HTMLCanvasElement; 
    blendMode?: GlobalCompositeOperation; 
    sortBias?: number; 
}

export interface Decal {
    x: number;
    y: number;
    color: string;
    life: number;
    scale: number;
}

export class VFXStateManager {
    public particles: Particle[] = [];
    public decals: Decal[] = [];

    // Object Pool
    private particlePool: Particle[] = [];

    public getParticle(): Particle {
        if (this.particlePool.length > 0) {
            const p = this.particlePool.pop()!;
            // Reset Properties
            p.active = true;
            p.x = 0; p.y = 0; p.z = 0;
            p.vx = 0; p.vy = 0; p.vz = 0;
            p.rotation = 0; p.vRotation = 0;
            p.life = 0; p.maxLife = 0;
            p.color = '#ff00ff'; p.size = 0;
            p.type = 'GENERIC_DEBUG'; // Distinctive default

            p.sx = undefined; p.sy = undefined; p.sz = undefined;
            p.tx = undefined; p.ty = undefined; p.tz = undefined;

            p.targetX = undefined;
            p.targetY = undefined;
            p.targetZ = undefined;

            p.image = undefined; 
            p.texture = undefined;
            p.blendMode = undefined;
            p.style = undefined; 

            p.delay = 0; 
            p.locked = false; 
            p.sortBias = 0; 
            p.drag = undefined; 
            p.gravity = undefined;
            p.killAtTarget = undefined; 

            return p;
        }
        return { 
            active: true,
            x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, 
            rotation: 0, vRotation: 0,
            life: 0, maxLife: 0, color: '#ff00ff', size: 0, type: 'GENERIC_DEBUG',
            delay: 0,
            locked: false,
            sortBias: 0
        };
    }

    public releaseParticle(p: Particle) {
        p.active = false;
        p.image = undefined;
        p.texture = undefined;
        this.particlePool.push(p);
    }

    public reset() {
        while (this.particles.length > 0) {
            const p = this.particles.pop();
            if (p) this.releaseParticle(p);
        }
        this.decals.length = 0;
    }
}

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";

const GRAVITY = 1800; 

// Interface for 3D points
interface Point3D { x: number; y: number; z: number; }

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambientTimer: number = 0;

    public reset() {
        this.state.reset();
        this.ambientTimer = 0;
    }

    /**
     * Play a particle effect from the registry
     */
    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride);
    }

    /**
     * Play a beam effect between two points
     */
    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();

        // 3D Anchors
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

        // Sorting Key (Start Point)
        p.x = start.x; p.y = start.y; p.z = start.z;

        p.life = duration; 
        p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; 
        p.style = styleId; // Generic Style Key
        p.locked = true;

        this.state.particles.push(p);
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // --- V2.0 PHYSICS LOCK ---
            // Locked particles are purely visual/kinematic (controlled by spawner or static)
            if (p.locked) {
                p.rotation += p.vRotation * dt;
                continue; 
            }

            // --- KILL AT TARGET ---
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) {
                    p.life = 0; 
                }
            }

            // --- PHYSICS UPDATE ---
            const isPhysical = p.type === 'DEBRIS' || p.type === 'SHARD' || p.type === 'SPRITE' || p.type === 'ROCK' || p.type === 'CHIP';

            if (isPhysical) {
                // IMPORTANT: Fetch dynamic terrain height for this particle's location
                let groundH = getTerrainHeight ? getTerrainHeight(p.x, p.y) : 0;

                // Apply Gravity to Z (Height)
                const g = p.gravity !== undefined ? p.gravity : GRAVITY;
                p.vz -= g * dt;

                // Integrate
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                // Floor Collision
                if (p.z < groundH) {
                    p.z = groundH;
                    if (Math.abs(p.vz) > 100) {
                        p.vz = -p.vz * 0.5; // Bounce
                        p.vx *= 0.6; 
                        p.vy *= 0.6;
                        p.vRotation *= 0.5;
                    } else {
                        // Resting
                        p.vz = 0;
                        p.vx *= 0.1; 
                        p.vy *= 0.1;
                        p.vRotation = 0;
                        p.z = groundH; // Snap
                    }
                }
            } else {
                // Weightless / Atmospheric
                p.x += p.vx * dt;
                p.y += p.vy * dt;
                p.z += p.vz * dt;
                p.rotation += p.vRotation * dt;

                if (p.drag !== undefined) {
                    const dragFactor = 1 - p.drag; 
                    p.vx *= dragFactor;
                    p.vy *= dragFactor;
                    p.vz *= dragFactor;
                } else if (p.type === 'SPARK' || p.type === 'SMOKE') {
                    p.vx *= 0.90; 
                    p.vy *= 0.90;
                    p.vz *= 0.90; 
                } else if (p.type === 'ATMOSPHERE' || p.type === 'GLOW') {
                    // Float
                    p.vx += Math.sin(globalTime * 2 + p.x) * 50 * dt;
                    p.vy += Math.cos(globalTime * 2 + p.y) * 50 * dt;
                }
            }
        }

        // Update Decals
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                this.state.decals.splice(i, 1);
            }
        }

        this.updateAmbient(dt, ambientType);
    }

    private updateAmbient(dt: number, type: string) {
        if (type === 'NONE') return;
        this.ambientTimer += dt;
        const rate = type === 'SNOW' || type === 'ASH' ? 0.05 : 0.2; 

        if (this.ambientTimer > rate) {
            this.ambientTimer = 0;
            const x = Math.random() * 1200 - 100;
            const y = Math.random() * 800 - 100;

            const p = this.state.getParticle();
            p.x = x; p.y = y; p.z = Math.random() * 200 + 50;
            p.type = 'ATMOSPHERE'; // Replaces generic GLOW

            if (type === 'SNOW') {
                p.color = '#fff';
                p.size = Math.random() * 3 + 1;
                p.vx = 20 + Math.random() * 20;
                p.vy = 50 + Math.random() * 30;
                p.life = 3.0; p.maxLife = 3.0;
                p.blendMode = 'source-over'; // Opaque flakes
            } else if (type === 'ASH') {
                p.color = '#78350f';
                p.size = Math.random() * 4 + 1;
                p.vx = 30 + Math.random() * 30;
                p.vy = 20 + Math.random() * 20;
                p.life = 4.0; p.maxLife = 4.0;
                p.blendMode = 'source-over';
            } else if (type === 'EMBER') {
                p.color = '#fbbf24';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 20;
                p.vy = -30 - Math.random() * 20;
                p.life = 2.0; p.maxLife = 2.0;
                p.blendMode = 'screen'; // Glowing but not additive blowout
            } else if (type === 'SPORES') {
                p.color = Math.random() > 0.5 ? '#bef264' : '#a855f7';
                p.size = Math.random() * 2 + 1;
                p.vx = (Math.random() - 0.5) * 10;
                p.vy = (Math.random() - 0.5) * 10;
                p.life = 5.0; p.maxLife = 5.0;
                p.blendMode = 'screen';
            }
            this.state.particles.push(p);
        }
    }
}

import { Particle } from "../state";
import { ISO_SCALE_Y } from "../../../../constants";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { PROCEDURAL_VISUALS, PillarVisualDef } from "../../../../data/vfx/procedural_visuals";

// Helper for hex tracing (used by procedural beams)
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_CORNERS_X: number[] = [];
const HEX_CORNERS_Y: number[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_CORNERS_X.push(Math.cos(angle));
    HEX_CORNERS_Y.push(Math.sin(angle));
}

// Fixed Trace (Static)
function traceHexagonFast(ctx: CanvasRenderingContext2D, r: number) {
    ctx.beginPath();
    ctx.moveTo(HEX_CORNERS_X[0] * r, HEX_CORNERS_Y[0] * r);
    for (let i = 1; i < 6; i++) ctx.lineTo(HEX_CORNERS_X[i] * r, HEX_CORNERS_Y[i] * r);
    ctx.closePath();
}

// Dynamic Rotation Trace (Fixes the wobble issue)
function traceHexagonRotated(ctx: CanvasRenderingContext2D, r: number, rotation: number) {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
        const angle = START_ANGLE + i * Math.PI / 3 + rotation;
        const x = Math.cos(angle) * r;
        const y = Math.sin(angle) * r; // Note: ISO Scale applied by context, so we draw perfect hex here
        if (i===0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
    }
    ctx.closePath();
}

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean) {
        ctx.save();
        ctx.translate(drawX, drawY);

        const now = Date.now() / 1000;

        // --- 1. PERSPECTIVE CORRECTION (THE 2.5D RULE) ---
        const isGroundEffect = ['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'DOMAIN', 'MAGIC_CIRCLE'].includes(p.type);
        // GIANT_HEX handles scale internally to fix rotation artifacts
        if (isGroundEffect) {
            ctx.scale(1, ISO_SCALE_Y); 
        }

        // Standard 2D Sprite Rotation (Billboard)
        if (!['GIANT_HEX', 'HEX_BEAM'].includes(p.type)) {
            ctx.rotate(p.rotation);
        }

        // --- 2. BLEND MODES ---
        if (p.blendMode) {
            ctx.globalCompositeOperation = p.blendMode;
        } else {
            if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD', 'CHIP', 'GIANT_HEX'].includes(p.type)) {
                 ctx.globalCompositeOperation = 'source-over'; 
            } else if (['SMOKE', 'SMOKE_PUFF', 'ATMOSPHERE'].includes(p.type)) {
                 ctx.globalCompositeOperation = 'screen';      
            } else {
                 ctx.globalCompositeOperation = 'screen';      
            }
        }

        // --- 3. RENDERING ---

        // A. PROCEDURAL COMPLEX SHAPES (Beams, Pillars, Domains)
        if (['BEAM', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'GRID_FIELD', 'DOMAIN', 'DEATH_RAY'].includes(p.type)) {
            this.drawProcedural(ctx, p, progress, isChaos, now);
        }
        // B. TEXTURE BASED (Everything else)
        else {
            // Safety Net: If image missing, try fetch one last time
            if (!p.image && !p.texture) {
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }

            const img = p.image || p.texture;

            if (img) {
                this.drawTexture(ctx, img, p.size, progress, p.type);
            } else {
                // LAST RESORT: Simple Circle (No Squares allowed!)
                const s = p.size * (1 - progress);
                ctx.fillStyle = p.color;
                ctx.beginPath(); ctx.arc(0, 0, s, 0, Math.PI*2); ctx.fill();
            }
        }

        ctx.restore();
    },

    drawTexture(ctx: CanvasRenderingContext2D, img: HTMLCanvasElement, baseSize: number, progress: number, type: string) {
        let scale = 1.0;
        let alpha = 1.0 - progress;

        // FIX: Solid Large Projectiles (Meteors/Rocks) should not fade/shrink
        if (type === 'ROCK' && baseSize > 30) {
            scale = 1.0;
            alpha = 1.0; // Maintain opacity
        }
        else if (type === 'SHOCKWAVE' || type === 'RING') {
            scale = 0.5 + progress * 2.0;
            alpha = 1.0 - Math.pow(progress, 3);
        } else if (type === 'SMOKE' || type === 'SMOKE_PUFF' || type === 'ATMOSPHERE') {
            scale = 0.8 + progress * 1.2;
            alpha = (1.0 - progress) * 0.5; 
        } else {
            // Standard debris fade out
            scale = 1.0 - Math.pow(progress, 2);
        }

        const drawSize = baseSize * scale;
        ctx.globalAlpha = Math.max(0, Math.min(1, alpha));

        // Shadow for solid objects
        if (['RUBBLE', 'DEBRIS', 'ROCK', 'SHARD'].includes(type)) {
            ctx.save();
            ctx.globalCompositeOperation = 'multiply';
            ctx.globalAlpha = 0.5 * alpha;
            ctx.fillStyle = 'rgba(0,0,0,0.5)';
            // Draw a hex shadow instead of circle
            traceHexagonFast(ctx, drawSize * 0.5);
            ctx.fill();
            ctx.restore();
        }

        ctx.drawImage(img, -drawSize, -drawSize, drawSize * 2, drawSize * 2);
    },

    drawProcedural(ctx: CanvasRenderingContext2D, p: Particle, progress: number, isChaos: boolean, now: number) {

        if (p.type === 'BEAM' || p.type === 'DEATH_RAY') {
             if (p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.targetX;
                const dy = p.targetY; 

                ctx.beginPath();
                ctx.moveTo(0,0);
                ctx.lineTo(dx, dy - (p.targetZ || 0));
                ctx.strokeStyle = p.color;
                ctx.lineWidth = p.size * (1-progress) * 1.5; 
                ctx.lineCap = 'round';
                ctx.shadowColor = p.color;
                ctx.shadowBlur = 15;
                ctx.globalCompositeOperation = 'screen';
                ctx.stroke();

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = p.size * (1-progress) * 0.4;
                ctx.shadowBlur = 0;
                ctx.stroke();
             }
        }
        else if (p.type === 'HEX_BEAM' || p.type === 'GIANT_HEX') {
            // FIX: Handle Scale locally to allow correct rotation math
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);

            // Calculate Current Rotation
            const rot = p.rotation + (p.vRotation ? p.vRotation * now : 0);

            // FIX: Giant Hex (Heaven Fall / Black Hole)
            if (p.type === 'GIANT_HEX') {
                ctx.globalCompositeOperation = 'source-over';

                // Solid Core (Accretion Disk)
                ctx.fillStyle = p.color; 
                ctx.globalAlpha = 1.0;
                traceHexagonRotated(ctx, p.size, rot); 
                ctx.fill();

                // Bright Rim
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 4;
                traceHexagonRotated(ctx, p.size, rot); 
                ctx.stroke();

                // Inner Detail (Opposite spin)
                ctx.fillStyle = 'rgba(255,255,255,0.2)';
                traceHexagonRotated(ctx, p.size * 0.6, -rot * 1.5);
                ctx.fill();

                // --- BLACK HOLE SPECIAL: SINGULARITY SPHERE ---
                // Draw a non-iso-scaled black circle in center if color is black-ish
                if (p.color === '#000' || p.color === '#000000' || p.color === '#0f172a') {
                    ctx.restore(); // Pop the ISO scale
                    ctx.save();
                    // Draw Sphere
                    ctx.globalCompositeOperation = 'source-over';
                    ctx.fillStyle = '#000';
                    ctx.shadowColor = '#8b5cf6'; // Purple glow
                    ctx.shadowBlur = 20;
                    ctx.beginPath(); ctx.arc(0, 0, p.size * 0.4, 0, Math.PI * 2); ctx.fill();

                    // White Ring (Event Horizon)
                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    ctx.shadowBlur = 0;
                    ctx.beginPath(); ctx.arc(0, 0, p.size * 0.42, 0, Math.PI * 2); ctx.stroke();
                    ctx.restore(); // Pop Sphere
                    // Re-add dummy save for final restore
                    ctx.save();
                }

            } else {
                // HEX_BEAM (Energy)
                ctx.globalCompositeOperation = 'screen';
                const grad = ctx.createRadialGradient(0,0,0,0,0,p.size);
                grad.addColorStop(0, p.color); 
                grad.addColorStop(0.8, p.color);
                grad.addColorStop(1, 'transparent');
                ctx.fillStyle = grad;
                ctx.globalAlpha = (1 - progress) * 0.8;
                traceHexagonRotated(ctx, p.size, rot); 
                ctx.fill();

                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 1 - progress;
                traceHexagonRotated(ctx, p.size * 0.9, rot); 
                ctx.stroke();
            }
            ctx.restore();
        }
        else if (p.type === 'PILLAR') {
            // ... (Pillar logic remains valid)
            const rawDef = PROCEDURAL_VISUALS[p.style || ''] || {};
            const def = rawDef as PillarVisualDef;
            const h = def.height || 1200; 
            const width = p.size * (1 - progress * 0.5) * (def.widthScale || 1.0);

            ctx.save();
            if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

            const cylinderGrad = ctx.createLinearGradient(-width/2, 0, width/2, 0);
            cylinderGrad.addColorStop(0, p.color); 
            cylinderGrad.addColorStop(0.5, '#ffffff'); 
            cylinderGrad.addColorStop(1, p.color); 

            ctx.fillStyle = cylinderGrad;
            ctx.globalAlpha = (1 - progress) * 0.8;

            ctx.fillRect(-width/2, -h, width, h);

            if (def.hasBaseRing) {
                ctx.scale(1, ISO_SCALE_Y);
                const ringGrad = ctx.createRadialGradient(0,0, width*0.5, 0,0, width*1.2);
                ringGrad.addColorStop(0, 'transparent');
                ringGrad.addColorStop(0.5, p.color);
                ringGrad.addColorStop(1, 'transparent');
                ctx.fillStyle = ringGrad;
                ctx.beginPath(); ctx.arc(0, 0, width*1.5, 0, Math.PI*2); ctx.fill();
            }
            ctx.restore();
        }
        else if (p.type === 'DOMAIN' || p.type === 'GRID_FIELD') {
            ctx.save();
            ctx.scale(1, ISO_SCALE_Y);
            const r = p.size * (progress < 0.1 ? progress/0.1 : 1.0); 

            const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
            grad.addColorStop(0, 'rgba(255,255,255,0)');
            grad.addColorStop(0.7, p.color); 
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.globalAlpha = 0.4 * (1 - progress);
            ctx.globalCompositeOperation = 'screen';
            // Use Hex shape for domains too!
            traceHexagonFast(ctx, r); ctx.fill();

            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = 0.2;
            traceHexagonFast(ctx, r * 0.9); ctx.stroke();

            ctx.restore();
        }
    }
};

import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { GroundHazard } from "../../../types";
import { HAZARD_VISUALS } from "../../../data/vfx/hazard_visuals";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";

export const ZoneRenderer = {

    drawHazard(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        hazard: GroundHazard,
        globalTime: number
    ) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfaceAssets.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfaceAssets.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'FOG') {
            // Uses new Volumetric Smoke Puff texture internally
            SurfaceAssets.drawFog(ctx, x, y, def.primaryColor, globalTime * def.speed);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) SurfaceAssets.drawExtrusion(ctx, x, y, 8, def.primaryColor, 0.5);

            // Ground Crystal Glow
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Texture
            const texture = VFXFactory.getTexture('SHARD', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;

            // Draw scattered crystal shards on floor
            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 10;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-10, py-10, 20, 20);
            }

            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Dark Core
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();

            // Event Horizon Glow
            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.5, 0,0,HEX_SIZE);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

            // Rotating Accretion Disk
            ctx.rotate(globalTime * def.speed);
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 10]);
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    },

    /**
     * REFACTORED: Volumetric Hex Expansion with Warning Support
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visualTag: string, 
        progress: number, // 0.0 (Start) -> 1.0 (Ready)
        globalTime: number,
        dist: number,     // Distance from center of zone (in tiles)
        maxRadius: number // Radius of zone (in tiles)
    ) {
        // Warning Override: If color is red/enemy, assume warning logic
        const isWarning = visualTag === 'AOE_WARNING';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC EXPANSION ---
        // Progress determines how far out the "wave" has gone
        // progress 0.0 = center only
        // progress 1.0 = full radius coverage
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. WARNING PULSE (High Frequency) ---
        // Flash red vigorously if it's a warning
        const pulse = isWarning 
            ? (0.6 + Math.abs(Math.sin(globalTime * 15)) * 0.4) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. INNER FILL
        if (isInsideWave) {
            // Opacity ramps up as skill completes
            let fogOpacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
            if (isWarning) fogOpacity = 0.3 * pulse; // Higher opacity for warning

            SurfaceAssets.drawVolumetricHex(ctx, x, y, size * 0.9, color, fogOpacity);
        }

        // B. EXPANDING EDGE
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const edgeWidth = (def.baseRingWidth || 3);
            SurfaceAssets.drawHexRipple(ctx, x, y, size, color, edgeOpacity, edgeWidth);
        }

        // C. PERIMETER MARKER (Always Visible for Warning)
        const showBorder = isWarning || (dist >= maxRadius - 0.5);
        if (showBorder) {
            const borderAlpha = isWarning ? 0.8 * pulse : Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.4;

            ctx.strokeStyle = color;
            ctx.lineWidth = isWarning ? 2 : 1; 
            ctx.globalAlpha = borderAlpha;

            if (def.dashed) ctx.setLineDash([5, 5]);

            // Draw Warning Crosshatch?
            if (isWarning) {
                // SurfaceAssets.drawHatch(ctx, x, y, size, color, 0.2); // Optional: add hatching
                ctx.fillStyle = color; // Tint floor slightly
                ctx.globalAlpha = 0.1 * pulse;
                SurfaceAssets.traceHex(ctx, x, y, size);
                ctx.fill();
                ctx.globalAlpha = borderAlpha;
            }

            SurfaceAssets.traceHex(ctx, x, y, size);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { Team } from "../../../types";
import { HEX_SIZE, ISO_SCALE_Y, UNIT_BODY_OFFSET } from "../../../constants";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { AssetManager } from "../../assets";
import { VFXFactory } from "../../graphics/VFXFactory";

