export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.deathSpiritColor; 

    ctx.save();
    const grad = ctx.createLinearGradient(0, 0, 0, physZ);
    grad.addColorStop(0, 'rgba(0,0,0,0)'); 
    grad.addColorStop(0.5, color);        
    grad.addColorStop(1, 'rgba(0,0,0,0)'); 

    ctx.globalAlpha = 0.3 + Math.sin(t * 5) * 0.1;
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;

    const w = 4;
    ctx.fillRect(-w/2, 0, w, physZ);

    ctx.translate(0, physZ);
    ctx.scale(1, ISO_SCALE_Y); 

    const glow = VFXFactory.getTexture('GLOW', color);
    const sz = 32;
    ctx.drawImage(glow, -sz/2, -sz/2, sz, sz);

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.flightTrailColor;
    const glow = VFXFactory.getTexture('GLOW', color);

    ctx.save();
    ctx.translate(0, 10); 

    for(let i = -1; i <= 1; i += 2) {
        ctx.save();
        const offsetX = i * 10;
        const pulse = Math.sin(t * 20 + i) * 0.2 + 0.8;
        ctx.translate(offsetX, 0);
        ctx.scale(0.5 * pulse, 1.0 * pulse);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -16, 0, 32, 48); 
        ctx.restore();
    }
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -50); 

    const ring = VFXFactory.getTexture('HEX_HALO', color);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.8 * progress;

    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(t * 3); 
    const size = 64 * (0.8 + progress * 0.2);
    ctx.drawImage(ring, -size/2, -size/2, size, size);
    ctx.restore();

    const glow = VFXFactory.getTexture('GLOW', color);
    const coreSize = 32 * progress;
    ctx.drawImage(glow, -coreSize/2, -coreSize/2, coreSize, coreSize);

    ctx.restore();

    // If AOE, draw ground expansion
    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    // Large Ground Ripple
    const texture = VFXFactory.getTexture('SHOCKWAVE', color); 
    ctx.save();
    // Move to feet
    ctx.translate(0, UNIT_BODY_OFFSET); 
    ctx.scale(1, ISO_SCALE_Y); 

    // Scale up massively
    const scale = (0.5 + progress * 2.5) * 4.0; 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = (1 - progress) * 0.3; // Fade as it gets huge

    const size = 64 * scale;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // 1. Magic Circle (Spinning)
    const texture = VFXFactory.getTexture('MAGIC_CIRCLE', color);
    ctx.save();
    ctx.translate(0, -60); 
    const rot = t * (2 + progress * 5);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.6 + progress * 0.4;
    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(rot);
    const size = 120;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();

    // 2. Rising Energy
    const glow = VFXFactory.getTexture('GLOW', color);
    ctx.globalAlpha = 0.5 * progress;
    ctx.scale(0.5, 1.5); 
    ctx.drawImage(glow, -40, -40 - (progress * 50), 80, 80);
    ctx.restore();

    // 3. 3D Domain Expansion (Volumetric)
    ctx.save();
    ctx.translate(0, 40); // Move to ground

    const domainSize = 200 * progress;
    // Use the new 3D prism for casting
    SurfaceAssets.draw3DPrism(ctx, 0, 0, domainSize, 20, color, 0.3 * progress, 'SOLID');

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    const pixelRadius = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = pixelRadius * progress;
    const opacity = 0.3 + Math.sin(t * 5) * 0.1;

    // Use volumetric for local skill indicator too
    SurfaceAssets.drawVolumetricHex(ctx, 0, 0, currentRadius, color, opacity);

    const ringSize = currentRadius * 2.5; 
    const ring = VFXFactory.getTexture('RING', color);

    ctx.save();
    ctx.scale(1, ISO_SCALE_Y); 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = opacity * 1.2;
    ctx.drawImage(ring, -ringSize/2, -ringSize/2, ringSize, ringSize);
    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);
            const bg = VFXFactory.getTexture('GLOW', skill.color);
            ctx.globalAlpha = 0.6;
            ctx.globalCompositeOperation = 'screen';
            ctx.drawImage(bg, -30, -30, 60, 60);
            ctx.restore();
        }
    }
}

function draw3DHexPrism(ctx: CanvasRenderingContext2D, t: number, color: string, height: number, radius: number) {
    // Legacy helper kept for Status Effects (Banish/Stasis) 
    // Ideally this should also use SurfaceAssets but status effects handle their own transforms peculiarly
    // So we keep this local for now or refactor later.
    const startAngle = Math.PI / 6 + Math.PI / 4;
    const r = radius;

    ctx.save();
    ctx.globalCompositeOperation = 'screen';

    const pulse = 2 + Math.sin(t * 5) * 1.0;
    ctx.lineWidth = pulse;
    ctx.strokeStyle = color;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    const topVerts: {x: number, y: number}[] = [];
    const botVerts: {x: number, y: number}[] = [];

    for(let i=0; i<6; i++) {
        const angle = startAngle + i * Math.PI / 3 + t * 0.5; 
        const x = Math.cos(angle) * r;
        const y = Math.sin(angle) * r * ISO_SCALE_Y;

        topVerts.push({x: x, y: y - height});
        botVerts.push({x: x, y: y});
    }

    ctx.globalAlpha = 0.4;
    ctx.beginPath();
    for(let i=0; i<6; i++) {
        ctx.moveTo(topVerts[i].x, topVerts[i].y);
        ctx.lineTo(botVerts[i].x, botVerts[i].y);
    }
    ctx.stroke();

    ctx.globalAlpha = 0.8;
    ctx.beginPath();
    ctx.moveTo(topVerts[0].x, topVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(topVerts[i].x, topVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(botVerts[0].x, botVerts[0].y);
    for(let i=1; i<6; i++) ctx.lineTo(botVerts[i].x, botVerts[i].y);
    ctx.closePath();
    ctx.stroke();

    const grad = ctx.createLinearGradient(0, -height, 0, 0);
    grad.addColorStop(0, 'rgba(0,0,0,0)');
    grad.addColorStop(0.5, color);
    grad.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.globalAlpha = 0.2; 
    ctx.fillStyle = grad;
    ctx.fill();

    ctx.restore();
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    let statusId = 'NONE';
    if (agent.banished) statusId = 'BANISH';
    else if (agent.stunTimer > 0) statusId = 'STUN';
    else if (agent.silenceTimer > 0) statusId = 'SILENCE';
    else if (agent.visualStatus !== 'NONE') statusId = agent.visualStatus;

    if (statusId === 'NONE') return;

    if (statusId === 'BANISH' || statusId === 'STASIS') {
        const color = statusId === 'STASIS' ? '#facc15' : '#c084fc';
        ctx.save();
        ctx.translate(0, 0); 
        draw3DHexPrism(ctx, t, color, 120, 45); 
        ctx.restore();
        return;
    }

    if (statusId === 'STUN') {
        const color = '#facc15';
        const halo = VFXFactory.getTexture('HEX_HALO', color);
        ctx.save();
        ctx.translate(0, -90); 
        const float = Math.sin(t * 8) * 5;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'screen';
        ctx.save();
        ctx.scale(1, 0.4); 
        ctx.rotate(t * 6); 
        const size1 = 60; 
        ctx.globalAlpha = 1.0; 
        ctx.drawImage(halo, -size1/2, -size1/2, size1, size1);
        ctx.restore();
        ctx.save();
        ctx.scale(1, 0.4);
        ctx.rotate(-t * 2); 
        const size2 = 90; 
        ctx.globalAlpha = 0.7;
        ctx.drawImage(halo, -size2/2, -size2/2, size2, size2);
        ctx.restore();
        ctx.restore();
        return;
    }

    if (statusId === 'SILENCE') {
        const color = '#94a3b8';
        const lock = VFXFactory.getTexture('HEX_LOCK', color);
        ctx.save();
        ctx.translate(0, -100); 
        const float = Math.sin(t * 3) * 3;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'source-over';
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        const pulse = 1 + Math.sin(t * 5) * 0.1;
        const size = 48 * pulse; 
        ctx.drawImage(lock, -size/2, -size/2, size, size);
        ctx.restore();
        return;
    }

    if (statusId === 'FROZEN') {
        const glow = VFXFactory.getTexture('GLOW', '#bae6fd');
        ctx.save();
        ctx.translate(0, -40);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -50, -50, 100, 100);
        ctx.restore();
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";
import { VFXFactory } from "./VFXFactory";

// --- PRECOMPUTED GEOMETRY ---
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 
const HEX_COS: number[] = [];
const HEX_SIN: number[] = [];

for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_COS.push(Math.cos(angle));
    HEX_SIN.push(Math.sin(angle));
}

export const GEOMETRY = {
    HEX_COS,
    HEX_SIN,
    START_ANGLE
};

export const SurfaceAssets = {

    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
        ctx.beginPath();
        const startX = x + radius * HEX_COS[0];
        const startY = y + radius * HEX_SIN[0] * ISO_SCALE_Y;
        ctx.moveTo(startX, startY);

        for (let i = 1; i < 6; i++) {
            const vx = x + radius * HEX_COS[i];
            const vy = y + radius * HEX_SIN[i] * ISO_SCALE_Y;
            ctx.lineTo(vx, vy);
        }
        ctx.closePath();
    },

    /**
     * NEW: Volumetric Hexagon
     * Renders a soft, glowing pillar base or fog pool.
     */
    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        // We use the "ATMOSPHERE" texture which is a perfect soft radial glow
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; // Oversize slightly for bleed

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); // Flatten to ground plane

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';

        // Draw the soft fog texture
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        // Optional: Draw a second smaller, brighter core
        ctx.globalAlpha = opacity * 0.5;
        const coreSize = size * 0.6;
        ctx.drawImage(texture, -coreSize/2, -coreSize/2, coreSize, coreSize);

        ctx.restore();
    },

    /**
     * NEW: Draw Hatching Pattern (Stripes)
     * Used for Danger Zones / Warnings
     */
    drawHatch(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        ctx.save();
        // 1. Clip to Hexagon
        this.traceHex(ctx, x, y, radius);
        ctx.clip();

        // 2. Draw Diagonal Lines
        ctx.strokeStyle = color;
        ctx.lineWidth = 3; // Thicker lines for visibility
        ctx.globalAlpha = opacity;

        const size = radius * 2;
        const spacing = 12; // Wider spacing

        ctx.beginPath();
        // Draw across the bounding box of the hex
        // We draw at screen angle (45deg look) to make them stand out against the ISO grid
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(x + i - size, y - size);
            ctx.lineTo(x + i + size, y + size);
        }
        ctx.stroke();

        ctx.restore();
    },

    /**
     * NEW: Generalized 3D Prism
     * Renders a 3D hex pillar/zone with gradient walls
     */
    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING'
    ) {
        const topY = y - height;

        ctx.save();

        // 1. Vertical Walls (Gradient for 3D effect)
        // Indices for front-facing hex sides: 5, 0, 1
        const indices = [5, 0, 1]; 

        for (const i of indices) {
            const j = (i + 1) % 6;

            const x1 = x + radius * HEX_COS[i];
            const y1 = y + radius * HEX_SIN[i] * ISO_SCALE_Y;

            const x2 = x + radius * HEX_COS[j];
            const y2 = y + radius * HEX_SIN[j] * ISO_SCALE_Y;

            // Side Quad
            const grad = ctx.createLinearGradient(0, topY, 0, y);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); // Fade to bottom

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; // Semi-transparent walls

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineTo(x2, y2 - height);
            ctx.lineTo(x1, y1 - height);
            ctx.closePath();
            ctx.fill();

            // Vertical Edge Pillars
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x1, y1 - height);
            ctx.stroke();

            // Close the loop for last edge (vertex j)
            if (i === 1) {
                 ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2, y2 - height); ctx.stroke();
            }
        }

        // 2. Top Face (Solid Cap)
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.3;
        this.traceHex(ctx, x, topY, radius);
        ctx.fill();

        // 3. Style Specific Overlays
        if (style === 'HATCHED_WARNING') {
            this.drawHatch(ctx, x, topY, radius, '#ffffff', opacity);
        } else if (style === 'SOLID') {
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.2;
            this.traceHex(ctx, x, topY, radius);
            ctx.fill();
        }

        // 4. Top Rim (Bright Outline)
        ctx.strokeStyle = color;
        ctx.lineWidth = style === 'HATCHED_WARNING' ? 2 : 1.5;
        ctx.globalAlpha = Math.min(1.0, opacity * 3.0 + 0.4); // Rim stays relatively visible but fades if opacity is super low
        this.traceHex(ctx, x, topY, radius);
        ctx.stroke();

        // 5. Inner Glow / Detail
        if (radius > 20) {
            ctx.globalCompositeOperation = 'screen';
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            this.traceHex(ctx, x, topY, radius * 0.8);
            ctx.stroke();
        }

        ctx.restore();
    },

    /**
     * Alias specifically for AOE Warnings (Legacy support + semantic naming)
     */
    drawWarningBlock(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        pulse: number
    ) {
        // Height reduced by ~2/3 (original 40 -> 14)
        const height = 14; 
        // Opacity reduced to ~20% (Transparency 80%)
        // Pulse oscillates 0.5 to 1.0. Result: 0.15 to 0.25
        const opacity = 0.1 + pulse * 0.15;
        this.draw3DPrism(ctx, x, y, radius, height, color, opacity, 'HATCHED_WARNING');
    },

    /**
     * NEW: Hex Ripple (Volumetric Ring)
     */
    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        // Soft glow for the line
        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        this.traceHex(ctx, x, y, radius);
        ctx.stroke();

        // Secondary white hot core
        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = opacity * 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawLiquid(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number,
        intensity: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        const r = HEX_SIZE * 0.9;

        // 1. Base Liquid Shape (Wobbly)
        ctx.beginPath();
        const segments = 12; 
        for (let i = 0; i <= segments; i++) {
            const theta = (i / segments) * Math.PI * 2;
            // More organic noise
            const noise = Math.sin(theta * 4 + time) * 3 + Math.cos(theta * 2 - time * 1.5) * 2; 
            const px = Math.cos(theta) * (r + noise);
            const py = Math.sin(theta) * (r + noise);
            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();

        // 2. Deep Base
        ctx.fillStyle = color;
        ctx.globalAlpha = 0.8 * intensity;
        ctx.fill();

        // 3. Surface Ripples (Darker)
        ctx.globalCompositeOperation = 'multiply';
        ctx.beginPath();
        const rippleX = Math.sin(time) * 5;
        const rippleY = Math.cos(time * 0.8) * 5;
        ctx.ellipse(rippleX, rippleY, r * 0.6, r * 0.5, time*0.1, 0, Math.PI * 2);
        ctx.fill();

        // 4. Specular Highlights (Bubbles/Reflection)
        ctx.globalCompositeOperation = 'overlay';
        ctx.fillStyle = '#fff';
        ctx.globalAlpha = 0.5;

        const bX = Math.cos(time * 1.5) * r * 0.4;
        const bY = Math.sin(time * 1.5) * r * 0.4;
        ctx.beginPath(); ctx.ellipse(bX, bY, 6, 3, 0, 0, Math.PI*2); ctx.fill();

        ctx.restore();
    },

    drawFog(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        time: number
    ) {
        // Use the factory generated cloud texture for better performance & look
        const texture = VFXFactory.getTexture('SMOKE_PUFF', color);
        const size = HEX_SIZE * 3.0;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.15; // Very subtle

        const puffs = 3;
        for(let i=0; i<puffs; i++) {
            const angle = time * 0.2 + (i * Math.PI * 2 / puffs);
            const dist = 12 + Math.sin(time + i) * 6;
            const px = Math.cos(angle) * dist;
            const py = Math.sin(angle) * dist;

            // Breathe
            const pulse = 1.0 + Math.sin(time * 1.5 + i) * 0.1;
            const pSize = size * 0.5 * pulse;

            ctx.drawImage(texture, px - pSize/2, py - pSize/2, pSize, pSize);
        }

        // Center Core
        ctx.globalAlpha = 0.2;
        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    drawCracks(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        color: string,
        intensity: number
    ) {
        const texture = VFXFactory.generateCracks(color);
        const size = HEX_SIZE * 2.2; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalCompositeOperation = 'lighter';
        ctx.globalAlpha = intensity;

        const staticRot = (x + y) * 0.1; // Consistent rotation based on position
        ctx.rotate(staticRot);

        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        height: number,
        color: string,
        opacity: number
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity;

        const visibleFaces = [5, 0, 1]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;

            const x1 = x + HEX_SIZE * HEX_COS[i];
            const y1 = HEX_SIZE * HEX_SIN[i] * ISO_SCALE_Y; 

            const x2 = x + HEX_SIZE * HEX_COS[j];
            const y2 = HEX_SIZE * HEX_SIN[j] * ISO_SCALE_Y; 

            // Gradient for 3D depth
            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); // Fade into ground

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, topY + y1);
            ctx.lineTo(x2, topY + y2);
            ctx.lineTo(x2, bottomY + y2);
            ctx.lineTo(x1, bottomY + y1);
            ctx.closePath();
            ctx.fill();

            // Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            ctx.stroke();
            ctx.globalAlpha = opacity;
        }

        // Top Cap
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        this.traceHex(ctx, x, topY, HEX_SIZE);
        ctx.fill();

        // Rim
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    },

    drawDetailTexture(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        type: string,
        color: string,
        seed: number
    ) {
        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        // Simple deterministic random
        const rnd = (offset: number) => {
            const v = Math.sin(seed + offset) * 1000;
            return v - Math.floor(v);
        };

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;

                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             // Circuit lines
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            // Generic
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        ctx.restore();
    },
};

import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";
import { GroundHazard } from "../../../types";
import { HAZARD_VISUALS } from "../../../data/vfx/hazard_visuals";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";

export const ZoneRenderer = {

    drawHazard(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        hazard: GroundHazard,
        globalTime: number
    ) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'LIQUID') {
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfaceAssets.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfaceAssets.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'FOG') {
            // Uses new Volumetric Smoke Puff texture internally
            SurfaceAssets.drawFog(ctx, x, y, def.primaryColor, globalTime * def.speed);
        }
        else if (def.type === 'CRYSTAL') {
            if (def.extrude) SurfaceAssets.drawExtrusion(ctx, x, y, 8, def.primaryColor, 0.5);

            // Ground Crystal Glow
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Texture
            const texture = VFXFactory.getTexture('SHARD', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;

            // Draw scattered crystal shards on floor
            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 10;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-10, py-10, 20, 20);
            }

            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Dark Core
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();

            // Event Horizon Glow
            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.5, 0,0,HEX_SIZE);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

            // Rotating Accretion Disk
            ctx.rotate(globalTime * def.speed);
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 10]);
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    },

    /**
     * REFACTORED: Volumetric Hex Expansion with Warning Support
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visualTag: string, 
        progress: number, // 0.0 (Start) -> 1.0 (Ready)
        globalTime: number,
        dist: number,     // Distance from center of zone (in tiles)
        maxRadius: number // Radius of zone (in tiles)
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC EXPANSION ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. INNER FILL
        // For WARNINGS & ULTS, we draw volumetric fill
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Prism (Height 14, Opacity ~0.2)
                SurfaceAssets.drawWarningBlock(ctx, x, y, size, color, pulse);
            } 
            else if (isUlt) {
                // Friendly Ult: Smooth Prism
                // Balance intensity with warning (Height 30 -> 14, Opacity 0.4 -> 0.25)
                const height = 14;
                SurfaceAssets.draw3DPrism(ctx, x, y, size, height, color, 0.25 * pulse, 'SOLID');
            }
            else {
                // Basic/Active: Fog
                let fogOpacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                SurfaceAssets.drawVolumetricHex(ctx, x, y, size * 0.9, color, fogOpacity);
            }
        }

        // B. EXPANDING EDGE (Ripple)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const edgeWidth = (def.baseRingWidth || 3);
            SurfaceAssets.drawHexRipple(ctx, x, y, size, color, edgeOpacity, edgeWidth);
        }

        // C. PERIMETER MARKER (Always Visible for Warning)
        // If it's a warning or ult, the block already handles the rim
        const showBorder = (!isWarning && !isUlt) && (dist >= maxRadius - 0.5);
        if (showBorder) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.4;

            ctx.strokeStyle = color;
            ctx.lineWidth = 1; 
            ctx.globalAlpha = borderAlpha;

            if (def.dashed) ctx.setLineDash([5, 5]);

            SurfaceAssets.traceHex(ctx, x, y, size);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

import { Agent, GameEngine } from "../game";
import { SpriteManager } from "../sprites";
import { Role, Team, MovementType } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { STATUS_VISUALS } from "../../data/vfx/status_visuals";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawStatusEffects, drawStatusIcons, drawSkillGroundIndicator, drawUltimateChantVFX } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    // ... (submitRenderables and drawSilhouette kept same, omitted for brevity but assumed present in full file) ...
    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            let terrainH = 0;
            if (agent.isMoving && agent.path.length > 0) {
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                terrainH = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    terrainH = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    terrainH = getTerrainHeight(agent.q, agent.r);
                }
            }

            const visualGroundY = agent.py - terrainH;

            const op = renderList.next();
            op.type = RenderOpType.UNIT;
            op.y = agent.py + 1; 
            op.z = 10;
            op.agent = agent;
            op.tx = agent.px; 
            op.ty = visualGroundY;  
            op.th = terrainH; 
            op.time = globalTime;
            op.uSelected = (highlightAgent === agent);
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        let terrainH = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            terrainH = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            terrainH = getTerrainHeight(agent.q, agent.r);
        }

        const visualGroundY = agent.py - terrainH;
        this.drawAssembly(ctx, agent, agent.px, visualGroundY, globalTime, false, true);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }
        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY); 
        ctx.scale(scaleFactor, scaleFactor);

        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // 3. LAYER: GROUND
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            this.drawGroundElements(ctx, agent, physX, physY, physZ, globalTime);
        }

        // 4. LAYER: UNIT BODY ROOT
        ctx.save(); // Push body transform state
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); 

        // 6. LAYER: ANIMATED BODY
        this.drawBodyElements(ctx, agent, globalTime, isSilhouette, isSelected, scaleFactor);

        ctx.restore(); // Pop body transform (reset rotation/facing)

        // 7. LAYER: STATUS EFFECTS (Un-flipped, World Aligned)
        // We are still at (drawX, drawY) scaled by scaleFactor.
        // We need to translate to the unit's visual top center (physX, physY - physZ)
        if (!isSilhouette && agent.hp > 0) {
            ctx.save();
            ctx.translate(physX, physY - physZ);

            // Adjust for body float (UnitVisuals usually expects 0,0 to be feet)
            let bodyFloat = -UNIT_BODY_OFFSET;
            if (agent.movementType !== MovementType.FLYING) bodyFloat -= Math.sin(globalTime * 2) * 3;
            else bodyFloat -= Math.sin(globalTime * 4) * 2;

            ctx.translate(0, bodyFloat);

            // Draw Status overheads (Not mirrored)
            drawStatusIcons(ctx, agent, globalTime, 0, 0, scaleFactor);
            drawStatusEffects(ctx, agent, globalTime);

            ctx.restore();
        }

        ctx.restore(); // Pop global scale/translate
    }

    private drawGroundElements(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        ctx.save();
        ctx.translate(px, py); 

        const shadowScale = Math.max(0.6, 1.0 - (pz / 400));
        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        ctx.save();
        const iconBaseY = -24; 
        ctx.translate(0, iconBaseY);
        const breath = Math.sin(t * 2) * 1.5;
        ctx.translate(0, breath);

        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

        ctx.globalAlpha = 1.0; 
        ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
        ctx.drawImage(assets.icon, -32, -32, 64, 64);
        ctx.restore();

        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                const visualRadius = isAOE ? 0.8 : radius;
                drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, visualRadius, skill.tag, isAOE);
            }
        }

        ctx.restore();

        if (agent.movementType === MovementType.FLYING && pz > 5) {
            drawFlyingAnchor(ctx, agent, t, px, py, pz);
        }
    }

    private drawBodyElements(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isSelected: boolean, scaleFactor: number) {
        let bodyFloat = -UNIT_BODY_OFFSET; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat -= Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat -= Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        let spawnAlpha = 1.0;
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            spawnAlpha = eased;
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= spawnAlpha;
        }

        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, t);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill && skill.tag === 'ULT') {
                    drawUltimateChantVFX(ctx, agent, t);
                } else {
                    drawCastingVFX(ctx, agent, t);
                }
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }

            // Note: Stasis/StatusEffects moved outside
        }
    }
}

import { Agent } from "../../game";
import { Team } from "../../../types";
import { HEX_SIZE, ISO_SCALE_Y, UNIT_BODY_OFFSET } from "../../../constants";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { AssetManager } from "../../assets";
import { VFXFactory } from "../../graphics/VFXFactory";

// ... (Keep existing imports and functions up to drawDomainExpansion) ...

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.deathSpiritColor; 

    ctx.save();
    const grad = ctx.createLinearGradient(0, 0, 0, physZ);
    grad.addColorStop(0, 'rgba(0,0,0,0)'); 
    grad.addColorStop(0.5, color);        
    grad.addColorStop(1, 'rgba(0,0,0,0)'); 

    ctx.globalAlpha = 0.3 + Math.sin(t * 5) * 0.1;
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;

    const w = 4;
    ctx.fillRect(-w/2, 0, w, physZ);

    ctx.translate(0, physZ);
    ctx.scale(1, ISO_SCALE_Y); 

    const glow = VFXFactory.getTexture('GLOW', color);
    const sz = 32;
    ctx.drawImage(glow, -sz/2, -sz/2, sz, sz);

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.flightTrailColor;
    const glow = VFXFactory.getTexture('GLOW', color);

    ctx.save();
    ctx.translate(0, 10); 

    for(let i = -1; i <= 1; i += 2) {
        ctx.save();
        const offsetX = i * 10;
        const pulse = Math.sin(t * 20 + i) * 0.2 + 0.8;
        ctx.translate(offsetX, 0);
        ctx.scale(0.5 * pulse, 1.0 * pulse);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -16, 0, 32, 48); 
        ctx.restore();
    }
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -50); 

    const ring = VFXFactory.getTexture('HEX_HALO', color);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.8 * progress;

    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(t * 3); 
    const size = 64 * (0.8 + progress * 0.2);
    ctx.drawImage(ring, -size/2, -size/2, size, size);
    ctx.restore();

    const glow = VFXFactory.getTexture('GLOW', color);
    const coreSize = 32 * progress;
    ctx.drawImage(glow, -coreSize/2, -coreSize/2, coreSize, coreSize);

    ctx.restore();

    // If AOE, draw ground expansion
    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    // Large Ground Ripple
    const texture = VFXFactory.getTexture('SHOCKWAVE', color); 
    ctx.save();
    // Move to feet
    ctx.translate(0, UNIT_BODY_OFFSET); 
    ctx.scale(1, ISO_SCALE_Y); 

    // Scale up massively
    const scale = (0.5 + progress * 2.5) * 4.0; 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = (1 - progress) * 0.3; // Fade as it gets huge

    const size = 64 * scale;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // 1. Magic Circle (Spinning)
    const texture = VFXFactory.getTexture('MAGIC_CIRCLE', color);
    ctx.save();
    ctx.translate(0, -60); 
    const rot = t * (2 + progress * 5);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.6 + progress * 0.4;
    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(rot);
    const size = 120;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();

    // 2. Rising Energy
    const glow = VFXFactory.getTexture('GLOW', color);
    ctx.globalAlpha = 0.5 * progress;
    ctx.scale(0.5, 1.5); 
    ctx.drawImage(glow, -40, -40 - (progress * 50), 80, 80);
    ctx.restore();

    // 3. 3D Domain Expansion (Volumetric)
    ctx.save();
    ctx.translate(0, 40); // Move to ground

    const domainSize = 200 * progress;
    // Use the new 3D prism for casting
    SurfaceAssets.draw3DPrism(ctx, 0, 0, domainSize, 20, color, 0.3 * progress, 'SOLID');

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    const pixelRadius = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = pixelRadius * progress;
    const opacity = 0.3 + Math.sin(t * 5) * 0.1;

    // Use volumetric for local skill indicator too
    SurfaceAssets.drawVolumetricHex(ctx, 0, 0, currentRadius, color, opacity);

    const ringSize = currentRadius * 2.5; 
    const ring = VFXFactory.getTexture('RING', color);

    ctx.save();
    ctx.scale(1, ISO_SCALE_Y); 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = opacity * 1.2;
    ctx.drawImage(ring, -ringSize/2, -ringSize/2, ringSize, ringSize);
    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);
            const bg = VFXFactory.getTexture('GLOW', skill.color);
            ctx.globalAlpha = 0.6;
            ctx.globalCompositeOperation = 'screen';
            ctx.drawImage(bg, -30, -30, 60, 60);
            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    let statusId = 'NONE';
    if (agent.banished) statusId = 'BANISH';
    else if (agent.stunTimer > 0) statusId = 'STUN';
    else if (agent.silenceTimer > 0) statusId = 'SILENCE';
    else if (agent.visualStatus !== 'NONE') statusId = agent.visualStatus;

    if (statusId === 'NONE') return;

    if (statusId === 'BANISH' || statusId === 'STASIS') {
        const color = statusId === 'STASIS' ? '#facc15' : '#c084fc';
        const pulse = 0.8 + Math.sin(t * 3) * 0.2;

        ctx.save();
        // Since we are inside UnitRenderSystem's transform stack, we are at (physX, physY - physZ).
        // draw3DPrism draws upwards from Y.
        // We move down to the "feet" of the visual representation to draw the prism base.
        ctx.translate(0, 40); 

        // Use standard Prism for consistent look
        // Height 100 covers the unit comfortably
        // Opacity 0.4 for semi-transparent crystal look
        SurfaceAssets.draw3DPrism(ctx, 0, 0, 40, 100, color, 0.4 * pulse, 'SOLID');

        ctx.restore();
        return;
    }

    if (statusId === 'STUN') {
        const color = '#facc15';
        const halo = VFXFactory.getTexture('HEX_HALO', color);
        ctx.save();
        ctx.translate(0, -90); // Head height
        const float = Math.sin(t * 8) * 5;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'screen';
        ctx.save();
        ctx.scale(1, 0.4); 
        ctx.rotate(t * 6); 
        const size1 = 60; 
        ctx.globalAlpha = 1.0; 
        ctx.drawImage(halo, -size1/2, -size1/2, size1, size1);
        ctx.restore();
        ctx.save();
        ctx.scale(1, 0.4);
        ctx.rotate(-t * 2); 
        const size2 = 90; 
        ctx.globalAlpha = 0.7;
        ctx.drawImage(halo, -size2/2, -size2/2, size2, size2);
        ctx.restore();
        ctx.restore();
        return;
    }

    if (statusId === 'SILENCE') {
        const color = '#94a3b8';
        const lock = VFXFactory.getTexture('HEX_LOCK', color);
        ctx.save();
        ctx.translate(0, -90); // Head height
        const float = Math.sin(t * 3) * 3;
        ctx.translate(0, float);
        ctx.globalCompositeOperation = 'source-over';
        ctx.shadowColor = color;
        ctx.shadowBlur = 10;
        const pulse = 1 + Math.sin(t * 5) * 0.1;
        const size = 48 * pulse; 
        ctx.drawImage(lock, -size/2, -size/2, size, size);
        ctx.restore();
        return;
    }

    // Note: Frozen and Polymorph are handled as model swaps/overlays in drawBodyElements
}

