export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.deathSpiritColor; 

    ctx.save();
    const grad = ctx.createLinearGradient(0, 0, 0, physZ);
    grad.addColorStop(0, 'rgba(0,0,0,0)'); 
    grad.addColorStop(0.5, color);        
    grad.addColorStop(1, 'rgba(0,0,0,0)'); 

    ctx.globalAlpha = 0.3 + Math.sin(t * 5) * 0.1;
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;

    const w = 4;
    ctx.fillRect(-w/2, 0, w, physZ);

    ctx.translate(0, physZ);
    ctx.scale(1, ISO_SCALE_Y); 

    const glow = VFXFactory.getTexture('GLOW', color);
    const sz = 32;
    ctx.drawImage(glow, -sz/2, -sz/2, sz, sz);

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.flightTrailColor;
    const glow = VFXFactory.getTexture('GLOW', color);

    ctx.save();
    ctx.translate(0, 10); 

    for(let i = -1; i <= 1; i += 2) {
        ctx.save();
        const offsetX = i * 10;
        const pulse = Math.sin(t * 20 + i) * 0.2 + 0.8;
        ctx.translate(offsetX, 0);
        ctx.scale(0.5 * pulse, 1.0 * pulse);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -16, 0, 32, 48); 
        ctx.restore();
    }
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -50); 

    const ring = VFXFactory.getTexture('HEX_HALO', color);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.8 * progress;

    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(t * 3); 
    const size = 64 * (0.8 + progress * 0.2);
    ctx.drawImage(ring, -size/2, -size/2, size, size);
    ctx.restore();

    const glow = VFXFactory.getTexture('GLOW', color);
    const coreSize = 32 * progress;
    ctx.drawImage(glow, -coreSize/2, -coreSize/2, coreSize, coreSize);

    ctx.restore();

    // If AOE, draw ground expansion
    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    // Large Ground Ripple
    const texture = VFXFactory.getTexture('SHOCKWAVE', color); 
    ctx.save();
    // Move to feet
    ctx.translate(0, UNIT_BODY_OFFSET); 
    ctx.scale(1, ISO_SCALE_Y); 

    // Scale up massively
    const scale = (0.5 + progress * 2.5) * 4.0; 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = (1 - progress) * 0.3; // Fade as it gets huge

    const size = 64 * scale;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // 1. Magic Circle (Spinning)
    const texture = VFXFactory.getTexture('MAGIC_CIRCLE', color);
    ctx.save();
    ctx.translate(0, -60); 
    const rot = t * (2 + progress * 5);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.6 + progress * 0.4;
    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(rot);
    const size = 120;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();

    // 2. Rising Energy
    const glow = VFXFactory.getTexture('GLOW', color);
    ctx.globalAlpha = 0.5 * progress;
    ctx.scale(0.5, 1.5); 
    ctx.drawImage(glow, -40, -40 - (progress * 50), 80, 80);
    ctx.restore();

    // 3. 3D Domain Expansion (Volumetric)
    ctx.save();
    ctx.translate(0, 40); // Move to ground

    const domainSize = 200 * progress;
    // Use the new 3D prism for casting
    SurfaceAssets.draw3DPrism(ctx, 0, 0, domainSize, 20, color, 0.3 * progress, 'SOLID');

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    const pixelRadius = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = pixelRadius * progress;
    const opacity = 0.3 + Math.sin(t * 5) * 0.1;

    // Use volumetric for local skill indicator too
    SurfaceAssets.drawVolumetricHex(ctx, 0, 0, currentRadius, color, opacity);

    const ringSize = currentRadius * 2.5; 
    const ring = VFXFactory.getTexture('RING', color);

    ctx.save();
    ctx.scale(1, ISO_SCALE_Y); 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = opacity * 1.2;
    ctx.drawImage(ring, -ringSize/2, -ringSize/2, ringSize, ringSize);
    ctx.restore();
}

export function drawStatusIcons(ctx: CanvasRenderingContext2D, agent: Agent, t: number, drawX: number, drawY: number, scaleFactor: number) {
    if (agent.hp > 0 && agent.castingSkillIdx !== -1) {
        const skill = agent.skills[agent.castingSkillIdx];
        if (skill) {
            ctx.save();
            ctx.translate(0, -110);
            const bg = VFXFactory.getTexture('GLOW', skill.color);
            ctx.globalAlpha = 0.6;
            ctx.globalCompositeOperation = 'screen';
            ctx.drawImage(bg, -30, -30, 60, 60);
            ctx.restore();
        }
    }
}

export function drawStatusEffects(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    if (agent.hp <= 0) return;

    // Priority Status Drawing
    // We check specific conditions and draw the corresponding VFX

    // 1. ROOT (Chains at feet)
    if (agent.rootTimer > 0) {
        const color = '#fbbf24'; // Amber chains
        ctx.save();
        ctx.translate(0, 40); // Ground level
        // Draw 3 Spikes
        for(let i=0; i<3; i++) {
            const angle = i * (Math.PI*2/3) + t;
            const r = 15;
            const px = Math.cos(angle) * r;
            const py = Math.sin(angle) * r * ISO_SCALE_Y;
            ctx.beginPath();
            ctx.moveTo(px, py);
            ctx.lineTo(px, py - 30); // Spike Up
            ctx.lineTo(px + 5, py);
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'overlay';
            ctx.fill();
        }

        // Ring
        SurfaceAssets.drawHexRipple(ctx, 0, 0, 20, color, 0.8, 2);
        ctx.restore();
    }

    // 2. SHIELD (Rotating Prism Shell)
    if (agent.shield > 0) {
        // Shield color depends on team or generic
        const color = agent.team === Team.BLUE ? '#bae6fd' : '#f87171';
        const pulse = 0.3 + Math.sin(t * 2) * 0.1;

        ctx.save();
        ctx.translate(0, 40); // Ground level anchor for Prism
        ctx.globalCompositeOperation = 'screen';

        // Rotating shell
        ctx.save();
        // Since Prism drawing is static, we can't rotate it easily without 3D math.
        // Instead, we just draw the prism with pulsing opacity to simulate field.
        SurfaceAssets.draw3DPrism(ctx, 0, 0, 35, 90, color, pulse, 'SOLID');
        ctx.restore();

        // Inner brighter rim
        SurfaceAssets.drawHexRipple(ctx, 0, -45, 30, color, 0.5, 2);

        ctx.restore();
    }

    // 3. BANISH / STASIS (Full Encapsulation)
    if (agent.banished) {
        const color = agent.visualStatus === 'STASIS' ? '#facc15' : '#c084fc';
        const pulse = 0.5 + Math.sin(t * 3) * 0.2;

        ctx.save();
        ctx.translate(0, 40); 
        // Use standard Prism for consistent look
        // Height 100 covers the unit comfortably
        SurfaceAssets.draw3DPrism(ctx, 0, 0, 40, 100, color, pulse, 'SOLID');
        ctx.restore();
        return; // Banish hides other effects
    }

    // 4. OVERHEAD ICONS (Stun, Silence, Fear, Taunt, Blind)
    let iconType = '';
    let iconColor = '#fff';

    if (agent.stunTimer > 0) { iconType = 'STUN'; iconColor = '#facc15'; }
    else if (agent.fearTimer > 0) { iconType = 'FEAR'; iconColor = '#a855f7'; }
    else if (agent.tauntTimer > 0) { iconType = 'TAUNT'; iconColor = '#ef4444'; }
    else if (agent.silenceTimer > 0) { iconType = 'SILENCE'; iconColor = '#94a3b8'; }
    else if (agent.blindTimer > 0) { iconType = 'BLIND'; iconColor = '#cbd5e1'; }

    if (iconType) {
        const def = STATUS_VISUALS[iconType];
        const shape = def.iconShape;
        const color = def.primaryColor;

        ctx.save();
        ctx.translate(0, -95); // Head height + padding

        // Float animation
        const float = Math.sin(t * 5) * 4;
        ctx.translate(0, float);

        // Draw the specific icon from AssetManager/UIFactory logic
        // Since UnitVisuals usually calls factories, we can do manual drawing here or helper
        // Let's use the Factory texture for consistency
        const icon = AssetManager.getStatusIcon(iconType);

        ctx.scale(0.8, 0.8); // Scale down slightly for overhead
        ctx.drawImage(icon, -24, -24, 48, 48);

        ctx.restore();
    }
}

import { Agent } from "../../game";
import { Skill, Role } from "../../../types";
import { COMBAT_PARAM } from "../../../constants";

export interface DamageResult {
    finalValue: number;     // Final HP delta (negative for damage, positive for heal)
    shieldAbsorb: number;   // Amount absorbed by shield
    isCrit: boolean;        // Critical hit?
    isExecute: boolean;     // Execute trigger?
    isBlock: boolean;       // Tank block?
    isMiss: boolean;        // Blind miss?
    vampAmount: number;     // Lifesteal value
    manaBurn: number;       // MP burned
    manaRestore: number;    // MP restored
    overkill: number;       // Damage exceeding remaining HP
}

export class DamageCalculator {

    /**
     * The Core Damage Pipeline:
     * Hit Check (Blind) -> Base -> Multipliers -> Crit/Execute -> Mitigation (Shield/Def/Block) -> Final
     */
    public static calculate(source: Agent, target: Agent, skill: Skill): DamageResult {
        const isHeal = skill.power < 0;
        let base = Math.abs(skill.power);

        const result: DamageResult = {
            finalValue: 0,
            shieldAbsorb: 0,
            isCrit: false,
            isExecute: false,
            isBlock: false,
            isMiss: false,
            vampAmount: 0,
            manaBurn: 0,
            manaRestore: 0,
            overkill: 0
        };

        // 0. Miss Logic (Blind)
        if (!isHeal && source.blindTimer > 0) {
            // 50% Chance to miss if blinded
            if (Math.random() < 0.5) {
                result.isMiss = true;
                return result; // Early exit on miss
            }
        }

        // 1. Role Multipliers & Base Logic
        if (!isHeal) {
            // Ranger: Bonus dmg at max range? (Placeholder logic)
            // Mage: Bonus vs High Armor? 
        }

        // 2. Execute Logic (斩杀)
        const isExec1 = skill.effectType === 'EXECUTE';
        const isExec2 = skill.effectType2 === 'EXECUTE';

        if (!isHeal && (isExec1 || isExec2)) {
            const threshold = COMBAT_PARAM.EXECUTE_THRESHOLD;
            if (target.hp < target.maxHp * threshold) {
                const multiplier = (isExec1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_EXECUTE_MULTIPLIER;
                base *= multiplier;
                result.isExecute = true;
            }
        }

        // 3. Crit Logic
        if (!isHeal && Math.random() < 0.1) {
            base *= 1.5;
            result.isCrit = true;
        }

        // 4. Mitigation (Tank Block Logic)
        if (!isHeal && target.role === Role.TANK && target.hp > 0) {
            base *= 0.85; 
            result.isBlock = true;
        }

        // 5. Shield Absorption (NEW)
        let absorbed = 0;
        if (!isHeal && target.shield > 0) {
            absorbed = Math.min(target.shield, base);
            base -= absorbed;
            result.shieldAbsorb = absorbed;
        }

        // 6. Final Calculation
        let final = Math.floor(base);

        // 7. Secondary Effects (Vamp, Mana)
        const isVamp1 = skill.effectType === 'VAMP';
        const isVamp2 = skill.effectType2 === 'VAMP';
        if (!isHeal && (isVamp1 || isVamp2)) {
            const vampPct = (isVamp1 ? skill.effectVal : skill.effectVal2) || COMBAT_PARAM.BASE_VAMP_PCT;
            // Vamp based on unmitigated damage or actual HP damage? Usually actual.
            result.vampAmount = Math.floor(final * vampPct);
        }

        // Mana Burn
        let mb = 0;
        if (skill.effectType === 'MANA_BURN') mb += (skill.effectVal || COMBAT_PARAM.MANA_BURN_DEFAULT);
        if (skill.effectType2 === 'MANA_BURN') mb += (skill.effectVal2 || COMBAT_PARAM.MANA_BURN_DEFAULT);
        result.manaBurn = mb;

        // Mana Restore
        let mr = 0;
        if (skill.effectType === 'MANA_RESTORE') mr += (skill.effectVal || COMBAT_PARAM.MANA_RESTORE_DEFAULT);
        if (skill.effectType2 === 'MANA_RESTORE') mr += (skill.effectVal2 || COMBAT_PARAM.MANA_RESTORE_DEFAULT);
        result.manaRestore = mr;

        // 8. Apply Direction (Damage is negative)
        result.finalValue = isHeal ? final : -final;

        // 9. Overkill Calc
        if (!isHeal && final > target.hp) {
            result.overkill = final - target.hp;
        }

        return result;
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState, Hex } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { BLOCK_HEIGHT } from "../../../constants";
import { DamageCalculator } from "./DamageCalculator";

export class SkillResolutionSystem {

    // ... (Previous logic unchanged, omitting for brevity until spawnHazards) ...

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        if (a.stunTimer > 0 || a.banished || a.hp <= 0 || a.fearTimer > 0 || a.silenceTimer > 0) {
            // Fear also interrupts casting
            // Silence interrupts Non-Basic
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            const isSilencedInterrupt = a.silenceTimer > 0 && currentSkill && currentSkill.tag !== 'BASIC';
            const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;

            if (isHardCC || isSilencedInterrupt) {
                this.handleInterruption(a, engine);
                return;
            }
        }

        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 
        if (a.castTimer <= 0) {
            this.completeCast(a, engine);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            engine.log(a, 'CC', '中斷', s.name, '詠唱被打斷');
            let centerPos = { x: a.px, y: a.py };
            engine.events.push({ type: 'CAST_BREAK', pos: centerPos, value: 0, color: s.color, skill: s });
        }
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.IDLE); 
    }

    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd;
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             engine.combat.spawnProjectile(a, s, engine);
        } else {
            this.executeInstantSkill(a, s, engine);
        }
        a.castingSkillIdx = -1;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });
            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

            this.spawnHazards(source, impactCells, skill, engine);

        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexMath.distance(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        // Self-Target for buffs (Shields etc) if target list empty and skill is beneficial
        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        targets.forEach(t => {
            const dist = HexMath.distance(source, t);
            if (dist > 1) engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            else engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            this.resolveHit(source, t, skill, origin, engine);
        });

        engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
    }

    private spawnHazards(source: Agent, cells: {q: number, r: number}[], skill: Skill, engine: GameEngine) {
        const dur = skill.ccDur || 5.0;
        let hType: any = null;

        if (skill.ccType === 'DOT') hType = 'POISON';
        if (skill.element === 'FIRE') hType = 'FIRE';
        if (skill.element === 'ICE') hType = 'ICE';
        if (skill.element === 'VOID' || skill.ccType === 'PULL') hType = 'GRAVITY';

        if (hType) {
            cells.forEach(tile => {
                engine.map.addHazard(
                    tile.q, tile.r, 
                    hType, 
                    dur, 
                    source.id, 
                    source.team, 
                    skill.color,
                    (Math.abs(skill.power) * 0.2) || 10, 
                    0.5,
                    engine // Pass engine for VFX trigger
                );
            });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);

        // Handle MISS
        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "MISS", color: "#94a3b8" });
            return;
        }

        const oldHp = Math.ceil(target.hp);

        // Absorb feedback
        if (result.shieldAbsorb > 0) {
            target.shield -= result.shieldAbsorb;
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "ABSORB", color: "#bae6fd" });
        }

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
        }
        if (result.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - result.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + result.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${result.manaBurn} MP`, color: "#3b82f6" });
        }
        if (result.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + result.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${result.manaRestore} MP`, color: "#60a5fa" });
        }

        if (result.finalValue < 0) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const impulse = this.calculateImpulseVector(originPx, {x: target.px, y: target.py}, Math.abs(result.finalValue));
            target.physics.vx += impulse.x;
            target.physics.vy += impulse.y;
            target.physics.vAngle += (Math.random() - 0.5) * 0.5;
        }

        if (result.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        if (result.isCrit) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "CRIT!", color: "#ef4444" });
        if (result.isBlock) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "BLOCK", color: "#9ca3af" });

        engine.events.push({
            type: result.finalValue < 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // SHIELD APPLICATION Logic (Negative damage + HOT type usually)
        // But better to use explicit CC Type for Shield
        // If skill power is negative (heal) and ccType is SHIELD, apply shield hp

        this.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        this.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        const actionType = result.finalValue < 0 ? 'HIT' : 'HEAL';
        engine.log(source, actionType, skill.name, target.id, `${actionType === 'HIT' ? '造成傷害' : '回復生命'} ${Math.abs(result.finalValue)} (HP: ${oldHp} -> ${newHp})`);

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }

    private calculateImpulseVector(origin: {x: number, y: number}, target: {x: number, y: number}, damage: number) {
        const dx = target.x - origin.x;
        const dy = target.y - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);
        const force = Math.min(400, Math.max(100, damage * 1.5));
        if (len <= 0.1) {
            const ang = Math.random() * Math.PI * 2;
            return { x: Math.cos(ang) * force, y: Math.sin(ang) * force };
        }
        return { x: (dx / len) * force, y: (dy / len) * force };
    }

    public applyCC(source: Agent, target: Agent, skill: Skill, type: string | undefined, dur: number | undefined, force: number | undefined, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        if (!type || type === 'NONE') return;
        const { effectiveDuration, isImmune } = this.checkDR(target, type, dur || 0);
        if (isImmune) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "免疫", color: "#9ca3af" });
            return;
        }

        let statusText = "";
        let statusColor = "#fff";

        switch (type) {
            case 'STUN':
                if (effectiveDuration > target.stunTimer) {
                    target.stunTimer = effectiveDuration;
                    target.stunMax = effectiveDuration;
                }
                target.isMoving = false;
                target.setAnim(AnimState.STUN);
                statusText = "暈眩"; statusColor = "#facc15";
                if (skill.element === 'ICE') target.visualStatus = 'FROZEN';
                break;
            case 'SILENCE':
                if (effectiveDuration > target.silenceTimer) {
                    target.silenceTimer = effectiveDuration;
                    target.silenceMax = effectiveDuration;
                }
                statusText = "沉默"; statusColor = "#94a3b8";
                break;
            case 'BANISH':
                if (effectiveDuration > target.banishTimer) {
                    target.banishTimer = effectiveDuration;
                    target.banishMax = effectiveDuration;
                }
                target.banished = true;
                target.isMoving = false;
                target.setAnim(AnimState.STUN);
                statusText = "放逐"; statusColor = "#c084fc";
                if (skill.specialVisualStatus) target.visualStatus = skill.specialVisualStatus;
                break;

            // --- NEW EFFECTS ---
            case 'ROOT':
                if (effectiveDuration > target.rootTimer) target.rootTimer = effectiveDuration;
                target.isMoving = false;
                statusText = "禁錮"; statusColor = "#fbbf24";
                break;
            case 'FEAR':
                if (effectiveDuration > target.fearTimer) target.fearTimer = effectiveDuration;
                statusText = "恐懼"; statusColor = "#a855f7";
                break;
            case 'TAUNT':
                if (effectiveDuration > target.tauntTimer) {
                    target.tauntTimer = effectiveDuration;
                    target.tauntTargetId = source.id; // Target the caster
                }
                statusText = "嘲諷"; statusColor = "#ef4444";
                break;
            case 'BLIND':
                if (effectiveDuration > target.blindTimer) target.blindTimer = effectiveDuration;
                statusText = "致盲"; statusColor = "#cbd5e1";
                break;
            case 'SHIELD':
                // Shield amount passed via ccForce or just power
                // If it's a heal/buff skill, use negative power? Or just use ccForce
                const amount = force || 50;
                target.shield += amount;
                target.maxShield = Math.max(target.maxShield, target.shield);
                statusText = "護盾"; statusColor = "#bae6fd";
                break;

            case 'KNOCKBACK':
            case 'PULL':
                const result = this.calculateKnockback(target, force || 0, source, origin, type, engine);
                if (result.applied) {
                    statusText = type === 'PULL' ? "牽引" : "擊退";
                    target.setAnim(AnimState.HIT);
                    target.physics.vz += 200; 
                }
                break;
            case 'DOT':
                target.dotDmg = force || 10;
                target.dotTimer = effectiveDuration;
                statusText = "中毒"; statusColor = "#10b981";
                break;
            case 'HOT':
                target.hotVal = force || 10;
                target.hotTimer = effectiveDuration;
                statusText = "再生"; statusColor = "#86efac";
                break;
        }

        if (statusText) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: statusText, color: statusColor });
        }
    }

    private checkDR(target: Agent, type: string, baseDuration: number) {
        const isHardCC = ['STUN', 'SILENCE', 'BANISH', 'FEAR', 'TAUNT', 'ROOT'].includes(type);
        if (!isHardCC) return { effectiveDuration: baseDuration, isImmune: false };
        const stacks = target.drStacks[type] || 0;
        const multiplier = Math.pow(0.5, stacks);
        if (multiplier < 0.2) return { effectiveDuration: 0, isImmune: true };
        target.drStacks[type] = stacks + 1;
        target.drTimers[type] = 10.0;
        return { effectiveDuration: baseDuration * multiplier, isImmune: false };
    }

    private calculateKnockback(target: Agent, force: number, source: Agent, origin: {x: number, y: number} | undefined, type: string, engine: GameEngine) {
        const rawForce = Math.max(1, force);
        const resistance = target.weight || 1; 
        const tilesToPush = Math.max(0, rawForce - resistance);
        if (tilesToPush === 0) return { applied: false };

        const originPx = origin ? origin : {x: source.px, y: source.py};
        const dir = Vector.normalize(Vector.sub({x: target.px, y: target.py}, originPx));
        const vector = type === 'KNOCKBACK' ? dir : Vector.mult(dir, -1);

        let currentH = {q: target.q, r: target.r};
        let finalH = currentH;

        for(let k=0; k<tilesToPush; k++) {
            const neighbors = HexUtils.neighbors(currentH);
            let bestN: Hex | null = null;
            let bestDot = -99;
            for(const n of neighbors) {
                const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                const cPx = HexUtils.toPx(currentH.q, currentH.r, engine.mapConfig);
                const nDir = Vector.normalize(Vector.sub(nPx, cPx));
                const dot = nDir.x * vector.x + nDir.y * vector.y;
                if (dot > bestDot) {
                    bestDot = dot;
                    bestN = n;
                }
            }
            if (bestN) {
                if (!engine.map.isValid(bestN.q, bestN.r) || engine.map.hasObstacle(bestN.q, bestN.r)) break; 
                if (engine.getAgentAt(bestN.q, bestN.r)) break;
                const curHeight = engine.map.getTerrainHeight(currentH.q, currentH.r);
                const nextHeight = engine.map.getTerrainHeight(bestN.q, bestN.r);
                if (nextHeight > curHeight + 24) break; 
                currentH = bestN;
                finalH = bestN;
            } else {
                break;
            }
        }

        if (finalH.q !== target.q || finalH.r !== target.r) {
            engine.updateAgentPosition(target, finalH.q, finalH.r);
            if (target.isMoving) {
                target.isMoving = false;
                target.path = [];
            }
            return { applied: true };
        }
        return { applied: false };
    }
}

import { Agent, GameEngine } from "../game";
import { AnimState } from "../../types";
import { COMBAT_PARAM, UNIT_BODY_OFFSET } from "../../constants";
import { STATUS_VISUALS } from "../../data/vfx/status_visuals";
import { HexUtils } from "../utils";

export class StatusSystem {

    // Track VFX intervals to avoid spamming particles every frame
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. Cooldowns
        agent.curCDs = agent.curCDs.map(c => Math.max(0, c - dt));

        // 2. DR Logic
        for (const type in agent.drTimers) {
            if (agent.drTimers.hasOwnProperty(type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        if (agent.spawnTimer > 0) agent.spawnTimer -= dt;

        // 3. Status VFX Tick
        this.processStatusVFX(agent, dt, engine);

        // 4. Banish Logic
        if (agent.banishTimer > 0) {
            agent.banishTimer -= dt;
            if (agent.banishTimer <= 0) {
                agent.banished = false;
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            } else {
                if (agent.visualStatus === 'POLYMORPH') {
                    // Sheep keep ticking
                } else {
                    return; // Hard Pause
                }
            }
        }

        // 5. Timers
        if (agent.stunTimer > 0) agent.stunTimer -= dt;
        if (agent.silenceTimer > 0) agent.silenceTimer -= dt;
        if (agent.rootTimer > 0) agent.rootTimer -= dt;
        if (agent.blindTimer > 0) agent.blindTimer -= dt;
        if (agent.tauntTimer > 0) {
            agent.tauntTimer -= dt;
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 6. FEAR LOGIC (Random Movement)
        if (agent.fearTimer > 0) {
            agent.fearTimer -= dt;
            // Fear Override Movement
            if (!agent.isMoving && agent.hp > 0 && agent.stunTimer <= 0 && agent.rootTimer <= 0) {
                const neighbors = HexUtils.neighbors(agent);
                // Filter valid
                const valid = neighbors.filter(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, agent.id));
                if (valid.length > 0) {
                    const next = valid[Math.floor(Math.random() * valid.length)];
                    // Use moveAgentToHex with high speed (panic run)
                    engine.movement.moveAgentToHex(agent, next, 0, engine, 1.5);
                }
            }
        }

        // 7. Visual State Reset
        if (agent.visualStatus === 'FROZEN' && agent.stunTimer <= 0) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'POLYMORPH' && !agent.banished) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'STASIS' && !agent.banished) agent.visualStatus = 'NONE';

        // 8. DoT
        if (agent.dotTimer > 0) {
            agent.dotTimer -= dt;
            // Shield absorbs DoT too
            let dmg = agent.dotDmg * dt;
            if (agent.shield > 0) {
                const absorbed = Math.min(agent.shield, dmg);
                agent.shield -= absorbed;
                dmg -= absorbed;
            }

            agent.hp -= dmg;
            if (Math.random() < 0.05) { 
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.round(agent.dotDmg), 
                    color: '#10b981',
                    skill: { ccType: 'DOT' } as any 
                });
                agent.hitFlashTimer = 0.1;
            }
        }

        // 9. HoT
        if (agent.hotTimer > 0) {
            agent.hotTimer -= dt;
            agent.hp = Math.min(agent.maxHp, agent.hp + agent.hotVal * dt);
            if (Math.random() < 0.05) {
                engine.events.push({ 
                    type: 'HEAL', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: Math.round(agent.hotVal), 
                    color: '#86efac' 
                });
            }
        }

        // 10. Anim Reset
        if (agent.stunTimer <= 0 && agent.banishTimer <= 0 && !agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + agent.physics.z + UNIT_BODY_OFFSET
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('FEAR', agent.fearTimer > 0);
    }
}

