export enum Team {
    BLUE = 0,
    RED = 1
}

export enum Role {
    TANK = 'TANK',
    WARRIOR = 'WARRIOR',
    RANGER = 'RANGER',
    MAGE = 'MAGE',
    SUPPORT = 'SUPPORT'
}

export enum MovementType {
    GROUND = 0,
    FLYING = 1
}

export enum AnimState {
    IDLE = 0,
    COMBAT_IDLE = 1,
    ATTACK = 2,
    HIT = 3,
    DEAD = 4,
    STUN = 5,
    MOVE = 6
}

export interface Hex {
    q: number;
    r: number;
}

export interface Cube {
    x: number;
    y: number;
    z: number;
}

export interface Point {
    x: number;
    y: number;
}

// Scene / Environment Types
export interface SceneTheme {
    id: string;
    name: string;
    background: string; // Sky Top Color
    horizon: string;    // Sky Bottom/Horizon Color (New)
    fogColor: string;   // Low-lying fog color (New)
    textureType: 'VOID' | 'FOREST' | 'ICE' | 'MAGMA' | 'DESERT';
    obstacleStyle: string; 
    hexStroke: string; 
    ambientType: 'NONE' | 'SNOW' | 'ASH' | 'SPORES' | 'RAIN' | 'EMBER';
    ambientColor: string;
    bgFeature: 'NONE' | 'SKY_RIVER' | 'AURORA' | 'CANOPY' | 'HEAT_WAVE' | 'DUNES';
}

// Data Models
export interface Skill {
    id: string;
    tag: 'BASIC' | 'ACTIVE' | 'ULT';
    role: Role;
    team?: Team; // Optional: If specified, only this team can learn it
    name: string;
    desc?: string; // For Tooltips
    range: number;
    cast: number;
    cd: number;
    cost: number;
    gain: number;
    type: 'SINGLE' | 'AOE';
    aoeRadius?: number; // Default 1 if not specified
    power: number;
    color: string;

    // Semantic Visual Tags (NEW: Fully Decoupled)
    element?: 'PHYSICAL' | 'FIRE' | 'ICE' | 'LIGHTNING' | 'HOLY' | 'VOID' | 'POISON' | 'ARCANE' | 'BLOOD';
    specialVisualStatus?: 'POLYMORPH' | 'STASIS' | 'FROZEN'; 

    // Control Effects (Slot 1)
    ccType?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE' | 'ROOT' | 'FEAR' | 'TAUNT' | 'BLIND' | 'SHIELD';
    ccDur?: number;
    ccForce?: number;

    // Control Effects (Slot 2) - NEW: Allows composite effects like Knockback + Stun
    ccType2?: 'STUN' | 'BANISH' | 'KNOCKBACK' | 'PULL' | 'DOT' | 'HOT' | 'SILENCE' | 'ROOT' | 'FEAR' | 'TAUNT' | 'BLIND' | 'SHIELD';
    ccDur2?: number;
    ccForce2?: number;

    // Special Combat Effects (Slot 1)
    effectType?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal?: number; // e.g. 0.5 for 50% Vamp, 1.5 for 50% bonus Execute dmg

    // Special Combat Effects (Slot 2)
    effectType2?: 'VAMP' | 'MANA_BURN' | 'EXECUTE' | 'MANA_RESTORE';
    effectVal2?: number;

    projectileSpeed?: number; // 0 = Instant
    visual?: 'ARROW' | 'FIREBALL' | 'BOLT' | 'SLASH' | 'SMASH' | 'BEAM' | 'BOMB';

    // --- PHASE 2: DATA DRIVEN VFX LINKS ---
    visualHitEffect?: string;  // ID in VFXRegistry (Impact)
    visualCastEffect?: string; // ID in VFXRegistry (Muzzle flash / Cast finish)
    visualProjectileEffect?: string; // ID for Projectile Visuals (Future)
}

export interface UnitStats {
    role: Role;
    maxHp: number;
    maxMp: number;
    moveSpeed: number; // Tiles per second. 1.0 = 1 tile/sec
    movementType: MovementType; // Ground or Flying
}

export interface ObstacleDef {
    id: string;
    name: string;
    blocksVision: boolean;
    blocksMovement: boolean;
    blocksFlying?: boolean; // New: If true, blocks even flying units (High Towers/Pillars)
}

// Logic State Types
export enum NodeState {
    SUCCESS = 'S',
    FAILURE = 'F',
    RUNNING = 'R'
}

export type LogActionType = 'MOVE' | 'CAST' | 'HIT' | 'DECISION' | 'DEATH' | 'SYSTEM' | 'HEAL' | 'CC' | 'HAZARD';

export interface LogEntry {
    id: string;
    time: string;
    turn: number; // Battle tick or frame count
    agentId: string; // "Who"
    team: Team | undefined;
    location: string; // "Where" (e.g., "(10, 5)")
    actionType: LogActionType;
    actionName: string; // "What" (e.g., "Fireball", "MoveTo")
    targetInfo?: string; // "To Whom" (e.g., "Tank-A @ (12,5)")
    detail: string; // Narrative details
    visualColor?: string; // For UI highlighting

    // Legacy support fields (optional)
    action?: string;
    target?: string;
    loc?: string;
}

export interface Projectile {
    id: string;
    x: number;
    y: number;
    startX: number; // New: For Height Interpolation
    startY: number; // New: For Height Interpolation
    startZ?: number; // New: Initial height offset (for flying units)
    targetId: string;
    targetPos: Point;
    speed: number;
    skill: Skill;
    sourceId: string;
    team: Team;
    trail: Point[];
}

// NEW: Per-Tile Hazard
export interface GroundHazard {
    id: string;
    q: number;
    r: number;
    type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC';
    duration: number; // Seconds remaining
    sourceId: string;
    team: Team;
    color: string;
    power: number; // Damage per tick
    interval: number; // Tick rate
    timer: number; // Current tick timer
    vfxId?: string; // NEW: Phase 3 ready
}

// Event System (Bridge between Logic and Visuals)
export type GameEventType = 'DAMAGE' | 'HEAL' | 'CC_APPLIED' | 'CAST_START' | 'CAST_FINISH' | 'PROJECTILE_SPAWN' | 'PROJECTILE_HIT' | 'DEATH' | 'SPAWN' | 'VISUAL_BEAM' | 'CAST_BREAK' | 'VISUAL_SLASH' | 'KILL' | 'IMPACT_AOE' | 'KILL_STREAK';

export interface GameEvent {
    type: GameEventType;
    pos: Point;
    value?: number; // Damage amount, heal amount, etc.
    text?: string; // For specialized text
    color?: string;
    skill?: Skill;
    sourceId?: string;
    targetId?: string;
    team?: Team;
}

// Tooling
export enum ToolType {
    SELECT = 'SELECT',
    ADD_BLUE = 'ADD_BLUE',
    ADD_RED = 'ADD_RED',
    OBSTACLE = 'OBSTACLE',
    DELETE = 'DELETE'
}

import { Agent, GameEngine } from "../game";
import { AnimState } from "../../types";
import { COMBAT_PARAM, UNIT_BODY_OFFSET } from "../../constants";
import { STATUS_VISUALS } from "../../data/vfx/status_visuals";
import { HexUtils } from "../utils";

export class StatusSystem {

    // Track VFX intervals to avoid spamming particles every frame
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. Cooldowns
        agent.curCDs = agent.curCDs.map(c => Math.max(0, c - dt));

        // 2. DR Logic
        for (const type in agent.drTimers) {
            if (agent.drTimers.hasOwnProperty(type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        if (agent.spawnTimer > 0) agent.spawnTimer -= dt;

        // 3. Status VFX Tick
        this.processStatusVFX(agent, dt, engine);

        // 4. Banish Logic
        if (agent.banishTimer > 0) {
            agent.banishTimer -= dt;
            if (agent.banishTimer <= 0) {
                agent.banished = false;
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            } else {
                if (agent.visualStatus === 'POLYMORPH') {
                    // Sheep keep ticking
                } else {
                    return; // Hard Pause
                }
            }
        }

        // 5. Timers
        if (agent.stunTimer > 0) agent.stunTimer -= dt;
        if (agent.silenceTimer > 0) agent.silenceTimer -= dt;
        if (agent.rootTimer > 0) agent.rootTimer -= dt;
        if (agent.blindTimer > 0) agent.blindTimer -= dt;
        if (agent.tauntTimer > 0) {
            agent.tauntTimer -= dt;
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 6. FEAR LOGIC (Random Movement)
        if (agent.fearTimer > 0) {
            agent.fearTimer -= dt;
            // Fear Override Movement
            if (!agent.isMoving && agent.hp > 0 && agent.stunTimer <= 0 && agent.rootTimer <= 0) {
                const neighbors = HexUtils.neighbors(agent);
                // Filter valid
                const valid = neighbors.filter(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine, agent.id));
                if (valid.length > 0) {
                    const next = valid[Math.floor(Math.random() * valid.length)];
                    // Use moveAgentToHex with high speed (panic run)
                    engine.movement.moveAgentToHex(agent, next, 0, engine, 1.5);
                }
            }
        }

        // 7. Visual State Reset
        if (agent.visualStatus === 'FROZEN' && agent.stunTimer <= 0) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'POLYMORPH' && !agent.banished) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'STASIS' && !agent.banished) agent.visualStatus = 'NONE';

        // 8. DoT
        if (agent.dotTimer > 0) {
            agent.dotTimer -= dt;
            // Shield absorbs DoT too
            let dmg = agent.dotDmg * dt;
            if (agent.shield > 0) {
                const absorbed = Math.min(agent.shield, dmg);
                agent.shield -= absorbed;
                dmg -= absorbed;
            }

            agent.hp -= dmg;
            if (Math.random() < 0.05) { 
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.round(agent.dotDmg), 
                    color: '#10b981',
                    skill: { ccType: 'DOT' } as any 
                });
                agent.hitFlashTimer = 0.1;
            }
        }

        // 9. HoT
        if (agent.hotTimer > 0) {
            agent.hotTimer -= dt;
            agent.hp = Math.min(agent.maxHp, agent.hp + agent.hotVal * dt);
            if (Math.random() < 0.05) {
                engine.events.push({ 
                    type: 'HEAL', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: Math.round(agent.hotVal), 
                    color: '#86efac' 
                });
            }
        }

        // 10. Anim Reset
        if (agent.stunTimer <= 0 && agent.banishTimer <= 0 && !agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + agent.physics.z + UNIT_BODY_OFFSET
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('FEAR', agent.fearTimer > 0);
    }
}

