import { Agent, GameEngine } from "../../game";
import { Team } from "../../../types";
import { ISO_SCALE_Y, UNIT_BODY_OFFSET } from "../../../constants";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { AssetManager } from "../../assets";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

// =========================================================================================
// 🛡️ STATUS RENDER LAYER (Dedicated Pipeline)
// 
// Purpose: Exclusive renderer for persistent status effects (Shields, CC, Debuffs).
// Architecture: Decoupled from UnitRenderer. Handles its own Z-sorting relative to units.
// Performance: Batches context state changes.
// =========================================================================================

export class StatusRenderLayer {

    public draw(ctx: CanvasRenderingContext2D, agents: Agent[], globalTime: number) {
        // We do two passes to handle depth correctly:
        // Pass 1: Floor Effects (Root, Traps) - Drawn BEHIND unit body logic (usually)
        // Pass 2: Body/Overhead Effects (Shield, Stun, Silence) - Drawn ABOVE unit

        // However, since this layer runs *after* unit body drawing in the main loop,
        // we utilize Z-offset logic to visual depth.

        for (const agent of agents) {
            if (agent.hp <= 0 && agent.fullyDead) continue;

            // Calculate Unit Center Mass
            // Note: We access physics directly for raw interpolation if needed
            const px = agent.px;
            const py = agent.py; 
            const pz = agent.physics.z; 

            // Banish hides everything else, render it and skip
            if (agent.banished) {
                this.drawBanishment(ctx, agent, px, py, pz, globalTime);
                continue;
            }

            this.drawFloorEffects(ctx, agent, px, py, pz, globalTime);
            this.drawBodyEffects(ctx, agent, px, py, pz, globalTime);
            this.drawOverheadIcons(ctx, agent, px, py, pz, globalTime);
        }
    }

    // --- 1. FLOOR / GROUND EFFECTS ---
    private drawFloorEffects(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        // ROOT (Chain/Vines)
        if (agent.rootTimer > 0) {
            const color = '#fbbf24'; // Amber
            ctx.save();
            ctx.translate(x, y - z); // Anchor to feet position visually

            // Dynamic pulsing ring
            const pulse = 0.8 + Math.sin(t * 10) * 0.2;
            SurfaceAssets.drawHexRipple(ctx, 0, 0, 20, color, pulse, 2);

            // 3D Spikes (Simulated)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'source-over'; // Solid
            for(let i=0; i<3; i++) {
                const angle = i * (Math.PI*2/3) + t;
                const r = 18;
                const sx = Math.cos(angle) * r;
                const sy = Math.sin(angle) * r * ISO_SCALE_Y;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx, sy - 25); // Spike tip up
                ctx.lineTo(sx + 6, sy + 3);
                ctx.fill();
            }
            ctx.restore();
        }
    }

    // --- 2. BODY ENCAPSULATION (Shields, Fields) ---
    private drawBodyEffects(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        // SHIELD
        if (agent.shield > 0) {
            const isBlue = agent.team === Team.BLUE;
            const color = isBlue ? '#bae6fd' : '#f87171'; // Cyan vs Red tint

            // Shield Pulse
            const pct = Math.min(1, agent.shield / (agent.maxShield || 100));
            const pulse = 0.2 + (pct * 0.3) + Math.sin(t * 3) * 0.1;

            ctx.save();
            ctx.translate(x, y - z); // Ground level anchor

            // Volumetric Prism Shell
            // Height 90 covers most standard units
            SurfaceAssets.draw3DPrism(ctx, 0, 0, 35, 90, color, pulse, 'SOLID');

            // Inner Core Ripple
            ctx.translate(0, -45); // Center mass
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;
            // Simple energy line
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.ellipse(0, 0, 25, 12, 0, 0, Math.PI*2);
            ctx.stroke();

            ctx.restore();
        }
    }

    // --- 3. OVERHEAD ICONS (CC Status) ---
    private drawOverheadIcons(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        // Priority System: Only show most severe CC
        let type = '';
        if (agent.stunTimer > 0) type = 'STUN';
        else if (agent.fearTimer > 0) type = 'FEAR';
        else if (agent.tauntTimer > 0) type = 'TAUNT';
        else if (agent.silenceTimer > 0) type = 'SILENCE';
        else if (agent.blindTimer > 0) type = 'BLIND';

        if (!type) return;

        const icon = AssetManager.getStatusIcon(type);
        if (!icon) return;

        // Bobbing Animation
        const bob = Math.sin(t * 6) * 5;
        const anchorY = y - z - UNIT_BODY_OFFSET - 60 + bob; // Approx 60px above body center

        ctx.save();
        ctx.translate(x, anchorY);

        // Glow Backing
        const color = STATUS_VISUALS[type]?.primaryColor || '#fff';
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        // Draw Icon
        ctx.drawImage(icon, -24, -24, 48, 48);

        ctx.restore();
    }

    // --- SPECIAL: BANISH / STASIS ---
    private drawBanishment(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        const isStasis = agent.visualStatus === 'STASIS';
        const color = isStasis ? '#facc15' : '#c084fc'; // Gold or Purple
        const height = 110; 

        ctx.save();
        ctx.translate(x, y - z);

        // Use SurfaceAssets for high-quality Prism
        // Opacity oscillation
        const opacity = 0.4 + Math.sin(t * 2) * 0.1;
        SurfaceAssets.draw3DPrism(ctx, 0, 0, 40, height, color, opacity, 'SOLID');

        // Lock Icon Floating inside
        const icon = AssetManager.getStatusIcon(isStasis ? 'STASIS' : 'BANISH');
        if (icon) {
            ctx.translate(0, -height/2);
            ctx.scale(0.8, 0.8);
            ctx.globalCompositeOperation = 'overlay';
            ctx.drawImage(icon, -24, -24);
        }

        ctx.restore();
    }
}

import { Agent } from "../../game";
import { Team } from "../../../types";
import { HEX_SIZE, ISO_SCALE_Y, UNIT_BODY_OFFSET } from "../../../constants";
import { FACTION_VISUALS } from "../../../data/vfx/faction_visuals";
import { SurfaceAssets } from "../../graphics/SurfaceAssets";
import { VFXFactory } from "../../graphics/VFXFactory";

// =========================================================================================
// 🦴 UNIT BODY VISUALS (Pure Geometry & Animation)
// 
// Responsible ONLY for:
// 1. Casting Animations (Chant circles)
// 2. Flight/Hover Effects
// 3. Skill Indicators (Ground decals)
//
// MOVED OUT: Status Effects -> StatusRenderLayer.ts
// =========================================================================================

export function drawFlyingAnchor(ctx: CanvasRenderingContext2D, agent: Agent, t: number, physX: number, physY: number, physZ: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.deathSpiritColor; 

    ctx.save();
    const grad = ctx.createLinearGradient(0, 0, 0, physZ);
    grad.addColorStop(0, 'rgba(0,0,0,0)'); 
    grad.addColorStop(0.5, color);        
    grad.addColorStop(1, 'rgba(0,0,0,0)'); 

    ctx.globalAlpha = 0.3 + Math.sin(t * 5) * 0.1;
    ctx.globalCompositeOperation = 'screen';
    ctx.fillStyle = grad;

    const w = 4;
    ctx.fillRect(-w/2, 0, w, physZ);

    ctx.translate(0, physZ);
    ctx.scale(1, ISO_SCALE_Y); 

    const glow = VFXFactory.getTexture('GLOW', color);
    const sz = 32;
    ctx.drawImage(glow, -sz/2, -sz/2, sz, sz);

    ctx.restore();
}

export function drawFlightVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const faction = FACTION_VISUALS[agent.team] || FACTION_VISUALS[Team.BLUE];
    const color = faction.flightTrailColor;
    const glow = VFXFactory.getTexture('GLOW', color);

    ctx.save();
    ctx.translate(0, 10); 

    for(let i = -1; i <= 1; i += 2) {
        ctx.save();
        const offsetX = i * 10;
        const pulse = Math.sin(t * 20 + i) * 0.2 + 0.8;
        ctx.translate(offsetX, 0);
        ctx.scale(0.5 * pulse, 1.0 * pulse);
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.6;
        ctx.drawImage(glow, -16, 0, 32, 48); 
        ctx.restore();
    }
    ctx.restore();
}

export function drawCastingVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;

    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    ctx.save();
    ctx.translate(0, -50); 

    const ring = VFXFactory.getTexture('HEX_HALO', color);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.8 * progress;

    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(t * 3); 
    const size = 64 * (0.8 + progress * 0.2);
    ctx.drawImage(ring, -size/2, -size/2, size, size);
    ctx.restore();

    const glow = VFXFactory.getTexture('GLOW', color);
    const coreSize = 32 * progress;
    ctx.drawImage(glow, -coreSize/2, -coreSize/2, coreSize, coreSize);

    ctx.restore();

    // If AOE, draw ground expansion
    if (skill.type === 'AOE') {
        drawDomainExpansion(ctx, agent, t, color, progress);
    }
}

export function drawDomainExpansion(ctx: CanvasRenderingContext2D, agent: Agent, t: number, color: string, progress: number) {
    // Large Ground Ripple
    const texture = VFXFactory.getTexture('SHOCKWAVE', color); 
    ctx.save();
    // Move to feet
    ctx.translate(0, UNIT_BODY_OFFSET); 
    ctx.scale(1, ISO_SCALE_Y); 

    // Scale up massively
    const scale = (0.5 + progress * 2.5) * 4.0; 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = (1 - progress) * 0.3; // Fade as it gets huge

    const size = 64 * scale;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();
}

export function drawUltimateChantVFX(ctx: CanvasRenderingContext2D, agent: Agent, t: number) {
    const skill = agent.skills[agent.castingSkillIdx];
    if (!skill) return;
    const progress = 1 - (agent.castTimer / skill.cast);
    const color = skill.color;

    // 1. Magic Circle (Spinning)
    const texture = VFXFactory.getTexture('MAGIC_CIRCLE', color);
    ctx.save();
    ctx.translate(0, -60); 
    const rot = t * (2 + progress * 5);
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = 0.6 + progress * 0.4;
    ctx.save();
    ctx.scale(1, 0.4); 
    ctx.rotate(rot);
    const size = 120;
    ctx.drawImage(texture, -size/2, -size/2, size, size);
    ctx.restore();

    // 2. Rising Energy
    const glow = VFXFactory.getTexture('GLOW', color);
    ctx.globalAlpha = 0.5 * progress;
    ctx.scale(0.5, 1.5); 
    ctx.drawImage(glow, -40, -40 - (progress * 50), 80, 80);
    ctx.restore();

    // 3. 3D Domain Expansion (Volumetric)
    ctx.save();
    ctx.translate(0, 40); // Move to ground

    const domainSize = 200 * progress;
    // Use the new 3D prism for casting
    SurfaceAssets.draw3DPrism(ctx, 0, 0, domainSize, 20, color, 0.3 * progress, 'SOLID');

    ctx.restore();
}

export function drawSkillGroundIndicator(
    ctx: CanvasRenderingContext2D, 
    x: number, y: number, 
    color: string, 
    t: number, 
    progress: number, 
    skillRadius: number, 
    type: string, 
    isAOE: boolean
) {
    const pixelRadius = Math.max(1, skillRadius) * HEX_SIZE;
    const currentRadius = pixelRadius * progress;
    const opacity = 0.3 + Math.sin(t * 5) * 0.1;

    // Use volumetric for local skill indicator too
    SurfaceAssets.drawVolumetricHex(ctx, 0, 0, currentRadius, color, opacity);

    const ringSize = currentRadius * 2.5; 
    const ring = VFXFactory.getTexture('RING', color);

    ctx.save();
    ctx.scale(1, ISO_SCALE_Y); 
    ctx.globalCompositeOperation = 'screen';
    ctx.globalAlpha = opacity * 1.2;
    ctx.drawImage(ring, -ringSize/2, -ringSize/2, ringSize, ringSize);
    ctx.restore();
}

import { Agent, GameEngine } from "../game";
import { SpriteManager } from "../sprites";
import { Role, Team, MovementType } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { HEX_SIZE, UNIT_BODY_OFFSET } from "../../constants";
import { HexUtils, MapConfig } from "../utils";
import { STATUS_VISUALS } from "../../data/vfx/status_visuals";

// Modules
import { ImperialRenderer } from "../renderers/units/factions/ImperialRenderer";
import { CovenantRenderer } from "../renderers/units/factions/CovenantRenderer";
import { drawFlyingAnchor, drawFlightVFX, drawCastingVFX, drawSkillGroundIndicator, drawUltimateChantVFX } from "../renderers/units/UnitVisuals";

// Visual Constants
const MAX_UNIT_SIZE_RATIO = 0.85; 
const UNIT_REFERENCE_HEIGHT = 100; 

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            let terrainH = 0;
            if (agent.isMoving && agent.path.length > 0) {
                const h1 = getTerrainHeight(agent.q, agent.r);
                const nextHex = agent.path[0];
                const h2 = getTerrainHeight(nextHex.q, nextHex.r);
                terrainH = HexUtils.lerp(h1, h2, agent.moveProgress);
            } else {
                const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
                const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;
                if (distSq > 100) {
                    const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                    terrainH = getTerrainHeight(visualHex.q, visualHex.r);
                } else {
                    terrainH = getTerrainHeight(agent.q, agent.r);
                }
            }

            const visualGroundY = agent.py - terrainH;

            const op = renderList.next();
            op.type = RenderOpType.UNIT;
            op.y = agent.py + 1; 
            op.z = 10;
            op.agent = agent;
            op.tx = agent.px; 
            op.ty = visualGroundY;  
            op.th = terrainH; 
            op.time = globalTime;
            op.uSelected = (highlightAgent === agent);
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        let terrainH = 0;
        if (agent.isMoving && agent.path.length > 0) {
            const h1 = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const h2 = getTerrainHeight(nextHex.q, nextHex.r);
            terrainH = HexUtils.lerp(h1, h2, agent.moveProgress);
        } else {
            terrainH = getTerrainHeight(agent.q, agent.r);
        }

        const visualGroundY = agent.py - terrainH;
        this.drawAssembly(ctx, agent, agent.px, visualGroundY, globalTime, false, true);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const maxDimension = HEX_SIZE * 2 * MAX_UNIT_SIZE_RATIO;
        let roleScaleMod = 1.0;
        switch(agent.role) {
            case Role.TANK: roleScaleMod = 1.25; break; 
            case Role.WARRIOR: roleScaleMod = 1.1; break; 
            case Role.RANGER: roleScaleMod = 0.9; break; 
            case Role.MAGE: roleScaleMod = 0.9; break; 
            case Role.SUPPORT: roleScaleMod = 0.95; break;
        }
        const scaleFactor = (maxDimension / UNIT_REFERENCE_HEIGHT) * roleScaleMod;

        ctx.save();
        ctx.translate(drawX, drawY); 
        ctx.scale(scaleFactor, scaleFactor);

        const physX = agent.physics.x / scaleFactor;
        const physY = agent.physics.y / scaleFactor;
        const physZ = agent.physics.z / scaleFactor; 

        // 3. LAYER: GROUND
        if (!isSilhouette && agent.hp > 0 && agent.visualStatus !== 'POLYMORPH') {
            this.drawGroundElements(ctx, agent, physX, physY, physZ, globalTime);
        }

        // 4. LAYER: UNIT BODY ROOT
        ctx.save(); 
        ctx.translate(physX, physY - physZ); 
        ctx.rotate(agent.physics.angle); 

        // 6. LAYER: ANIMATED BODY
        this.drawBodyElements(ctx, agent, globalTime, isSilhouette, isSelected, scaleFactor);

        ctx.restore(); 

        // NOTE: Layer 7 (Status Effects) removed from here. 
        // It is now handled by StatusRenderLayer in the main Render Loop.

        ctx.restore(); 
    }

    private drawGroundElements(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number) {
        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        ctx.save();
        ctx.translate(px, py); 

        const shadowScale = Math.max(0.6, 1.0 - (pz / 400));
        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        ctx.save();
        const iconBaseY = -24; 
        ctx.translate(0, iconBaseY);
        const breath = Math.sin(t * 2) * 1.5;
        ctx.translate(0, breath);

        ctx.fillStyle = 'rgba(0,0,0,0.4)';
        ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

        ctx.globalAlpha = 1.0; 
        ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
        ctx.drawImage(assets.icon, -32, -32, 64, 64);
        ctx.restore();

        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                const visualRadius = isAOE ? 0.8 : radius;
                drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, visualRadius, skill.tag, isAOE);
            }
        }

        ctx.restore();

        if (agent.movementType === MovementType.FLYING && pz > 5) {
            drawFlyingAnchor(ctx, agent, t, px, py, pz);
        }
    }

    private drawBodyElements(ctx: CanvasRenderingContext2D, agent: Agent, t: number, isSilhouette: boolean, isSelected: boolean, scaleFactor: number) {
        let bodyFloat = -UNIT_BODY_OFFSET; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat -= Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat -= Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        let spawnAlpha = 1.0;
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            spawnAlpha = eased;
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= spawnAlpha;
        }

        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            drawFlightVFX(ctx, agent, t);
        }

        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill && skill.tag === 'ULT') {
                    drawUltimateChantVFX(ctx, agent, t);
                } else {
                    drawCastingVFX(ctx, agent, t);
                }
            }

            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                ctx.drawImage(ice, -48, -75, 96, 128);
                ctx.restore();
            }
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "./game";
import { HexUtils } from "./utils";
import { Hex, GameEvent, Skill } from "../types";

// Sub-systems
import { GridSystem } from "./systems/grid";
import { VFXSystem } from "./systems/vfx";
import { VFXRenderer } from "./systems/vfx/render";
import { UnitRenderSystem } from "./systems/unit";
import { HUDSystem } from "./systems/hud";
import { CameraSystem, Camera } from "./systems/CameraSystem";
import { VisualEventListener } from "./systems/VisualEventListener";

// Renderers & Pool
import { BackgroundRenderer } from "./renderers/background";
import { TacticalRenderer } from "./renderers/tactical";
import { HUDRenderer } from "./renderers/HUDRenderer";
import { StatusRenderLayer } from "./renderers/layers/StatusRenderLayer"; // NEW IMPORT
import { RenderList, RenderOpType, RenderOp } from "./renderers/RenderList";
import { SpriteManager } from "./sprites";
import { TerrainRenderer } from "./renderers/grid/TerrainRenderer";
import { GridOverlays } from "./renderers/grid/GridOverlays";
import { AssetManager } from "./assets";
import { ParticleRenderer } from "./systems/vfx/renderers/ParticleRenderer";
import { PostProcessor } from "./renderers/PostProcessor"; 

const OBSTACLE_HALF_WIDTH = 40;

export { Camera };

export class GameRenderer {
    public globalTime: number = 0;

    // Sub-systems
    public grid: GridSystem;
    public vfx: VFXSystem;
    private vfxRenderer: VFXRenderer;
    public unit: UnitRenderSystem;
    public statusLayer: StatusRenderLayer; // NEW LAYER
    public hud: HUDSystem;
    private hudRenderer: HUDRenderer;
    public camera: CameraSystem;
    private eventListener: VisualEventListener;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private postProcessor: PostProcessor;

    // Memory Pool
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor() {
        this.grid = new GridSystem();
        this.vfx = new VFXSystem();
        this.vfxRenderer = new VFXRenderer();
        this.unit = new UnitRenderSystem();
        this.statusLayer = new StatusRenderLayer(); // Init
        this.hud = new HUDSystem();
        this.hudRenderer = new HUDRenderer(); 
        this.camera = new CameraSystem();
        this.eventListener = new VisualEventListener();
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public reset() {
        this.vfx.reset();
        this.hud.reset();
        this.camera.reset();
        this.eventListener.reset();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    // --- Core Accessors ---

    public getTerrainHeight(q: number, r: number, engine: GameEngine): number {
        return this.grid.getTerrainHeight(q, r, engine);
    }

    public getHexAtScreenPoint(mouseX: number, mouseY: number, width: number, height: number, camera: Camera, engine: GameEngine): Hex | null {
        const cx = width / 2;
        const cy = height / 2;

        const wx = (mouseX - cx) / camera.zoom + camera.x;
        const wy = (mouseY - cy) / camera.zoom + camera.y;

        return this.grid.getHexAtWorldPoint(wx, wy, engine);
    }

    // --- Update Loop ---

    public update(dt: number, engine: GameEngine): void {
        this.globalTime += dt;
        this.camera.update(dt);
        this.tacticalRenderer.update(dt, engine);

        const getTerrainHeightPx = (x: number, y: number) => {
            const hex = HexUtils.fromPx(x, y, engine.mapConfig);
            return this.grid.getTerrainHeight(hex.q, hex.r, engine);
        };

        this.vfx.update(dt, this.globalTime, engine.currentScene.ambientType, getTerrainHeightPx);
        this.hud.update(dt);
    }

    public processEventsWithEngine(events: GameEvent[], engine: GameEngine): void {
        this.eventListener.process(
            events, 
            engine, 
            this.vfx, 
            this.hud, 
            this.grid, 
            this.camera
        );
    }

    // --- Main Rendering Loop ---

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, this.globalTime);

        // 4. Camera Transform
        ctx.save();
        this.camera.sync(camera); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.grid.getTerrainHeight(q, r, engine);

        // Collect
        this.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            this.globalTime
        );

        this.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase
        );

        this.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            this.globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (Now utilizing strictly logical Y for stability)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            // PIXEL SNAPPING: Strictly align all translation anchors to integer coordinates
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlockGeometry(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, this.globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, snapX, snapY - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, snapX - OBSTACLE_HALF_WIDTH, snapY);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);

                        if (p.targetX !== undefined && p.targetY !== undefined) {
                            const origTx = p.targetX;
                            const origTy = p.targetY;
                            p.targetX = origTx - snapX;
                            p.targetY = (origTy - (p.targetZ || 0)) - snapY;
                            ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                            p.targetX = origTx;
                            p.targetY = origTy;
                        } else {
                            ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                        }
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    this.drawProjectile(ctx, op);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    this.globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. STATUS LAYER PASS (NEW: Dedicated Channel)
        // Draws persistent effects (Shields, CC) on top of units but below UI overlay
        this.statusLayer.draw(ctx, engine.agents, this.globalTime);

        // 8. Top VFX (Particles above everything)
        this.vfxRenderer.drawTopLayerParticles(ctx, this.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.camera.getTrauma(), transitionAberration);

        ctx.save(); 
        this.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.grid, this.globalTime);

        this.hudRenderer.draw(ctx, this.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, this.globalTime);

        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, this.globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }

    private drawProjectile(ctx: CanvasRenderingContext2D, op: RenderOp) {
        // --- VECTOR BEAM REFACTOR (Moving High-Speed Projectiles) ---
        const isRay = op.pSkillVis === 'BEAM'; 

        if (isRay && op.pTrail && op.pTrail.length > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';

            const start = op.pTrail[op.pTrail.length - 1]; 
            const end = { x: op.pVisX, y: op.pVisY };
            const dx = end.x - start.x;
            const dy = end.y - start.y;
            const len = Math.sqrt(dx*dx + dy*dy);
            const angle = Math.atan2(dy, dx);

            // 1. Energetic Core Beam
            const grad = ctx.createLinearGradient(start.x, start.y, end.x, end.y);
            grad.addColorStop(0, 'rgba(0,0,0,0)');
            grad.addColorStop(0.2, op.pColor);
            grad.addColorStop(0.8, op.pColor);
            grad.addColorStop(1, '#fff');

            ctx.strokeStyle = grad;
            ctx.lineWidth = op.pIsUlt ? 6 : 3;
            ctx.lineCap = 'round';
            ctx.globalAlpha = 1.0;
            ctx.beginPath();
            ctx.moveTo(Math.round(start.x), Math.round(start.y));
            ctx.lineTo(Math.round(end.x), Math.round(end.y));
            ctx.stroke();

            // 2. Shock Rings (Mach Cones)
            if (len > 20) {
                const ringCount = Math.floor(len / 30);
                ctx.translate(start.x, start.y);
                ctx.rotate(angle);
                ctx.strokeStyle = op.pColor;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.6;

                for(let i=1; i<=ringCount; i++) {
                    const x = i * 30 - (this.globalTime * 200 % 30); 
                    if (x > 0 && x < len) {
                        ctx.beginPath();
                        ctx.ellipse(x, 0, 3, 10, 0, 0, Math.PI*2);
                        ctx.stroke();
                    }
                }
            }

            // 3. Bloom
            ctx.shadowColor = op.pColor;
            ctx.shadowBlur = 15;
            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = op.pIsUlt ? 16 : 8;
            ctx.globalAlpha = 0.3;
            ctx.stroke();
            ctx.shadowBlur = 0;

            ctx.restore();
            return;
        }

        // --- STANDARD SPRITE PROJECTILE ---
        if (op.pTrail && op.pTrail.length > 1) {
            ctx.save();
            ctx.globalCompositeOperation = 'lighter';
            ctx.beginPath();
            const trail = op.pTrail;
            ctx.moveTo(Math.round(trail[0].x), Math.round(trail[0].y));
            for(let i=1; i<trail.length; i++) {
                ctx.lineTo(Math.round(trail[i].x), Math.round(trail[i].y));
            }
            ctx.strokeStyle = op.pColor;
            ctx.lineWidth = 3;
            ctx.lineCap = 'round';
            ctx.stroke();
            ctx.restore();
        }

        const shadowAltitude = op.pVisShadowY - op.pVisY; 
        if (Math.abs(shadowAltitude) > 5) {
            ctx.save();
            ctx.translate(Math.round(op.pVisX), Math.round(op.pVisShadowY));
            const shadowAlpha = Math.max(0, 0.4 - Math.abs(shadowAltitude)/800);
            ctx.scale(1, 0.5); 
            ctx.fillStyle = `rgba(0,0,0,${shadowAlpha})`;
            ctx.beginPath(); ctx.arc(0, 0, 15, 0, Math.PI*2); ctx.fill();
            ctx.restore();
        }

        ctx.save();
        ctx.translate(Math.round(op.pVisX), Math.round(op.pVisY));
        if (op.pSpin !== 0) ctx.rotate(op.pSpin); 
        else ctx.rotate(op.pAngle);

        const img = AssetManager.getProjectile(op.pSkillVis, op.pColor);
        if (img && img.width > 0) {
            let scale = 0.6;
            if (op.pIsUlt) scale = 1.0;
            ctx.scale(scale, scale);
            ctx.drawImage(img, -48, -32, 96, 64);
        }
        ctx.restore();
    }
}

import React, { useRef, useState, useEffect } from 'react';
import { MatrixConfig, LayoutPreset } from './showcase/types';
import { DEFAULT_MATRIX_CONFIG } from './showcase/defaults';
