// Constants
export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];

    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }

    get logs() { return this.logger.logs; }

    public events: GameEvent[] = [];
    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;

    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    // Time & Victory Proxies
    get timeScale() { return this.time.timeScale; }
    set timeScale(v: number) { this.time.timeScale = v; }
    get targetTimeScale() { return this.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.time.targetTimeScale = v; }
    get battleTime() { return this.time.battleTime; }
    set battleTime(v: number) { this.time.battleTime = v; }

    get isFinishing() { return this.victory.isFinishing; }
    get victoryTimer() { return this.victory.victoryTimer; }
    get winningTeam() { return this.victory.winningTeam; }

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public agentMap: Map<number, Agent> = new Map();

    // Systems
    public movement: MovementSystem;
    public physics: PhysicsSystem; 
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public hazards: HazardSystem; // New
    public ai: AISystem;
    public agentManager: AgentManager;
    public announcer: AnnouncerSystem; 
    public director: DirectorSystem;
    public logger: BattleLogger; 
    public time: TimeSystem; 
    public victory: VictorySystem; 
    public zones: ZoneSystem; 

    get directorTargetId() { return this.director.targetId; }

    constructor() {
        this.movement = new MovementSystem();
        this.physics = new PhysicsSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.hazards = new HazardSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.announcer = new AnnouncerSystem(); 
        this.director = new DirectorSystem();
        this.logger = new BattleLogger();
        this.time = new TimeSystem();
        this.victory = new VictorySystem();
        this.zones = new ZoneSystem();
        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }
    randomizeEnvironment() { this.map.randomizeEnvironment(this); }
    rebuildMap() { this.map.rebuildMap(this); }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        const oldH = this.map.getTerrainHeight(agent.q, agent.r);
        const newH = this.map.getTerrainHeight(newQ, newR);
        const deltaH = oldH - newH;

        agent.physics.z += deltaH;

        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.time.reset();
            this.logger.clear();
            this.victory.reset();
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    stop() { this.isRunning = false; }

    restart() {
        this.stop();
        this.victory.reset();
        this.time.reset();
        this.agentMap.clear();
        this.hazards.reset();
        this.announcer.reset(); 
        this.director.reset();

        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });

        this.events = []; 
        this.combat.reset(); 

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); 
            this.renderer.vfx.reset(); 
        }

        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.hazards.reset();
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.announcer.reset();
        this.director.reset();

        this.combat.reset(); 
        this.events = [];

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }

        this.logger.clear();

        if (!keepScene) this.map.randomizeEnvironment(this); 
        else this.map.rebuildMap(this); 

        this.bus.emit('GAME_CLEAR', {});
    }

    tick(dt: number) {
        if (!this.isRunning) return;

        this.time.update(dt);
        this.events.length = 0;
        this.director.update(dt, this);
        this.zones.update(this); 

        // Check Victory
        if (this.victory.check(this)) {
            this.victory.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }

        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        // 1. Physics (Global)
        this.physics.update(dt, this);

        // 2. Logic
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            this.status.update(a, dt, this);

            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        // 3. Combat
        this.combat.update(dt, this);
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill } from "../../../types";

export const HazardManager = {

    spawnHazards(source: Agent, cells: {q: number, r: number}[], skill: Skill, engine: GameEngine) {
        const dur = skill.ccDur || 5.0;
        let hType: any = null;

        // Map Skill Properties to Hazard Types
        if (skill.ccType === 'DOT') hType = 'POISON';
        if (skill.element === 'FIRE') hType = 'FIRE';
        if (skill.element === 'ICE') hType = 'ICE';
        if (skill.element === 'VOID' || skill.ccType === 'PULL') hType = 'GRAVITY';

        if (hType) {
            cells.forEach(tile => {
                engine.hazards.addHazard(
                    tile.q, tile.r, 
                    hType, 
                    dur, 
                    source.id, 
                    source.team, 
                    skill.color,
                    (Math.abs(skill.power) * 0.2) || 10, 
                    0.5,
                    engine 
                );
            });
        }
    }
};

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            const offsetY = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            const drawY = d.y + offsetY;
            if (drawY > d.y + 800) return;

            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; // Reuse tx/ty for pos
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        // 2. Physical Particles (Sorted with World)
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;
            // Only Physical types that should be occluded by units
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX'].includes(p.type)) {

                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (offset > 800) return;

                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);

                const op = renderList.next();
                op.type = RenderOpType.VFX;

                // V6.1 FIX: Use correct sorting by Ground Y, but draw at Visual Y
                // Visual Y = GroundY - Height(z)
                op.y = p.y + offset; // Sort Key (Ground Level)
                op.z = 5;
                op.sortBias = p.sortBias || 0; 

                // Z-FIGHTING FIX: Lift giant flat effects slightly
                let visualLift = 0;
                if (p.type === 'GIANT_HEX' || p.type === 'GRID_FIELD' || p.type === 'DOMAIN') {
                    visualLift = 5; 
                }

                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaos;
                op.tx = p.x;
                op.ty = p.y + offset - p.z - visualLift; // Drawing Y
                op.th = p.z; // Height used for shadow calc
            }
        });

        // 3. Projectiles (Delegated)
        ProjectileRenderer.submit(renderList, engine, getTerrainHeight, transitionT, transitionPhase);
    }

    // Items here are drawn ON TOP of everything (Overlay VFX like flashes, text, magic circles)
    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            // Filter out physicals already drawn
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (offset > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            ParticleRenderer.drawSingleParticle(ctx, p, p.x, drawY, progress, isChaos);
        });
    }
}

import { ZoneRenderer } from "./ZoneRenderer";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

interface ZoneInfo {
    type: 'CAST';
    color: string;
    visual: string; // Skill visual tag
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face Y
        size: number,

        // State Props
        specialStatus: string | undefined, 
        zoneInfo: ZoneInfo | undefined,    

        // Lighting
        lightColor: string | null,
        lightIntensity: number,

        // Interactive
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        // Metadata
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        // --- LAYER 1: HAZARDS ---
        if (hazard) {
            ZoneRenderer.drawHazard(ctx, x, y, hazard, globalTime);
        }

        // --- LAYER 2: UNIT STATUS FLOOR TINT ---
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                // Use source-over for tinted glass look instead of additive
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill();
                ctx.restore();
            }
        }

        // --- LAYER 3: CAST ZONES (Volumetric) ---
        if (zoneInfo) {
            ZoneRenderer.drawZone(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // --- LAYER 4: DYNAMIC LIGHTING ---
        // Reduced intensity to prevent overexposure
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen'; // Screen is safer than lighter
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4); 
            ctx.fillStyle = lightColor;
            HexGeometry.traceHex(ctx, x, y, size);
            ctx.fill();
            ctx.restore();
        }

        // --- LAYER 5: INTERACTIVE UI HIGHLIGHTS ---
        if (isRange || isHover || hasUnit) {
            ctx.save();

            // Use 'screen' for light projection look instead of flat paint
            ctx.globalCompositeOperation = 'screen';

            // Valid Move/Skill Range
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill();

                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.5; 
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke();
            }

            // Mouse Hover - Bright Spotlight
            if (isHover) { 
                ctx.fillStyle = '#ffffff'; 
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill(); 

                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke(); 
            }

            // Unit Position - Subtle selection ring
            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, x, y, size * 0.9);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, TERRAIN_THEMES, ISO_SCALE_Y } from "../../constants";
import { GameEngine, Agent } from "../game";
import { HexUtils, getTransitionOffset } from "../utils";
import { HexMath } from "../math/HexMath";
import { Hex, Skill, Projectile, Team } from "../../types";
import { RenderList, RenderOpType } from "../renderers/RenderList";

interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
    key: string;
}

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 

export class GridSystem {
    private _tileMap: Map<string, CachedTile> = new Map();
    private _tileList: CachedTile[] = []; 
    private _lastMapVersion: number = -1;
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public reset() {
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        this._lastMapVersion = -1; 
    }

    getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    private ensureCache(engine: GameEngine) {
        if (this._lastMapVersion !== engine.mapVersion || this._tileList.length === 0) {
            this.rebuildTileCache(engine);
        }
    }

    private rebuildTileCache(engine: GameEngine) {
        this._tileList = [];
        this._tileMap.clear();
        this._lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);
            const tile = { q, r, px: pos.x, py: pos.y, h, key: k };
            this._tileList.push(tile);
            this._tileMap.set(k, tile);
        });
    }

    public getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        this.ensureCache(engine);
        const maxHeight = 200; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;

        for (let h = 0; h <= maxHeight; h += step) {
            const testY = wy + h; 
            const frac = HexMath.pixelToHex(wx, testY, engine.mapConfig.offsetX, engine.mapConfig.offsetY);
            const rounded = HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));

            const key = HexUtils.key(rounded);
            const tile = this._tileMap.get(key);

            if (tile) {
                const tileVisualY = tile.py - tile.h;
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - tileVisualY);

                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    if (tile.h >= h - step && tile.h <= h + step) {
                         if (!bestHex || tile.h > (this._tileMap.get(HexUtils.key(bestHex))?.h || -999)) {
                             bestHex = rounded;
                         }
                    }
                }
            }
        }
        return bestHex;
    }

    getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];
        engine.agents.forEach(a => {
            if (a.hp <= 0 && a.fullyDead) return;
            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const uHeight = engine.map.getTerrainHeight(a.q, a.r);
            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});
            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    if (nPx.y > uPx.y) {
                         if (engine.map.getTerrainHeight(n.q, n.r) > uHeight) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        });
        return occluded;
    }

    submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.ensureCache(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // Update Unit Presence map for overlays
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const PROJ_LIGHT_RADIUS_SQ = 1600; 

        // 2. Iterate Tiles
        for (let i = 0; i < this._tileList.length; i++) {
            const tile = this._tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            const visualY = py + offset;

            if (offset > 800) continue;

            const sortY = py; 

            // Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualY - h - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // Zones (Delegated to ZoneSystem)
            let zoneInfo = undefined;
            const zResult = engine.zones.getZoneAt(q, r);
            if (zResult) {
                const { zone, dist } = zResult;
                zoneInfo = { 
                    type: zone.type, 
                    color: zone.color, 
                    visual: zone.visual, 
                    progress: zone.progress, 
                    centerQ: zone.q, 
                    centerR: zone.r, 
                    radius: zone.radius, 
                    dist 
                };
            }

            // Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const bonus = Math.max(0, Math.floor((agentH - h) / BLOCK_HEIGHT));
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            // Updated to use engine.hazards
            const hazard = engine.hazards.getHazardAt(q, r);

            // Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // Create Render Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0;
            op.tx = px; 
            op.ty = visualY; 
            op.th = h;
            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillResolutionSystem } from "./SkillResolutionSystem";
import { PROJECTILE_VISUALS } from "../../../data/vfx/projectile_visuals";
import { UNIT_BODY_OFFSET } from "../../../constants";

export class ProjectileSystem {
    public projectiles: Projectile[] = [];

    public update(dt: number, engine: GameEngine, skillResolver: SkillResolutionSystem) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            // 1. Resolve Definition
            const def = PROJECTILE_VISUALS[p.skill.id] || PROJECTILE_VISUALS[p.skill.visual || 'BOLT'];
            const isInstant = def ? def.trajectory === 'INSTANT' : false;

            // LOGICAL RAY DETECTION
            // High velocity skills or INSTANT trajectory move instantly
            const moveInstantly = isInstant || p.skill.projectileSpeed > 1400;

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = moveInstantly ? 4000 * dt : p.speed * dt;

            // Update trail before moving
            const lastTrail = p.trail.length > 0 ? p.trail[p.trail.length - 1] : null;
            if (!lastTrail || Vector.dist(lastTrail, {x: p.x, y: p.y}) > 10) {
                p.trail.push({x: p.x, y: p.y});
                if (p.trail.length > 12) p.trail.shift(); 
            }

            // Reach target?
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId);

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const radius = p.skill.aoeRadius || 1;
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);

                    targets.forEach(t => { 
                        if (source) skillResolver.resolveHit(source, t, p.skill, hitPos, engine); 
                    });

                    if (p.skill.ccType === 'DOT' || p.skill.name.includes("霧") || p.skill.name.includes("雨")) {
                        if (source) {
                            const centerHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                            const affectedTiles = HexUtils.range(centerHex, radius);
                            const dur = p.skill.ccDur || 5.0;
                            let hType: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC' = 'GENERIC';

                            if (p.skill.ccType === 'DOT') hType = 'POISON';
                            if (p.skill.name.includes('火') || p.skill.name.includes('Lava')) hType = 'FIRE';
                            if (p.skill.name.includes('冰') || p.skill.name.includes('Frost')) hType = 'ICE';

                            affectedTiles.forEach(tile => {
                                engine.hazards.addHazard(
                                    tile.q, tile.r, 
                                    hType, 
                                    dur, 
                                    source.id, 
                                    source.team, 
                                    p.skill.color,
                                    (p.skill.power * 0.2) || 10, 
                                    0.5,
                                    engine 
                                );
                            });
                        }
                    }
                    engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) skillResolver.resolveHit(source, target, p.skill, undefined, engine);
                    }
                }
                engine.events.push({ type: 'PROJECTILE_HIT', pos: p.targetPos, skill: p.skill });

                this.removeProjectile(i);
            } else {
                const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    private removeProjectile(idx: number) {
        const lastIdx = this.projectiles.length - 1;
        if (idx !== lastIdx) this.projectiles[idx] = this.projectiles[lastIdx];
        this.projectiles.pop();
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let targetPos = {x: 0, y: 0};
        let tid = "";

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 targetPos = p; tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 targetPos = {x: source.target.px, y: source.target.py}; tid = source.target.id;
             } else return;
             this.createProjectile(source, skill, targetPos, tid);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });
        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                targetPos = {x: source.target.px, y: source.target.py};
                this.createProjectile(source, skill, targetPos, source.target.id);
                engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: source.target.id });
            }
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string) {
        this.projectiles.push({
            id: Math.random().toString(36).substr(2, 6),
            x: source.px, y: source.py, 
            startX: source.px, startY: source.py, 
            // FIXED: Start Z includes Body Offset to launch from chest, not feet
            startZ: source.physics.z + UNIT_BODY_OFFSET, 
            targetId, targetPos,
            speed: skill.projectileSpeed || 600, skill, sourceId: source.id, team: source.team, trail: []
        });
    }
}

import { Agent } from "../../../../game";
import { Team } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const ShieldPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#bae6fd' : '#f87171'; // Cyan vs Red tint

        // Shield Pulse based on % remaining
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));
        const pulse = 0.2 + (pct * 0.3) + Math.sin(t * 3) * 0.1;

        ctx.save();
        ctx.translate(x, y - z); // Ground level anchor

        // Volumetric Prism Shell
        // Height 90 covers most standard units
        VolumePainter.draw3DPrism(ctx, 0, 0, 35, 90, color, pulse, 'SOLID');

        // Inner Core Ripple (Tech Ring)
        ctx.translate(0, -45); // Center mass
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.ellipse(0, 0, 25, 12, 0, 0, Math.PI*2);
        ctx.stroke();

        // Vertical Energy Line
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(0, 40);
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { UNIT_BODY_OFFSET } from "../../../../../constants";
import { AssetManager } from "../../../assets";
import { STATUS_VISUALS } from "../../../../../data/vfx/status_visuals";

export const OverheadPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        // Priority System: Only show most severe CC
        let type = '';
        if (agent.stunTimer > 0) type = 'STUN';
        else if (agent.fearTimer > 0) type = 'FEAR';
        else if (agent.tauntTimer > 0) type = 'TAUNT';
        else if (agent.silenceTimer > 0) type = 'SILENCE';
        else if (agent.blindTimer > 0) type = 'BLIND';

        if (!type) return;

        const icon = AssetManager.getStatusIcon(type);
        if (!icon) return;

        // Bobbing Animation
        const bob = Math.sin(t * 6) * 5;
        const anchorY = y - z - UNIT_BODY_OFFSET - 60 + bob; // Approx 60px above body center

        ctx.save();
        ctx.translate(x, anchorY);

        // Glow Backing
        const def = STATUS_VISUALS[type];
        const color = def?.primaryColor || '#fff';

        ctx.shadowColor = color;
        ctx.shadowBlur = 15;

        // Draw Icon
        ctx.drawImage(icon, -24, -24, 48, 48);

        // Extra "Dizzy" stars for Stun
        if (type === 'STUN') {
            ctx.rotate(t * 2);
            ctx.fillStyle = '#fff';
            for(let i=0; i<3; i++) {
                const a = i * (Math.PI*2/3);
                const sx = Math.cos(a) * 20;
                const sy = Math.sin(a) * 20;
                ctx.beginPath(); ctx.arc(sx, sy, 3, 0, Math.PI*2); ctx.fill();
            }
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const GroundEffectPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        // ROOT (Chain/Vines)
        if (agent.rootTimer > 0) {
            const color = '#fbbf24'; // Amber
            ctx.save();
            ctx.translate(x, y - z); // Anchor to feet position visually

            // Dynamic pulsing ring
            const pulse = 0.8 + Math.sin(t * 10) * 0.2;
            VolumePainter.drawHexRipple(ctx, 0, 0, 20, color, pulse, 2);

            // 3D Spikes (Simulated)
            ctx.fillStyle = color;
            ctx.globalCompositeOperation = 'source-over'; // Solid

            for(let i=0; i<3; i++) {
                const angle = i * (Math.PI*2/3) + t;
                const r = 18;
                const sx = Math.cos(angle) * r;
                const sy = Math.sin(angle) * r * ISO_SCALE_Y;

                ctx.beginPath();
                ctx.moveTo(sx, sy);
                ctx.lineTo(sx, sy - 25); // Spike tip up
                ctx.lineTo(sx + 6, sy + 3);
                ctx.fill();
            }
            ctx.restore();
        }
    }
};

import { Agent } from "../../../../game";
import { AssetManager } from "../../../assets";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const StateModelPainter = {
    drawBanishment(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (!agent.banished) return;

        const isStasis = agent.visualStatus === 'STASIS';
        const color = isStasis ? '#facc15' : '#c084fc'; // Gold or Purple
        const height = 110; 

        ctx.save();
        ctx.translate(x, y - z);

        // Use VolumePainter for high-quality Prism
        // Opacity oscillation
        const opacity = 0.4 + Math.sin(t * 2) * 0.1;
        VolumePainter.draw3DPrism(ctx, 0, 0, 40, height, color, opacity, 'SOLID');

        // Lock Icon Floating inside
        const icon = AssetManager.getStatusIcon(isStasis ? 'STASIS' : 'BANISH');
        if (icon) {
            ctx.translate(0, -height/2);
            const floatY = Math.sin(t * 3) * 5;
            ctx.translate(0, floatY);
            ctx.scale(0.8, 0.8);
            ctx.globalCompositeOperation = 'overlay';
            ctx.drawImage(icon, -24, -24);
        }

        ctx.restore();
    }
};

import { Agent } from "../../game";
import { ShieldPainter } from "./painters/ShieldPainter";
import { OverheadPainter } from "./painters/OverheadPainter";
import { GroundEffectPainter } from "./painters/GroundEffectPainter";
import { StateModelPainter } from "./painters/StateModelPainter";

export class StatusOrchestrator {

    public draw(ctx: CanvasRenderingContext2D, agents: Agent[], globalTime: number) {
        for (const agent of agents) {
            if (agent.hp <= 0 && agent.fullyDead) continue;

            const px = agent.px;
            const py = agent.py; 
            const pz = agent.physics.z; 

            // Banish hides everything else, render it and skip the rest
            if (agent.banished) {
                StateModelPainter.drawBanishment(ctx, agent, px, py, pz, globalTime);
                continue;
            }

            // Standard Layers
            GroundEffectPainter.draw(ctx, agent, px, py, pz, globalTime);
            ShieldPainter.draw(ctx, agent, px, py, pz, globalTime);
            OverheadPainter.draw(ctx, agent, px, py, pz, globalTime);
        }
    }
}

