import React, { useRef, useState, useEffect } from 'react';
import { MatrixConfig, LayoutPreset } from './showcase/types';
import { DEFAULT_MATRIX_CONFIG } from './showcase/defaults';
import { useMatrixRain } from './showcase/useMatrixRain';
import { ShowcaseSettings } from './showcase/ShowcaseSettings';
import { Icons } from './icons';

interface ShowcaseOverlayProps {
    onEnter: () => void;
    timeScale: number;
    setTimeScale: (v: number) => void;
}

export const ShowcaseOverlay: React.FC<ShowcaseOverlayProps> = ({ onEnter, timeScale, setTimeScale }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [config, setConfig] = useState<MatrixConfig>(DEFAULT_MATRIX_CONFIG);
    const [layout, setLayout] = useState<LayoutPreset>('BOTTOM_CENTER');
    const [showSettings, setShowSettings] = useState(false);

    // Track window size for canvas init
    const [viewport, setViewport] = useState({ w: window.innerWidth, h: window.innerHeight });

    useEffect(() => {
        const handleResize = () => setViewport({ w: window.innerWidth, h: window.innerHeight });
        window.addEventListener('resize', handleResize);
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    // Hook: Handles the Matrix Rain rendering on the transparent canvas
    useMatrixRain(canvasRef, config, viewport.w, viewport.h);

    // Helper: Determine UI Layout classes
    const getLayoutClasses = () => {
        switch (layout) {
            case 'CENTER': 
                return 'inset-0 flex-col justify-center items-center text-center p-4 md:p-8';
            case 'BOTTOM_CENTER': 
                return 'bottom-12 left-0 right-0 mx-auto w-full max-w-[calc(100vw-4rem)] md:max-w-5xl flex-col md:flex-row justify-between items-center';
            case 'BOTTOM_LEFT': 
                return 'bottom-10 left-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-start';
            case 'BOTTOM_RIGHT': 
                return 'bottom-10 right-6 w-[min(320px,90vw)] md:w-[400px] flex-col justify-end items-end text-right';
            default: 
                return 'inset-0 justify-center items-center';
        }
    };

    const isCompact = layout !== 'CENTER';
    const isWideBar = layout === 'BOTTOM_CENTER';

    const getRgbaBg = (hex: string, alpha: number) => {
        const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        if (!result) return `rgba(0,0,0,${alpha})`;
        const r = parseInt(result[1], 16);
        const g = parseInt(result[2], 16);
        const b = parseInt(result[3], 16);
        return `rgba(${r}, ${g}, ${b}, ${alpha})`;
    };

    return (
        <div className="absolute inset-0 z-50 overflow-hidden pointer-events-none">

            {/* LAYER 1: Background Color Overlay */}
            <div 
                className="absolute inset-0 transition-colors duration-300"
                style={{ backgroundColor: getRgbaBg(config.bgColor, config.enabled ? config.bgOpacity : 0) }}
            ></div>

            {/* LAYER 2: Matrix Rain Canvas */}
            <canvas 
                ref={canvasRef} 
                className="absolute inset-0 block w-full h-full pointer-events-none mix-blend-screen"
            />

            {/* LAYER 3: CRT Scanline / Vignette Effects */}
            {config.enabled && config.bgOpacity > 0.1 && (
                <>
                    <div className="absolute inset-0 bg-[url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjMDAwIiAvPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSIxIiBmaWxsPSJyZ2JhKDI1NSwgMjU1LDI1NSwgMC4wNSkiIC8+Cjwvc3ZnPg==')] opacity-30 pointer-events-none"></div>
                    <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(0,0,0,0.4)_90%)] pointer-events-none"></div>
                </>
            )}

            {/* LAYER 4: UI Content */}
            <div className={`absolute z-[55] flex animate-slide-up pointer-events-none transition-all duration-500 ${getLayoutClasses()}`}>

                {/* Main Liquid Card */}
                <div className={`liquid-card p-8 md:p-10 pointer-events-auto flex max-w-full ${isWideBar ? 'w-full flex-col md:flex-row items-center gap-8' : 'flex-col items-center gap-8 w-full'}`}>

                    {/* Content Text */}
                    <div className={`relative flex flex-col max-w-full ${isWideBar ? 'items-center md:items-start text-center md:text-left flex-1' : (layout.includes('RIGHT') ? 'items-end' : 'items-center')}`}>

                        {/* Header Badge */}
                        <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-cyan-950/30 border border-cyan-500/30 text-[10px] text-cyan-400 font-mono tracking-widest mb-4 shadow-[0_0_10px_rgba(6,182,212,0.2)]">
                            <span className="w-1.5 h-1.5 rounded-full bg-cyan-400 animate-pulse box-shadow-[0_0_5px_cyan]"></span>
                            <span>SYSTEM_READY // V6.5.0</span>
                        </div>

                        <h1 className={`font-black text-transparent bg-clip-text bg-gradient-to-b from-white via-cyan-100 to-cyan-500 font-mono tracking-tighter drop-shadow-[0_0_30px_rgba(6,182,212,0.5)] ${isCompact ? 'text-5xl' : 'text-7xl md:text-8xl'}`}>
                            TACTICAL.OS
                        </h1>

                        <div className="text-slate-400 font-mono text-xs tracking-[0.4em] uppercase mt-3 opacity-80 mix-blend-plus-lighter">
                            Neural Battle Simulation
                        </div>
                    </div>

                    {/* Start Button */}
                    <div className={`relative shrink-0 ${isCompact && !isWideBar ? 'w-full' : ''}`}>
                        <button 
                            onClick={onEnter}
                            className={`group liquid-btn-primary rounded-2xl overflow-hidden transition-all duration-300 ${isWideBar ? 'px-16 py-6 w-full md:w-auto text-xl' : 'w-full px-12 py-5 text-lg'} shadow-[0_0_30px_rgba(6,182,212,0.2)]`}
                        >
                            <span className="relative flex items-center justify-center gap-4 z-10">
                                <span>INITIALIZE</span>
                                <Icons.Play className="w-5 h-5 fill-current group-hover:translate-x-1 transition-transform" />
                            </span>
                        </button>
                    </div>
                </div>
            </div>

            {/* LAYER 5: Controls */}
            <div className="absolute top-6 left-6 z-[60] pointer-events-auto">
                <button 
                    onClick={() => setShowSettings(!showSettings)}
                    className={`liquid-icon-btn hover:text-cyan-400 hover:border-cyan-500/50 hover:bg-white/10 ${showSettings ? 'text-cyan-400 border-cyan-500/50 bg-white/10' : 'text-slate-400'}`}
                    title="特效設定"
                >
                    <Icons.Settings className={`w-5 h-5 ${showSettings ? 'animate-spin-slow' : ''}`} />
                </button>
            </div>

            <ShowcaseSettings 
                show={showSettings} 
                onClose={() => setShowSettings(false)}
                config={config} 
                setConfig={setConfig} 
                timeScale={timeScale}
                setTimeScale={setTimeScale}
                layout={layout}
                setLayout={setLayout}
            />
        </div>
    );
};

import { GameEvent } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";

// Architects & Effects
import { UltArchitect } from "./UltArchitect";
import { SkillArchitect } from "./SkillArchitect";
import { UnitShatter } from "./effects/UnitShatter";

interface Point3D { x: number; y: number; z: number; }

export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        // Calculate Origin & Target in 3D Space
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        // Calculate pure Ground Z for the target location (for floor-snapping effects)
        const groundZ = grid.getTerrainHeight(
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).q,
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).r,
            engine
        );

        // Fallback for non-unit targets (ground click)
        if (!event.targetId) target.z = groundZ + 20;

        switch (event.type) {
            case 'VISUAL_SLASH':
            case 'VISUAL_BEAM':
                // Visual Events trigger full cinematic scripts
                this.playCinematicEffect(event, engine, vfx, grid, camera, origin, target);
                break;

            case 'DAMAGE': 
                // Damage only triggers Hit VFX, never scripts (prevent shake spam)
                if (!event.skill?.projectileSpeed) {
                    this.playHitVFX(event, vfx, target, groundZ);
                }
                break;

            case 'PROJECTILE_HIT': 
                // Projectiles trigger impact.
                if (event.skill?.type !== 'AOE') {
                    this.playHitVFX(event, vfx, target, groundZ);
                    camera.addTrauma(0.05); 
                } else {
                    // Direct hit for AOE projectile contact (spark only)
                    vfx.playEffect('FX_HIT_GENERIC', event.pos.x, event.pos.y, groundZ + 5, event.skill?.color, groundZ);
                }
                break;

            case 'IMPACT_AOE':
                // AOE Centers trigger scripts
                this.handleAOE(event, engine, vfx, grid, camera, groundZ);
                break;

            case 'DEATH':
                const dAgent = engine.agents.find(a => a.id === event.sourceId);
                if (dAgent) {
                    // Death occurs at body center
                    UnitShatter.spawn(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
                }
                camera.addTrauma(0.1); 
                break;

            case 'SPAWN':
                // Teleport is a floor-to-sky effect, verify groundZ
                vfx.playEffect('FX_TELEPORT', origin.x, origin.y, groundZ, event.color, groundZ);
                break;

            case 'CAST_BREAK':
                vfx.playEffect('FX_CAST_BREAK', origin.x, origin.y, origin.z, event.color);
                if (event.skill && event.skill.tag === 'ULT') {
                    camera.addTrauma(0.4);
                } else {
                    camera.addTrauma(0.15); 
                }
                break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        // If ID not found, check if there is an agent at that location spatially
        if (!agent && !agentId) {
            const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
            agent = engine.getAgentAt(hex.q, hex.r);
        }

        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                // Critical: Target is Chest Height, not feet
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);
        return { x: defaultX, y: defaultY, z: terrainH };
    }

    private playCinematicEffect(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, camera: CameraSystem, origin: Point3D, target: Point3D) {
        const skill = event.skill;
        if (!skill) return;

        // 1. Try Ult Script
        if (skill.tag === 'ULT') {
             if (UltArchitect.play(skill.id, target, engine, vfx, grid, camera, event.sourceId)) return;
        }

        // 2. Try Skill Script
        if (SkillArchitect.play(skill.id, target, engine, vfx, grid, camera, event.sourceId)) return;

        // 3. Fallback (If no script found)
        if (event.type === 'VISUAL_SLASH') {
            vfx.playBeam('SLASH_CONNECT', origin, target, event.color || '#fff', 0.2);
        } else {
            vfx.playBeam('GENERIC_BEAM', origin, target, event.color || '#fff', 0.4);
            // Pass origin.z - UNIT_BODY_OFFSET as approximate groundZ if needed, but hit effect resolves its own ground
            const groundZ = Math.max(0, target.z - UNIT_BODY_OFFSET);
            this.playHitVFX(event, vfx, target, groundZ);
        }
    }

    private playHitVFX(event: GameEvent, vfx: VFXSystem, target: Point3D, groundZ: number) {
        const skill = event.skill;
        const color = event.color || '#fff';

        let effectId = 'FX_HIT_GENERIC';
        if (skill && skill.visualHitEffect && VFX_REGISTRY[skill.visualHitEffect]) {
            effectId = skill.visualHitEffect;
        }

        // Pass groundZ separately so the player knows where the floor is for shockwaves
        vfx.playEffect(effectId, target.x, target.y, target.z, color, groundZ);
    }

    private handleAOE(event: GameEvent, engine: GameEngine, vfx: VFXSystem, grid: GridSystem, camera: CameraSystem, groundZ: number) {
        if (!event.skill) return;

        // AOE Center is usually slightly above ground
        const centerPt = { x: event.pos.x, y: event.pos.y, z: groundZ + 5 };

        // Scripts
        if (UltArchitect.play(event.skill.id, centerPt, engine, vfx, grid, camera, event.sourceId)) return;
        if (SkillArchitect.play(event.skill.id, centerPt, engine, vfx, grid, camera, event.sourceId)) return;

        // Fallback
        this.playHitVFX(event, vfx, centerPt, groundZ);
        camera.addTrauma(0.2);
    }
}

import { VFXSystem } from "../vfx";
import { VFX_REGISTRY } from "../../../data/vfx/VFXRegistry";
import { EmitterConfig, Range } from "../../../types/VFXSchema";
import { VFXFactory } from "../../graphics/VFXFactory";

// Helper: Get random number from Range [min, max] or number
const rnd = (r: Range | number): number => {
    if (typeof r === 'number') return r;
    return r[0] + Math.random() * (r[1] - r[0]);
};

// Helper: Pick random color
const pickColor = (colors: string[]): string => {
    if (!colors || colors.length === 0) return '#ffffff';
    return colors[Math.floor(Math.random() * colors.length)];
};

// List of particles that MUST snap to ground Z
const GROUND_PARTICLES = new Set([
    'SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE', 
    'HEX_GLOW', 'PILLAR', 'DOMAIN'
]);

export class VFXPlayer {

    public static play(system: VFXSystem, effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        const asset = VFX_REGISTRY[effectId];

        if (!asset) {
            return;
        }

        for (const emitter of asset.emitters) {
            this.processEmitter(system, emitter, x, y, z, colorOverride, groundZ);
        }
    }

    private static processEmitter(system: VFXSystem, config: EmitterConfig, cx: number, cy: number, cz: number, colorOverride?: string, groundZ?: number) {
        const count = Math.floor(rnd(config.count));

        // Determine effective Z for this emitter
        // If the particle type is a ground effect and we know where the ground is, snap it.
        // Otherwise use the target Z (which might be body height).
        const isGroundType = GROUND_PARTICLES.has(config.particleType);
        const effectiveZ = (isGroundType && groundZ !== undefined) ? groundZ : cz;

        for (let i = 0; i < count; i++) {
            const p = system.state.getParticle();

            // 1. Position & Velocity Calculation based on Shape
            let vx = 0, vy = 0, vz = 0;
            let px = cx, py = cy, pz = effectiveZ;
            const speed = rnd(config.speed);

            if (config.shape === 'POINT') {
                // No offset
            } 
            else if (config.shape === 'BURST_DIR') {
                // Omnidirectional Sphere Burst
                const theta = Math.random() * Math.PI * 2;
                const phi = (Math.random() - 0.5) * Math.PI; 
                const cosPhi = Math.cos(phi);

                vx = Math.cos(theta) * cosPhi * speed;
                vy = Math.sin(theta) * cosPhi * speed;
                vz = Math.sin(phi) * speed + (speed * 0.5); // Bias upwards slightly
            }
            else if (config.shape === 'CIRCLE') {
                // Flat ring burst
                const angle = Math.random() * Math.PI * 2;
                const r = config.shapeRadius || 10;
                px += Math.cos(angle) * r;
                py += Math.sin(angle) * r;

                vx = Math.cos(angle) * speed;
                vy = Math.sin(angle) * speed;
            }

            // 2. Properties
            p.x = px; p.y = py; p.z = pz;
            p.vx = vx; p.vy = vy; p.vz = vz;

            p.life = rnd(config.lifetime); 
            p.maxLife = p.life;
            p.delay = rnd(config.delay);

            p.size = rnd(config.size);

            // Color priority: Override > Config
            p.color = colorOverride || pickColor(config.colors);

            // Type Casting (Ensure string matches Particle internal type)
            p.type = config.particleType as any;

            // Apply Visual Style if defined
            if (config.visualStyle) p.style = config.visualStyle;

            // Optional Physics Overrides
            if (config.drag !== undefined) p.drag = config.drag;
            if (config.locked) p.locked = true;
            if (config.vRotation) p.vRotation = rnd(config.vRotation);
            else p.vRotation = (Math.random() - 0.5) * 10; // Default gentle rotation

            if (config.blendMode) p.blendMode = config.blendMode;

            // --- CRITICAL FIX: HYDRATE TEXTURE ---
            // Force load the high-quality Hexagon texture immediately.
            if (!p.image && !['PILLAR', 'BEAM', 'HEX_BEAM', 'GRID_FIELD', 'DOMAIN'].includes(p.type)) {
                // We cast p.type to any because the Factory accepts specific string literals
                p.image = VFXFactory.getTexture(p.type as any, p.color);
            }

            // Push to System
            system.state.particles.push(p);
        }
    }
}

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } // Optional for culling
    ) {
        // CULLING SETUP
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            // Visible Window in World Coordinates
            // Pad by 200px to account for particle size
            const pad = 200;
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;

            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            if (d.x < cullMinX || d.x > cullMaxX || d.y < cullMinY || d.y > cullMaxY) return;

            const offsetY = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            // Cull if completely off screen due to transition
            if (Math.abs(offsetY) > 800) return;

            const drawY = d.y + offsetY;

            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; // Reuse tx/ty for pos
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        // 2. Physical Particles (Sorted with World)
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            // FRUSTUM CULLING
            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            // Only Physical types that should be occluded by units
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) {

                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (Math.abs(offset) > 800) return;

                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);

                const op = renderList.next();
                op.type = RenderOpType.VFX;

                // Sort Key (Ground Level with Offset)
                op.y = p.y + offset; 
                op.z = 5;
                op.sortBias = p.sortBias || 0; 

                // Visual Lift
                let visualLift = 0;
                if (p.type === 'GIANT_HEX' || p.type === 'GRID_FIELD' || p.type === 'DOMAIN') {
                    visualLift = 5; 
                }

                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaos;
                op.tx = p.x;

                // COORDINATE CALCULATION FIX:
                // Ground effects (Shockwave) are drawn at ground Y (p.y + offset).
                // Air effects (Debris) are drawn at visual Y (p.y + offset - p.z).
                // ParticleRenderer checks p.type to decide, so we pass the *Ground* coordinates
                // and let the painter handle Z-offset logic if needed, OR we pass the calculated Visual Y?

                // Decision: We pass the Visual Anchor Point.
                // For Air Particles: VisualY = GroundY - Z
                // For Ground Particles: VisualY = GroundY. (They will apply ISO scale to flat geometry)

                const isFlatGround = ['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE'].includes(p.type);
                if (isFlatGround) {
                    op.ty = p.y + offset - visualLift; // Draw at floor
                } else {
                    op.ty = p.y + offset - p.z - visualLift; // Draw in air
                }

                op.th = p.z; 
            }
        });

        // 3. Projectiles (Delegated)
        ProjectileRenderer.submit(renderList, engine, getTerrainHeight, transitionT, transitionPhase);
    }

    // Items here are drawn ON TOP of everything (Overlay VFX like flashes, text, magic circles)
    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            // Filter out physicals already drawn
            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return; 

            const progress = 1 - (p.life / p.maxLife);
            const drawY = p.y + offset - p.z;
            const isChaos = isChaosStyle(p.color);

            ParticleRenderer.drawSingleParticle(ctx, p, p.x, drawY, progress, isChaos);
        });
    }
}

import { Agent } from "../game";
import { Particle } from "../systems/vfx/state";
import { Projectile, Point, GroundHazard } from "../../types";

export enum RenderOpType {
    TERRAIN,
    OBSTACLE,
    UNIT,
    VFX,
    PROJECTILE,
    DECAL
}

export class RenderOp {
    type: RenderOpType = RenderOpType.TERRAIN;
    y: number = 0; 
    z: number = 0; 
    sortBias: number = 0; 

    tx: number = 0; 
    ty: number = 0; 
    th: number = 0; 
    tsize: number = 0;
    ttheme: any = null;
    tq: number = 0;
    tr: number = 0;
    ttype: string = ''; 
    tdetail: string = '';

    oStatus: string | undefined;
    oDanger: any;
    oHazard: GroundHazard | undefined; 
    oLightCol: string | null = null;
    oLightInt: number = 0;
    oRange: boolean = false;
    oRangeCol: string = '';
    oHover: boolean = false;
    oHasUnit: boolean = false;

    agent: Agent | null = null;
    uSelected: boolean = false;
    uSilhouette: boolean = false;

    particle: Particle | null = null;
    vProgress: number = 0;
    vChaos: boolean = false;

    pVisX: number = 0;
    pVisY: number = 0;
    pVisShadowY: number = 0;
    pSkillVis: string = '';
    pColor: string = '';
    pIsUlt: boolean = false;
    pAngle: number = 0;
    pSpin: number = 0;
    pTrail: Point[] = []; 
    proj: Projectile | null = null;

    dColor: string = '';
    dScale: number = 1;
    dLife: number = 0;

    time: number = 0;
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;

    // Double buffer approach for sorting to avoid 'slice()' allocation
    private sortBuffer: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            this.ops.push(new RenderOp());
            this.sortBuffer.push(new RenderOp()); // Placeholder, will be overwritten by pointers
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            // Panic expand (should be rare)
            for(let i=0; i<1000; i++) {
                this.ops.push(new RenderOp());
                this.sortBuffer.push(new RenderOp());
            }
        }
        const op = this.ops[this.count++];
        op.sortBias = 0; 
        return op;
    }

    public sort() {
        if (this.count > 1) {
            // 1. Copy active pointers to buffer
            for (let i = 0; i < this.count; i++) {
                this.sortBuffer[i] = this.ops[i];
            }

            // 2. Sort the buffer (Only the active part)
            // Using subarray view for sort to avoid creating new array
            const activeView = this.sortBuffer.slice(0, this.count); // We still slice for native sort api compatibility :(
            // Actually, modern engines optimize small slices well. 
            // If we want zero allocation we need a custom QuickSort.
            // For now, sorting the slice is faster than sorting the whole 8000-item array with empty slots.
            activeView.sort(this.compare);

            // 3. Copy back
            for (let i = 0; i < this.count; i++) {
                this.ops[i] = activeView[i];
            }
        }
    }

    private compare(a: RenderOp, b: RenderOp): number {
        // High Z items (Floating UI/Effects) always on top
        if (a.z > 50 && b.z <= 50) return 1;
        if (b.z > 50 && a.z <= 50) return -1;

        const scoreA = a.y + a.sortBias;
        const scoreB = b.y + b.sortBias;

        if (Math.abs(scoreA - scoreB) < 2) return a.z - b.z;
        return scoreA - scoreB;
    }
}

import { Particle } from "../../state";
import { ISO_SCALE_Y } from "../../../../../constants";
import { VFXFactory } from "../../../../graphics/VFXFactory";
import { HexGeometry } from "../../../../graphics/utils/HexGeometry";

export const GroundPainter = {
    // drawX, drawY are passed from the renderer (already includes transition offset)
    draw(ctx: CanvasRenderingContext2D, p: Particle, progress: number, drawX: number, drawY: number) {
        if (!p.image && !p.texture) {
            p.image = VFXFactory.getTexture(p.type as any, p.color);
        }
        const img = p.image || p.texture;

        let scale = 1.0;
        let alpha = 1.0 - progress;

        if (p.type === 'SHOCKWAVE' || p.type === 'RING' || p.type === 'BLAST') {
            // Explosive expansion
            scale = 0.5 + progress * 2.5; 
            alpha = 1.0 - Math.pow(progress, 3);
        } else if (p.type === 'CRACKS' || p.type === 'GRID_FIELD') {
            // Static linger
            scale = 1.0;
            alpha = 1.0 - Math.pow(progress, 4); // Fade out late
        }

        if (alpha <= 0.01) return;

        ctx.save();

        // 1. Position (Corrected: Use passed coordinates)
        ctx.translate(drawX, drawY); 

        // 2. ISO PROJECTION (Critical for "Flat" look on floor)
        ctx.scale(1, ISO_SCALE_Y);

        // 3. Rotation (Ground plane rotation)
        if (p.rotation) ctx.rotate(p.rotation);

        // 4. Blend Mode
        if (p.blendMode) ctx.globalCompositeOperation = p.blendMode;
        else if (p.type === 'CRACKS') ctx.globalCompositeOperation = 'source-over'; // Dark cracks
        else ctx.globalCompositeOperation = 'screen'; // Glowing rings

        ctx.globalAlpha = Math.min(1, alpha);

        if (img) {
            const size = p.size * scale;
            ctx.drawImage(img, -size, -size, size * 2, size * 2);
        } else {
            // Fallback geometry
            ctx.fillStyle = p.color;
            ctx.beginPath(); ctx.arc(0, 0, p.size * scale, 0, Math.PI*2); ctx.fill();
        }

        ctx.restore();
    }
};

import { Particle } from "../state";
import { BillboardPainter } from "./painters/BillboardPainter";
import { GroundPainter } from "./painters/GroundPainter";
import { ProceduralPainter } from "./painters/ProceduralPainter";

export const ParticleRenderer = {

    drawSingleParticle(ctx: CanvasRenderingContext2D, p: Particle, drawX: number, drawY: number, progress: number, isChaos: boolean) {
        const now = Date.now() / 1000;

        // --- DISPATCHER ---

        // 1. Procedural Complex Shapes (Pillars, Beams, Domains)
        if (['PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'DOMAIN', 'DEATH_RAY', 'BEAM'].includes(p.type)) {
            ctx.save();
            ctx.translate(drawX, drawY);
            ProceduralPainter.draw(ctx, p, progress, now);
            ctx.restore();
            return;
        }

        // 2. Ground/Floor Effects (Must Scale Y for Perspective)
        // These stick to the grid surface.
        if (['SHOCKWAVE', 'RING', 'BLAST', 'CRACKS', 'GRID_FIELD', 'MAGIC_CIRCLE', 'HEX_GLOW'].includes(p.type)) {
            GroundPainter.draw(ctx, p, progress, drawX, drawY);
            return;
        }

        // 3. Billboard Sprites (Face Camera)
        // Smoke, Sparks, Debris, Rocks - They have 3D position but draw as 2D sprites facing viewer.
        // They handle their own rotation relative to screen.
        BillboardPainter.draw(ctx, p, drawX, drawY, progress);
    }
};

import { GameEvent, GameEventType, Skill, Team, Point } from "../../types";

export class GameEventPool {
    private pool: GameEvent[] = [];
    private _index = 0;

    constructor(initialSize: number = 100) {
        for (let i = 0; i < initialSize; i++) {
            this.pool.push(this.createEmpty());
        }
    }

    private createEmpty(): GameEvent {
        return {
            type: 'DAMAGE', // Dummy
            pos: { x: 0, y: 0 }
        };
    }

    public get(
        type: GameEventType, 
        pos: Point, 
        opts: { 
            value?: number, 
            text?: string, 
            color?: string, 
            skill?: Skill, 
            sourceId?: string, 
            targetId?: string, 
            team?: Team 
        } = {}
    ): GameEvent {
        let event: GameEvent;

        if (this.pool.length > 0) {
            event = this.pool.pop()!;
        } else {
            event = this.createEmpty();
        }

        // Hydrate
        event.type = type;

        // Critical: Clone position to avoid reference drift if 'pos' is reused/mutated elsewhere
        event.pos = { x: pos.x, y: pos.y };

        event.value = opts.value;
        event.text = opts.text;
        event.color = opts.color;
        event.skill = opts.skill;
        event.sourceId = opts.sourceId;
        event.targetId = opts.targetId;
        event.team = opts.team;

        return event;
    }

    public release(event: GameEvent) {
        // Clear references to help GC if the pool grows large, though mostly primitives/strings.
        event.skill = undefined;
        event.sourceId = undefined;
        event.targetId = undefined;
        event.team = undefined;
        this.pool.push(event);
    }
}

export const EventPool = new GameEventPool(200);

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";
import { VFXPhysics } from "./vfx/VFXPhysics";
import { VFXAmbience } from "./vfx/VFXAmbience";

// Interface for 3D points
interface Point3D { x: number; y: number; z: number; }

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambience: VFXAmbience = new VFXAmbience();

    public reset() {
        this.state.reset();
        // ambience reset implied by zeroing timer locally in next update if needed, 
        // but ambience class state is transient anyway.
    }

    /**
     * Play a particle effect from the registry
     */
    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride, groundZ);
    }

    /**
     * Play a beam effect between two points
     */
    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();

        // 3D Anchors
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

        // Sorting Key (Start Point)
        p.x = start.x; p.y = start.y; p.z = start.z;

        p.life = duration; 
        p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; 
        p.style = styleId; // Generic Style Key
        p.locked = true;

        this.state.particles.push(p);
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // Locked particles are purely visual/kinematic (controlled by spawner or static)
            if (p.locked) {
                p.rotation += p.vRotation * dt;
                continue; 
            }

            // Kill condition check
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) {
                    p.life = 0; 
                }
            }

            // Delegate Physics Logic
            VFXPhysics.update(p, dt, getTerrainHeight);
        }

        // Update Decals (Simple linear decay)
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                this.state.decals.splice(i, 1);
            }
        }

        // Delegate Ambience Logic
        this.ambience.update(dt, ambientType, this.state);
    }
}

import { createCanvas } from "./CanvasUtils";
import { GeometryPainter } from "./painters/GeometryPainter";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

const TEXTURE_SIZE = 64; 
const CENTER = TEXTURE_SIZE / 2;

// ============================================================================
// 🏭 MAIN FACTORY (The Facade)
// ============================================================================

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Entry point for generic particles (Smoke, Glow, Shards)
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalization for legacy keys
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;
        ctx.translate(CENTER, CENTER);

        // --- DISPATCHER ---
        switch (type) {
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': // NEW: Dense volumetric cloud for poison/fog
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                ParticlePainter.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.5, 'FILL');
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');
                ctx.beginPath(); ctx.arc(0, 0, r*0.7, 0, Math.PI*2); ctx.stroke();
                break;
            case 'WARNING_HATCH':
                this.drawWarningHatch(ctx, r, color);
                break;
            default:
                // Fallback debug shape
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // New: Dense Cloud Texture Generation
    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Base Blob
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;

        // Draw multiple overlapping circles to create irregular cloud shape
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;

            ctx.beginPath();
            ctx.arc(x, y, size, 0, Math.PI*2);
            ctx.fill();
        }

        // Center fill
        ctx.beginPath();
        ctx.arc(0, 0, r * 0.5, 0, Math.PI*2);
        ctx.fill();
    }

    // --- TERRAIN DETAIL CACHING (FPS OPTIMIZATION) ---
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        ctx.scale(1, ISO_SCALE_Y); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;

                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawWarningHatch(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.save();
        GeometryPainter.drawHex(ctx, 0, 0, r, 'FILL');
        ctx.globalCompositeOperation = 'source-in';
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;

        const size = r * 2;
        const spacing = 10;
        ctx.beginPath();
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(i - size, -size);
            ctx.lineTo(i + size, size);
        }
        ctx.stroke();

        ctx.globalCompositeOperation = 'source-over';
        ctx.lineWidth = 2;
        GeometryPainter.drawHex(ctx, 0, 0, r, 'STROKE');
        ctx.restore();
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;
        ctx.translate(cx, cy);

        switch (visual) {
            case 'HEX_DART':
            case 'ARROW': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(64, 32, 30, 0, Math.PI*2);
        ctx.arc(44, 32, 20, 0, Math.PI*2);
        ctx.arc(84, 32, 20, 0, Math.PI*2);
        ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {

    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'FOG') {
            // --- VOLUMETRIC POISON CLOUD ---
            // Uses cached CLOUD texture for performance
            const texture = VFXFactory.getTexture('CLOUD', def.primaryColor);
            const size = HEX_SIZE * 3.5;
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Use Source-Over for thick smoke/gas look (not additive)
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = def.intensity * 0.4; // Base opacity

            // Layer 1: Slow rotating base
            ctx.save();
            ctx.rotate(speed * 0.2);
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Layer 2: Counter-rotating smaller detail
            ctx.save();
            ctx.rotate(-speed * 0.3 + 1.0);
            ctx.scale(0.7, 0.7);
            ctx.globalAlpha = def.intensity * 0.6;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Core Glow
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.2;
            const glow = VFXFactory.getTexture('GLOW', def.secondaryColor);
            ctx.drawImage(glow, -size*0.4, -size*0.4, size*0.8, size*0.8);

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            // Lava / Acid Pool
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'CRYSTAL') {
            // Ice Field
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE, 8, def.primaryColor, 0.5);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            const texture = VFXFactory.getTexture('SHARD', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;

            // Scattered shards
            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 10;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-10, py-10, 20, 20);
            }
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            // Gravity Well
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Dark Core
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();

            // Event Horizon
            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.5, 0,0,HEX_SIZE);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

            // Accretion Disk
            ctx.rotate(globalTime * def.speed);
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 10]);
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; // New Import
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

interface ZoneInfo {
    type: 'CAST';
    color: string;
    visual: string; // Skill visual tag
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face Y
        size: number,

        // State Props
        specialStatus: string | undefined, 
        zoneInfo: ZoneInfo | undefined,    

        // Lighting
        lightColor: string | null,
        lightIntensity: number,

        // Interactive
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        // Metadata
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        // --- LAYER 1: HAZARDS (Decoupled) ---
        if (hazard) {
            HazardPainter.draw(ctx, x, y, hazard, globalTime);
        }

        // --- LAYER 2: UNIT STATUS FLOOR TINT ---
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                // Use source-over for tinted glass look instead of additive
                ctx.globalCompositeOperation = 'source-over';
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill();
                ctx.restore();
            }
        }

        // --- LAYER 3: CAST ZONES (Volumetric) ---
        if (zoneInfo) {
            ZoneRenderer.drawZone(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // --- LAYER 4: DYNAMIC LIGHTING ---
        // Reduced intensity to prevent overexposure
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen'; // Screen is safer than lighter
            ctx.globalAlpha = Math.min(0.5, lightIntensity * 0.4); 
            ctx.fillStyle = lightColor;
            HexGeometry.traceHex(ctx, x, y, size);
            ctx.fill();
            ctx.restore();
        }

        // --- LAYER 5: INTERACTIVE UI HIGHLIGHTS ---
        if (isRange || isHover || hasUnit) {
            ctx.save();

            // Use 'screen' for light projection look instead of flat paint
            ctx.globalCompositeOperation = 'screen';

            // Valid Move/Skill Range
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.2; 
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill();

                ctx.strokeStyle = rangeColor; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.5; 
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke();
            }

            // Mouse Hover - Bright Spotlight
            if (isHover) { 
                ctx.fillStyle = '#ffffff'; 
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill(); 

                ctx.strokeStyle = '#fff'; 
                ctx.lineWidth = 2; 
                ctx.globalAlpha = 0.8;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke(); 
            }

            // Unit Position - Subtle selection ring
            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, x, y, size * 0.9);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { VolumePainter } from "../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";

export const ZoneRenderer = {

    /**
     * Volumetric Hex Expansion with Warning Support
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visualTag: string, 
        progress: number, // 0.0 (Start) -> 1.0 (Ready)
        globalTime: number,
        dist: number,     // Distance from center of zone (in tiles)
        maxRadius: number // Radius of zone (in tiles)
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC EXPANSION ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. INNER FILL
        // For WARNINGS & ULTS, we draw volumetric fill
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Prism (Height 14, Opacity ~0.2)
                VolumePainter.drawWarningBlock(ctx, x, y, size, color, pulse);
            } 
            else if (isUlt) {
                // Friendly Ult: Smooth Prism
                // Balance intensity with warning (Height 30 -> 14, Opacity 0.4 -> 0.25)
                const height = 14;
                VolumePainter.draw3DPrism(ctx, x, y, size, height, color, 0.25 * pulse, 'SOLID');
            }
            else {
                // Basic/Active: Fog
                let fogOpacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                VolumePainter.drawVolumetricHex(ctx, x, y, size * 0.9, color, fogOpacity);
            }
        }

        // B. EXPANDING EDGE (Ripple)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const edgeWidth = (def.baseRingWidth || 3);
            VolumePainter.drawHexRipple(ctx, x, y, size, color, edgeOpacity, edgeWidth);
        }

        // C. PERIMETER MARKER (Always Visible for Warning)
        // If it's a warning or ult, the block already handles the rim
        const showBorder = (!isWarning && !isUlt) && (dist >= maxRadius - 0.5);
        if (showBorder) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.4;

            ctx.strokeStyle = color;
            ctx.lineWidth = 1; 
            ctx.globalAlpha = borderAlpha;

            if (def.dashed) ctx.setLineDash([5, 5]);

            HexGeometry.traceHex(ctx, x, y, size);
            ctx.stroke();
            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

