export { Agent, SpecialVisualStatus };

// Constants
export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];

    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }

    get logs() { return this.logger.logs; }

    public events: GameEvent[] = [];

    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;

    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    // Time & Victory Proxies
    get timeScale() { return this.time.timeScale; }
    set timeScale(v: number) { this.time.timeScale = v; }
    get targetTimeScale() { return this.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.time.targetTimeScale = v; }
    get battleTime() { return this.time.battleTime; }
    set battleTime(v: number) { this.time.battleTime = v; }

    get isFinishing() { return this.victory.isFinishing; }
    get victoryTimer() { return this.victory.victoryTimer; }
    get winningTeam() { return this.victory.winningTeam; }

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public agentMap: Map<number, Agent> = new Map();

    // Systems
    public movement: MovementSystem;
    public physics: PhysicsSystem; 
    public status: StatusSystem;
    public combat: CombatSystem;
    public map: MapSystem;
    public hazards: HazardSystem;
    public ai: AISystem;
    public agentManager: AgentManager;
    public announcer: AnnouncerSystem; 
    public director: DirectorSystem;
    public logger: BattleLogger; 
    public time: TimeSystem; 
    public victory: VictorySystem; 
    public zones: ZoneSystem; 

    get directorTargetId() { return this.director.targetId; }

    constructor() {
        this.movement = new MovementSystem();
        this.physics = new PhysicsSystem();
        this.status = new StatusSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.hazards = new HazardSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.announcer = new AnnouncerSystem(); 
        this.director = new DirectorSystem();
        this.logger = new BattleLogger();
        this.time = new TimeSystem();
        this.victory = new VictorySystem();
        this.zones = new ZoneSystem();
        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }

    randomizeEnvironment() { 
        this.hazards.reset(); // Crucial: Wipe floor hazards
        if (this.renderer) this.renderer.vfx.reset(); // Crucial: Wipe decals
        this.map.randomizeEnvironment(this); 
    }

    rebuildMap() { 
        this.hazards.reset();
        this.map.rebuildMap(this); 
    }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        const oldH = this.map.getTerrainHeight(agent.q, agent.r);
        const newH = this.map.getTerrainHeight(newQ, newR);
        const deltaH = oldH - newH;

        agent.physics.z += deltaH;

        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    // Helper to push event via Pool
    public pushEvent(
        type: GameEventType, 
        pos: {x: number, y: number}, 
        opts: { value?: number, text?: string, color?: string, skill?: Skill, sourceId?: string, targetId?: string, team?: Team } = {}
    ) {
        const evt = EventPool.get(type, pos, opts);
        this.events.push(evt);
    }

    public play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.time.reset();
            this.logger.clear();
            this.victory.reset();
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    public stop() { this.isRunning = false; }

    public restart() {
        this.stop();
        this.victory.reset();
        this.time.reset();
        this.agentMap.clear();
        this.hazards.reset(); // Crucial: Reset hazards on restart
        this.announcer.reset(); 
        this.director.reset();

        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });

        this.flushEvents();
        this.combat.reset(); 

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); 
            this.renderer.vfx.reset(); 
        }

        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    public clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.hazards.reset(); // Crucial
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.announcer.reset();
        this.director.reset();

        this.combat.reset(); 
        this.flushEvents();

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }

        this.logger.clear();

        if (!keepScene) {
            this.map.randomizeEnvironment(this); 
        } else {
            this.map.rebuildMap(this); 
        }

        this.bus.emit('GAME_CLEAR', {});
    }

    private flushEvents() {
        // Recycle all pending events
        for(const e of this.events) EventPool.release(e);
        this.events.length = 0;
    }

    public tick(dt: number) {
        if (!this.isRunning) return;

        this.time.update(dt);
        this.flushEvents(); // Clear previous frame events
        this.director.update(dt, this);
        this.zones.update(this); 

        // Check Victory
        if (this.victory.check(this)) {
            this.victory.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }

        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        // 1. Physics (Global)
        this.physics.update(dt, this);

        // 2. Logic
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            this.status.update(a, dt, this);

            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        // 3. Combat & Environment
        this.combat.update(dt, this);
        this.hazards.update(dt, this); // DIRECT HAZARD UPDATE
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }
}

import { Agent } from "../game";
import { Particle } from "../systems/vfx/state";
import { Projectile, Point, GroundHazard } from "../../types";

export enum RenderOpType {
    TERRAIN,
    OBSTACLE,
    UNIT,
    VFX,
    PROJECTILE,
    DECAL
}

export class RenderOp {
    type: RenderOpType = RenderOpType.TERRAIN;

    // Sort Key (Calculated once)
    sortKey: number = 0;

    y: number = 0; 
    z: number = 0; 
    sortBias: number = 0; 

    tx: number = 0; 
    ty: number = 0; 
    th: number = 0; 
    tsize: number = 0;
    ttheme: any = null;
    tq: number = 0;
    tr: number = 0;
    ttype: string = ''; 
    tdetail: string = '';

    oStatus: string | undefined;
    oDanger: any;
    oHazard: GroundHazard | undefined; 
    oLightCol: string | null = null;
    oLightInt: number = 0;
    oRange: boolean = false;
    oRangeCol: string = '';
    oHover: boolean = false;
    oHasUnit: boolean = false;

    agent: Agent | null = null;
    uSelected: boolean = false;
    uSilhouette: boolean = false;

    particle: Particle | null = null;
    vProgress: number = 0;
    vChaos: boolean = false;

    pVisX: number = 0;
    pVisY: number = 0;
    pVisShadowY: number = 0;
    pSkillVis: string = '';
    pColor: string = '';
    pIsUlt: boolean = false;
    pAngle: number = 0;
    pSpin: number = 0;
    pTrail: Point[] = []; 
    proj: Projectile | null = null;

    dColor: string = '';
    dScale: number = 1;
    dLife: number = 0;

    time: number = 0;
}

export class RenderList {
    public ops: RenderOp[] = [];
    public count: number = 0;

    // Double buffer approach for sorting
    private sortBuffer: RenderOp[] = [];
    private capacity: number = 8000;

    constructor() {
        for(let i=0; i<this.capacity; i++) {
            this.ops.push(new RenderOp());
            this.sortBuffer.push(new RenderOp()); 
        }
    }

    public reset() {
        this.count = 0;
    }

    public next(): RenderOp {
        if (this.count >= this.ops.length) {
            // Panic expand
            for(let i=0; i<1000; i++) {
                this.ops.push(new RenderOp());
                this.sortBuffer.push(new RenderOp());
            }
        }
        const op = this.ops[this.count++];
        op.sortBias = 0; 
        return op;
    }

    public sort() {
        if (this.count > 1) {
            // 1. Calculate Sort Keys for Active Ops (Batch Processing)
            // Concept: (Layer * 10,000,000) + (Y * 1000) + Z
            // Layer 0: Ground/Low
            // Layer 1: High/Air (Z > 50)
            // Using integer math avoids slow float comparisons in the sort function

            for (let i = 0; i < this.count; i++) {
                const op = this.ops[i];
                // Bias high-Z items (Projectiles, Flying Units, UI FX) to draw last in same-y situations
                // Shift by 10,000,000 to segregate "Air Layer"
                const layerScore = (op.z > 50) ? 10000000 : 0;

                // Y-Sorting (Primary Depth)
                // Multiply Y by 1000 to preserve sub-pixel order if integers, 
                // but rounding usually fine. Using Math.floor ensures stable int key.
                // Add sortBias for manual tweaking (e.g. Decals below Units)
                const yScore = Math.floor(op.y + op.sortBias) * 1000;

                // Z-Sorting (Secondary Depth)
                // Within same Y line, higher Z draws on top
                const zScore = Math.floor(op.z);

                op.sortKey = layerScore + yScore + zScore;
            }

            // 2. Copy active pointers to buffer
            for (let i = 0; i < this.count; i++) {
                this.sortBuffer[i] = this.ops[i];
            }

            // 3. Sort buffer (Fast Integer Compare)
            const activeView = this.sortBuffer.slice(0, this.count);
            activeView.sort((a, b) => a.sortKey - b.sortKey);

            // 4. Copy back
            for (let i = 0; i < this.count; i++) {
                this.ops[i] = activeView[i];
            }
        }
    }
}

import { GameEvent } from "../../../types";
import { GameEngine } from "../../game";
import { VFXSystem } from "../vfx";
import { GridSystem } from "../grid";
import { CameraSystem } from "../CameraSystem";
import { HexUtils } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

// Sub-Handlers
import { CombatVFXHandler } from "./handlers/CombatVFXHandler";
import { UnitVFXHandler } from "./handlers/UnitVFXHandler";
import { CinematicVFXHandler } from "./handlers/CinematicVFXHandler";

// Types
export interface Point3D { x: number; y: number; z: number; }

/**
 * EventVFXMapper (Refactored Router)
 * 
 * Responsibility:
 * 1. Calculate Spatial Coordinates (Origin/Target/Ground)
 * 2. Route events to specialized handlers based on Type.
 * 3. NO direct rendering logic here.
 */
export class EventVFXMapper {

    public process(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem
    ) {
        // 1. Resolve Spatial Context
        const origin = this.resolvePoint(event.pos.x, event.pos.y, event.sourceId, engine, grid);
        let target = this.resolvePoint(event.pos.x, event.pos.y, event.targetId, engine, grid);

        // Calculate pure Ground Z for the target location
        const groundZ = grid.getTerrainHeight(
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).q,
            HexUtils.fromPx(event.pos.x, event.pos.y, engine.mapConfig).r,
            engine
        );

        // Fallback for non-unit targets (ground click)
        if (!event.targetId) target.z = groundZ + 20;

        // 2. Route to Specialized Handlers
        switch (event.type) {

            // --- COMBAT EVENTS (Hits, Damage, Impacts) ---
            case 'DAMAGE': 
            case 'PROJECTILE_HIT': 
            case 'IMPACT_AOE':
                CombatVFXHandler.handle(event, vfx, camera, target, groundZ);
                break;

            // --- UNIT EVENTS (Lifecycle, Status) ---
            case 'DEATH':
            case 'SPAWN':
            case 'CAST_BREAK':
                UnitVFXHandler.handle(event, engine, vfx, camera, origin, groundZ);
                break;

            // --- CINEMATIC EVENTS (Scripts, Beams, Ults) ---
            case 'VISUAL_SLASH':
            case 'VISUAL_BEAM':
                CinematicVFXHandler.handle(event, engine, vfx, grid, camera, origin, target);
                break;
        }
    }

    private resolvePoint(defaultX: number, defaultY: number, agentId: string | undefined, engine: GameEngine, grid: GridSystem): Point3D {
        let agent = agentId ? engine.agents.find(a => a.id === agentId) : null;

        // If ID not found, check if there is an agent at that location spatially
        if (!agent && !agentId) {
            const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
            agent = engine.getAgentAt(hex.q, hex.r);
        }

        if (agent) {
            const terrainH = grid.getTerrainHeight(agent.q, agent.r, engine);
            return {
                x: agent.px,
                y: agent.py,
                // Critical: Target is Chest Height, not feet
                z: terrainH + agent.physics.z + UNIT_BODY_OFFSET
            };
        }

        const hex = HexUtils.fromPx(defaultX, defaultY, engine.mapConfig);
        const terrainH = grid.getTerrainHeight(hex.q, hex.r, engine);
        return { x: defaultX, y: defaultY, z: terrainH };
    }
}

import { GameEvent } from "../../../../types";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../EventVFXMapper";
import { VFX_REGISTRY } from "../../../../data/vfx/VFXRegistry";

export class CombatVFXHandler {

    public static handle(event: GameEvent, vfx: VFXSystem, camera: CameraSystem, target: Point3D, groundZ: number) {

        if (event.type === 'DAMAGE') {
            // Damage triggers Hit VFX only if not part of a projectile (proj handled separately)
            if (!event.skill?.projectileSpeed) {
                this.playHitVFX(event, vfx, target, groundZ);
            }
            return;
        }

        if (event.type === 'PROJECTILE_HIT') {
            if (event.skill?.type !== 'AOE') {
                this.playHitVFX(event, vfx, target, groundZ);
                camera.addTrauma(0.05); 
            } else {
                // Direct hit for AOE projectile contact (spark only, AOE impact handled by IMPACT_AOE)
                vfx.playEffect('FX_HIT_GENERIC', event.pos.x, event.pos.y, groundZ + 5, event.skill?.color, groundZ);
            }
            return;
        }

        if (event.type === 'IMPACT_AOE') {
            // Fallback for AOE if no specific script ran in Cinematic Handler (Router handles script priority?)
            // Actually EventVFXMapper routes IMPACT_AOE to here.
            // But usually AOE has a script. We should check script here or let CinematicHandler handle it?
            // Re-design: IMPACT_AOE is often triggered by scripts. 
            // If it's a generic AOE impact:
            this.playHitVFX(event, vfx, {x: event.pos.x, y: event.pos.y, z: groundZ}, groundZ);
            camera.addTrauma(0.2);
            return;
        }
    }

    private static playHitVFX(event: GameEvent, vfx: VFXSystem, target: Point3D, groundZ: number) {
        const skill = event.skill;
        const color = event.color || '#fff';

        let effectId = 'FX_HIT_GENERIC';
        if (skill && skill.visualHitEffect && VFX_REGISTRY[skill.visualHitEffect]) {
            effectId = skill.visualHitEffect;
        }

        // Pass groundZ separately so the player knows where the floor is for shockwaves
        vfx.playEffect(effectId, target.x, target.y, target.z, color, groundZ);
    }
}

import { GameEvent } from "../../../../types";
import { GameEngine } from "../../../game";
import { VFXSystem } from "../../vfx";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../EventVFXMapper";
import { UnitShatter } from "../effects/UnitShatter";

export class UnitVFXHandler {

    public static handle(event: GameEvent, engine: GameEngine, vfx: VFXSystem, camera: CameraSystem, origin: Point3D, groundZ: number) {

        if (event.type === 'DEATH') {
            const dAgent = engine.agents.find(a => a.id === event.sourceId);
            if (dAgent) {
                // Death occurs at body center
                UnitShatter.spawn(vfx, origin.x, origin.y, origin.z, dAgent.team, dAgent.role, dAgent.physics.vx, dAgent.physics.vy);
            }
            camera.addTrauma(0.1);
            return;
        }

        if (event.type === 'SPAWN') {
            // Teleport is a floor-to-sky effect, verify groundZ
            vfx.playEffect('FX_TELEPORT', origin.x, origin.y, groundZ, event.color, groundZ);
            return;
        }

        if (event.type === 'CAST_BREAK') {
            vfx.playEffect('FX_CAST_BREAK', origin.x, origin.y, origin.z, event.color);
            if (event.skill && event.skill.tag === 'ULT') {
                camera.addTrauma(0.4);
            } else {
                camera.addTrauma(0.15); 
            }
            return;
        }
    }
}

import { GameEvent } from "../../../../types";
import { GameEngine } from "../../../game";
import { VFXSystem } from "../../vfx";
import { GridSystem } from "../../grid";
import { CameraSystem } from "../../CameraSystem";
import { Point3D } from "../EventVFXMapper";
import { UltArchitect } from "../UltArchitect";
import { SkillArchitect } from "../SkillArchitect";
import { UNIT_BODY_OFFSET } from "../../../../constants";

export class CinematicVFXHandler {

    public static handle(
        event: GameEvent, 
        engine: GameEngine, 
        vfx: VFXSystem, 
        grid: GridSystem, 
        camera: CameraSystem, 
        origin: Point3D, 
        target: Point3D
    ) {
        const skill = event.skill;
        if (!skill) return;

        // 1. Try Ult Script
        if (skill.tag === 'ULT') {
             if (UltArchitect.play(skill.id, target, engine, vfx, grid, camera, event.sourceId)) return;
        }

        // 2. Try Skill Script
        if (SkillArchitect.play(skill.id, target, engine, vfx, grid, camera, event.sourceId)) return;

        // 3. Fallback (If no script found)
        if (event.type === 'VISUAL_SLASH') {
            vfx.playBeam('SLASH_CONNECT', origin, target, event.color || '#fff', 0.2);
        } else {
            vfx.playBeam('GENERIC_BEAM', origin, target, event.color || '#fff', 0.4);
            // Pass origin.z - UNIT_BODY_OFFSET as approximate groundZ if needed
            // But generic hit is handled by CombatHandler usually. 
            // This is just the BEAM part.
        }
    }
}

import { VFXStateManager } from "./vfx/state";
import { VFXPlayer } from "./vfx/VFXPlayer";
import { VFXPhysics } from "./vfx/VFXPhysics";
import { VFXAmbience } from "./vfx/VFXAmbience";

// Interface for 3D points
interface Point3D { x: number; y: number; z: number; }

export class VFXSystem {
    public state: VFXStateManager = new VFXStateManager();
    private ambience: VFXAmbience = new VFXAmbience();

    public reset() {
        this.state.reset(); // Clears particles and decals
        // Ambience reset is stateless usually, but good practice if we add state later
    }

    /**
     * Play a particle effect from the registry
     */
    public playEffect(effectId: string, x: number, y: number, z: number, colorOverride?: string, groundZ?: number) {
        VFXPlayer.play(this, effectId, x, y, z, colorOverride, groundZ);
    }

    /**
     * Play a beam effect between two points
     */
    public playBeam(styleId: string, start: Point3D, end: Point3D, colorOverride?: string, duration: number = 0.4) {
        const p = this.state.getParticle();

        // 3D Anchors
        p.sx = start.x; p.sy = start.y; p.sz = start.z;
        p.tx = end.x;   p.ty = end.y;   p.tz = end.z;

        // Sorting Key (Start Point)
        p.x = start.x; p.y = start.y; p.z = start.z;

        p.life = duration; 
        p.maxLife = duration; 
        p.color = colorOverride || '#fff'; 
        p.type = 'BEAM'; 
        p.style = styleId; // Generic Style Key
        p.locked = true;

        this.state.particles.push(p);
    }

    update(dt: number, globalTime: number, ambientType: string, getTerrainHeight?: (x: number, y: number) => number) {
        const particles = this.state.particles;
        let count = particles.length;

        for (let i = count - 1; i >= 0; i--) {
            const p = particles[i];

            if (p.delay && p.delay > 0) {
                p.delay -= dt;
                continue;
            }

            p.life -= dt;
            if (p.life <= 0) {
                this.state.releaseParticle(p);
                particles[i] = particles[count - 1];
                particles.pop();
                count--;
                continue;
            }

            // Locked particles are purely visual/kinematic (controlled by spawner or static)
            if (p.locked) {
                p.rotation += p.vRotation * dt;
                continue; 
            }

            // Kill condition check
            if (p.killAtTarget !== undefined && p.targetX !== undefined && p.targetY !== undefined) {
                const dx = p.x - p.targetX;
                const dy = p.y - p.targetY;
                if (dx*dx + dy*dy < p.killAtTarget) {
                    p.life = 0; 
                }
            }

            // Delegate Physics Logic
            VFXPhysics.update(p, dt, getTerrainHeight);
        }

        // Update Decals (Simple linear decay)
        for (let i = this.state.decals.length - 1; i >= 0; i--) {
            this.state.decals[i].life -= dt * 0.5;
            if (this.state.decals[i].life <= 0) {
                this.state.decals.splice(i, 1);
            }
        }

        // Delegate Ambience Logic
        this.ambience.update(dt, ambientType, this.state);
    }
}

import { GameEngine } from "../game";
import { GroundHazard, Team } from "../../types";
import { HexUtils } from "../utils";
import { HAZARD_VISUALS } from "../../data/vfx/hazard_visuals";

export class HazardSystem {
    public hazards: Map<string, GroundHazard> = new Map();

    public reset() {
        this.hazards.clear();
    }

    public addHazard(
        q: number, r: number, 
        type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC', 
        duration: number, 
        sourceId: string, 
        team: Team, 
        color: string,
        power: number,
        interval: number,
        engine?: GameEngine 
    ) {
        if (!engine || !engine.map.isValid(q, r)) return;
        const key = HexUtils.key({q, r});

        // --- PERSISTENCE FIX ---
        // Check if a compatible hazard already exists
        const existing = this.hazards.get(key);

        if (existing) {
            // If same type and team, EXTEND it instead of replacing it.
            // This prevents visual flickering (spawn/despawn loop) on continuous application.
            if (existing.type === type && existing.team === team) {
                existing.duration = Math.max(existing.duration, duration);
                existing.power = Math.max(existing.power, power); // Update power if stronger
                existing.sourceId = sourceId; // Update credit
                // Do NOT reset existing.timer or existing.id to maintain visual continuity
                return;
            }
        }

        // Create New
        const hazard: GroundHazard = {
            id: Math.random().toString(36).substr(2, 6),
            q, r, type, duration, sourceId, team, color, power, interval, timer: 0 
        };

        this.hazards.set(key, hazard);

        // Trigger Spawn VFX only on NEW creation
        if (engine.renderer) {
            const def = HAZARD_VISUALS[type];
            if (def && def.spawnVfx) {
                const px = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                engine.renderer.vfx.playEffect(def.spawnVfx, px.x, px.y, h);
            }
        }
    }

    public getHazardAt(q: number, r: number): GroundHazard | undefined {
        return this.hazards.get(HexUtils.key({q, r}));
    }

    public update(dt: number, engine: GameEngine) {
        const toRemove: string[] = [];

        // 1. Tick Durations
        for (const [key, h] of this.hazards.entries()) {
            h.duration -= dt;
            h.timer -= dt; // Tick timer counts down
            if (h.duration <= 0) toRemove.push(key);
        }
        toRemove.forEach(k => this.hazards.delete(k));

        // 2. Resolve Effects (Damage/CC)
        for (const h of this.hazards.values()) {
            if (h.timer <= 0) {
                h.timer = h.interval; // Reset tick

                // Find units in this tile
                const occupants = engine.agents.filter(a => 
                    a.hp > 0 && !a.banished && a.q === h.q && a.r === h.r && a.team !== h.team
                );

                occupants.forEach(agent => {
                    if (agent.movementType === 1 && (h.type === 'FIRE' || h.type === 'POISON')) return; // Flyers avoid ground hazards

                    const dmg = h.power;
                    agent.hp = Math.max(0, agent.hp - dmg);

                    // Visual Feedback
                    engine.events.push({ 
                        type: 'DAMAGE', 
                        pos: {x: agent.px, y: agent.py}, 
                        value: -Math.floor(dmg), 
                        color: h.color,
                        skill: { color: h.color, ccType: 'DOT' } as any 
                    });

                    engine.log(agent, 'HAZARD', h.type, `(${h.q},${h.r})`, `受到地形傷害 ${Math.floor(dmg)}`);
                });
            }
        }

        // 3. Physics (Gravity/Suction)
        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished) return;
            const hazard = this.getHazardAt(agent.q, agent.r);

            if (hazard && hazard.type === 'GRAVITY' && hazard.team !== agent.team) {
                const center = HexUtils.toPx(hazard.q, hazard.r, engine.mapConfig);
                const dx = center.x - agent.px;
                const dy = center.y - agent.py;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 5) {
                    const pull = 300 * dt;
                    agent.physics.vx += (dx/dist) * pull;
                    agent.physics.vy += (dy/dist) * pull;
                    agent.moveSpeedMult = 0.3; // Slow down
                }
            }
        });
    }
}

import { Agent, GameEngine } from "../game";
import { MovementType, AnimState } from "../../types";
import { HexUtils, Vector } from "../utils";
import { PHYSICS } from "../../constants";

// Physics Constants
const PHYSICS_STIFFNESS_ALIVE = 150;
const PHYSICS_DAMPING_ALIVE = 25; 

export class PhysicsEngine {

    // --- STATIC UTILS (Decoupled Physics Math) ---

    /**
     * Calculates and applies a physical impulse vector to an agent based on an origin point.
     */
    public static applyImpulse(
        target: Agent, 
        origin: {x: number, y: number}, 
        force: number, 
        randomness: number = 0
    ) {
        const dx = target.px - origin.x;
        const dy = target.py - origin.y;
        const len = Math.sqrt(dx * dx + dy * dy);

        // Minimum force clamp to ensure impact feel
        const effectiveForce = Math.min(400, Math.max(50, force));

        let vx = 0, vy = 0;

        if (len <= 0.1) {
            // Stacked perfectly? Push random direction
            const ang = Math.random() * Math.PI * 2;
            vx = Math.cos(ang) * effectiveForce;
            vy = Math.sin(ang) * effectiveForce;
        } else {
            vx = (dx / len) * effectiveForce;
            vy = (dy / len) * effectiveForce;
        }

        // Apply
        target.physics.vx += vx;
        target.physics.vy += vy;

        // Add rotational torque impact
        if (randomness > 0) {
            target.physics.vAngle += (Math.random() - 0.5) * randomness;
        }
    }

    // --- INSTANCE METHODS ---

    public update(a: Agent, dt: number, engine: GameEngine) {
        // PERF: Skip physics for units that are fully removed from visual play
        if (a.fullyDead) return;

        const isDead = a.hp <= 0;

        // 1. Spring Forces (Return to 0,0 relative local space)
        // Only apply stiffness if alive. Dead units go limp (no spring back).
        const stiffness = isDead ? 0 : PHYSICS_STIFFNESS_ALIVE;
        const damping = PHYSICS_DAMPING_ALIVE; // Keep damping to prevent oscillation

        const fx = -stiffness * a.physics.x;
        const fy = -stiffness * a.physics.y;
        const fRot = -stiffness * a.physics.angle * 0.1; 

        // 2. Acceleration (Force - Damping)
        const ax = fx - damping * a.physics.vx;
        const ay = fy - damping * a.physics.vy;
        const aRot = fRot - damping * a.physics.vAngle;

        // 3. Integrate Velocity
        a.physics.vx += ax * dt;
        a.physics.vy += ay * dt;
        a.physics.vAngle += aRot * dt;

        // 4. Vertical Dynamics (Gravity vs Flight)
        const isAirborne = a.physics.z > 0;
        const isFlying = a.movementType === MovementType.FLYING && !isDead;
        const isDisabled = a.stunTimer > 0 || a.visualStatus === 'FROZEN' || a.visualStatus === 'POLYMORPH';

        if (isFlying && !isDisabled) {
            // HOVER STATE: Bob around a target altitude
            // Adjusted: Lowered from 90 to 55 to be closer to action but still visually flying
            const hoverHeight = 55; 
            const hoverFreq = 2.5; 
            const targetZ = hoverHeight + Math.sin(engine.battleTime * hoverFreq) * 5;

            // Soft spring to maintain height
            const dz = targetZ - a.physics.z;
            a.physics.vz += dz * 5 * dt;
            a.physics.vz *= 0.92; // Increased drag to stop oscillation
        } else {
            // Gravity applies if airborne OR if grounded-but-dead (to prevent float glitches) OR if flying unit crashed
            if (isAirborne || a.physics.z > 0.1) {
                a.physics.vz -= PHYSICS.GRAVITY * dt;
            }
        }

        // 5. Integrate Position
        a.physics.x += a.physics.vx * dt;
        a.physics.y += a.physics.vy * dt;
        a.physics.z += a.physics.vz * dt;
        a.physics.angle += a.physics.vAngle * dt;

        // 6. Ground Collision & FALL DAMAGE
        if (a.physics.z < 0) {
            // Snap to ground
            a.physics.z = 0;

            // --- IMPACT CALCULATION ---
            // Only check if moving downwards fast
            if (a.physics.vz < -PHYSICS.SAFE_FALL_VELOCITY) {
                const impactSpeed = Math.abs(a.physics.vz);

                // Fall Damage Logic
                // Only alive units take fall damage.
                // Flying units crash if disabled, so they DO take damage here.
                if (!isDead) {
                    const velocityOverhead = impactSpeed - PHYSICS.SAFE_FALL_VELOCITY;
                    const scaling = PHYSICS.FATAL_FALL_VELOCITY - PHYSICS.SAFE_FALL_VELOCITY;

                    // Damage % = Linear interpolation between Safe and Fatal velocity
                    const pct = Math.min(1.0, velocityOverhead / scaling);
                    const rawDmg = Math.floor(a.maxHp * pct) + PHYSICS.FALL_DAMAGE_MIN;

                    // Apply Damage
                    a.hp = Math.max(0, a.hp - rawDmg);

                    // Feedback
                    engine.events.push({ 
                        type: 'DAMAGE', 
                        pos: {x: a.px, y: a.py}, 
                        value: -rawDmg, 
                        color: '#ef4444',
                        text: "墜落"
                    });
                    engine.log(a, 'HAZARD', '墜落', '地面', `受到墜落傷害 ${rawDmg} (速度: ${Math.round(impactSpeed)})`);

                    // Camera Shake based on impact
                    if (engine.renderer) engine.renderer.camera.addTrauma(pct * 0.5);

                    // Visuals
                    engine.events.push({ 
                        type: 'IMPACT_AOE', 
                        pos: {x: a.px, y: a.py}, 
                        color: '#9ca3af',
                        skill: { aoeRadius: 1 } as any // Mock skill for size
                    });

                    // Death Check
                    if (a.hp <= 0) {
                        engine.log(a, 'DEATH', '墜落', null, '死於重力');
                        engine.agentManager.handleDeadState(a, engine);
                    } else {
                        a.setAnim(AnimState.HIT);
                    }
                }

                // Bounce Physics
                a.physics.vz = -a.physics.vz * 0.3; // Dampened bounce
                a.physics.vx *= 0.5; // Friction
                a.physics.vy *= 0.5;
                a.physics.vAngle *= 0.5;

            } else {
                // Soft Landing
                a.physics.vz = 0;
            }
        }

        // 7. World Position Drift (Slide effect for knockback correction)
        if (!isDead && !a.isMoving) {
            const targetPos = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            const dx = targetPos.x - a.px;
            const dy = targetPos.y - a.py;
            const distSq = dx*dx + dy*dy;

            // Increased snap threshold to stop jitter
            if (distSq > 0.5) {
                const driftSpeed = 12.0 * dt; // Exp decay
                a.px += dx * driftSpeed;
                a.py += dy * driftSpeed;
                if (distSq < 2) {
                    a.px = targetPos.x;
                    a.py = targetPos.y;
                }
            } else {
                a.px = targetPos.x;
                a.py = targetPos.y;
            }
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState, Hex } from "../../../types";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../physics/PhysicsEngine";

export class SkillResolutionSystem {

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // 1. HARD CC INTERRUPT CHECK
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;

        if (isHardCC) {
            this.handleInterruption(a, engine);
            return;
        }

        if (a.silenceTimer > 0) {
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            if (currentSkill && currentSkill.tag !== 'BASIC') {
                this.handleInterruption(a, engine);
                return;
            }
        }

        // 2. CAST PROGRESS
        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        if (a.castTimer <= 0) {
            this.completeCast(a, engine);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            if (s.tag !== 'BASIC') {
                engine.log(a, 'CC', '中斷', s.name, '詠唱被打斷');
                let centerPos = { x: a.px, y: a.py };
                engine.events.push({ type: 'CAST_BREAK', pos: centerPos, value: 0, color: s.color, skill: s });
            }
        }
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.IDLE); 
    }

    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;

        // Resource Management
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd; 

        // Execution Fork
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             engine.combat.spawnProjectile(a, s, engine);
        } else {
            this.executeInstantSkill(a, s, engine);
        }

        a.castingSkillIdx = -1;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        // 1. Calculate Impact Area
        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

            // Spawn Hazards (Delegated)
            HazardManager.spawnHazards(source, impactCells, skill, engine);

        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexMath.distance(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        // 2. Resolve Hits
        targets.forEach(t => {
            const dist = HexMath.distance(source, t);
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);

        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "未命中", color: "#94a3b8" });
            return;
        }

        const oldHp = Math.ceil(target.hp);

        if (result.shieldAbsorb > 0) {
            target.shield -= result.shieldAbsorb;
            if (result.shieldAbsorb > 20) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "吸收", color: "#bae6fd" });
            }
        }

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
        }
        if (result.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - result.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + result.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${result.manaBurn} MP`, color: "#3b82f6" });
        }
        if (result.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + result.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${result.manaRestore} MP`, color: "#60a5fa" });
        }

        if (result.finalValue < 0) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Delegate Impulse Calc to PhysicsEngine
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const damageForce = Math.abs(result.finalValue) * 2.0;
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.5);
        }

        if (result.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        if (result.isCrit) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暴擊!", color: "#ef4444" });
        if (result.isBlock) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "格擋", color: "#9ca3af" });

        engine.events.push({
            type: result.finalValue < 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // 9. Apply Status Effects (Delegated to CCManager)
        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        const actionType = result.finalValue < 0 ? 'HIT' : 'HEAL';

        const shouldLog = skill.tag !== 'BASIC' || result.isCrit || result.isExecute || newHp <= 0;

        if (shouldLog) {
            engine.log(source, actionType, skill.name, target.id, `${actionType === 'HIT' ? '造成傷害' : '回復生命'} ${Math.abs(result.finalValue)} (HP: ${oldHp} -> ${newHp})`);
        }

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { HEX_VERTICES, HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { GridOverlays } from "./GridOverlays";

// --- MATERIAL CACHE ---
// Keys: `${themeId}_${height}`
// Stores reusable CanvasGradients to avoid creation every frame (CPU killer)
const MATERIAL_CACHE: Map<string, { side: CanvasGradient, top: CanvasGradient }> = new Map();

// Helper to get or create cached gradient
function getMaterials(ctx: CanvasRenderingContext2D, theme: any, height: number, themeId: string) {
    // Round height to nearest BLOCK_HEIGHT to reduce cache entries in case of float drifts
    // although heights should be integers of BLOCK_HEIGHT usually.
    const hKey = Math.round(height);
    const key = `${themeId}_${hKey}`;

    if (MATERIAL_CACHE.has(key)) return MATERIAL_CACHE.get(key)!;

    // 1. Side Gradient (Vertical)
    // We assume drawing in local space (0,0 is base of block)
    // The visual face goes from -height to 0. Plus BASE_THICKNESS (12px).
    const topY = -height;
    const bottomY = 12; // Base thickness

    const sideGrad = ctx.createLinearGradient(0, topY, 0, bottomY);
    sideGrad.addColorStop(0, theme.sideDark);
    sideGrad.addColorStop(0.5, theme.sideLight);
    sideGrad.addColorStop(1, '#020617'); // Fade to black at bottom

    // 2. Top Gradient (Diagonal)
    // Local coords relative to top face center (0, -height)
    // Hex size radius is approx 36.
    const r = HEX_SIZE;
    const topGrad = ctx.createLinearGradient(-r, topY - r, r, topY + r);
    topGrad.addColorStop(0, theme.rim); 
    topGrad.addColorStop(0.3, theme.top);
    topGrad.addColorStop(1, theme.sideDark);

    const mats = { side: sideGrad, top: topGrad };
    MATERIAL_CACHE.set(key, mats);
    return mats;
}

export const TerrainRenderer = {

    /**
     * Optimized Block Drawer using Local Space Coordinates and Cached Materials.
     */
    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        const BASE_THICKNESS = 12; 
        const faceY = -height; // Local Top Face Y

        ctx.save();
        ctx.translate(x, y); // Move to Base Center

        // Retrieve Cached Gradients
        const mats = getMaterials(ctx, theme, height, type);

        // 1. Draw Side Faces
        // Visible indices: 5, 0, 1
        const visibleIndices = [5, 0, 1]; 

        ctx.fillStyle = mats.side;
        ctx.strokeStyle = 'rgba(0,0,0,0.3)'; 
        ctx.lineWidth = 1; 

        ctx.beginPath();
        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const v1 = HEX_VERTICES[i];
            const v2 = HEX_VERTICES[j];

            // Pre-calc coordinates
            const v1x = v1.x * size;
            const v1y = v1.y * size * ISO_SCALE_Y;
            const v2x = v2.x * size;
            const v2y = v2.y * size * ISO_SCALE_Y;

            // Top vertices
            const x1 = v1x;
            const y1_top = faceY + v1y;
            const x2 = v2x;
            const y2_top = faceY + v2y;

            // Bottom vertices
            const y1_bottom = v1y + BASE_THICKNESS; 
            const y2_bottom = v2y + BASE_THICKNESS;

            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.lineTo(x1, y1_bottom); // Close quad
        }
        ctx.fill();
        ctx.stroke();

        // 2. Draw Top Face
        ctx.fillStyle = mats.top;
        HexGeometry.traceHex(ctx, 0, faceY, size, true);
        ctx.fill();

        // Tier lines (Only if tall)
        if (height > BLOCK_HEIGHT) {
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            for (const i of visibleIndices) {
                const j = (i + 1) % 6;
                const v1 = HEX_VERTICES[i];
                const v2 = HEX_VERTICES[j];

                const x1 = v1.x * size;
                const x2 = v2.x * size;
                const y1_base = v1.y * size * ISO_SCALE_Y;
                const y2_base = v2.y * size * ISO_SCALE_Y;

                // Draw lines at step intervals
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    const localY = -hStep;
                    ctx.moveTo(x1, localY + y1_base);
                    ctx.lineTo(x2, localY + y2_base);
                }
            }
            ctx.stroke();
        }

        // 3. Surface Assets (Animated)
        if (type === 'MAGMA' || type === 'VOID' || type === 'ICE') {
            if (type === 'MAGMA') {
                SurfacePainter.drawLiquid(ctx, 0, faceY, '#ef4444', globalTime, 1.0);
                const crackInt = 0.5 + Math.sin(globalTime) * 0.2;
                SurfacePainter.drawCracks(ctx, 0, faceY, '#fca5a5', crackInt);
            } else if (type === 'VOID') {
                SurfacePainter.drawFog(ctx, 0, faceY, theme.fogColor || '#6366f1', globalTime);
            } else if (type === 'ICE') {
                const bandPos = (globalTime * 50 + x + y) % (size * 4) - size * 2;
                ctx.save(); 
                HexGeometry.traceHex(ctx, 0, faceY, size, true);
                ctx.clip(); 
                const specGrad = ctx.createLinearGradient(-size, faceY - size, size, faceY + size);
                specGrad.addColorStop(0, 'transparent');
                specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.3)'); 
                specGrad.addColorStop(1, 'transparent');
                ctx.translate(bandPos * 0.5, 0); 
                ctx.fillStyle = specGrad;
                ctx.fill();
                ctx.restore();
            } 
        }

        // 4. Rim Light (Highlight Edges)
        ctx.lineCap = 'round';
        ctx.lineWidth = 2;
        ctx.strokeStyle = theme.rim || 'rgba(255,255,255,0.3)';
        ctx.globalAlpha = 0.6;

        ctx.beginPath();
        // Visible top back edges (4, 3, 2 indices) for highlight
        const v4 = HEX_VERTICES[4];
        const v3 = HEX_VERTICES[3];
        const v2 = HEX_VERTICES[2];

        // Scale vertices
        const sx = size;
        const sy = size * ISO_SCALE_Y;

        ctx.moveTo(v4.x * sx, faceY + v4.y * sy);
        ctx.lineTo(v3.x * sx, faceY + v3.y * sy);
        ctx.lineTo(v2.x * sx, faceY + v2.y * sy);

        ctx.stroke();
        ctx.globalAlpha = 1.0;

        // Final outline
        ctx.lineWidth = 1;
        ctx.strokeStyle = 'rgba(0,0,0,0.2)';
        HexGeometry.traceHex(ctx, 0, faceY, size, true);
        ctx.stroke();

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        // Optimized: Uses cached sprites from VFXFactory internally
        const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
        SurfacePainter.drawDetailTexture(ctx, cx, cy, type, detailColor, seed);
    }
};

import { Agent, GameEngine } from "../../game";
import { Skill, GameEventType, AnimState, Hex } from "../../../types";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";

export class SkillResolutionSystem {

    public updateCasting(a: Agent, dt: number, engine: GameEngine) {
        // 1. HARD CC INTERRUPT CHECK
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;

        if (isHardCC) {
            this.handleInterruption(a, engine);
            return;
        }

        if (a.silenceTimer > 0) {
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            if (currentSkill && currentSkill.tag !== 'BASIC') {
                this.handleInterruption(a, engine);
                return;
            }
        }

        // 2. CAST PROGRESS
        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        if (a.castTimer <= 0) {
            this.completeCast(a, engine);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            if (s.tag !== 'BASIC') {
                engine.log(a, 'CC', '中斷', s.name, '詠唱被打斷');
                let centerPos = { x: a.px, y: a.py };
                engine.events.push({ type: 'CAST_BREAK', pos: centerPos, value: 0, color: s.color, skill: s });
            }
        }
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.IDLE); 
    }

    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;

        // Resource Management
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd; 

        // Execution Fork
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             engine.combat.spawnProjectile(a, s, engine);
        } else {
            this.executeInstantSkill(a, s, engine);
        }

        a.castingSkillIdx = -1;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        // 1. Calculate Impact Area
        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

            // Spawn Hazards (Delegated)
            HazardManager.spawnHazards(source, impactCells, skill, engine);

        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexMath.distance(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        // 2. Resolve Hits
        targets.forEach(t => {
            const dist = HexMath.distance(source, t);
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);

        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "未命中", color: "#94a3b8" });
            return;
        }

        const oldHp = Math.ceil(target.hp);

        if (result.shieldAbsorb > 0) {
            target.shield -= result.shieldAbsorb;
            if (result.shieldAbsorb > 20) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "吸收", color: "#bae6fd" });
            }
        }

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
        }
        if (result.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - result.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + result.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${result.manaBurn} MP`, color: "#3b82f6" });
        }
        if (result.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + result.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${result.manaRestore} MP`, color: "#60a5fa" });
        }

        if (result.finalValue < 0) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Delegate Impulse Calc to PhysicsEngine
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const damageForce = Math.abs(result.finalValue) * 2.0;
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.5);
        }

        if (result.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        if (result.isCrit) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暴擊!", color: "#ef4444" });
        if (result.isBlock) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "格擋", color: "#9ca3af" });

        engine.events.push({
            type: result.finalValue < 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // 9. Apply Status Effects (Delegated to CCManager)
        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        const actionType = result.finalValue < 0 ? 'HIT' : 'HEAL';

        const shouldLog = skill.tag !== 'BASIC' || result.isCrit || result.isExecute || newHp <= 0;

        if (shouldLog) {
            engine.log(source, actionType, skill.name, target.id, `${actionType === 'HIT' ? '造成傷害' : '回復生命'} ${Math.abs(result.finalValue)} (HP: ${oldHp} -> ${newHp})`);
        }

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

import { createCanvas } from "./CanvasUtils";
import { GeometryPainter } from "./painters/GeometryPainter";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

const TEXTURE_SIZE = 64; 
const CENTER = TEXTURE_SIZE / 2;

// ============================================================================
// 🏭 MAIN FACTORY (The Facade)
// ============================================================================

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Entry point for generic particles (Smoke, Glow, Shards)
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalization for legacy keys
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;
        ctx.translate(CENTER, CENTER);

        // --- DISPATCHER ---
        switch (type) {
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': // Dense volumetric cloud for poison/fog
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                ParticlePainter.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.5, 'FILL');
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');
                ctx.beginPath(); ctx.arc(0, 0, r*0.7, 0, Math.PI*2); ctx.stroke();
                break;
            case 'WARNING_HATCH':
                this.drawWarningHatch(ctx, r, color);
                break;
            // NEW: Optimization for ZoneRenderer
            case 'ZONE_RIPPLE':
                this.drawZoneRipple(ctx, r, color);
                break;
            case 'ZONE_BASE':
                this.drawZoneBase(ctx, r, color);
                break;
            default:
                // Fallback debug shape
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // New: Dense Cloud Texture Generation
    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.beginPath(); ctx.arc(0, 0, r * 0.5, 0, Math.PI*2); ctx.fill();
    }

    // New: Optimized Zone Ripple (Replaces expensive stroking)
    private drawZoneRipple(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');

        // Inner thin line
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.7, 'STROKE');
    }

    // New: Optimized Zone Base (Replaces volumetric fills)
    private drawZoneBase(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Soft Hex Glow
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'FILL');
    }

    // --- TERRAIN DETAIL CACHING (FPS OPTIMIZATION) ---
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        ctx.scale(1, ISO_SCALE_Y); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawWarningHatch(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.save();
        GeometryPainter.drawHex(ctx, 0, 0, r, 'FILL');
        ctx.globalCompositeOperation = 'source-in';
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        const size = r * 2;
        const spacing = 10;
        ctx.beginPath();
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(i - size, -size);
            ctx.lineTo(i + size, size);
        }
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
        ctx.lineWidth = 2;
        GeometryPainter.drawHex(ctx, 0, 0, r, 'STROKE');
        ctx.restore();
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;
        ctx.translate(cx, cy);
        switch (visual) {
            case 'HEX_DART':
            case 'ARROW': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(64, 32, 30, 0, Math.PI*2);
        ctx.arc(44, 32, 20, 0, Math.PI*2);
        ctx.arc(84, 32, 20, 0, Math.PI*2);
        ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { VolumePainter } from "../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";
import { ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    /**
     * Optimized Zone Drawer using Sprites
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visualTag: string, 
        progress: number, // 0.0 (Start) -> 1.0 (Ready)
        globalTime: number,
        dist: number,     // Distance from center of zone (in tiles)
        maxRadius: number // Radius of zone (in tiles)
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC EXPANSION ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. INNER FILL (Using Sprites)
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Prism - Cached in VolumePainter
                VolumePainter.drawWarningBlock(ctx, x, y, size, color, pulse);
            } 
            else if (isUlt) {
                // Friendly Ult: Smooth Prism
                const height = 14;
                VolumePainter.draw3DPrism(ctx, x, y, size, height, color, 0.25 * pulse, 'SOLID');
            }
            else {
                // Basic/Active: Sprite Base
                const opacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                const texture = VFXFactory.getTexture('ZONE_BASE', color);
                const drawSize = size * 2.8;

                ctx.translate(x, y);
                ctx.scale(1, ISO_SCALE_Y);
                ctx.globalAlpha = opacity;
                ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
                // Undo transform for next layers
                ctx.scale(1, 1/ISO_SCALE_Y);
                ctx.translate(-x, -y);
            }
        }

        // B. EXPANDING EDGE (Using Ripple Sprite)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const texture = VFXFactory.getTexture('ZONE_RIPPLE', color);
            const drawSize = size * 2.5;

            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalAlpha = edgeOpacity;
            ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
            // Undo
            ctx.scale(1, 1/ISO_SCALE_Y);
            ctx.translate(-x, -y);
        }

        // C. PERIMETER MARKER (Always Visible for Warning)
        // Optimized: Only trace path if strictly necessary (border logic)
        // Reduced frequency: only draw solid border, no dashed logic for standard tiles
        const showBorder = (!isWarning && !isUlt) && (dist >= maxRadius - 0.5);
        if (showBorder) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.4;

            ctx.strokeStyle = color;
            ctx.lineWidth = 1; 
            ctx.globalAlpha = borderAlpha;

            // Only use HexGeometry pathing here as it is efficient enough for single outline
            HexGeometry.traceHex(ctx, x, y, size);
            ctx.stroke();
        }

        ctx.restore();
    }
};

import { GameEngine } from "../game";
import { GroundHazard, Team } from "../../types";
import { HexUtils } from "../utils";
import { HAZARD_VISUALS } from "../../data/vfx/hazard_visuals";

export class HazardSystem {
    public hazards: Map<string, GroundHazard> = new Map();

    public reset() {
        this.hazards.clear();
    }

    public addHazard(
        q: number, r: number, 
        type: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC', 
        duration: number, 
        sourceId: string, 
        team: Team, 
        color: string,
        power: number,
        interval: number,
        engine?: GameEngine 
    ) {
        if (!engine || !engine.map.isValid(q, r)) return;
        const key = HexUtils.key({q, r});

        // --- PERSISTENCE FIX ---
        // Check if a compatible hazard already exists
        const existing = this.hazards.get(key);

        if (existing) {
            // If same type and team, EXTEND it instead of replacing it.
            if (existing.type === type && existing.team === team) {
                existing.duration = Math.max(existing.duration, duration);
                existing.power = Math.max(existing.power, power); // Update power if stronger
                existing.sourceId = sourceId; // Update credit
                return;
            }
        }

        // Create New
        const hazard: GroundHazard = {
            id: Math.random().toString(36).substr(2, 6),
            q, r, type, duration, sourceId, team, color, power, interval, timer: 0 
        };

        this.hazards.set(key, hazard);

        // Trigger Spawn VFX only on NEW creation
        if (engine.renderer) {
            const def = HAZARD_VISUALS[type];
            if (def && def.spawnVfx) {
                const px = HexUtils.toPx(q, r, engine.mapConfig);
                const h = engine.map.getTerrainHeight(q, r);
                engine.renderer.vfx.playEffect(def.spawnVfx, px.x, px.y, h);
            }
        }
    }

    public getHazardAt(q: number, r: number): GroundHazard | undefined {
        return this.hazards.get(HexUtils.key({q, r}));
    }

    public update(dt: number, engine: GameEngine) {
        const toRemove: string[] = [];

        // 1. Tick Durations & Update Global Timers
        for (const [key, h] of this.hazards.entries()) {
            h.duration -= dt;
            h.timer -= dt; // Tick timer counts down
            if (h.duration <= 0) toRemove.push(key);
        }
        toRemove.forEach(k => this.hazards.delete(k));

        // 2. Resolve Effects (Optimized: Iterate Agents, not Hazards)
        // O(Agents) is much better than O(Hazards * Agents) when carpet bombing

        engine.agents.forEach(agent => {
            if (agent.hp <= 0 || agent.banished) return;

            // Spatial Lookup
            const hazard = this.getHazardAt(agent.q, agent.r);
            if (!hazard) return;

            // Effect Logic
            if (hazard.timer <= 0) {
                // Apply Damage if hostile
                if (hazard.team !== agent.team) {
                    if (agent.movementType === 1 && (hazard.type === 'FIRE' || hazard.type === 'POISON')) return; // Flyers check

                    const dmg = hazard.power;
                    agent.hp = Math.max(0, agent.hp - dmg);

                    engine.events.push({ 
                        type: 'DAMAGE', 
                        pos: {x: agent.px, y: agent.py}, 
                        value: -Math.floor(dmg), 
                        color: hazard.color,
                        skill: { color: hazard.color, ccType: 'DOT' } as any 
                    });

                    engine.log(agent, 'HAZARD', hazard.type, `(${hazard.q},${hazard.r})`, `受到地形傷害 ${Math.floor(dmg)}`);
                }
            }

            // Physics Logic (Gravity)
            if (hazard.type === 'GRAVITY' && hazard.team !== agent.team) {
                const center = HexUtils.toPx(hazard.q, hazard.r, engine.mapConfig);
                const dx = center.x - agent.px;
                const dy = center.y - agent.py;
                const dist = Math.sqrt(dx*dx + dy*dy);

                if (dist > 5) {
                    const pull = 300 * dt;
                    agent.physics.vx += (dx/dist) * pull;
                    agent.physics.vy += (dy/dist) * pull;
                    agent.moveSpeedMult = 0.3; // Slow down
                }
            }
        });

        // 3. Reset Hazard Timers (Batch)
        // Since logic is applied via Agent iteration, we need to reset the tick timer for hazards that "fired".
        // But since hazards fire on a frequency, we can just reset any negative timer.
        for (const h of this.hazards.values()) {
            if (h.timer <= 0) {
                h.timer = h.interval;
            }
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";

export class CastingEngine {

    public updateCasting(a: Agent, dt: number, engine: GameEngine, onComplete: (a: Agent) => void) {
        // 1. HARD CC INTERRUPT CHECK
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;

        if (isHardCC) {
            this.handleInterruption(a, engine);
            return;
        }

        if (a.silenceTimer > 0) {
            const currentSkill = a.castingSkillIdx !== -1 ? a.skills[a.castingSkillIdx] : null;
            if (currentSkill && currentSkill.tag !== 'BASIC') {
                this.handleInterruption(a, engine);
                return;
            }
        }

        // 2. CAST PROGRESS
        a.castTimer -= dt;
        if (a.castingAnimationTimer > 0) a.castingAnimationTimer -= dt; 

        if (a.castTimer <= 0) {
            onComplete(a);
            this.resetCaster(a);
        }
    }

    private handleInterruption(a: Agent, engine: GameEngine) {
        const skillIdx = a.castingSkillIdx;
        if (skillIdx !== -1 && a.castTimer > 0 && a.skills[skillIdx]) {
            const s = a.skills[skillIdx]!;
            if (s.tag !== 'BASIC') {
                engine.log(a, 'CC', '中斷', s.name, '詠唱被打斷');
                let centerPos = { x: a.px, y: a.py };
                engine.events.push({ type: 'CAST_BREAK', pos: centerPos, value: 0, color: s.color, skill: s });
            }
        }
        this.resetCaster(a);
        a.setAnim(AnimState.IDLE); 
    }

    private resetCaster(a: Agent) {
        a.castingSkillIdx = -1;
        a.castTimer = 0;
        a.castingAnimationTimer = 0;
        a.setAnim(AnimState.COMBAT_IDLE);
    }
}

import { Agent, GameEngine } from "../../game";
import { Skill, AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { DamageCalculator } from "./DamageCalculator";
import { CCManager } from "./CCManager";
import { HazardManager } from "./HazardManager";
import { PhysicsEngine } from "../../physics/PhysicsEngine";

export class SkillExecutor {

    public executeInstantSkill(source: Agent, skill: Skill, engine: GameEngine) {
        let targets: Agent[] = [];
        let origin = {x: source.px, y: source.py}; 
        let targetHex = source.targetHex || (source.target ? {q: source.target.q, r: source.target.r} : {q: source.q, r: source.r});

        // 1. Calculate Impact Area
        const impactCells = engine.movement.targeting.getImpactArea(source, targetHex, skill, engine);

        if (skill.type === 'AOE' || impactCells.length > 1) {
            impactCells.forEach(cell => {
                const u = engine.getAgentAt(cell.q, cell.r);
                if (u && u.hp > 0 && !u.banished) {
                    if (skill.power >= 0 && u.team !== source.team) targets.push(u);
                    else if (skill.power < 0 && u.team === source.team) targets.push(u);
                }
            });

            const p = HexUtils.toPx(targetHex.q, targetHex.r, engine.mapConfig);
            origin = { x: p.x, y: p.y };
            engine.events.push({ type: 'IMPACT_AOE', pos: origin, skill, color: skill.color });

            // Spawn Hazards (Delegated)
            HazardManager.spawnHazards(source, impactCells, skill, engine);

        } else {
            if (source.target && source.target.hp > 0 && !source.target.banished) {
                const effRange = engine.movement.getEffectiveRange(source, source.target.q, source.target.r, skill.range, engine);
                if (HexMath.distance(source, source.target) <= effRange) {
                    targets.push(source.target);
                }
            }
        }

        if (targets.length === 0 && skill.power <= 0 && skill.type === 'SINGLE') {
            targets.push(source);
        }

        // 2. Resolve Hits
        targets.forEach(t => {
            const dist = HexMath.distance(source, t);
            if (dist > 1) {
                engine.events.push({ type: 'VISUAL_BEAM', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            } else {
                engine.events.push({ type: 'VISUAL_SLASH', pos: { x: t.px, y: t.py }, sourceId: source.id, targetId: t.id, skill, color: skill.color });
            }
            this.resolveHit(source, t, skill, origin, engine);
        });

        if (skill.tag !== 'BASIC') {
            engine.events.push({ type: 'CAST_FINISH', pos: {x: source.px, y: source.py}, skill: skill });
        }
    }

    public resolveHit(source: Agent, target: Agent, skill: Skill, origin: {x: number, y: number} | undefined, engine: GameEngine) {
        const result = DamageCalculator.calculate(source, target, skill);

        if (result.isMiss) {
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "未命中", color: "#94a3b8" });
            return;
        }

        const oldHp = Math.ceil(target.hp);

        if (result.shieldAbsorb > 0) {
            target.shield -= result.shieldAbsorb;
            if (result.shieldAbsorb > 20) {
                engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "吸收", color: "#bae6fd" });
            }
        }

        target.hp = Math.min(target.maxHp, target.hp + result.finalValue);

        if (result.vampAmount > 0 && source.hp > 0) {
            source.hp = Math.min(source.maxHp, source.hp + result.vampAmount);
            engine.events.push({ type: 'HEAL', pos: {x: source.px, y: source.py}, value: result.vampAmount, color: '#86efac' });
        }
        if (result.manaBurn > 0) {
            target.mp = Math.max(0, target.mp - result.manaBurn);
            source.mp = Math.min(source.maxMp, source.mp + result.manaBurn);
            engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `-${result.manaBurn} MP`, color: "#3b82f6" });
        }
        if (result.manaRestore > 0) {
             target.mp = Math.min(target.maxMp, target.mp + result.manaRestore);
             engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: `+${result.manaRestore} MP`, color: "#60a5fa" });
        }

        if (result.finalValue < 0) { 
            target.setAnim(AnimState.HIT);
            target.hitFlashTimer = 0.2;

            // Delegate Impulse Calc to PhysicsEngine
            const originPx = origin ? origin : {x: source.px, y: source.py};
            const damageForce = Math.abs(result.finalValue) * 2.0;
            PhysicsEngine.applyImpulse(target, originPx, damageForce, 0.5);
        }

        if (result.isExecute) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "斬殺!", color: "#dc2626" });
        if (result.isCrit) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "暴擊!", color: "#ef4444" });
        if (result.isBlock) engine.events.push({ type: 'CC_APPLIED', pos: {x: target.px, y: target.py}, text: "格擋", color: "#9ca3af" });

        engine.events.push({
            type: result.finalValue < 0 ? 'DAMAGE' : 'HEAL',
            pos: { x: target.px, y: target.py },
            value: result.finalValue,
            sourceId: source.id,
            targetId: target.id,
            skill: skill,
            color: skill.color
        });

        // 9. Apply Status Effects (Delegated to CCManager)
        CCManager.applyCC(source, target, skill, skill.ccType, skill.ccDur, skill.ccForce, origin, engine);
        CCManager.applyCC(source, target, skill, skill.ccType2, skill.ccDur2, skill.ccForce2, origin, engine);

        const newHp = Math.ceil(target.hp);
        const actionType = result.finalValue < 0 ? 'HIT' : 'HEAL';

        const shouldLog = skill.tag !== 'BASIC' || result.isCrit || result.isExecute || newHp <= 0;

        if (shouldLog) {
            engine.log(source, actionType, skill.name, target.id, `${actionType === 'HIT' ? '造成傷害' : '回復生命'} ${Math.abs(result.finalValue)} (HP: ${oldHp} -> ${newHp})`);
        }

        if (oldHp > 0 && newHp <= 0) {
            engine.log(source, 'DEATH', '擊殺', target.id, `${target.id} 已陣亡`);
            engine.events.push({ type: 'KILL', pos: { x: target.px, y: target.py }, sourceId: source.id, targetId: target.id });
        }
    }
}

import { Agent, GameEngine } from "../game";
import { Projectile, Skill, NodeState, AnimState } from "../../types";
import { ProjectileSystem } from "./combat/ProjectileSystem";
import { CastingEngine } from "./combat/CastingEngine";
import { SkillExecutor } from "./combat/SkillExecutor";
import { HexUtils } from "../utils";

export class CombatSystem {
    public projectileSystem: ProjectileSystem;
    public castingEngine: CastingEngine;
    public skillExecutor: SkillExecutor;

    constructor() {
        this.projectileSystem = new ProjectileSystem();
        this.castingEngine = new CastingEngine();
        this.skillExecutor = new SkillExecutor();
    }

    get projectiles(): Projectile[] { return this.projectileSystem.projectiles; }
    set projectiles(v: Projectile[]) { this.projectileSystem.projectiles = v; }

    public reset() {
        this.projectileSystem.projectiles = [];
    }

    public initiateCast(a: Agent, skillIdx: number, engine: GameEngine): NodeState {
        // --- LOOP BUG FIX: Strict State Check ---
        const isHardCC = a.stunTimer > 0 || a.banished || a.fearTimer > 0 || a.hp <= 0;
        if (isHardCC) return NodeState.FAILURE;

        const skill = a.skills[skillIdx];
        if (!skill) return NodeState.FAILURE;

        // Silence check
        if (a.silenceTimer > 0 && skill.tag !== 'BASIC') return NodeState.FAILURE;

        if (a.castingSkillIdx === -1) {
            a.castingSkillIdx = skillIdx;
            a.castTimer = skill.cast;
            a.castingAnimationTimer = skill.cast; 
            a.btStatus = `詠唱 ${skill.tag}`;

            let targetName = '地面';
            if (a.target) targetName = a.target.id;
            else if (a.targetHex) targetName = `(${a.targetHex.q},${a.targetHex.r})`;

            engine.log(a, 'CAST', '詠唱', targetName, `開始引導 ${skill.name} (需 ${skill.cast} 秒)`);
            engine.events.push({ type: 'CAST_START', pos: {x: a.px, y: a.py}, sourceId: a.id, skill: skill });

            a.setAnim(AnimState.ATTACK);

            if (a.target) {
                a.facing = a.target.px > a.px ? 1 : -1;
            } else if (a.targetHex) {
                const tx = HexUtils.toPx(a.targetHex.q, a.targetHex.r, engine.mapConfig).x;
                a.facing = tx > a.px ? 1 : -1;
            }
        }
        return NodeState.RUNNING;
    }

    public update(dt: number, engine: GameEngine) {
        // 1. Casting Updates (Logic)
        engine.agents.forEach(a => {
            if (a.hp <= 0) return;
            if (a.castingSkillIdx !== -1) {
                this.castingEngine.updateCasting(a, dt, engine, (agent) => {
                    this.completeCast(agent, engine);
                });
            }
        });

        // 2. Projectile Physics & Impacts (Pass SkillExecutor for impacts)
        this.projectileSystem.update(dt, engine, this.skillExecutor);
    }

    private completeCast(a: Agent, engine: GameEngine) {
        const s = a.skills[a.castingSkillIdx]!;

        // Resource Management
        a.mp = Math.min(a.maxMp, Math.max(0, a.mp - s.cost + s.gain));
        a.curCDs[a.castingSkillIdx] = s.cd; 

        // Execution Fork
        if (s.projectileSpeed && s.projectileSpeed > 0) {
             this.spawnProjectile(a, s, engine);
        } else {
            this.skillExecutor.executeInstantSkill(a, s, engine);
        }
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        this.projectileSystem.spawnProjectile(source, skill, engine);
    }
}

import { Agent, GameEngine } from "../../game";
import { Projectile, Skill } from "../../../types";
import { HexUtils, Vector } from "../../utils";
import { SkillExecutor } from "./SkillExecutor";
import { PROJECTILE_VISUALS } from "../../../data/vfx/projectile_visuals";
import { UNIT_BODY_OFFSET } from "../../../constants";

export class ProjectileSystem {
    public projectiles: Projectile[] = [];

    public update(dt: number, engine: GameEngine, skillExecutor: SkillExecutor) {
        for (let i = this.projectiles.length - 1; i >= 0; i--) {
            const p = this.projectiles[i];

            // 1. Resolve Definition
            const def = PROJECTILE_VISUALS[p.skill.id] || PROJECTILE_VISUALS[p.skill.visual || 'BOLT'];
            const isInstant = def ? def.trajectory === 'INSTANT' : false;

            // LOGICAL RAY DETECTION
            // High velocity skills or INSTANT trajectory move instantly
            const moveInstantly = isInstant || p.skill.projectileSpeed > 1400;

            const isGroundTarget = p.targetId.startsWith('ground-');
            let target = isGroundTarget ? null : engine.agents.find(a => a.id === p.targetId);

            if (target && !isGroundTarget) {
                p.targetPos = {x: target.px, y: target.py};
            }

            const dist = Vector.dist({x: p.x, y: p.y}, p.targetPos);
            const moveDist = moveInstantly ? 4000 * dt : p.speed * dt;

            // Update trail before moving
            const lastTrail = p.trail.length > 0 ? p.trail[p.trail.length - 1] : null;
            if (!lastTrail || Vector.dist(lastTrail, {x: p.x, y: p.y}) > 10) {
                p.trail.push({x: p.x, y: p.y});
                if (p.trail.length > 12) p.trail.shift(); 
            }

            // Reach target?
            if (dist <= moveDist || dist < 10) {
                const source = engine.agents.find(a => a.id === p.sourceId);

                if (p.skill.type === 'AOE') {
                    const hitPos = p.targetPos; 
                    const radius = p.skill.aoeRadius || 1;
                    const hitHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                    const targets = engine.agents.filter(e => e.team !== p.team && e.hp > 0 && !e.banished && HexUtils.dist(hitHex, e) <= radius);

                    targets.forEach(t => { 
                        if (source) skillExecutor.resolveHit(source, t, p.skill, hitPos, engine); 
                    });

                    // DoT Logic handled by SkillExecutor or Impact? 
                    // Keeping simple DoT logic here for now but ideally moved to Executor
                    // For now, spawn hazards directly via Manager if needed, but ImpactAOE usually handles instantaneous.
                    // If projectile has persistent effects, handle here:
                    if (p.skill.ccType === 'DOT' || p.skill.name.includes("霧") || p.skill.name.includes("雨")) {
                        if (source) {
                            const centerHex = HexUtils.fromPx(hitPos.x, hitPos.y, engine.mapConfig);
                            const affectedTiles = HexUtils.range(centerHex, radius);
                            const dur = p.skill.ccDur || 5.0;
                            let hType: 'POISON' | 'FIRE' | 'ICE' | 'GRAVITY' | 'GENERIC' = 'GENERIC';

                            if (p.skill.ccType === 'DOT') hType = 'POISON';
                            if (p.skill.name.includes('火') || p.skill.name.includes('Lava')) hType = 'FIRE';
                            if (p.skill.name.includes('冰') || p.skill.name.includes('Frost')) hType = 'ICE';

                            affectedTiles.forEach(tile => {
                                engine.hazards.addHazard(
                                    tile.q, tile.r, 
                                    hType, 
                                    dur, 
                                    source.id, 
                                    source.team, 
                                    p.skill.color,
                                    (p.skill.power * 0.2) || 10, 
                                    0.5,
                                    engine 
                                );
                            });
                        }
                    }
                    engine.events.push({ type: 'IMPACT_AOE', pos: hitPos, skill: p.skill, color: p.skill.color });
                } else {
                    if (target && target.hp > 0 && !target.banished) {
                        if (source) skillExecutor.resolveHit(source, target, p.skill, undefined, engine);
                    }
                }
                engine.events.push({ type: 'PROJECTILE_HIT', pos: p.targetPos, skill: p.skill });

                this.removeProjectile(i);
            } else {
                const dir = Vector.normalize(Vector.sub(p.targetPos, {x: p.x, y: p.y}));
                p.x += dir.x * moveDist;
                p.y += dir.y * moveDist;
            }
        }
    }

    private removeProjectile(idx: number) {
        const lastIdx = this.projectiles.length - 1;
        if (idx !== lastIdx) this.projectiles[idx] = this.projectiles[lastIdx];
        this.projectiles.pop();
    }

    public spawnProjectile(source: Agent, skill: Skill, engine: GameEngine) {
        let targetPos = {x: 0, y: 0};
        let tid = "";

        if (skill.type === 'AOE') {
             if (source.targetHex) {
                 const p = HexUtils.toPx(source.targetHex.q, source.targetHex.r, engine.mapConfig);
                 targetPos = p; tid = `ground-${source.targetHex.q},${source.targetHex.r}`;
             } else if (source.target) {
                 targetPos = {x: source.target.px, y: source.target.py}; tid = source.target.id;
             } else return;
             this.createProjectile(source, skill, targetPos, tid);
             engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: tid });
        } else {
            if (source.target && !source.target.banished && source.target.hp > 0) {
                targetPos = {x: source.target.px, y: source.target.py};
                this.createProjectile(source, skill, targetPos, source.target.id);
                engine.events.push({ type: 'PROJECTILE_SPAWN', pos: {x: source.px, y: source.py}, skill: skill, targetId: source.target.id });
            }
        }
    }

    private createProjectile(source: Agent, skill: Skill, targetPos: {x: number, y: number}, targetId: string) {
        this.projectiles.push({
            id: Math.random().toString(36).substr(2, 6),
            x: source.px, y: source.py, 
            startX: source.px, startY: source.py, 
            // FIXED: Start Z includes Body Offset to launch from chest, not feet
            startZ: source.physics.z + UNIT_BODY_OFFSET, 
            targetId, targetPos,
            speed: skill.projectileSpeed || 600, skill, sourceId: source.id, team: source.team, trail: []
        });
    }
}

