import { createCanvas } from "./CanvasUtils";
import { GeometryPainter } from "./painters/GeometryPainter";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

const TEXTURE_SIZE = 64; 
const CENTER = TEXTURE_SIZE / 2;

// ============================================================================
// 🏭 MAIN FACTORY (The Facade)
// ============================================================================

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Entry point for generic particles (Smoke, Glow, Shards)
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalization for legacy keys
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;
        ctx.translate(CENTER, CENTER);

        // --- DISPATCHER ---
        switch (type) {
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': 
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                ParticlePainter.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.5, 'FILL');
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');
                ctx.beginPath(); ctx.arc(0, 0, r*0.7, 0, Math.PI*2); ctx.stroke();
                break;
            case 'WARNING_HATCH':
                this.drawWarningHatch(ctx, r, color);
                break;
            case 'ZONE_RIPPLE':
                this.drawZoneRipple(ctx, r, color);
                break;
            case 'ZONE_BASE':
                this.drawZoneBase(ctx, r, color);
                break;
            // NEW: Pre-baked Shadow Blob (FPS Saver)
            case 'SHADOW_BLOB':
                this.drawShadowBlob(ctx, r, color);
                break;
            default:
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawShadowBlob(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // High quality blurred ellipse
        ctx.fillStyle = color;
        ctx.filter = 'blur(8px)'; // Bake the blur
        ctx.beginPath();
        // Scale for ISO perspective
        ctx.ellipse(0, 0, r * 0.8, r * 0.4, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';
    }

    // New: Dense Cloud Texture Generation
    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.beginPath(); ctx.arc(0, 0, r * 0.5, 0, Math.PI*2); ctx.fill();
    }

    // New: Optimized Zone Ripple (Replaces expensive stroking)
    private drawZoneRipple(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');

        // Inner thin line
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.7, 'STROKE');
    }

    // New: Optimized Zone Base (Replaces volumetric fills)
    private drawZoneBase(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Soft Hex Glow
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'FILL');
    }

    // --- TERRAIN DETAIL CACHING (FPS OPTIMIZATION) ---
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        ctx.scale(1, ISO_SCALE_Y); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawWarningHatch(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.save();
        GeometryPainter.drawHex(ctx, 0, 0, r, 'FILL');
        ctx.globalCompositeOperation = 'source-in';
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        const size = r * 2;
        const spacing = 10;
        ctx.beginPath();
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(i - size, -size);
            ctx.lineTo(i + size, size);
        }
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
        ctx.lineWidth = 2;
        GeometryPainter.drawHex(ctx, 0, 0, r, 'STROKE');
        ctx.restore();
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;
        ctx.translate(cx, cy);
        switch (visual) {
            case 'HEX_DART':
            case 'ARROW': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(64, 32, 30, 0, Math.PI*2);
        ctx.arc(44, 32, 20, 0, Math.PI*2);
        ctx.arc(84, 32, 20, 0, Math.PI*2);
        ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { HEX_VERTICES, HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";
import { GridOverlays } from "./GridOverlays";

// --- MATERIAL CACHE ---
const MATERIAL_CACHE: Map<string, { side: CanvasGradient, top: CanvasPattern | CanvasGradient }> = new Map();

function createNoisePattern(color: string, opacity: number): CanvasPattern | null {
    const size = 64;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d')!;

    ctx.fillStyle = color;
    ctx.fillRect(0,0,size,size);

    // Add noise
    for (let i = 0; i < 400; i++) {
        ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.1 * opacity})`;
        ctx.fillRect(Math.random() * size, Math.random() * size, 2, 2);
        ctx.fillStyle = `rgba(0,0,0,${Math.random() * 0.1 * opacity})`;
        ctx.fillRect(Math.random() * size, Math.random() * size, 2, 2);
    }

    return ctx.createPattern(canvas, 'repeat');
}

// Helper to get or create cached gradient
function getMaterials(ctx: CanvasRenderingContext2D, theme: any, height: number, themeId: string) {
    const hKey = Math.round(height);
    const key = `${themeId}_${hKey}`;

    if (MATERIAL_CACHE.has(key)) return MATERIAL_CACHE.get(key)!;

    // 1. Side Gradient (Vertical)
    const topY = -height;
    const bottomY = 12; 

    const sideGrad = ctx.createLinearGradient(0, topY, 0, bottomY);
    sideGrad.addColorStop(0, theme.sideDark);
    sideGrad.addColorStop(0.5, theme.sideLight);
    sideGrad.addColorStop(1, '#020617'); 

    // 2. Top Material (Noise + Gradient simulation)
    // We render a small canvas for the top to include noise texture
    const r = HEX_SIZE;
    const topCanvas = document.createElement('canvas');
    topCanvas.width = r * 2;
    topCanvas.height = r * 2 * ISO_SCALE_Y;
    const tCtx = topCanvas.getContext('2d')!;

    // Base Gradient
    const topGrad = tCtx.createLinearGradient(0, 0, r*2, r*2*ISO_SCALE_Y);
    topGrad.addColorStop(0, theme.rim); 
    topGrad.addColorStop(0.3, theme.top);
    topGrad.addColorStop(1, theme.sideDark);

    tCtx.fillStyle = topGrad;
    tCtx.fillRect(0, 0, topCanvas.width, topCanvas.height);

    // Noise Overlay
    tCtx.globalCompositeOperation = 'overlay';
    const noise = createNoisePattern('#808080', 0.5);
    if (noise) {
        tCtx.fillStyle = noise;
        tCtx.fillRect(0,0, topCanvas.width, topCanvas.height);
    }

    const topPattern = ctx.createPattern(topCanvas, 'no-repeat');

    const mats = { side: sideGrad, top: topPattern || topGrad };
    MATERIAL_CACHE.set(key, mats);
    return mats;
}

export const TerrainRenderer = {

    /**
     * Optimized Block Drawer using Local Space Coordinates and Cached Materials.
     */
    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        const BASE_THICKNESS = 12; 
        const faceY = -height; // Local Top Face Y

        ctx.save();
        ctx.translate(x, y); // Move to Base Center

        const mats = getMaterials(ctx, theme, height, type);

        // 1. Draw Side Faces
        const visibleIndices = [5, 0, 1]; 

        ctx.fillStyle = mats.side;
        // Fix: Use lighter stroke for edge definition instead of dark shadow
        ctx.strokeStyle = theme.sideDark; 
        ctx.lineWidth = 0.5; 

        // SEAM FIX: Overlap factor to prevent gaps
        const overlap = 0.5;

        ctx.beginPath();
        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const v1 = HEX_VERTICES[i];
            const v2 = HEX_VERTICES[j];

            // Pre-calc coordinates
            const v1x = v1.x * size;
            const v1y = v1.y * size * ISO_SCALE_Y;
            const v2x = v2.x * size;
            const v2y = v2.y * size * ISO_SCALE_Y;

            // Top vertices (Use floating point precision)
            const x1 = v1x;
            const y1_top = faceY + v1y;
            const x2 = v2x;
            const y2_top = faceY + v2y;

            // Bottom vertices (Extend slightly down for overlap)
            const y1_bottom = v1y + BASE_THICKNESS + overlap; 
            const y2_bottom = v2y + BASE_THICKNESS + overlap;

            // Use overlap for X as well to seal vertical seams
            // We push the edges out slightly based on vertex normal (approx)
            const pushX = (v1.x + v2.x) * 0.1; 

            ctx.moveTo(x1, y1_bottom);
            ctx.lineTo(x2, y2_bottom); 
            ctx.lineTo(x2, y2_top);    
            ctx.lineTo(x1, y1_top);    
            ctx.lineTo(x1, y1_bottom); 
        }
        ctx.fill();
        ctx.stroke();

        // 2. Draw Top Face
        // Pattern needs to be offset to match translate
        ctx.save();
        ctx.translate(-size, faceY - size * ISO_SCALE_Y); // Align pattern origin
        ctx.fillStyle = mats.top;

        // Trace hex relative to pattern origin
        ctx.beginPath();
        const startX = size;
        const startY = size * ISO_SCALE_Y;

        const v0 = HEX_VERTICES[0];
        ctx.moveTo(startX + v0.x * size, startY + v0.y * size * ISO_SCALE_Y);
        for (let i = 1; i < 6; i++) {
            const v = HEX_VERTICES[i];
            ctx.lineTo(startX + v.x * size, startY + v.y * size * ISO_SCALE_Y);
        }
        ctx.closePath();
        ctx.fill();
        ctx.restore();

        // 3. Bevel Highlight (Visual Pop)
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.4;
        ctx.beginPath();
        // Highlight top-left edges (Indices 2,3,4) - Simulates light source from Top-Left
        const hlIndices = [2, 3, 4];
        for (const i of hlIndices) {
            const j = (i + 1) % 6;
            const v1 = HEX_VERTICES[i];
            const v2 = HEX_VERTICES[j];
            ctx.moveTo(v1.x * size, faceY + v1.y * size * ISO_SCALE_Y);
            ctx.lineTo(v2.x * size, faceY + v2.y * size * ISO_SCALE_Y);
        }
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        // Tier lines (Only if tall)
        if (height > BLOCK_HEIGHT) {
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            for (const i of visibleIndices) {
                const j = (i + 1) % 6;
                const v1 = HEX_VERTICES[i];
                const v2 = HEX_VERTICES[j];
                const x1 = v1.x * size;
                const x2 = v2.x * size;
                const y1_base = v1.y * size * ISO_SCALE_Y;
                const y2_base = v2.y * size * ISO_SCALE_Y;

                // Draw lines at step intervals
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    const localY = -hStep;
                    ctx.moveTo(x1, localY + y1_base);
                    ctx.lineTo(x2, localY + y2_base);
                }
            }
            ctx.stroke();
        }

        // 4. Surface Assets (Animated)
        if (type === 'MAGMA' || type === 'VOID' || type === 'ICE') {
            if (type === 'MAGMA') {
                SurfacePainter.drawLiquid(ctx, 0, faceY, '#ef4444', globalTime, 1.0);
                const crackInt = 0.5 + Math.sin(globalTime) * 0.2;
                SurfacePainter.drawCracks(ctx, 0, faceY, '#fca5a5', crackInt);
            } else if (type === 'VOID') {
                SurfacePainter.drawFog(ctx, 0, faceY, theme.fogColor || '#6366f1', globalTime);
            } else if (type === 'ICE') {
                const bandPos = (globalTime * 50 + x + y) % (size * 4) - size * 2;
                ctx.save(); 
                HexGeometry.traceHex(ctx, 0, faceY, size, true);
                ctx.clip(); 
                const specGrad = ctx.createLinearGradient(-size, faceY - size, size, faceY + size);
                specGrad.addColorStop(0, 'transparent');
                specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.3)'); 
                specGrad.addColorStop(1, 'transparent');
                ctx.translate(bandPos * 0.5, 0); 
                ctx.fillStyle = specGrad;
                ctx.fill();
                ctx.restore();
            } 
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
        SurfacePainter.drawDetailTexture(ctx, cx, cy, type, detailColor, seed);
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { MovementType } from "../../../../../types";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        ctx.save();
        ctx.translate(px, py); // Ground Level

        // 1. Drop Shadow (Optimized: Use Cached Blob)
        const shadowScale = Math.max(0.6, 1.0 - (pz / 400));
        const shadowAlpha = Math.max(0.2, 1.0 - (pz / 200));

        // Reuse VFXFactory for generic shadow blob
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.5)'); 

        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        // Shadow Blob is 64x64, unit base is 128x128 approx visual weight
        // Scale it up
        ctx.drawImage(shadowBlob, -48, -24, 96, 48); 
        ctx.restore();

        // 2. Base Token (Falls backward if flying? No, base usually stays on ground or fades)
        // Design Choice: Base stays on ground, unit floats above it.
        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. Class Icon (Anchored to ground, breathing effect)
        if (agent.hp > 0) {
            ctx.save();
            const iconBaseY = -24; 
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            // Dark backing for icon visibility
            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. Casting Indicators (Ground Level)
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                const visualRadius = isAOE ? 0.8 : radius;
                UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, visualRadius, skill.tag, isAOE);
            }
        }

        ctx.restore();

        // 5. Flying Anchor Line (If high up)
        if (agent.movementType === MovementType.FLYING && pz > 5) {
            UnitFlightPainter.drawFlyingAnchor(ctx, agent, t, px, py, pz);
        }
    }
};

import { Agent } from "../../game";

export class CooldownSystem {
    public update(agent: Agent, dt: number) {
        // Skill Cooldowns
        for (let i = 0; i < agent.curCDs.length; i++) {
            if (agent.curCDs[i] > 0) {
                agent.curCDs[i] = Math.max(0, agent.curCDs[i] - dt);
            }
        }

        // Spawn Animation Timer
        if (agent.spawnTimer > 0) {
            agent.spawnTimer -= dt;
        }
    }
}

import { Agent, GameEngine } from "../../game";

export class EffectSystem {
    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. DoT (Damage over Time)
        if (agent.dotTimer > 0) {
            agent.dotTimer -= dt;

            let dmg = agent.dotDmg * dt;

            // Shield Absorption
            if (agent.shield > 0) {
                const absorbed = Math.min(agent.shield, dmg);
                agent.shield -= absorbed;
                dmg -= absorbed;
            }

            if (dmg > 0) {
                agent.hp -= dmg;
            }

            // Visual Feedback (Throttled)
            if (Math.random() < 0.05) { 
                engine.events.push({ 
                    type: 'DAMAGE', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: -Math.round(agent.dotDmg), 
                    color: '#10b981',
                    skill: { ccType: 'DOT' } as any 
                });
                agent.hitFlashTimer = 0.1;
            }
        }

        // 2. HoT (Heal over Time)
        if (agent.hotTimer > 0) {
            agent.hotTimer -= dt;
            agent.hp = Math.min(agent.maxHp, agent.hp + agent.hotVal * dt);

            if (Math.random() < 0.05) {
                engine.events.push({ 
                    type: 'HEAL', 
                    pos: {x: agent.px, y: agent.py}, 
                    value: Math.round(agent.hotVal), 
                    color: '#86efac' 
                });
            }
        }
    }
}

import { Agent, GameEngine } from "../../game";
import { AnimState } from "../../../types";
import { HexUtils } from "../../utils";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";

export class ControlSystem {
    // Track VFX intervals to avoid spamming particles every frame
    private vfxTimers = new Map<string, number>();

    public update(agent: Agent, dt: number, engine: GameEngine) {
        // 1. Diminishing Returns (DR) Decay
        for (const type in agent.drTimers) {
            if (agent.drTimers.hasOwnProperty(type)) {
                agent.drTimers[type] -= dt;
                if (agent.drTimers[type] <= 0) {
                    agent.drStacks[type] = 0;
                    delete agent.drTimers[type];
                }
            }
        }

        // 2. Banish Logic
        if (agent.banishTimer > 0) {
            agent.banishTimer -= dt;
            if (agent.banishTimer <= 0) {
                agent.banished = false;
                engine.log(agent, 'CC', '放逐結束', null, '重返戰場');
            } else {
                // Hard CC: Skip other logic if banished (unless Polymorph which allows wandering visuals sometimes)
                if (agent.visualStatus !== 'POLYMORPH') return; 
            }
        }

        // 3. CC Timers
        if (agent.stunTimer > 0) agent.stunTimer -= dt;
        if (agent.silenceTimer > 0) agent.silenceTimer -= dt;
        if (agent.rootTimer > 0) agent.rootTimer -= dt;
        if (agent.blindTimer > 0) agent.blindTimer -= dt;
        if (agent.tauntTimer > 0) {
            agent.tauntTimer -= dt;
            if (agent.tauntTimer <= 0) agent.tauntTargetId = null;
        }

        // 4. Fear Logic (Random Movement)
        if (agent.fearTimer > 0) {
            agent.fearTimer -= dt;
            if (!agent.isMoving && agent.hp > 0 && agent.stunTimer <= 0 && agent.rootTimer <= 0) {
                const neighbors = HexUtils.neighbors(agent);
                const valid = neighbors.filter(n => engine.map.isValid(n.q, n.r) && !engine.map.isBlocked(n.q, n.r, engine, agent.id));
                if (valid.length > 0) {
                    const next = valid[Math.floor(Math.random() * valid.length)];
                    // Panic run speed
                    engine.movement.moveAgentToHex(agent, next, 0, engine, 1.5);
                }
            }
        }

        // 5. Visual State Reset
        if (agent.visualStatus === 'FROZEN' && agent.stunTimer <= 0) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'POLYMORPH' && !agent.banished) agent.visualStatus = 'NONE';
        if (agent.visualStatus === 'STASIS' && !agent.banished) agent.visualStatus = 'NONE';

        // 6. Animation State Reset (Idle)
        if (agent.stunTimer <= 0 && agent.banishTimer <= 0 && !agent.isMoving && agent.castingSkillIdx === -1 && agent.hitFlashTimer <= 0) {
            if (agent.target) agent.setAnim(AnimState.COMBAT_IDLE);
            else agent.setAnim(AnimState.IDLE);
        }

        // 7. Status VFX Tick
        this.processStatusVFX(agent, dt, engine);
    }

    private processStatusVFX(agent: Agent, dt: number, engine: GameEngine) {
        if (!engine.renderer) return;

        const checkVFX = (key: string, condition: boolean) => {
            if (!condition) return;
            const def = STATUS_VISUALS[key];
            if (!def || !def.particleEffect) return;

            const timerKey = `${agent.id}_${key}`;
            let t = this.vfxTimers.get(timerKey) || 0;
            t -= dt;

            if (t <= 0) {
                t = def.particleInterval || 0.5;
                const h = engine.map.getTerrainHeight(agent.q, agent.r);
                // Adjust height to body center
                engine.renderer.vfx.playEffect(
                    def.particleEffect, 
                    agent.px, agent.py, 
                    h + agent.physics.z + 45
                );
            }
            this.vfxTimers.set(timerKey, t);
        };

        checkVFX('POISON', agent.dotTimer > 0 && agent.dotDmg > 0);
        checkVFX('REGEN', agent.hotTimer > 0);
        checkVFX('BANISH', agent.banished);
        checkVFX('FEAR', agent.fearTimer > 0);
    }
}

import { DEFAULT_SKILL_DB } from "../skillDatabase";
import { SCENE_DB } from "../data/scenes";
import { LogEntry, NodeState, Role, Skill, Team, Projectile, GameEvent, GameEventType, AnimState, SceneTheme, Hex, MovementType, LogActionType } from "../types";
import { BTNode } from "./behaviorTree";
import { HexUtils, MapConfig, Vector } from "./utils";

// Core Entities
import { Agent, SpecialVisualStatus } from "./core/Agent";

// Systems
import { MovementSystem } from "./systems/movement";
import { PhysicsSystem } from "./systems/PhysicsSystem"; 
import { CombatSystem } from "./systems/combat";
import { MapSystem } from "./systems/map";
import { HazardSystem } from "./systems/HazardSystem"; 
import { AISystem } from "./systems/ai";
import { AgentManager } from "./systems/agentManager";
import { AnnouncerSystem } from "./systems/AnnouncerSystem"; 
import { DirectorSystem } from "./systems/DirectorSystem"; 
import { BattleLogger } from "./systems/BattleLogger"; 
import { TimeSystem } from "./systems/TimeSystem"; 
import { VictorySystem } from "./systems/VictorySystem"; 
import { ZoneSystem } from "./systems/ZoneSystem"; 
import { EventBus } from "./events/EventBus";
import { EventPool } from "./events/GameEventPool"; 

// Split Status Systems
import { CooldownSystem } from "./systems/status/CooldownSystem";
import { EffectSystem } from "./systems/status/EffectSystem";
import { ControlSystem } from "./systems/status/ControlSystem";

import type { GameRenderer } from "./renderer";

export { Agent, SpecialVisualStatus };

// Constants
export const VICTORY_PHASE_DURATION = 0.5; 

export class GameEngine {
    public agents: Agent[] = [];

    get mapKeys() { return this.map.mapKeys; }
    get obstacles() { return this.map.obstacles; }
    get projectiles() { return this.combat.projectiles; }

    get logs() { return this.logger.logs; }

    public events: GameEvent[] = [];

    public bus: EventBus = new EventBus();
    public renderer?: GameRenderer;

    public isRunning: boolean = false;
    public mapVersion: number = 0; 

    // Time & Victory Proxies
    get timeScale() { return this.time.timeScale; }
    set timeScale(v: number) { this.time.timeScale = v; }
    get targetTimeScale() { return this.time.targetTimeScale; }
    set targetTimeScale(v: number) { this.time.targetTimeScale = v; }
    get battleTime() { return this.time.battleTime; }
    set battleTime(v: number) { this.time.battleTime = v; }

    get isFinishing() { return this.victory.isFinishing; }
    get victoryTimer() { return this.victory.victoryTimer; }
    get winningTeam() { return this.victory.winningTeam; }

    public mapConfig: MapConfig = { w: 12, h: 8, offsetX: 0, offsetY: 0 };
    public currentScene: SceneTheme = SCENE_DB[0];

    public skillDB: Skill[] = [...DEFAULT_SKILL_DB];

    public agentMap: Map<number, Agent> = new Map();

    // Systems
    public movement: MovementSystem;
    public physics: PhysicsSystem; 
    public combat: CombatSystem;
    public map: MapSystem;
    public hazards: HazardSystem;
    public ai: AISystem;
    public agentManager: AgentManager;
    public announcer: AnnouncerSystem; 
    public director: DirectorSystem;
    public logger: BattleLogger; 
    public time: TimeSystem; 
    public victory: VictorySystem; 
    public zones: ZoneSystem; 

    // New Split Status Systems
    public cooldowns: CooldownSystem;
    public effects: EffectSystem;
    public controls: ControlSystem;

    get directorTargetId() { return this.director.targetId; }

    constructor() {
        this.movement = new MovementSystem();
        this.physics = new PhysicsSystem();
        this.combat = new CombatSystem();
        this.map = new MapSystem();
        this.hazards = new HazardSystem();
        this.ai = new AISystem();
        this.agentManager = new AgentManager();
        this.announcer = new AnnouncerSystem(); 
        this.director = new DirectorSystem();
        this.logger = new BattleLogger();
        this.time = new TimeSystem();
        this.victory = new VictorySystem();
        this.zones = new ZoneSystem();

        // Initialize New Systems
        this.cooldowns = new CooldownSystem();
        this.effects = new EffectSystem();
        this.controls = new ControlSystem();

        this.map.randomizeEnvironment(this);
    }

    addAgent(team: Team, q: number, r: number, hpOverride?: number) { return this.agentManager.addAgent(this, team, q, r, hpOverride); }
    setObstacle(q: number, r: number, type: string) { this.map.setObstacle(q, r, type); }
    removeObstacle(q: number, r: number) { this.map.removeObstacle(q, r); }
    toggleObstacle(q: number, r: number, type: string = 'WALL') { this.map.toggleObstacle(q, r, this, type); }

    isValid(q: number, r: number) { return this.map.isValid(q, r); }
    isBlocked(q: number, r: number, ignoreId?: string, movementType: MovementType = MovementType.GROUND) { return this.map.isBlocked(q, r, this, ignoreId, movementType); }
    isValidHash(h: number) { return this.map.isValidHash(h); }
    hasObstacle(q: number, r: number) { return this.map.hasObstacle(q, r); }
    hasObstacleHash(h: number) { return this.map.hasObstacleHash(h); }

    randomizeEnvironment() { 
        this.hazards.reset(); 
        if (this.renderer) this.renderer.vfx.reset(); 
        this.map.randomizeEnvironment(this); 
    }

    rebuildMap() { 
        this.hazards.reset();
        this.map.rebuildMap(this); 
    }

    removeAgent(q: number, r: number) {
        const hash = HexUtils.hash(q, r);
        const agent = this.agentMap.get(hash);
        if (agent) {
            this.agents = this.agents.filter(a => a !== agent);
            this.agentMap.delete(hash);
        }
    }

    getAgentAt(q: number, r: number): Agent | undefined {
        const agent = this.agentMap.get(HexUtils.hash(q, r));
        return (agent && agent.hp > 0) ? agent : undefined;
    }

    updateAgentPosition(agent: Agent, newQ: number, newR: number) {
        const oldH = this.map.getTerrainHeight(agent.q, agent.r);
        const newH = this.map.getTerrainHeight(newQ, newR);
        const deltaH = oldH - newH;

        agent.physics.z += deltaH;

        this.agentMap.delete(HexUtils.hash(agent.q, agent.r));
        agent.q = newQ;
        agent.r = newR;
        this.agentMap.set(HexUtils.hash(agent.q, agent.r), agent);
    }

    // Helper to push event via Pool
    public pushEvent(
        type: GameEventType, 
        pos: {x: number, y: number}, 
        opts: { value?: number, text?: string, color?: string, skill?: Skill, sourceId?: string, targetId?: string, team?: Team } = {}
    ) {
        const evt = EventPool.get(type, pos, opts);
        this.events.push(evt);
    }

    public play() {
        if (!this.isRunning) {
            this.agents.forEach(a => a.saveState());
            this.time.reset();
            this.logger.clear();
            this.victory.reset();
            this.log(null, 'SYSTEM', '開始', null, '戰鬥分析開始');
            this.bus.emit('GAME_START', {});
        }
        this.agentMap.clear();
        this.agents.forEach(a => {
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            a.bt = this.ai.buildAI(a, this); 
            a.animState = AnimState.IDLE;
            if (a.hp > 0) {
                this.agentMap.set(HexUtils.hash(a.q, a.r), a);
            }
        });
        this.isRunning = true;
    }

    public stop() { this.isRunning = false; }

    public restart() {
        this.stop();
        this.victory.reset();
        this.time.reset();
        this.agentMap.clear();
        this.hazards.reset(); 
        this.announcer.reset(); 
        this.director.reset();

        this.agents.forEach(a => {
            a.reset(this.mapConfig);
            a.skills = a.skillIds.map(id => {
                if (!id) return null;
                return this.skillDB.find(s => s.id === id) || null;
            });
            this.agentMap.set(HexUtils.hash(a.q, a.r), a);
        });

        this.flushEvents();
        this.combat.reset(); 

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset(); 
            this.renderer.vfx.reset(); 
        }

        this.log(null, 'SYSTEM', '重置', null, '戰場狀態已重置');
        this.bus.emit('GAME_RESET', {});
    }

    public clear(keepScene: boolean = false) {
        this.stop();
        this.agents = [];
        this.agentMap.clear();
        this.hazards.reset(); 
        this.map.obstacles.clear();
        this.map.obstaclesHash.clear();
        this.announcer.reset();
        this.director.reset();

        this.combat.reset(); 
        this.flushEvents();

        if (this.renderer) {
            this.renderer.reset();
            this.renderer.grid.reset();
            this.renderer.vfx.reset();
        }

        this.logger.clear();

        if (!keepScene) {
            this.map.randomizeEnvironment(this); 
        } else {
            this.map.rebuildMap(this); 
        }

        this.bus.emit('GAME_CLEAR', {});
    }

    private flushEvents() {
        for(const e of this.events) EventPool.release(e);
        this.events.length = 0;
    }

    public tick(dt: number) {
        if (!this.isRunning) return;

        this.time.update(dt);
        this.flushEvents(); 
        this.director.update(dt, this);
        this.zones.update(this); 

        // Check Victory
        if (this.victory.check(this)) {
            this.victory.updateFinishing(dt, this);
            this.updateEntities(dt);
            return;
        }

        this.updateEntities(dt);
    }

    private updateEntities(dt: number) {
        // 1. Physics (Global)
        this.physics.update(dt, this);

        // 2. Logic
        for (const a of this.agents) {
            if (a.hitFlashTimer > 0) a.hitFlashTimer -= dt;

            if (a.hp <= 0) {
                this.agentManager.handleDeadState(a, this);
                continue;
            }

            // Execute Split Status Logic
            this.cooldowns.update(a, dt);
            this.effects.update(a, dt, this);
            this.controls.update(a, dt, this);

            if (a.isMoving && a.path.length > 0 && a.stunTimer <= 0) {
                this.movement.updateMovement(a, dt, this);
            }

            if (a.bt) {
                const resetTree = (node: BTNode) => { 
                    node.status = null; 
                    if (node.c) node.c.forEach(resetTree); 
                };
                resetTree(a.bt);
                a.bt.tick(a);
            }
        }

        // 3. Combat & Environment
        this.combat.update(dt, this);
        this.hazards.update(dt, this); 
        this.movement.resolveStacking(this);
        this.announcer.update(dt, this);
    }

    public log(agent: Agent | null, type: LogActionType, actionName: string, targetInfo: string | null, detail: string = '') {
        this.logger.log(this.battleTime, this.battleTime * 10, agent, type, actionName, targetInfo, detail);
    }
}

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Unit Scale)
// Vertices for a "Pointy Top" Hexagon with radius 1.0
// Angle 0 is at 30 degrees (PI/6) to align flat top with screen Y in ISO
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 

const UNIT_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    UNIT_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Pre-computed Render Paths (Performance)
// We cache the most common path: The Standard Grid Hex
let CACHED_HEX_PATH: Path2D | null = null;

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Uses strict ISO scaling on Y axis.
     */
    getVertices(radius: number): {x: number, y: number}[] {
        // Optimization: For standard grid size, we could cache this array too if needed.
        // For now, mapping is fast enough.
        return UNIT_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * ISO_SCALE_Y
        }));
    },

    /**
     * Optimized draw call. Uses Path2D if available and radius matches standard HEX_SIZE.
     * Guaranteed to match TerrainRenderer's geometry exactly.
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
        // Use cached path for standard grid cells (huge FPS boost for grid rendering)
        if (Math.abs(radius - HEX_SIZE) < 0.01) {
            if (!CACHED_HEX_PATH) {
                this.rebuildCache();
            }
            ctx.translate(x, y);
            // We fill/stroke the path relative to (0,0)
            // The caller must handle the operation (fill/stroke)
            // NOTE: Path2D cannot be stroked/filled directly here without context methods
            // but we can't return it easily for reuse in legacy code structure.
            // So we trace it.
            // Actually, ctx.fill(path) is the way. But current API expects trace logic.
            // Hybrid approach:
        }

        // Standard Trace (Fallback or Non-Standard Size)
        // This is mathematically identical to the cache.
        ctx.beginPath();
        const verts = this.getVertices(radius);
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * Returns a Path2D object for the standard hex. 
     * Callers can use ctx.fill(path) which is faster than JS-side moveTo/lineTo loops.
     */
    getStandardPath(): Path2D {
        if (!CACHED_HEX_PATH) this.rebuildCache();
        return CACHED_HEX_PATH!;
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_HEX_PATH = path;
    },

    /**
     * Returns vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

// --- MATERIAL CACHE ---
const MATERIAL_CACHE: Map<string, { side: CanvasGradient, top: CanvasPattern | CanvasGradient }> = new Map();

function createNoisePattern(color: string, opacity: number): CanvasPattern | null {
    const size = 64;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d')!;

    ctx.fillStyle = color;
    ctx.fillRect(0,0,size,size);

    // Add noise
    for (let i = 0; i < 400; i++) {
        ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.1 * opacity})`;
        ctx.fillRect(Math.random() * size, Math.random() * size, 2, 2);
        ctx.fillStyle = `rgba(0,0,0,${Math.random() * 0.1 * opacity})`;
        ctx.fillRect(Math.random() * size, Math.random() * size, 2, 2);
    }

    return ctx.createPattern(canvas, 'repeat');
}

// Helper to get or create cached gradient
function getMaterials(ctx: CanvasRenderingContext2D, theme: any, height: number, themeId: string) {
    const hKey = Math.round(height);
    const key = `${themeId}_${hKey}`;

    if (MATERIAL_CACHE.has(key)) return MATERIAL_CACHE.get(key)!;

    // 1. Side Gradient (Vertical)
    const topY = -height;
    const bottomY = 12; 

    const sideGrad = ctx.createLinearGradient(0, topY, 0, bottomY);
    sideGrad.addColorStop(0, theme.sideDark);
    sideGrad.addColorStop(0.5, theme.sideLight);
    sideGrad.addColorStop(1, '#020617'); 

    // 2. Top Material
    const r = HEX_SIZE;
    const topCanvas = document.createElement('canvas');
    topCanvas.width = r * 2;
    topCanvas.height = r * 2 * ISO_SCALE_Y;
    const tCtx = topCanvas.getContext('2d')!;

    // Base Gradient
    const topGrad = tCtx.createLinearGradient(0, 0, r*2, r*2*ISO_SCALE_Y);
    topGrad.addColorStop(0, theme.rim); 
    topGrad.addColorStop(0.3, theme.top);
    topGrad.addColorStop(1, theme.sideDark);

    tCtx.fillStyle = topGrad;
    tCtx.fillRect(0, 0, topCanvas.width, topCanvas.height);

    // Noise Overlay
    tCtx.globalCompositeOperation = 'overlay';
    const noise = createNoisePattern('#808080', 0.5);
    if (noise) {
        tCtx.fillStyle = noise;
        tCtx.fillRect(0,0, topCanvas.width, topCanvas.height);
    }

    const topPattern = ctx.createPattern(topCanvas, 'no-repeat');

    const mats = { side: sideGrad, top: topPattern || topGrad };
    MATERIAL_CACHE.set(key, mats);
    return mats;
}

export const TerrainRenderer = {

    drawBlockGeometry(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        const BASE_THICKNESS = 12; 
        const faceY = -height; // Local Top Face Y

        ctx.save();
        ctx.translate(x, y); // Move to Base Center

        const mats = getMaterials(ctx, theme, height, type);

        // --- 1. GEOMETRY SOURCE OF TRUTH ---
        // Get strict vertices from HexGeometry (No custom math here)
        const verts = HexGeometry.getVertices(size);

        // --- 2. DRAW SIDE FACES (With Overlap) ---
        const visibleIndices = [5, 0, 1]; // Front faces
        const overlap = 0.6; // Pixel overlap to hide seams between tiles

        ctx.fillStyle = mats.side;
        ctx.strokeStyle = theme.sideDark; 
        ctx.lineWidth = 0.5; 

        ctx.beginPath();
        for (const i of visibleIndices) {
            const j = (i + 1) % 6;
            const v1 = verts[i];
            const v2 = verts[j];

            // Side Geometry
            // Top edge matches top face exactly (y + faceY)
            // Bottom edge extends down + overlap
            // Sides extend out slightly if needed, but overlap Y is usually enough

            ctx.moveTo(v1.x, faceY + v1.y);           // Top Left
            ctx.lineTo(v2.x, faceY + v2.y);           // Top Right
            ctx.lineTo(v2.x, v2.y + BASE_THICKNESS + overlap); // Bottom Right (Extended)
            ctx.lineTo(v1.x, v1.y + BASE_THICKNESS + overlap); // Bottom Left (Extended)
            ctx.lineTo(v1.x, faceY + v1.y);           // Close
        }
        ctx.fill();
        ctx.stroke();

        // --- 3. DRAW TOP FACE (Strict Alignment) ---
        // Use the Pattern, but we must translate the pattern to match the face
        ctx.save();

        // Pattern logic: Align pattern to top-left of the bounding box of the top face
        // Hex bounding box is approx (-size, -size*iso) to (size, size*iso)
        // Pattern size is 2*size wide.
        ctx.translate(-size, faceY - size * ISO_SCALE_Y); 
        ctx.fillStyle = mats.top;

        // Path relative to pattern origin
        // Vertex 0 in pattern space: (size + v.x, size*iso + v.y)
        ctx.beginPath();
        const startX = size;
        const startY = size * ISO_SCALE_Y;

        ctx.moveTo(startX + verts[0].x, startY + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(startX + verts[i].x, startY + verts[i].y);
        }
        ctx.closePath();
        ctx.fill();
        ctx.restore();

        // --- 4. BEVEL HIGHLIGHT (Visual Pop) ---
        // Draws *inside* the strict geometry
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.4;
        ctx.beginPath();
        const hlIndices = [2, 3, 4]; // Top-Left edges
        for (const i of hlIndices) {
            const j = (i + 1) % 6;
            const v1 = verts[i];
            const v2 = verts[j];
            ctx.moveTo(v1.x, faceY + v1.y);
            ctx.lineTo(v2.x, faceY + v2.y);
        }
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        // --- 5. TIER LINES ---
        if (height > BLOCK_HEIGHT) {
            ctx.strokeStyle = 'rgba(0,0,0,0.2)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            for (const i of visibleIndices) {
                const j = (i + 1) % 6;
                const v1 = verts[i];
                const v2 = verts[j];

                // Draw lines at step intervals
                for (let hStep = BLOCK_HEIGHT; hStep < height; hStep += BLOCK_HEIGHT) {
                    const localY = -hStep;
                    // Note: Base vertices Y includes ISO scale already
                    ctx.moveTo(v1.x, localY + v1.y);
                    ctx.lineTo(v2.x, localY + v2.y);
                }
            }
            ctx.stroke();
        }

        // --- 6. SURFACE ASSETS ---
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, faceY, '#ef4444', globalTime, 1.0);
            const crackInt = 0.5 + Math.sin(globalTime) * 0.2;
            SurfacePainter.drawCracks(ctx, 0, faceY, '#fca5a5', crackInt);
        } else if (type === 'VOID') {
            SurfacePainter.drawFog(ctx, 0, faceY, theme.fogColor || '#6366f1', globalTime);
        } else if (type === 'ICE') {
            const bandPos = (globalTime * 50 + x + y) % (size * 4) - size * 2;
            ctx.save(); 
            // Clip to top face
            ctx.beginPath();
            ctx.moveTo(verts[0].x, faceY + verts[0].y);
            for (let i = 1; i < 6; i++) ctx.lineTo(verts[i].x, faceY + verts[i].y);
            ctx.closePath();
            ctx.clip(); 

            const specGrad = ctx.createLinearGradient(-size, faceY - size, size, faceY + size);
            specGrad.addColorStop(0, 'transparent');
            specGrad.addColorStop(0.5, 'rgba(255, 255, 255, 0.3)'); 
            specGrad.addColorStop(1, 'transparent');
            ctx.translate(bandPos * 0.5, 0); 
            ctx.fillStyle = specGrad;
            ctx.fill();
            ctx.restore();
        } 

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
        SurfacePainter.drawDetailTexture(ctx, cx, cy, type, detailColor, seed);
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { HEX_SIZE } from "../../../constants";

interface ZoneInfo {
    type: 'CAST';
    color: string;
    visual: string; // Skill visual tag
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face Y
        size: number,

        // State Props
        specialStatus: string | undefined, 
        zoneInfo: ZoneInfo | undefined,    

        // Lighting
        lightColor: string | null,
        lightIntensity: number,

        // Interactive
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        // Metadata
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        // --- PERFORMANCE OPTIMIZATION ---
        // If the size is standard (HEX_SIZE), use the cached Path2D from HexGeometry.
        // This avoids rebuilding the path logic every frame for every tile.
        // NOTE: We must translate to (x, y) first.

        const isStandard = Math.abs(size - HEX_SIZE) < 0.01;
        const hexPath = isStandard ? HexGeometry.getStandardPath() : null;

        const fillHex = (color: string, alpha: number) => {
            ctx.fillStyle = color;
            ctx.globalAlpha = alpha;
            if (hexPath) {
                ctx.translate(x, y);
                ctx.fill(hexPath);
                ctx.translate(-x, -y);
            } else {
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill();
            }
        };

        const strokeHex = (color: string, width: number, alpha: number) => {
            ctx.strokeStyle = color;
            ctx.lineWidth = width;
            ctx.globalAlpha = alpha;
            if (hexPath) {
                ctx.translate(x, y);
                ctx.stroke(hexPath);
                ctx.translate(-x, -y);
            } else {
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke();
            }
        };

        // --- LAYER 1: HAZARDS ---
        if (hazard) {
            HazardPainter.draw(ctx, x, y, hazard, globalTime);
        }

        // --- LAYER 2: UNIT STATUS FLOOR TINT ---
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.globalCompositeOperation = 'source-over';
                fillHex(def.floorColor, def.floorOpacity || 0.5);
                ctx.restore();
            }
        }

        // --- LAYER 3: CAST ZONES (Volumetric) ---
        // ZoneRenderer handles its own geometry (complex shapes)
        if (zoneInfo) {
            ZoneRenderer.drawZone(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // --- LAYER 4: DYNAMIC LIGHTING ---
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen'; 
            fillHex(lightColor, Math.min(0.5, lightIntensity * 0.4));
            ctx.restore();
        }

        // --- LAYER 5: INTERACTIVE UI HIGHLIGHTS ---
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';

            // Valid Move/Skill Range
            if (isRange) { 
                fillHex(rangeColor, 0.2);
                strokeHex(rangeColor, 2, 0.5);
            }

            // Mouse Hover - Bright Spotlight
            if (isHover) { 
                fillHex('#ffffff', 0.2);
                strokeHex('#ffffff', 2, 0.8);
            }

            // Unit Position - Subtle selection ring
            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                // Use trace here as we might want scaling/offset for the ring
                HexGeometry.traceHex(ctx, x, y, size * 0.9);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // 1. Interpolate Ground Position (Lerp if moving)
        let logicalX = agent.px;
        let logicalY = agent.py;
        let terrainH = 0;

        if (agent.isMoving && agent.path.length > 0) {
            const startH = getTerrainHeight(agent.q, agent.r);
            const nextHex = agent.path[0];
            const endH = getTerrainHeight(nextHex.q, nextHex.r);
            terrainH = HexUtils.lerp(startH, endH, agent.moveProgress);
            // px/py are already lerped by MotionEngine, but terrainH needs to sync
        } else {
            // Stability check for idle/knockback sliding
            const logicalPos = HexUtils.toPx(agent.q, agent.r, mapConfig);
            const distSq = (agent.px - logicalPos.x)**2 + (agent.py - logicalPos.y)**2;

            if (distSq > 400) { 
                const visualHex = HexUtils.fromPx(agent.px, agent.py, mapConfig);
                terrainH = getTerrainHeight(visualHex.q, visualHex.r);
            } else {
                terrainH = getTerrainHeight(agent.q, agent.r);
            }
        }

        // 2. Physics & Height
        // agent.physics.x/y/z are local offsets
        // x/y are used for shake/spring
        // z is the jump/flight height
        const visualX = logicalX + agent.physics.x;
        const visualY = logicalY + agent.physics.y; // Ground Y
        const visualZ = terrainH + agent.physics.z;

        // 3. Selection
        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, // Base scale, modified by Painter based on Role
            isSilhouette: false, // Calculated later by occlusion
            isSelected,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { Agent, GameEngine } from "../game";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { MapConfig } from "../utils";
import { UnitVisualProcessor } from "./unit/UnitVisualProcessor";
import { UnitBodyPainter } from "../renderers/units/painters/UnitBodyPainter";
import { UnitShadowPainter } from "../renderers/units/painters/UnitShadowPainter";

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // 1. Process Logic -> State
            const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, highlightAgent);

            const op = renderList.next();
            op.type = RenderOpType.UNIT;

            // Sort by ground Y for correct occlusion
            // Add +1 to draw slightly in front of center-aligned terrain elements
            op.y = state.y + 1; 
            op.z = 10;

            op.agent = agent;
            op.tx = state.x; 
            op.ty = state.y - state.terrainHeight; // Visual Ground Y (rendered relative to terrain top)
            op.th = state.terrainHeight; 
            op.time = globalTime;
            op.uSelected = state.isSelected;
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        // Recalculate state just for the silhouette pass
        const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, null);

        // Draw using the Assembly Painter directly (bypassing render list for this special pass)
        // Pass visual ground Y
        const visualGroundY = state.y - state.terrainHeight;
        this.drawAssembly(ctx, agent, state.x, visualGroundY, globalTime, false, true);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        // Legacy bridge: UnitBodyPainter expects these args
        // It calculates scale internally based on Role.
        // We could move scale calc to Processor later, but for now this is clean enough.

        // 1. Determine Scale (Logic still in Painter for now to avoid breaking sub-painters)
        // Ideally: Scale should be in VisualState.
        const scaleFactor = 1.0; 

        // 2. Global Transform for this Unit
        ctx.save();
        ctx.translate(drawX, drawY); 
        // ctx.scale is handled inside UnitBodyPainter to keep Shadow logic consistent (shadow scales differently)

        // 3. Coordinate Space
        // We are at (drawX, drawY). This corresponds to the Pixel on Screen where the unit stands.
        // Physics X/Y were already applied in drawX/drawY by the Processor.
        // We pass 0,0 as local coords.
        // Pass physics.z as the height offset.

        // NOTE: UnitBodyPainter expects raw physics for jitters.
        // Since we already added physics.x/y to drawX/Y, we pass 0 for x/y to painter?
        // Let's check UnitBodyPainter. It does: ctx.translate(px, py - pz).
        // If we pass 0,0, it translates 0, -pz. Correct.
        // But wait, UnitBodyPainter also draws Shadow at px, py.

        // Refactor: We pass 0,0 because we already translated context.
        const physX = 0; 
        const physY = 0;
        const physZ = agent.physics.z; 

        // 3. Draw Shadow & Base (Ground Layer)
        if (!isSilhouette && agent.hp > 0) {
            UnitShadowPainter.draw(ctx, agent, physX, physY, physZ, globalTime, isSilhouette);
        }

        // 4. Draw Body (Elevated Layer)
        UnitBodyPainter.draw(ctx, agent, physX, physY, physZ, globalTime, isSilhouette, isSelected, scaleFactor);

        ctx.restore(); 
    }
}

import { HexGeometry } from "../utils/HexGeometry";

export const GeometryPainter = {
    drawHex(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, style: 'FILL' | 'STROKE' | 'BOTH' = 'FILL') {
        // By default, GeometryPainter is used for VFX which are usually flat on ground, so applyIso = true
        HexGeometry.traceHex(ctx, x, y, r);

        if (style === 'FILL' || style === 'BOTH') ctx.fill();
        if (style === 'STROKE' || style === 'BOTH') ctx.stroke();
    },

    drawJaggedShape(ctx: CanvasRenderingContext2D, r: number) {
        ctx.beginPath();
        const spikes = 8;
        for(let i=0; i<spikes*2; i++) {
            const angle = (Math.PI * i) / spikes;
            const dist = (i % 2 === 0) ? r : r * 0.4;
            // Note: Jagged shapes (Fireballs) usually don't need strict ISO scaling, 
            // but if they are on the ground, they might. Assuming billboards here.
            ctx.lineTo(Math.cos(angle)*dist, Math.sin(angle)*dist);
        }
        ctx.closePath();
        ctx.fill();
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Unit Scale)
// Vertices for a "Pointy Top" Hexagon with radius 1.0
// Angle 0 is at 30 degrees (PI/6) to align flat top with screen Y in ISO
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 

export const HEX_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    HEX_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Pre-computed Render Paths (Performance)
// We cache the most common path: The Standard Grid Hex
let CACHED_HEX_PATH: Path2D | null = null;

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Uses strict ISO scaling on Y axis.
     */
    getVertices(radius: number): {x: number, y: number}[] {
        // Optimization: For standard grid size, we could cache this array too if needed.
        // For now, mapping is fast enough.
        return HEX_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * ISO_SCALE_Y
        }));
    },

    /**
     * Optimized draw call. Uses Path2D if available and radius matches standard HEX_SIZE.
     * Guaranteed to match TerrainRenderer's geometry exactly.
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
        // Use cached path for standard grid cells (huge FPS boost for grid rendering)
        if (Math.abs(radius - HEX_SIZE) < 0.01) {
            if (!CACHED_HEX_PATH) {
                this.rebuildCache();
            }
            ctx.translate(x, y);
            // We fill/stroke the path relative to (0,0)
            // The caller must handle the operation (fill/stroke)
            // NOTE: Path2D cannot be stroked/filled directly here without context methods
            // but we can't return it easily for reuse in legacy code structure.
            // So we trace it.
            // Actually, ctx.fill(path) is the way. But current API expects trace logic.
            // Hybrid approach:
        }

        // Standard Trace (Fallback or Non-Standard Size)
        // This is mathematically identical to the cache.
        ctx.beginPath();
        const verts = this.getVertices(radius);
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * Returns a Path2D object for the standard hex. 
     * Callers can use ctx.fill(path) which is faster than JS-side moveTo/lineTo loops.
     */
    getStandardPath(): Path2D {
        if (!CACHED_HEX_PATH) this.rebuildCache();
        return CACHED_HEX_PATH!;
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_HEX_PATH = path;
    },

    /**
     * Returns vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { GameEngine } from "../../game";
import { HexUtils } from "../../utils";
import { BLOCK_HEIGHT } from "../../../constants";

export interface CachedTile {
    q: number;
    r: number;
    px: number;
    py: number;
    h: number;
    key: string;
}

export class GridCache {
    public tileMap: Map<string, CachedTile> = new Map();
    public tileList: CachedTile[] = []; 
    private lastMapVersion: number = -1;

    public reset() {
        this.tileMap.clear();
        this.tileList = [];
        this.lastMapVersion = -1;
    }

    public ensure(engine: GameEngine) {
        if (this.lastMapVersion !== engine.mapVersion || this.tileList.length === 0) {
            this.rebuild(engine);
        }
    }

    private rebuild(engine: GameEngine) {
        this.tileList = [];
        this.tileMap.clear();
        this.lastMapVersion = engine.mapVersion;

        engine.mapKeys.forEach(k => {
            const [q, r] = k.split(',').map(Number);
            // Use standard HexUtils which delegates to HexMath for precision
            const pos = HexUtils.toPx(q, r, engine.mapConfig);
            const h = engine.map.getTerrainHeight(q, r);

            const tile: CachedTile = { q, r, px: pos.x, py: pos.y, h, key: k };

            this.tileList.push(tile);
            this.tileMap.set(k, tile);
        });
    }
}

import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";

export class GridSpatial {

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        const maxHeight = 200; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        // Raycast down from max possible height
        for (let h = 0; h <= maxHeight; h += step) {
            // "Unproject" the Y coordinate by adding height (since visual Y = ground Y - height)
            const testY = wy + h; 

            const frac = HexMath.pixelToHex(wx, testY, engine.mapConfig.offsetX, engine.mapConfig.offsetY);
            const rounded = HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
            const key = HexUtils.key(rounded);

            const tile = cache.tileMap.get(key);

            if (tile) {
                // Check if the click hits the top face or the slope
                // Visual Y of the tile top is (py - tile.h)
                const visualTopY = tile.py - tile.h;

                // Distance check in screen space roughly
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                // Tighter hit box for better precision
                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    // We found a candidate. Since we iterate from h=0 (Visual Top) downwards?
                    // Actually, we are testing logic planes.
                    // The tile with the highest visual Z (closest to camera) should win.
                    // Visual Z corresponds to (py + px) in ISO, or simply tile.h for stacking.

                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            // Visual Y of agent feet = uPx.y - terrainH
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);
            const uVisualY = uPx.y - uTerrainH;

            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const nTerrainH = engine.map.getTerrainHeight(n.q, n.r);
                    const nVisualY = nPx.y - nTerrainH;

                    // Occlusion Check:
                    // If neighbor is visually "below" (higher Y) on screen? No, objects in front have higher Y in ISO.
                    // Wait, standard 2D canvas: Y increases downwards.
                    // So "Front" is Higher Y.
                    // If neighbor Y > Agent Y, neighbor is in front.

                    if (nPx.y > uPx.y) { // Neighbor is "South" of agent
                         // Check Height: If neighbor is TALLER than agent's feet level?
                         if (nTerrainH > uTerrainH) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        }
        return occluded;
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 95; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            // Visual Ground Top Y = (BaseY - Height + Transition)
            const visualTopY = py - h + offset;
            const visualBaseY = py + offset;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Obstacles anchor to the visual top of the block
                op.ty = visualTopY - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            let zoneInfo = undefined;
            const zResult = engine.zones.getZoneAt(q, r);
            if (zResult) {
                const { zone, dist } = zResult;
                zoneInfo = { 
                    type: zone.type, 
                    color: zone.color, 
                    visual: zone.visual, 
                    progress: zone.progress, 
                    centerQ: zone.q, centerR: zone.r, 
                    radius: zone.radius, dist 
                };
            }

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            // Only show range if hovering a skill OR holding a skill hotkey (future)
            // Currently logic depends on hoveredSkill from UI
            if (hoveredSkill && highlightAgent) {
                // Check Range Logic
                // Note: TargetingSystem.getEffectiveRange logic duplicated here slightly for speed?
                // Better to use engine.movement.getEffectiveRange if accessible, but we are inside renderer.
                // Re-implement simple height check:
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                // Height bonus logic must match TargetingSystem
                const bonus = Math.max(0, Math.floor(deltaH / 24)); // 24 = BLOCK_HEIGHT
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights (Dynamic Lighting)
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    // Simple linear falloff
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; // Terrain is layer 0

            op.tx = px; 
            // Important: We pass the Visual Base Y. The renderer will draw up to -h.
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { GameEngine, Agent } from "../game";
import { Hex, Skill, Projectile } from "../../types";
import { RenderList } from "../renderers/RenderList";
import { GridCache } from "./grid/GridCache";
import { GridSpatial } from "./grid/GridSpatial";
import { GridRenderStrategy } from "./grid/GridRenderStrategy";

export class GridSystem {
    private cache: GridCache;
    private renderer: GridRenderStrategy;

    constructor() {
        this.cache = new GridCache();
        this.renderer = new GridRenderStrategy();
    }

    public reset() {
        this.cache.reset();
    }

    public getTerrainHeight(q: number, r: number, engine?: GameEngine): number {
        // Proxy to engine map, but this method exists for interface compatibility
        if(engine) return engine.map.getTerrainHeight(q, r);
        return 0; 
    }

    public getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine): Hex | null {
        return GridSpatial.getHexAtWorldPoint(wx, wy, engine, this.cache);
    }

    public getOccludedAgents(engine: GameEngine): Agent[] {
        return GridSpatial.getOccludedAgents(engine);
    }

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        this.renderer.submit(
            this.cache,
            renderList,
            engine,
            hoveredHex,
            hoveredSkill,
            highlightAgent,
            projectiles,
            transitionT,
            transitionPhase,
            globalTime
        );
    }
}

import { Agent, GameEngine } from "../game";
import { RenderList, RenderOpType } from "../renderers/RenderList";
import { MapConfig } from "../utils";
import { UnitVisualProcessor } from "./unit/UnitVisualProcessor";
import { UnitBodyPainter } from "../renderers/units/painters/UnitBodyPainter";
import { UnitShadowPainter } from "../renderers/units/painters/UnitShadowPainter";

export class UnitRenderSystem {

    public submitRenderables(
        renderList: RenderList,
        agents: Agent[], 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        highlightAgent: Agent | null,
        mapConfig: MapConfig
    ) {
        agents.forEach(agent => {
            if (agent.hp <= 0 && agent.fullyDead) return;

            // 1. Process Logic -> State
            const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, highlightAgent);

            const op = renderList.next();
            op.type = RenderOpType.UNIT;

            // Sort by ground Y for correct occlusion (Painter's Algorithm)
            // Add +1 to draw slightly in front of center-aligned terrain elements
            op.y = state.y + 1; 
            op.z = 10;

            op.agent = agent;

            // ALIGNMENT FIX:
            // state.x / state.y = Physical Ground Coordinates (Base of block)
            // state.terrainHeight = Height of block
            // visualGroundTop = state.y - state.terrainHeight

            op.tx = state.x; 
            op.ty = state.y - state.terrainHeight; // Anchor Visuals to TOP of block

            // Pass LOCAL Physics Z to painter, NOT Total Z.
            // Painter will translate(0, -pz).
            op.th = agent.physics.z; 

            op.time = globalTime;
            op.uSelected = state.isSelected;
            op.uSilhouette = false;
        });
    }

    public drawSilhouette(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number, 
        globalTime: number, 
        mapConfig: MapConfig
    ) {
        // Recalculate state just for the silhouette pass
        const state = UnitVisualProcessor.process(agent, getTerrainHeight, mapConfig, null);

        // Use consistent alignment
        const visualGroundY = state.y - state.terrainHeight;

        this.drawAssembly(ctx, agent, state.x, visualGroundY, agent.physics.z, globalTime, false, true);
    }

    public drawAssembly(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        drawX: number, 
        drawY: number, 
        localZ: number,
        globalTime: number, 
        isSelected: boolean,
        isSilhouette: boolean
    ) {
        const scaleFactor = 1.0; 

        // Global Transform for this Unit
        ctx.save();

        // Move to Visual Ground Top (drawX, drawY)
        ctx.translate(drawX, drawY); 

        // 1. Draw Shadow & Base (At Ground Level)
        // Passes localZ so shadow can scale based on jump height
        if (!isSilhouette && agent.hp > 0) {
            UnitShadowPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette);
        }

        // 2. Draw Body (Elevated Layer)
        // UnitBodyPainter handles the `translate(0, -localZ)` internally
        UnitBodyPainter.draw(ctx, agent, 0, 0, localZ, globalTime, isSilhouette, isSelected, scaleFactor);

        ctx.restore(); 
    }
}

import { GameEngine } from "../../game";
import { AssetManager } from "../../assets";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { SceneTheme } from "../../../types";
import { VFXSystem } from "../vfx";
import { MapConfig } from "../../utils";
import { Camera } from "../../systems/CameraSystem";

// Modules
import { getTransitionOffset, isChaosStyle } from "./utils";
import { ProjectileRenderer } from "./renderers/ProjectileRenderer";
import { ParticleRenderer } from "./renderers/ParticleRenderer";

export class VFXRenderer {

    public submitRenderables(
        renderList: RenderList,
        engine: GameEngine,
        vfx: VFXSystem,
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        viewport?: { width: number, height: number, camera: Camera } 
    ) {
        // CULLING SETUP
        let cullMinX = -Infinity, cullMaxX = Infinity, cullMinY = -Infinity, cullMaxY = Infinity;

        if (viewport) {
            const { width, height, camera } = viewport;
            const pad = 200;
            const viewW = width / camera.zoom;
            const viewH = height / camera.zoom;
            cullMinX = camera.x - (viewW / 2) - pad;
            cullMaxX = camera.x + (viewW / 2) + pad;
            cullMinY = camera.y - (viewH / 2) - pad;
            cullMaxY = camera.y + (viewH / 2) + pad;
        }

        // 1. Decals (Ground Level)
        vfx.state.decals.forEach(d => {
            if (d.x < cullMinX || d.x > cullMaxX || d.y < cullMinY || d.y > cullMaxY) return;

            const offset = getTransitionOffset(d.x, d.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return;

            const drawY = d.y + offset;

            const op = renderList.next();
            op.type = RenderOpType.DECAL;
            op.y = drawY; op.z = 0;
            op.tx = d.x; op.ty = drawY; 
            op.dColor = d.color;
            op.dScale = d.scale;
            op.dLife = d.life;
        });

        // 2. Physical Particles (Sorted)
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            if (p.x < cullMinX || p.x > cullMaxX || p.y < cullMinY || p.y > cullMaxY) return;

            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) {

                const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
                if (Math.abs(offset) > 800) return;

                const progress = 1 - (p.life / p.maxLife);
                const isChaos = isChaosStyle(p.color);

                const op = renderList.next();
                op.type = RenderOpType.VFX;

                // Sort Key (Ground Level with Offset)
                op.y = p.y + offset; 
                op.z = 5;
                op.sortBias = p.sortBias || 0; 

                op.particle = p;
                op.vProgress = progress;
                op.vChaos = isChaos;
                op.tx = p.x;

                // ALIGNMENT FIX:
                // p.z contains Total Height (Terrain + Offset).
                // p.y contains Ground Y.
                // We want to draw at Visual Y = GroundY - TotalZ.

                op.ty = p.y + offset - p.z; 
                op.th = p.z; 
            }
        });

        // 3. Projectiles
        ProjectileRenderer.submit(renderList, engine, getTerrainHeight, transitionT, transitionPhase);
    }

    public drawTopLayerParticles(
        ctx: CanvasRenderingContext2D, 
        vfx: VFXSystem,
        scene: SceneTheme,
        mapConfig: MapConfig,
        transitionT: number,
        transitionPhase: 'IN' | 'OUT' | 'IDLE'
    ) {
        vfx.state.particles.forEach(p => {
            if (p.delay && p.delay > 0) return;

            if (['SPRITE', 'SHARD', 'DEBRIS', 'CHIP', 'SMOKE', 'GRID_FIELD', 'ROCK', 'PILLAR', 'HEX_BEAM', 'GIANT_HEX', 'SHOCKWAVE', 'BLAST', 'RING', 'CRACKS', 'MAGIC_CIRCLE'].includes(p.type)) return;

            const offset = getTransitionOffset(p.x, p.y, mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 800) return; 

            const progress = 1 - (p.life / p.maxLife);

            // ALIGNMENT FIX: 
            // Consistent Visual Y calculation
            const drawY = p.y + offset - p.z;

            const isChaos = isChaosStyle(p.color);

            ParticleRenderer.drawSingleParticle(ctx, p, p.x, drawY, progress, isChaos);
        });
    }
}

