import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";

const OBSTACLE_HALF_WIDTH = 40;

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        // 4. Camera Transform
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        // Cache terrain lookup function for this frame
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        // Collect Grid
        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        // Collect VFX (with culling)
        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        // Collect Units (Optimized Pre-calculation)
        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (Strictly logical Y for stability)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            // PIXEL SNAPPING: Strictly align all translation anchors to integer coordinates to avoid sub-pixel blur
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlockGeometry(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, snapX, snapY - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, snapX - OBSTACLE_HALF_WIDTH, snapY);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);

                        if (p.targetX !== undefined && p.targetY !== undefined) {
                            // Relativize target
                            const origTx = p.targetX;
                            const origTy = p.targetY;
                            p.targetX = origTx - snapX;
                            p.targetY = (origTy - (p.targetZ || 0)) - snapY;
                            ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                            p.targetX = origTx;
                            p.targetY = origTy;
                        } else {
                            ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                        }
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. STATUS LAYER PASS
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime);

        // 8. Top VFX (Particles above everything)
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        // 9. Post Processing
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        // 10. HUD Layer (Screen Space)
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);

        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);

        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }
}

import { ISO_SCALE_Y } from "../../../constants";
import { HEX_VERTICES, HexGeometry } from "../utils/HexGeometry";
import { VFXFactory } from "../VFXFactory";

export const VolumePainter = {

    /**
     * Renders a soft, glowing pillar base or fog pool.
     */
    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; 

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y); 

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';

        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.globalAlpha = opacity * 0.5;
        const coreSize = size * 0.6;
        ctx.drawImage(texture, -coreSize/2, -coreSize/2, coreSize, coreSize);

        ctx.restore();
    },

    /**
     * Draw Hatching Pattern (Stripes) for Warnings
     * OPTIMIZED: Use cached texture instead of complex clipping/compositing in main loop.
     */
    drawHatch(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        // Use pre-rendered texture. It's safer and faster.
        const texture = VFXFactory.getTexture('WARNING_HATCH', color);
        const size = radius * 2.2;

        ctx.save();
        ctx.translate(x, y);
        ctx.scale(1, ISO_SCALE_Y);

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'source-over'; // Standard blend

        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    }
    ,

    /**
     * Generalized 3D Prism
     */
    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING'
    ) {
        const topY = y - height;

        ctx.save();

        const indices = [5, 0, 1]; 

        // 1. Draw Side Walls (Extrusion)
        // We calculate vertices manually based on radius to match HexGeometry logic
        for (const i of indices) {
            const j = (i + 1) % 6;

            const x1 = x + radius * HEX_VERTICES[i].x;
            const y1 = y + radius * HEX_VERTICES[i].y * ISO_SCALE_Y; // Base Y

            const x2 = x + radius * HEX_VERTICES[j].x;
            const y2 = y + radius * HEX_VERTICES[j].y * ISO_SCALE_Y; // Base Y

            const grad = ctx.createLinearGradient(0, topY, 0, y);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; 

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineTo(x2, y2 - height);
            ctx.lineTo(x1, y1 - height);
            ctx.closePath();
            ctx.fill();

            // Side Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x1, y1 - height);
            ctx.stroke();

            if (i === 1) { // Draw rightmost edge
                 ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2, y2 - height); ctx.stroke();
            }
        }

        // 2. Draw Top Face
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.3;

        if (style === 'HATCHED_WARNING') {
            // Use Hatch Texture for Top
            this.drawHatch(ctx, x, topY, radius, '#ffffff', opacity);

            // Border for hatch
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1.0;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();

        } else if (style === 'SOLID') {
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.2;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = Math.min(1.0, opacity * 3.0 + 0.4); 
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();
        } else {
            // Gradient Fade
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.3;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();
        }

        // 3. Inner Glow Ring (Optional for large shapes)
        if (radius > 20 && style !== 'HATCHED_WARNING') {
            ctx.globalCompositeOperation = 'screen';
            ctx.shadowColor = color;
            ctx.shadowBlur = 10;
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            HexGeometry.traceHex(ctx, x, topY, radius * 0.8);
            ctx.stroke();
        }

        ctx.restore();
    }

    drawWarningBlock(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        pulse: number
    ) {
        const height = 14; 
        const opacity = 0.3 + pulse * 0.4;
        // The draw3DPrism now correctly handles the Y offset internally (y - height)
        this.draw3DPrism(ctx, x, y, radius, height, color, opacity, 'HATCHED_WARNING');
    },

    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        // Use Trace Hex to get correct aspect ratio automatically
        HexGeometry.traceHex(ctx, x, y, radius);
        ctx.stroke();

        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = opacity * 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity;

        const visibleFaces = [5, 0, 1]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;

            const x1 = x + radius * HEX_VERTICES[i].x;
            const y1 = radius * HEX_VERTICES[i].y * ISO_SCALE_Y; 

            const x2 = x + radius * HEX_VERTICES[j].x;
            const y2 = radius * HEX_VERTICES[j].y * ISO_SCALE_Y; 

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, topY + y1);
            ctx.lineTo(x2, topY + y2);
            ctx.lineTo(x2, bottomY + y2);
            ctx.lineTo(x1, bottomY + y1);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            ctx.stroke();
            ctx.globalAlpha = opacity;
        }

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        HexGeometry.traceHex(ctx, x, topY, radius);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { VolumePainter } from "../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";
import { ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    /**
     * Optimized Zone Drawer using Sprites
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        size: number,
        color: string,
        visualTag: string, 
        progress: number, // 0.0 (Start) -> 1.0 (Ready)
        globalTime: number,
        dist: number,     // Distance from center of zone (in tiles)
        maxRadius: number // Radius of zone (in tiles)
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC EXPANSION ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. INNER FILL (Using Sprites)
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Prism - Cached in VolumePainter
                VolumePainter.drawWarningBlock(ctx, x, y, size, color, pulse);
            } 
            else if (isUlt) {
                // Friendly Ult: Smooth Prism
                const height = 14;
                VolumePainter.draw3DPrism(ctx, x, y, size, height, color, 0.25 * pulse, 'SOLID');
            }
            else {
                // Basic/Active: Sprite Base
                const opacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                const texture = VFXFactory.getTexture('ZONE_BASE', color);
                const drawSize = size * 2.8;

                // Texture drawing logic needs to apply ISO scale explicitly for the IMAGE
                ctx.translate(x, y);
                ctx.scale(1, ISO_SCALE_Y);
                ctx.globalAlpha = opacity;
                ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
                // Undo transform for next layers
                ctx.scale(1, 1/ISO_SCALE_Y);
                ctx.translate(-x, -y);
            }
        }

        // B. EXPANDING EDGE (Using Ripple Sprite)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const texture = VFXFactory.getTexture('ZONE_RIPPLE', color);
            const drawSize = size * 2.5;

            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalAlpha = edgeOpacity;
            ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
            // Undo
            ctx.scale(1, 1/ISO_SCALE_Y);
            ctx.translate(-x, -y);
        }

        // C. PERIMETER MARKER (Always Visible for Warning)
        // Optimized: Only trace path if strictly necessary (border logic)
        // Reduced frequency: only draw solid border, no dashed logic for standard tiles
        const showBorder = (!isWarning && !isUlt) && (dist >= maxRadius - 0.5);
        if (showBorder) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.4;

            ctx.strokeStyle = color;
            ctx.lineWidth = 1; 
            ctx.globalAlpha = borderAlpha;

            // Only use HexGeometry pathing here as it is efficient enough for single outline
            HexGeometry.traceHex(ctx, x, y, size);
            ctx.stroke();
        }

        ctx.restore();
    }
};

import { GroundHazard } from "../../../../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../../../../constants";
import { HAZARD_VISUALS } from "../../../../../data/vfx/hazard_visuals";
import { VFXFactory } from "../../../graphics/VFXFactory";
import { SurfacePainter } from "../../../graphics/painters/SurfacePainter";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";

export const HazardPainter = {

    draw(ctx: CanvasRenderingContext2D, x: number, y: number, hazard: GroundHazard, globalTime: number) {
        const def = HAZARD_VISUALS[hazard.type] || HAZARD_VISUALS['GENERIC'];

        if (def.type === 'FOG') {
            // --- VOLUMETRIC POISON CLOUD ---
            // Uses cached CLOUD texture for performance
            const texture = VFXFactory.getTexture('CLOUD', def.primaryColor);
            const size = HEX_SIZE * 3.5;
            const speed = globalTime * def.speed;

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Use Source-Over for thick smoke/gas look (not additive)
            ctx.globalCompositeOperation = 'source-over';
            ctx.globalAlpha = def.intensity * 0.4; // Base opacity

            // Layer 1: Slow rotating base
            ctx.save();
            ctx.rotate(speed * 0.2);
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Layer 2: Counter-rotating smaller detail
            ctx.save();
            ctx.rotate(-speed * 0.3 + 1.0);
            ctx.scale(0.7, 0.7);
            ctx.globalAlpha = def.intensity * 0.6;
            ctx.drawImage(texture, -size/2, -size/2, size, size);
            ctx.restore();

            // Core Glow
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.2;
            const glow = VFXFactory.getTexture('GLOW', def.secondaryColor);
            ctx.drawImage(glow, -size*0.4, -size*0.4, size*0.8, size*0.8);

            ctx.restore();
        }
        else if (def.type === 'LIQUID') {
            // Lava / Acid Pool
            const speed = globalTime * def.speed;
            const intensity = def.intensity * (0.85 + Math.sin(speed) * 0.15);
            SurfacePainter.drawLiquid(ctx, x, y, def.primaryColor, speed, intensity);
            if (def.cracks) SurfacePainter.drawCracks(ctx, x, y, def.secondaryColor, intensity);
        }
        else if (def.type === 'CRYSTAL') {
            // Ice Field
            if (def.extrude) VolumePainter.drawExtrusion(ctx, x, y, HEX_SIZE, 8, def.primaryColor, 0.5);

            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            const texture = VFXFactory.getTexture('SHARD', def.secondaryColor);
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = 0.4;

            // Scattered shards
            for(let i=0; i<3; i++) {
                const angle = i * 2.0;
                const dist = 10;
                const px = Math.cos(angle) * dist;
                const py = Math.sin(angle) * dist;
                ctx.drawImage(texture, px-10, py-10, 20, 20);
            }
            ctx.restore();
        }
        else if (def.type === 'VOID_HOLE') {
            // Gravity Well
            ctx.save();
            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);

            // Dark Core
            ctx.fillStyle = '#000';
            ctx.globalAlpha = 0.8;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.7, 0, Math.PI*2); ctx.fill();

            // Event Horizon
            const grad = ctx.createRadialGradient(0,0,HEX_SIZE*0.5, 0,0,HEX_SIZE);
            grad.addColorStop(0, def.primaryColor);
            grad.addColorStop(1, 'transparent');
            ctx.fillStyle = grad;
            ctx.globalCompositeOperation = 'screen';
            ctx.globalAlpha = def.intensity;
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE, 0, Math.PI*2); ctx.fill();

            // Accretion Disk
            ctx.rotate(globalTime * def.speed);
            ctx.strokeStyle = def.secondaryColor;
            ctx.lineWidth = 2;
            ctx.setLineDash([5, 10]);
            ctx.beginPath(); ctx.arc(0, 0, HEX_SIZE * 0.8, 0, Math.PI*2); ctx.stroke();

            ctx.restore();
        }
    }
};

import { createCanvas } from "./CanvasUtils";
import { GeometryPainter } from "./painters/GeometryPainter";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

const TEXTURE_SIZE = 64; 
const CENTER = TEXTURE_SIZE / 2;

// ============================================================================
// 🏭 MAIN FACTORY (The Facade)
// ============================================================================

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Entry point for generic particles (Smoke, Glow, Shards)
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalization for legacy keys
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        const r = CENTER - 4;
        ctx.translate(CENTER, CENTER);

        // --- DISPATCHER ---
        switch (type) {
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': 
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                ParticlePainter.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.5, 'FILL');
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');
                ctx.beginPath(); ctx.arc(0, 0, r*0.7, 0, Math.PI*2); ctx.stroke();
                break;
            case 'WARNING_HATCH':
                this.drawWarningHatch(ctx, r, color);
                break;
            case 'ZONE_RIPPLE':
                this.drawZoneRipple(ctx, r, color);
                break;
            case 'ZONE_BASE':
                this.drawZoneBase(ctx, r, color);
                break;
            // NEW: Pre-baked Shadow Blob (FPS Saver)
            case 'SHADOW_BLOB':
                this.drawShadowBlob(ctx, r, color);
                break;
            default:
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawShadowBlob(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // High quality blurred ellipse
        ctx.fillStyle = color;
        ctx.filter = 'blur(8px)'; // Bake the blur
        ctx.beginPath();
        // Scale for ISO perspective
        ctx.ellipse(0, 0, r * 0.8, r * 0.4, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';
    }

    // New: Dense Cloud Texture Generation
    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.beginPath(); ctx.arc(0, 0, r * 0.5, 0, Math.PI*2); ctx.fill();
    }

    // New: Optimized Zone Ripple (Replaces expensive stroking)
    private drawZoneRipple(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');

        // Inner thin line
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.7, 'STROKE');
    }

    // New: Optimized Zone Base (Replaces volumetric fills)
    private drawZoneBase(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Soft Hex Glow
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'FILL');
    }

    // --- TERRAIN DETAIL CACHING (FPS OPTIMIZATION) ---
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        ctx.scale(1, ISO_SCALE_Y); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawWarningHatch(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.save();
        GeometryPainter.drawHex(ctx, 0, 0, r, 'FILL');
        ctx.globalCompositeOperation = 'source-in';
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        const size = r * 2;
        const spacing = 10;
        ctx.beginPath();
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(i - size, -size);
            ctx.lineTo(i + size, size);
        }
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
        ctx.lineWidth = 2;
        GeometryPainter.drawHex(ctx, 0, 0, r, 'STROKE');
        ctx.restore();
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;
        ctx.translate(cx, cy);
        switch (visual) {
            case 'HEX_DART':
            case 'ARROW': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(64, 32, 30, 0, Math.PI*2);
        ctx.arc(44, 32, 20, 0, Math.PI*2);
        ctx.arc(84, 32, 20, 0, Math.PI*2);
        ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";

export class GridSpatial {

    /**
     * Get valid map tiles within a certain radius of a center point.
     * Used for rendering AOE zones strictly within map boundaries.
     */
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        const candidates = HexMath.range({q: centerQ, r: centerR}, radius);
        const valid: Hex[] = [];

        for (const hex of candidates) {
            if (engine.map.isValid(hex.q, hex.r)) {
                valid.push(hex);
            }
        }
        return valid;
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        const maxHeight = 200; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        // Raycast down from max possible height
        for (let h = 0; h <= maxHeight; h += step) {
            // "Unproject" the Y coordinate by adding height (since visual Y = ground Y - height)
            const testY = wy + h; 

            const frac = HexMath.pixelToHex(wx, testY, engine.mapConfig.offsetX, engine.mapConfig.offsetY);
            const rounded = HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
            const key = HexUtils.key(rounded);

            const tile = cache.tileMap.get(key);

            if (tile) {
                // Check if the click hits the top face or the slope
                // Visual Y of the tile top is (py - tile.h)
                const visualTopY = tile.py - tile.h;

                // Distance check in screen space roughly
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                // Tighter hit box for better precision
                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    // We found a candidate. The tile with the highest visual Z (closest to camera) should win.
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            // Visual Y of agent feet = uPx.y - terrainH
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);

            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const nTerrainH = engine.map.getTerrainHeight(n.q, n.r);

                    // Occlusion Check:
                    // If neighbor is "South" (Higher Y) and TALLER than agent's standing level
                    if (nPx.y > uPx.y) { 
                         if (nTerrainH > uTerrainH) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        }
        return occluded;
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 15; // Adjusted to align bottom of obstacle sprite with tile center
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            // Visual Ground Top Y = (BaseY - Height + Transition)
            const visualTopY = py - h + offset;
            const visualBaseY = py + offset;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Obstacles anchor to the visual top of the block
                // Adjust Y to align the bottom of the sprite with the center of the tile
                op.ty = visualTopY - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            // Fix: We now look up zones globally or attach them to tiles. 
            // The ZoneSystem returns a zone if this tile is inside it.
            let zoneInfo = undefined;
            const zResult = engine.zones.getZoneAt(q, r);
            if (zResult) {
                const { zone, dist } = zResult;
                zoneInfo = { 
                    type: zone.type, 
                    color: zone.color, 
                    visual: zone.visual, 
                    progress: zone.progress, 
                    centerQ: zone.q, centerR: zone.r, 
                    radius: zone.radius, dist 
                };
            }

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { VolumePainter } from "../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";
import { ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    /**
     * Renders zone effects relative to a SINGLE TILE.
     * This ensures the effect is clipped to the valid map area.
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the specific tile
        size: number,
        color: string,
        visualTag: string, 
        progress: number, 
        globalTime: number,
        dist: number,     
        maxRadius: number 
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC WAVE CALCULATION ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. TILE FILL (Individual Hex Highlight)
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Top Only (No huge prism)
                // Use the generic tile hatch logic
                VolumePainter.drawHatch(ctx, x, y, size, '#ffffff', 0.3 + pulse * 0.4);

                // Border
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke();
            } 
            else if (isUlt) {
                // Friendly Ult: Solid Color Fill
                ctx.fillStyle = color;
                ctx.globalAlpha = 0.3 * pulse;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.fill();
            }
            else {
                // Basic/Active: Texture Overlay
                const opacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                const texture = VFXFactory.getTexture('ZONE_BASE', color);
                const drawSize = size * 2.2; // Adjusted to fit single tile better

                ctx.translate(x, y);
                ctx.scale(1, ISO_SCALE_Y);
                ctx.globalAlpha = opacity;
                ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);

                // Undo transform
                ctx.scale(1, 1/ISO_SCALE_Y);
                ctx.translate(-x, -y);
            }
        }

        // B. WAVE EDGE (Ripple Effect on specific tiles)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const texture = VFXFactory.getTexture('ZONE_RIPPLE', color);
            const drawSize = size * 2.2;

            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalAlpha = edgeOpacity;
            ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
            ctx.scale(1, 1/ISO_SCALE_Y);
            ctx.translate(-x, -y);
        }

        // C. BORDER (Draws on tiles at the edge of radius)
        const isBorderTile = Math.abs(dist - maxRadius) < 0.5;
        if ((isWarning || isUlt) && isBorderTile) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.6;

            ctx.strokeStyle = color;
            ctx.lineWidth = isWarning ? 3 : 1.5; 
            ctx.globalAlpha = borderAlpha;

            if (isWarning) ctx.setLineDash([5, 5]);

            HexGeometry.traceHex(ctx, x, y, size * 0.9);
            ctx.stroke();

            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { UNIT_BODY_OFFSET } from "../../../../../constants";

export const ShieldPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#bae6fd' : '#f87171'; // Cyan vs Red tint

        // Shield Pulse based on % remaining
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));
        const pulse = 0.2 + (pct * 0.3) + Math.sin(t * 3) * 0.1;

        ctx.save();

        // ALIGNMENT FIX:
        // x, y are Ground coordinates.
        // z is total height.
        // We want shield centered on the body.
        const bodyCenterY = y - z - UNIT_BODY_OFFSET;

        ctx.translate(x, bodyCenterY); 

        // Volumetric Prism Shell around body
        // Height 90 covers most standard units
        VolumePainter.draw3DPrism(ctx, 0, 45, 35, 90, color, pulse, 'SOLID'); // y=45 relative to center creates bottom at +45, top at -45

        // Inner Core Ripple (Tech Ring)
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.ellipse(0, 0, 25, 12, 0, 0, Math.PI*2);
        ctx.stroke();

        // Vertical Energy Line
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(0, 40);
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_BODY_OFFSET } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { SpriteManager } from "../../../sprites";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. Transform to Body Center (Standard Anchor)
        // px, py are Ground Coordinates.
        // pz is Height from terrain.
        // UNIT_BODY_OFFSET shifts from feet to center of mass.
        const bodyY = py - pz - UNIT_BODY_OFFSET;

        ctx.translate(px, bodyY); 
        ctx.rotate(agent.physics.angle); 

        // 2. Animation Bobbing / Floating
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 3. Spawn Animation
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 4. Status Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        // 5. Flight VFX
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        // 6. Facing Flip
        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // 7. Render Strategy
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            // Sheep sprite is 64x64. Center is 32,32. 
            // We are at body center. Draw centered.
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Faction Specific Renderers
            // Renderers assume (0,0) is Body Center
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            // Casting Effects (Not in silhouette)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill && skill.tag === 'ULT') {
                    UnitAuraPainter.drawUltimateChantVFX(ctx, agent, t);
                } else {
                    UnitAuraPainter.drawCastingVFX(ctx, agent, t);
                }
            }

            // Frozen State Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice sprite is 96x128. Anchor center bottom?
                // Draw centered on body
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { MovementType } from "../../../../../types";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        ctx.save();
        ctx.translate(px, py); // Exactly at Ground Center of Tile

        // 1. Drop Shadow (Optimized: Use Cached Blob)
        // Shadow shrinks as unit jumps high
        const shadowScale = Math.max(0.6, 1.0 - (pz / 400));
        const shadowAlpha = Math.max(0.2, 1.0 - (pz / 200));

        // Reuse VFXFactory for generic shadow blob
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.5)'); 

        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        // Shadow Blob is 64x64. Draw centered.
        // Scale width to match unit base feel (1.5x)
        ctx.drawImage(shadowBlob, -32 * 1.5, -32 * 0.75, 64 * 1.5, 64 * 0.75); 
        ctx.restore();

        // 2. Base Token (Stays on ground)
        // Asset base is 128x128. Draw centered.
        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. Class Icon (Anchored to ground, breathing effect)
        if (agent.hp > 0) {
            ctx.save();
            const iconBaseY = -20; // Slightly above center to not overlap base ring too much
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            // Dark backing for icon visibility
            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            // Icon is 64x64. Draw centered.
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. Casting Indicators (Ground Level)
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                const visualRadius = isAOE ? 0.8 : radius;
                UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, visualRadius, skill.tag, isAOE);
            }
        }

        ctx.restore();

        // 5. Flying Anchor Line (If high up)
        if (agent.movementType === MovementType.FLYING && pz > 5) {
            UnitFlightPainter.drawFlyingAnchor(ctx, agent, t, px, py, pz);
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { HexUtils } from "../../utils";
import { HexMath } from "../../math/HexMath";
import { Hex } from "../../../types";
import { BLOCK_HEIGHT, HEX_SIZE } from "../../../constants";
import { GridCache } from "./GridCache";

export class GridSpatial {

    /**
     * Get valid map tiles within a certain radius of a center point.
     * Used for game logic (e.g. finding targets) to ensure we don't pick void tiles.
     */
    public static getValidHexesInRange(centerQ: number, centerR: number, radius: number, engine: GameEngine): Hex[] {
        const candidates = HexMath.range({q: centerQ, r: centerR}, radius);
        const valid: Hex[] = [];

        for (const hex of candidates) {
            if (engine.map.isValid(hex.q, hex.r)) {
                valid.push(hex);
            }
        }
        return valid;
    }

    public static getHexAtWorldPoint(wx: number, wy: number, engine: GameEngine, cache: GridCache): Hex | null {
        cache.ensure(engine);
        const maxHeight = 200; 
        const step = BLOCK_HEIGHT;
        let bestHex: Hex | null = null;
        let bestH = -999;

        // Raycast down from max possible height
        for (let h = 0; h <= maxHeight; h += step) {
            // "Unproject" the Y coordinate by adding height (since visual Y = ground Y - height)
            const testY = wy + h; 

            const frac = HexMath.pixelToHex(wx, testY, engine.mapConfig.offsetX, engine.mapConfig.offsetY);
            const rounded = HexMath.cubeToAxial(HexMath.cubeRound(HexMath.axialToCube(frac)));
            const key = HexUtils.key(rounded);

            const tile = cache.tileMap.get(key);

            if (tile) {
                // Check if the click hits the top face or the slope
                // Visual Y of the tile top is (py - tile.h)
                const visualTopY = tile.py - tile.h;

                // Distance check in screen space roughly
                const dx = Math.abs(wx - tile.px);
                const dy = Math.abs(wy - visualTopY);

                // Tighter hit box for better precision
                if (dx < HEX_SIZE * 0.9 && dy < HEX_SIZE * 0.6) {
                    // We found a candidate. The tile with the highest visual Z (closest to camera) should win.
                    if (tile.h >= bestH) {
                        bestHex = rounded;
                        bestH = tile.h;
                    }
                }
            }
        }
        return bestHex;
    }

    public static getOccludedAgents(engine: GameEngine): Agent[] {
        const occluded: Agent[] = [];

        for (const a of engine.agents) {
            if (a.hp <= 0 && a.fullyDead) continue;

            const uPx = HexUtils.toPx(a.q, a.r, engine.mapConfig);
            // Visual Y of agent feet = uPx.y - terrainH
            const uTerrainH = engine.map.getTerrainHeight(a.q, a.r);

            const neighbors = HexUtils.neighbors({q: a.q, r: a.r});

            for (const n of neighbors) {
                const k = HexUtils.key(n);
                if (engine.mapKeys.has(k)) {
                    const nPx = HexUtils.toPx(n.q, n.r, engine.mapConfig);
                    const nTerrainH = engine.map.getTerrainHeight(n.q, n.r);

                    // Occlusion Check:
                    // If neighbor is "South" (Higher Y) and TALLER than agent's standing level
                    if (nPx.y > uPx.y) { 
                         if (nTerrainH > uTerrainH) {
                             occluded.push(a);
                             break;
                         }
                    }
                }
            }
        }
        return occluded;
    }
}

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
// Adjusted: Obstacles are sprites drawn from bottom-center. 
// They sit on top of the block. No extra offset needed if sprite is anchored correctly.
const OBSTACLE_ANCHOR_Y = 0; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache,
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        cache.ensure(engine);
        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Presence
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        // 2. Iterate Tiles
        const len = cache.tileList.length;
        for (let i = 0; i < len; i++) {
            const tile = cache.tileList[i];
            const { q, r, px, py, h, key } = tile;

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            // Visual Ground Top Y = (BaseY - Height + Transition)
            const visualTopY = py - h + offset;
            const visualBaseY = py + offset;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 800) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                // Obstacles anchor to the visual top of the block
                op.ty = visualTopY - OBSTACLE_ANCHOR_Y; 
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            // Use ZoneSystem to check if THIS specific tile is in a zone.
            // This ensures we only draw AOE on valid tiles.
            let zoneInfo = undefined;
            const zResult = engine.zones.getZoneAt(q, r);
            if (zResult) {
                const { zone, dist } = zResult;
                zoneInfo = { 
                    type: zone.type, 
                    color: zone.color, 
                    visual: zone.visual, 
                    progress: zone.progress, 
                    centerQ: zone.q, centerR: zone.r, 
                    radius: zone.radius, dist 
                };
            }

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // Overlays
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { VolumePainter } from "../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";
import { ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    /**
     * Renders zone effects relative to a SINGLE TILE.
     * This ensures the effect is clipped to the valid map area.
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the specific tile
        size: number,
        color: string,
        visualTag: string, 
        progress: number, 
        globalTime: number,
        dist: number,     
        maxRadius: number 
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC WAVE CALCULATION ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. TILE FILL (Individual Hex Highlight)
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Top Only (No huge prism)
                // Use the generic tile hatch logic
                VolumePainter.drawHatch(ctx, x, y, size, '#ffffff', 0.3 + pulse * 0.4);

                // Border
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke();
            } 
            else if (isUlt) {
                // Friendly Ult: Solid Color Fill with slight extrusion
                // We draw a small prism just for this tile to give depth
                VolumePainter.draw3DPrism(ctx, x, y, size, 12, color, 0.25 * pulse, 'SOLID');
            }
            else {
                // Basic/Active: Texture Overlay
                const opacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                const texture = VFXFactory.getTexture('ZONE_BASE', color);
                const drawSize = size * 2.2; // Adjusted to fit single tile better

                ctx.translate(x, y);
                ctx.scale(1, ISO_SCALE_Y);
                ctx.globalAlpha = opacity;
                ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);

                // Undo transform
                ctx.scale(1, 1/ISO_SCALE_Y);
                ctx.translate(-x, -y);
            }
        }

        // B. WAVE EDGE (Ripple Effect on specific tiles)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const texture = VFXFactory.getTexture('ZONE_RIPPLE', color);
            const drawSize = size * 2.2;

            ctx.translate(x, y);
            ctx.scale(1, ISO_SCALE_Y);
            ctx.globalAlpha = edgeOpacity;
            ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
            ctx.scale(1, 1/ISO_SCALE_Y);
            ctx.translate(-x, -y);
        }

        // C. BORDER (Draws on tiles at the edge of radius)
        const isBorderTile = Math.abs(dist - maxRadius) < 0.5;
        if ((isWarning || isUlt) && isBorderTile) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.6;

            ctx.strokeStyle = color;
            ctx.lineWidth = isWarning ? 3 : 1.5; 
            ctx.globalAlpha = borderAlpha;

            if (isWarning) ctx.setLineDash([5, 5]);

            HexGeometry.traceHex(ctx, x, y, size * 0.9);
            ctx.stroke();

            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team } from "../../../../../types";
import { VolumePainter } from "../../../graphics/painters/VolumePainter";
import { UNIT_BODY_OFFSET } from "../../../../../constants";

export const ShieldPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, x: number, y: number, z: number, t: number) {
        if (agent.shield <= 0) return;

        const isBlue = agent.team === Team.BLUE;
        const color = isBlue ? '#bae6fd' : '#f87171'; // Cyan vs Red tint

        // Shield Pulse based on % remaining
        const pct = Math.min(1, agent.shield / (agent.maxShield || 100));
        const pulse = 0.2 + (pct * 0.3) + Math.sin(t * 3) * 0.1;

        ctx.save();

        // ALIGNMENT FIX:
        // x, y are Ground coordinates.
        // z is total height.
        // We want shield centered on the body.
        const bodyCenterY = y - z - UNIT_BODY_OFFSET;

        ctx.translate(x, bodyCenterY); 

        // Volumetric Prism Shell around body
        // Height 90 covers most standard units. Prism draws downwards from current Y.
        // To center it, we draw from (y - half_height)
        VolumePainter.draw3DPrism(ctx, 0, 45, 35, 90, color, pulse, 'SOLID'); // y=45 relative to center creates bottom at +45, top at -45

        // Inner Core Ripple (Tech Ring)
        ctx.globalCompositeOperation = 'screen';
        ctx.globalAlpha = 0.4;

        ctx.strokeStyle = color;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.ellipse(0, 0, 25, 12, 0, 0, Math.PI*2);
        ctx.stroke();

        // Vertical Energy Line
        ctx.beginPath();
        ctx.moveTo(0, -40); ctx.lineTo(0, 40);
        ctx.lineWidth = 1;
        ctx.stroke();

        ctx.restore();
    }
};

import { Agent } from "../../../../game";
import { Team, AnimState, MovementType } from "../../../../../types";
import { UNIT_BODY_OFFSET } from "../../../../../constants";
import { ImperialRenderer } from "../factions/ImperialRenderer";
import { CovenantRenderer } from "../factions/CovenantRenderer";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { UnitAuraPainter } from "./UnitAuraPainter";
import { SpriteManager } from "../../../sprites";

export const UnitBodyPainter = {
    draw(
        ctx: CanvasRenderingContext2D, 
        agent: Agent, 
        px: number, py: number, pz: number, 
        t: number, 
        isSilhouette: boolean, 
        isSelected: boolean,
        scaleFactor: number
    ) {
        ctx.save(); 

        // 1. Transform to Body Center (Standard Anchor)
        // px, py are Ground Coordinates.
        // pz is Height from terrain.
        // UNIT_BODY_OFFSET shifts from feet to center of mass.
        const bodyY = py - pz - UNIT_BODY_OFFSET;

        ctx.translate(px, bodyY); 
        ctx.rotate(agent.physics.angle); 

        // 2. Animation Bobbing / Floating
        let bodyFloat = 0; 
        if (agent.hp > 0 && agent.movementType !== MovementType.FLYING) {
             bodyFloat = Math.sin(t * 2) * 3; 
        } else if (agent.movementType === MovementType.FLYING) {
             bodyFloat = Math.sin(t * 4) * 2;
        }
        ctx.translate(0, bodyFloat);

        // 3. Spawn Animation
        if (agent.spawnTimer > 0) {
            const SPAWN_DURATION = 0.5; 
            const progress = 1 - (agent.spawnTimer / SPAWN_DURATION); 
            const eased = 1 - Math.pow(1 - progress, 3); 
            ctx.scale(1, 2.0 - eased); 
            ctx.globalAlpha *= eased;
        }

        // 4. Status Filters
        if (agent.hp <= 0 && !isSilhouette) {
            ctx.filter = 'grayscale(100%) opacity(80%)'; 
        } else if (!isSilhouette && agent.hitFlashTimer > 0) {
             ctx.filter = 'brightness(200%)';
        }

        // 5. Flight VFX
        if (agent.movementType === MovementType.FLYING && agent.hp > 0 && !isSilhouette && agent.visualStatus === 'NONE') {
            UnitFlightPainter.drawFlightVFX(ctx, agent, t);
        }

        // 6. Facing Flip
        ctx.scale(agent.facing > 0 ? 1 : -1, 1);

        // 7. Render Strategy
        if (isSilhouette) {
            ctx.globalCompositeOperation = 'source-over'; 
            ctx.globalAlpha = 0.8; 
        }

        if (agent.visualStatus === 'POLYMORPH') {
            const sheep = SpriteManager.getSpecialModel('SHEEP');
            const bounce = Math.abs(Math.sin(t * 5) * 5);
            // Sheep sprite is 64x64. Center is 32,32. 
            // We are at body center. Draw centered.
            ctx.drawImage(sheep, -32, -32 - bounce, 64, 64);
        } else {
            // Faction Specific Renderers
            // Renderers assume (0,0) is Body Center
            if (agent.team === Team.BLUE) {
                ImperialRenderer.draw(ctx, agent, t, isSilhouette);
            } else {
                CovenantRenderer.draw(ctx, agent, t, isSilhouette);
            }

            // Casting Effects (Not in silhouette)
            if (!isSilhouette && agent.hp > 0 && agent.castingSkillIdx !== -1) {
                const skill = agent.skills[agent.castingSkillIdx];
                if (skill && skill.tag === 'ULT') {
                    UnitAuraPainter.drawUltimateChantVFX(ctx, agent, t);
                } else {
                    UnitAuraPainter.drawCastingVFX(ctx, agent, t);
                }
            }

            // Frozen State Overlay
            if (agent.visualStatus === 'FROZEN') {
                const ice = SpriteManager.getSpecialModel('ICE');
                ctx.save();
                ctx.globalCompositeOperation = 'hard-light';
                // Ice sprite is 96x128. Anchor center bottom?
                // Draw centered on body
                ctx.drawImage(ice, -48, -64, 96, 128);
                ctx.restore();
            }
        }

        ctx.restore(); 
    }
};

import { Agent } from "../../../../game";
import { SpriteManager } from "../../../sprites";
import { UnitIndicatorPainter } from "./UnitIndicatorPainter";
import { MovementType } from "../../../../../types";
import { UnitFlightPainter } from "./UnitFlightPainter";
import { VFXFactory } from "../../../graphics/VFXFactory";

export const UnitShadowPainter = {
    draw(ctx: CanvasRenderingContext2D, agent: Agent, px: number, py: number, pz: number, t: number, isSilhouette: boolean) {
        if (isSilhouette || agent.visualStatus === 'POLYMORPH') return;

        const assets = SpriteManager.getUnitImages(agent.role, agent.team);

        ctx.save();
        ctx.translate(px, py); // Exactly at Ground Center of Tile

        // 1. Drop Shadow (Optimized: Use Cached Blob)
        // Shadow shrinks as unit jumps high
        const shadowScale = Math.max(0.6, 1.0 - (pz / 400));
        const shadowAlpha = Math.max(0.2, 1.0 - (pz / 200));

        // Reuse VFXFactory for generic shadow blob
        const shadowBlob = VFXFactory.getTexture('SHADOW_BLOB', 'rgba(0,0,0,0.5)'); 

        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        // Shadow Blob is 64x64. Draw centered.
        // Scale width to match unit base feel (1.5x)
        ctx.drawImage(shadowBlob, -32 * 1.5, -32 * 0.75, 64 * 1.5, 64 * 0.75); 
        ctx.restore();

        // 2. Base Token (Stays on ground)
        // Asset base is 128x128. Draw centered.
        ctx.save();
        ctx.scale(shadowScale, shadowScale);
        ctx.globalAlpha = shadowAlpha;
        ctx.drawImage(assets.base, -64, -64); 
        ctx.restore();

        // 3. Class Icon (Anchored to ground, breathing effect)
        if (agent.hp > 0) {
            ctx.save();
            const iconBaseY = -20; // Slightly above center to not overlap base ring too much
            ctx.translate(0, iconBaseY);
            const breath = Math.sin(t * 2) * 1.5;
            ctx.translate(0, breath);

            // Dark backing for icon visibility
            ctx.fillStyle = 'rgba(0,0,0,0.4)';
            ctx.beginPath(); ctx.ellipse(0, 28, 14, 6, 0, 0, Math.PI*2); ctx.fill();

            ctx.globalAlpha = 1.0; 
            ctx.shadowColor = 'rgba(0,0,0,0.3)'; ctx.shadowBlur = 5;
            // Icon is 64x64. Draw centered.
            ctx.drawImage(assets.icon, -32, -32, 64, 64);
            ctx.restore();
        }

        // 4. Casting Indicators (Ground Level)
        if (agent.castingSkillIdx !== -1) {
            const skill = agent.skills[agent.castingSkillIdx];
            if (skill) {
                const progress = 1 - (agent.castTimer / skill.cast);
                const radius = skill.aoeRadius || 1;
                const isAOE = skill.type === 'AOE';
                const visualRadius = isAOE ? 0.8 : radius;
                UnitIndicatorPainter.drawSkillGroundIndicator(ctx, 0, 0, skill.color, t, progress, visualRadius, skill.tag, isAOE);
            }
        }

        ctx.restore();

        // 5. Flying Anchor Line (If high up)
        if (agent.movementType === MovementType.FLYING && pz > 5) {
            UnitFlightPainter.drawFlyingAnchor(ctx, agent, t, px, py, pz);
        }
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Unit Scale)
// Vertices for a "Pointy Top" Hexagon with radius 1.0
// Angle 0 is at 30 degrees (PI/6) to align flat top with screen Y in ISO
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 

// Base Vertices (Flat, Radius 1.0)
const BASE_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    BASE_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Pre-computed Render Paths (Performance)
let CACHED_HEX_PATH: Path2D | null = null;

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Uses strict ISO scaling on Y axis.
     * This is the SOURCE OF TRUTH for all terrain and grid overlays.
     */
    getVertices(radius: number): {x: number, y: number}[] {
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * ISO_SCALE_Y
        }));
    },

    /**
     * Get FLAT vertices (No ISO scaling).
     * Used for creating textures that will be scaled later, or for UI elements.
     */
    getFlatVertices(radius: number): {x: number, y: number}[] {
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius
        }));
    },

    /**
     * Optimized draw call. Uses Path2D if available and radius matches standard HEX_SIZE.
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
        // Use cached path for standard grid cells (huge FPS boost for grid rendering)
        if (Math.abs(radius - HEX_SIZE) < 0.01) {
            if (!CACHED_HEX_PATH) {
                this.rebuildCache();
            }
            ctx.translate(x, y);
            // We draw the path relative to local 0,0
            // The context is already translated.
            // Note: Path2D drawing requires the context method, we can't 'trace' a Path2D easily onto existing path.
            // But this method assumes it's starting a new path or part of one.
            // Actually, for maximum compatibility with stroke/fill callers, we should manually trace 
            // UNLESS we change the API. 
            // Reverting to manual trace for 100% consistency with 'beginPath' logic outside.
            // The overhead is minimal compared to the transform/fill cost.
        }

        // Standard Trace (Manual) matches exactly what getVertices returns
        const verts = this.getVertices(radius);
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * Returns a Path2D object for the standard hex. 
     */
    getStandardPath(): Path2D {
        if (!CACHED_HEX_PATH) this.rebuildCache();
        return CACHED_HEX_PATH!;
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_HEX_PATH = path;
    },

    /**
     * Returns vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../utils/HexGeometry";
import { VFXFactory } from "../VFXFactory";

export const VolumePainter = {

    /**
     * Renders a soft, glowing pillar base or fog pool.
     */
    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        // Texture is already ISO projected by VFXFactory

        const size = radius * 2.8; 

        ctx.save();
        ctx.translate(x, y);
        // REMOVED: ctx.scale(1, ISO_SCALE_Y); -> Texture is already ISO!

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';

        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.globalAlpha = opacity * 0.5;
        const coreSize = size * 0.6;
        ctx.drawImage(texture, -coreSize/2, -coreSize/2, coreSize, coreSize);

        ctx.restore();
    },

    /**
     * Draw Hatching Pattern (Stripes) for Warnings
     */
    drawHatch(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        // Use pre-rendered texture.
        // The texture from VFXFactory('WARNING_HATCH') is generated using GeometryPainter.drawHex, 
        // which uses HexGeometry.traceHex, which applies ISO scaling.
        // So the image is already a "squashed" hexagon.

        const texture = VFXFactory.getTexture('WARNING_HATCH', color);
        const size = radius * 2.2; // Slightly larger to cover stroke width

        ctx.save();
        ctx.translate(x, y);
        // REMOVED: ctx.scale(1, ISO_SCALE_Y); -> Fixes the "Double Squash" bug

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'source-over'; 

        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    /**
     * Generalized 3D Prism
     * Uses HexGeometry vertices to ensure it matches the terrain exactly.
     */
    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING'
    ) {
        const topY = y - height;

        ctx.save();

        // 1. Get Standard Vertices (Already ISO Scaled relative to 0,0)
        const verts = HexGeometry.getVertices(radius);
        const indices = [5, 0, 1]; // Front facing walls

        // 2. Draw Side Walls
        for (const i of indices) {
            const j = (i + 1) % 6;

            // Vertices are relative to (0,0) center
            const x1 = x + verts[i].x;
            const y1 = y + verts[i].y; // Bottom Y (Base)

            const x2 = x + verts[j].x;
            const y2 = y + verts[j].y; // Bottom Y (Base)

            const grad = ctx.createLinearGradient(0, topY, 0, y);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; 

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineTo(x2, y2 - height); // Top Y is simply Base Y - height
            ctx.lineTo(x1, y1 - height);
            ctx.closePath();
            ctx.fill();

            // Side Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x1, y1 - height);
            ctx.stroke();

            if (i === 1) { // Draw rightmost edge
                 ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2, y2 - height); ctx.stroke();
            }
        }

        // 3. Draw Top Face
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.3;

        if (style === 'HATCHED_WARNING') {
            this.drawHatch(ctx, x, topY, radius, '#ffffff', opacity);

            // Border
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1.0;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();

        } else if (style === 'SOLID') {
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.2;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = Math.min(1.0, opacity * 3.0 + 0.4); 
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();
        } else {
            // Gradient Fade
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.3;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawWarningBlock(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        pulse: number
    ) {
        const height = 14; 
        const opacity = 0.3 + pulse * 0.4;
        this.draw3DPrism(ctx, x, y, radius, height, color, opacity, 'HATCHED_WARNING');
    },

    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        // Use Trace Hex to get correct aspect ratio automatically
        HexGeometry.traceHex(ctx, x, y, radius);
        ctx.stroke();

        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = opacity * 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity;

        // Use HexGeometry vertices for consistency
        const verts = HexGeometry.getVertices(radius);
        const visibleFaces = [5, 0, 1]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;
            const x1 = x + verts[i].x;
            const y1 = verts[i].y; // Relative Y
            const x2 = x + verts[j].x;
            const y2 = verts[j].y; // Relative Y

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, topY + y1);
            ctx.lineTo(x2, topY + y2);
            ctx.lineTo(x2, bottomY + y2);
            ctx.lineTo(x1, bottomY + y1);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            ctx.stroke();
            ctx.globalAlpha = opacity;
        }

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        HexGeometry.traceHex(ctx, x, topY, radius);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { GeometryPainter } from "./painters/GeometryPainter";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

// UPDATED: Increased from 64 to 128 to accommodate HEX_SIZE * 2 (72px) + Glow/Bleed
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

// ============================================================================
// 🏭 MAIN FACTORY (The Facade)
// ============================================================================

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Entry point for generic particles (Smoke, Glow, Shards)
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalization for legacy keys
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        // Radius logic: Hex Width is ~72px. So Radius 36 is safe.
        // We use slightly larger radius for glow effects.
        const r = 36; 
        ctx.translate(CENTER, CENTER);

        // --- DISPATCHER ---
        switch (type) {
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': 
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                ParticlePainter.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.5, 'FILL');
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');
                ctx.beginPath(); ctx.arc(0, 0, r*0.7, 0, Math.PI*2); ctx.stroke();
                break;
            case 'WARNING_HATCH':
                this.drawWarningHatch(ctx, r, color);
                break;
            case 'ZONE_RIPPLE':
                this.drawZoneRipple(ctx, r, color);
                break;
            case 'ZONE_BASE':
                this.drawZoneBase(ctx, r, color);
                break;
            case 'SHADOW_BLOB':
                this.drawShadowBlob(ctx, r, color);
                break;
            default:
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawShadowBlob(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // High quality blurred ellipse
        ctx.fillStyle = color;
        ctx.filter = 'blur(8px)'; 
        ctx.beginPath();
        // Scale for ISO perspective
        ctx.ellipse(0, 0, r * 0.8, r * 0.4, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';
    }

    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.beginPath(); ctx.arc(0, 0, r * 0.5, 0, Math.PI*2); ctx.fill();
    }

    private drawZoneRipple(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');

        // Inner thin line
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.7, 'STROKE');
    }

    private drawZoneBase(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Soft Hex Glow
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'FILL');
    }

    // --- TERRAIN DETAIL CACHING ---
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        ctx.scale(1, ISO_SCALE_Y); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawWarningHatch(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.save();
        GeometryPainter.drawHex(ctx, 0, 0, r, 'FILL');
        ctx.globalCompositeOperation = 'source-in';
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        const size = r * 2;
        const spacing = 10;
        ctx.beginPath();
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(i - size, -size);
            ctx.lineTo(i + size, size);
        }
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
        ctx.lineWidth = 2;
        GeometryPainter.drawHex(ctx, 0, 0, r, 'STROKE');
        ctx.restore();
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;
        ctx.translate(cx, cy);
        switch (visual) {
            case 'HEX_DART':
            case 'ARROW': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(64, 32, 30, 0, Math.PI*2);
        ctx.arc(44, 32, 20, 0, Math.PI*2);
        ctx.arc(84, 32, 20, 0, Math.PI*2);
        ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Unit Scale)
// Vertices for a "Pointy Top" Hexagon with radius 1.0
// Angle 0 is at 30 degrees (PI/6) to align flat top with screen Y in ISO
const START_ANGLE = Math.PI / 6 + Math.PI / 4; 

// Base Vertices (Flat, Radius 1.0)
const BASE_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    BASE_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Pre-computed Render Paths (Performance)
let CACHED_HEX_PATH: Path2D | null = null;

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Uses strict ISO scaling on Y axis.
     * This is the SOURCE OF TRUTH for all terrain and grid overlays.
     */
    getVertices(radius: number): {x: number, y: number}[] {
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * ISO_SCALE_Y
        }));
    },

    /**
     * Get FLAT vertices (No ISO scaling).
     * Used for creating textures that will be scaled later, or for UI elements.
     */
    getFlatVertices(radius: number): {x: number, y: number}[] {
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius
        }));
    },

    /**
     * Optimized draw call. Uses Path2D if available and radius matches standard HEX_SIZE.
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number) {
        // Use cached path for standard grid cells (huge FPS boost for grid rendering)
        if (Math.abs(radius - HEX_SIZE) < 0.01) {
            if (!CACHED_HEX_PATH) {
                this.rebuildCache();
            }
            ctx.translate(x, y);
            // We draw the path relative to local 0,0
            // The context is already translated.
            // Note: Path2D drawing requires the context method, we can't 'trace' a Path2D easily onto existing path.
            // But this method assumes it's starting a new path or part of one.
            // Actually, for maximum compatibility with stroke/fill callers, we should manually trace 
            // UNLESS we change the API. 
            // Reverting to manual trace for 100% consistency with 'beginPath' logic outside.
            // The overhead is minimal compared to the transform/fill cost.
        }

        // Standard Trace (Manual) matches exactly what getVertices returns
        const verts = this.getVertices(radius);
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * Returns a Path2D object for the standard hex. 
     */
    getStandardPath(): Path2D {
        if (!CACHED_HEX_PATH) this.rebuildCache();
        return CACHED_HEX_PATH!;
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_HEX_PATH = path;
    },

    /**
     * Returns vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../utils/HexGeometry";
import { VFXFactory } from "../VFXFactory";

export const VolumePainter = {

    /**
     * Renders a soft, glowing pillar base or fog pool.
     */
    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        // Texture is already ISO projected by VFXFactory

        const size = radius * 2.8; 

        ctx.save();
        ctx.translate(x, y);
        // REMOVED: ctx.scale(1, ISO_SCALE_Y); -> Texture is already ISO!

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';

        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.globalAlpha = opacity * 0.5;
        const coreSize = size * 0.6;
        ctx.drawImage(texture, -coreSize/2, -coreSize/2, coreSize, coreSize);

        ctx.restore();
    },

    /**
     * Draw Hatching Pattern (Stripes) for Warnings
     */
    drawHatch(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        // Use pre-rendered texture.
        // The texture from VFXFactory('WARNING_HATCH') is generated using GeometryPainter.drawHex, 
        // which uses HexGeometry.traceHex, which applies ISO scaling.
        // So the image is already a "squashed" hexagon.

        const texture = VFXFactory.getTexture('WARNING_HATCH', color);
        const size = radius * 2.2; // Slightly larger to cover stroke width

        ctx.save();
        ctx.translate(x, y);
        // REMOVED: ctx.scale(1, ISO_SCALE_Y); -> Fixes the "Double Squash" bug

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'source-over'; 

        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    /**
     * Generalized 3D Prism
     * Uses HexGeometry vertices to ensure it matches the terrain exactly.
     */
    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING'
    ) {
        const topY = y - height;

        ctx.save();

        // 1. Get Standard Vertices (Already ISO Scaled relative to 0,0)
        const verts = HexGeometry.getVertices(radius);
        const indices = [5, 0, 1]; // Front facing walls

        // 2. Draw Side Walls
        for (const i of indices) {
            const j = (i + 1) % 6;

            // Vertices are relative to (0,0) center
            const x1 = x + verts[i].x;
            const y1 = y + verts[i].y; // Bottom Y (Base)

            const x2 = x + verts[j].x;
            const y2 = y + verts[j].y; // Bottom Y (Base)

            const grad = ctx.createLinearGradient(0, topY, 0, y);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; 

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineTo(x2, y2 - height); // Top Y is simply Base Y - height
            ctx.lineTo(x1, y1 - height);
            ctx.closePath();
            ctx.fill();

            // Side Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x1, y1 - height);
            ctx.stroke();

            if (i === 1) { // Draw rightmost edge
                 ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2, y2 - height); ctx.stroke();
            }
        }

        // 3. Draw Top Face
        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.3;

        if (style === 'HATCHED_WARNING') {
            this.drawHatch(ctx, x, topY, radius, '#ffffff', opacity);

            // Border
            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1.0;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();

        } else if (style === 'SOLID') {
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.2;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = Math.min(1.0, opacity * 3.0 + 0.4); 
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();
        } else {
            // Gradient Fade
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.3;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            HexGeometry.traceHex(ctx, x, topY, radius);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawWarningBlock(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        pulse: number
    ) {
        const height = 14; 
        const opacity = 0.3 + pulse * 0.4;
        this.draw3DPrism(ctx, x, y, radius, height, color, opacity, 'HATCHED_WARNING');
    },

    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';
        ctx.lineJoin = 'round';

        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        // Use Trace Hex to get correct aspect ratio automatically
        HexGeometry.traceHex(ctx, x, y, radius);
        ctx.stroke();

        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.globalAlpha = opacity * 0.8;
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number
    ) {
        const topY = y - height;
        const bottomY = y;

        ctx.save();
        ctx.globalAlpha = opacity;

        // Use HexGeometry vertices for consistency
        const verts = HexGeometry.getVertices(radius);
        const visibleFaces = [5, 0, 1]; 

        for (const i of visibleFaces) {
            const j = (i + 1) % 6;
            const x1 = x + verts[i].x;
            const y1 = verts[i].y; // Relative Y
            const x2 = x + verts[j].x;
            const y2 = verts[j].y; // Relative Y

            const grad = ctx.createLinearGradient(0, topY, 0, bottomY);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, topY + y1);
            ctx.lineTo(x2, topY + y2);
            ctx.lineTo(x2, bottomY + y2);
            ctx.lineTo(x1, bottomY + y1);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity * 0.5;
            ctx.stroke();
            ctx.globalAlpha = opacity;
        }

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        HexGeometry.traceHex(ctx, x, topY, radius);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { createCanvas } from "./CanvasUtils";
import { GeometryPainter } from "./painters/GeometryPainter";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

// UPDATED: Increased from 64 to 128 to accommodate HEX_SIZE * 2 (72px) + Glow/Bleed
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

// ============================================================================
// 🏭 MAIN FACTORY (The Facade)
// ============================================================================

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    /**
     * Entry point for generic particles (Smoke, Glow, Shards)
     */
    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalization for legacy keys
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        // Radius logic: Hex Width is ~72px. So Radius 36 is safe.
        // We use slightly larger radius for glow effects.
        const r = 36; 
        ctx.translate(CENTER, CENTER);

        // --- DISPATCHER ---
        switch (type) {
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': 
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                ParticlePainter.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.5, 'FILL');
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');
                ctx.beginPath(); ctx.arc(0, 0, r*0.7, 0, Math.PI*2); ctx.stroke();
                break;
            case 'WARNING_HATCH':
                this.drawWarningHatch(ctx, r, color);
                break;
            case 'ZONE_RIPPLE':
                this.drawZoneRipple(ctx, r, color);
                break;
            case 'ZONE_BASE':
                this.drawZoneBase(ctx, r, color);
                break;
            case 'SHADOW_BLOB':
                this.drawShadowBlob(ctx, r, color);
                break;
            default:
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawShadowBlob(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // High quality blurred ellipse
        ctx.fillStyle = color;
        ctx.filter = 'blur(8px)'; 
        ctx.beginPath();
        // Scale for ISO perspective
        ctx.ellipse(0, 0, r * 0.8, r * 0.4, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';
    }

    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');

        ctx.fillStyle = grad;
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist;
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.beginPath(); ctx.arc(0, 0, r * 0.5, 0, Math.PI*2); ctx.fill();
    }

    private drawZoneRipple(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'STROKE');

        // Inner thin line
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.7, 'STROKE');
    }

    private drawZoneBase(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Soft Hex Glow
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        GeometryPainter.drawHex(ctx, 0, 0, r * 0.9, 'FILL');
    }

    // --- TERRAIN DETAIL CACHING ---
    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        ctx.scale(1, ISO_SCALE_Y); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        if (type === 'FOREST') {
            for(let i=0; i<8; i++) {
                const px = (rnd(i) - 0.5) * HEX_SIZE * 1.4;
                const py = (rnd(i+10) - 0.5) * HEX_SIZE * 1.4;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.moveTo(px, py);
                ctx.lineTo(px - 1.5, py - 5);
                ctx.lineTo(px + 1.5, py - 5);
                ctx.fill();
            }
        } else if (type === 'DESERT') {
            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.lineCap = 'round';
            for(let i=0; i<3; i++) {
                const py = (rnd(i) - 0.5) * HEX_SIZE;
                ctx.beginPath();
                ctx.moveTo(-10, py);
                ctx.quadraticCurveTo(0, py + 4, 10, py);
                ctx.stroke();
            }
        } else if (type === 'VOID') {
             ctx.strokeStyle = color;
             ctx.lineWidth = 1;
             ctx.beginPath();
             const px = (rnd(1) - 0.5) * HEX_SIZE;
             const py = (rnd(2) - 0.5) * HEX_SIZE;
             ctx.moveTo(px, py);
             ctx.lineTo(px + 10, py);
             ctx.lineTo(px + 15, py + 5);
             ctx.stroke();
             ctx.fillStyle = color;
             ctx.beginPath(); ctx.arc(px, py, 1.5, 0, Math.PI*2); ctx.fill();
        } else {
            for(let i=0; i<5; i++) {
                const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
                const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
                if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
                ctx.beginPath();
                ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
                ctx.fill();
            }
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    private drawWarningHatch(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.save();
        GeometryPainter.drawHex(ctx, 0, 0, r, 'FILL');
        ctx.globalCompositeOperation = 'source-in';
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        const size = r * 2;
        const spacing = 10;
        ctx.beginPath();
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(i - size, -size);
            ctx.lineTo(i + size, size);
        }
        ctx.stroke();
        ctx.globalCompositeOperation = 'source-over';
        ctx.lineWidth = 2;
        GeometryPainter.drawHex(ctx, 0, 0, r, 'STROKE');
        ctx.restore();
    }

    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const cx = 64, cy = 32;
        ctx.translate(cx, cy);
        switch (visual) {
            case 'HEX_DART':
            case 'ARROW': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath();
        ctx.arc(64, 32, 30, 0, Math.PI*2);
        ctx.arc(44, 32, 20, 0, Math.PI*2);
        ctx.arc(84, 32, 20, 0, Math.PI*2);
        ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        const key = `BLAST_ZONE_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { VolumePainter } from "../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";
import { ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    /**
     * Renders zone effects relative to a SINGLE TILE.
     * This ensures the effect is clipped to the valid map area.
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the specific tile
        size: number,
        color: string,
        visualTag: string, 
        progress: number, 
        globalTime: number,
        dist: number,     
        maxRadius: number 
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. DYNAMIC WAVE CALCULATION ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. TILE FILL (Individual Hex Highlight)
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Top Only (No huge prism)
                // Use the generic tile hatch logic
                VolumePainter.drawHatch(ctx, x, y, size, '#ffffff', 0.3 + pulse * 0.4);

                // Border
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                HexGeometry.traceHex(ctx, x, y, size);
                ctx.stroke();
            } 
            else if (isUlt) {
                // Friendly Ult: Solid Color Fill with slight extrusion
                // We draw a small prism just for this tile to give depth
                VolumePainter.draw3DPrism(ctx, x, y, size, 12, color, 0.25 * pulse, 'SOLID');
            }
            else {
                // Basic/Active: Texture Overlay
                const opacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                const texture = VFXFactory.getTexture('ZONE_BASE', color);
                const drawSize = size * 2.2; // Adjusted to fit single tile better

                // Texture is ALREADY ISO-SCALED in VFXFactory
                ctx.translate(x, y);
                // REMOVED: ctx.scale(1, ISO_SCALE_Y);
                ctx.globalAlpha = opacity;
                ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);

                ctx.translate(-x, -y);
            }
        }

        // B. WAVE EDGE (Ripple Effect on specific tiles)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const texture = VFXFactory.getTexture('ZONE_RIPPLE', color);
            const drawSize = size * 2.2;

            ctx.translate(x, y);
            // REMOVED: ctx.scale(1, ISO_SCALE_Y);
            ctx.globalAlpha = edgeOpacity;
            ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
            ctx.translate(-x, -y);
        }

        // C. BORDER (Draws on tiles at the edge of radius)
        const isBorderTile = Math.abs(dist - maxRadius) < 0.5;
        if ((isWarning || isUlt) && isBorderTile) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.6;

            ctx.strokeStyle = color;
            ctx.lineWidth = isWarning ? 3 : 1.5; 
            ctx.globalAlpha = borderAlpha;

            if (isWarning) ctx.setLineDash([5, 5]);

            HexGeometry.traceHex(ctx, x, y, size * 0.9);
            ctx.stroke();

            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

import { HEX_SIZE, ISO_SCALE_Y } from "../../../constants";

// 1. Static Geometry Cache (Unit Scale)
// Vertices for a "Pointy Top" Hexagon.
// Angle 0 is at 30 degrees (PI/6) to align flat top with screen Y in ISO
const START_ANGLE = Math.PI / 6 + Math.PI / 4; // 75 degrees base rotation to align with game iso

// Pre-calculate base vertices (Flat 2D, Radius 1.0)
const BASE_VERTICES: {x: number, y: number}[] = [];
for (let i = 0; i < 6; i++) {
    const angle = START_ANGLE + i * Math.PI / 3;
    BASE_VERTICES.push({
        x: Math.cos(angle),
        y: Math.sin(angle)
    });
}

// 2. Performance Cache
let CACHED_PATH_STD: Path2D | null = null; // Standard ISO Hex Path

export const HexGeometry = {

    /**
     * Get exact vertices for a hex at (0,0) with specified radius.
     * Applies ISO scaling to Y axis.
     * @param radius - The outer radius of the hex (usually HEX_SIZE)
     * @param applyIso - Whether to squash Y for 2.5D view (default true)
     */
    getVertices(radius: number, applyIso: boolean = true): {x: number, y: number}[] {
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;
        return BASE_VERTICES.map(v => ({
            x: v.x * radius,
            y: v.y * radius * scaleY
        }));
    },

    /**
     * Draw a hex path on the context at (x,y).
     * This ensures ALL hexes in the game share the exact same shape.
     */
    traceHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, applyIso: boolean = true) {
        // Optimization: Use Path2D for standard grid size
        const isStandard = Math.abs(radius - HEX_SIZE) < 0.01 && applyIso;

        if (isStandard) {
            if (!CACHED_PATH_STD) this.rebuildCache();
            ctx.translate(x, y);
            // Note: We perform the fill/stroke outside, this just sets the path
            // But Path2D objects need to be filled/stroked directly. 
            // For compatibility with 'beginPath' workflows, we fallback to manual trace if not using Path2D API directly.
            // To keep "Painter" logic simple (which expects to call stroke()/fill()), we manually trace points.
            // Using a pre-calculated array is faster than Math.cos/sin every frame.
        }

        const verts = this.getVertices(radius, applyIso);
        ctx.beginPath();
        ctx.moveTo(x + verts[0].x, y + verts[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(x + verts[i].x, y + verts[i].y);
        }
        ctx.closePath();
    },

    /**
     * Returns a Path2D object for the standard ISO hex.
     * Useful for hit testing or clipping.
     */
    getStandardPath(): Path2D {
        if (!CACHED_PATH_STD) this.rebuildCache();
        return CACHED_PATH_STD!;
    },

    rebuildCache() {
        const path = new Path2D();
        const verts = this.getVertices(HEX_SIZE, true);
        path.moveTo(verts[0].x, verts[0].y);
        for (let i = 1; i < 6; i++) {
            path.lineTo(verts[i].x, verts[i].y);
        }
        path.closePath();
        CACHED_PATH_STD = path;
    },

    /**
     * Get vertices for a rotated hexagon (used by VFX).
     */
    traceRotatedHex(ctx: CanvasRenderingContext2D, x: number, y: number, radius: number, rotation: number, applyIso: boolean = true) {
        ctx.beginPath();
        const scaleY = applyIso ? ISO_SCALE_Y : 1.0;

        for (let i = 0; i < 6; i++) {
            const angle = START_ANGLE + i * Math.PI / 3 + rotation;
            const px = x + Math.cos(angle) * radius;
            const py = y + Math.sin(angle) * radius * scaleY;

            if (i === 0) ctx.moveTo(px, py);
            else ctx.lineTo(px, py);
        }
        ctx.closePath();
    }
};

import { createCanvas } from "./CanvasUtils";
import { GeometryPainter } from "./painters/GeometryPainter";
import { ParticlePainter } from "./painters/ParticlePainter";
import { ProjectilePainter } from "./painters/ProjectilePainter";
import { IconPainter } from "./painters/IconPainter";
import { HexGeometry } from "./utils/HexGeometry";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

// Updated: 128px for high fidelity on all screens
const TEXTURE_SIZE = 128; 
const CENTER = TEXTURE_SIZE / 2;

export class VFXTextureCache {
    private cache: Map<string, HTMLCanvasElement> = new Map();

    public getTexture(type: string, color: string): HTMLCanvasElement {
        // Normalize keys
        if (type === 'DUST' || type === 'PEBBLE') type = 'RUBBLE';
        if (type === 'RING' || type === 'SHOCKWAVE_RING') type = 'SHOCKWAVE';

        const key = `VFX_${type}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const { canvas, ctx } = createCanvas(TEXTURE_SIZE, TEXTURE_SIZE);
        // Standard Radius for tile-sized effects (matches HEX_SIZE)
        const r = 36; 

        ctx.translate(CENTER, CENTER);

        switch (type) {
            case 'ZONE_BASE':
                this.drawZoneBase(ctx, r, color);
                break;
            case 'ZONE_RIPPLE':
                this.drawZoneRipple(ctx, r, color);
                break;
            case 'WARNING_HATCH':
                this.drawWarningHatch(ctx, r, color);
                break;
            case 'ATMOSPHERE':
            case 'GLOW':
                ParticlePainter.drawAtmosphere(ctx, r, color);
                break;
            case 'CLOUD': 
                this.drawCloudTexture(ctx, r, color);
                break;
            case 'SMOKE':
            case 'SMOKE_PUFF':
                ParticlePainter.drawSmoke(ctx, r, color);
                break;
            case 'SHOCKWAVE':
                ParticlePainter.drawShockwave(ctx, r, color);
                break;
            case 'SPIKE':
            case 'SPARK':
                ParticlePainter.drawSpike(ctx, r * (type === 'SPARK' ? 0.3 : 0.8), color);
                break;
            case 'SHARD':
            case 'RUBBLE':
            case 'ROCK':
            case 'CHIP':
                ctx.fillStyle = color;
                // Draw simple physical chunks (no iso needed for tiny debris)
                HexGeometry.traceHex(ctx, 0, 0, r * 0.5, false);
                ctx.fill();
                break;
            case 'HEX_HALO':
            case 'HEX_FRAME':
                IconPainter.drawHexHalo(ctx, r, color);
                break;
            case 'HEX_LOCK':
            case 'HEX_RUNE':
                IconPainter.drawHexLock(ctx, r, color);
                break;
            case 'MAGIC_CIRCLE':
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                HexGeometry.traceHex(ctx, 0, 0, r * 0.9, true);
                ctx.stroke();
                // Inner circle
                ctx.beginPath(); 
                ctx.ellipse(0, 0, r*0.7, r*0.7*ISO_SCALE_Y, 0, 0, Math.PI*2); 
                ctx.stroke();
                break;
            case 'SHADOW_BLOB':
                this.drawShadowBlob(ctx, r, color);
                break;
            default:
                ctx.fillStyle = color;
                ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI*2); ctx.fill();
                break;
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // --- REFACTORED GENERATORS USING HEX_GEOMETRY ---

    private drawZoneBase(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // Soft Glow Hex
        const grad = ctx.createRadialGradient(0, 0, r*0.2, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;

        // Use HexGeometry to ensure shape matches map exactly
        HexGeometry.traceHex(ctx, 0, 0, r * 0.95, true);
        ctx.fill();
    }

    private drawZoneRipple(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.strokeStyle = color;
        ctx.lineWidth = 3;
        ctx.shadowColor = color;
        ctx.shadowBlur = 8;

        HexGeometry.traceHex(ctx, 0, 0, r * 0.9, true);
        ctx.stroke();

        // Inner thin line
        ctx.lineWidth = 1;
        ctx.globalAlpha = 0.5;
        HexGeometry.traceHex(ctx, 0, 0, r * 0.7, true);
        ctx.stroke();
    }

    private drawWarningHatch(ctx: CanvasRenderingContext2D, r: number, color: string) {
        // 1. Create Hex Mask
        ctx.save();
        HexGeometry.traceHex(ctx, 0, 0, r, true);
        ctx.fill(); // Fill to define shape for clipping (source-in)

        // 2. Draw Stripes
        ctx.globalCompositeOperation = 'source-in';
        ctx.strokeStyle = color;
        ctx.lineWidth = 4;
        const size = r * 2;
        const spacing = 10;

        ctx.beginPath();
        for (let i = -size; i < size; i += spacing) {
            ctx.moveTo(i - size, -size);
            ctx.lineTo(i + size, size);
        }
        ctx.stroke();

        // 3. Border
        ctx.globalCompositeOperation = 'source-over';
        ctx.lineWidth = 2;
        HexGeometry.traceHex(ctx, 0, 0, r, true);
        ctx.stroke();

        ctx.restore();
    }

    private drawShadowBlob(ctx: CanvasRenderingContext2D, r: number, color: string) {
        ctx.fillStyle = color;
        ctx.filter = 'blur(8px)'; 
        ctx.beginPath();
        // Accurate ISO shadow
        ctx.ellipse(0, 0, r * 0.8, r * 0.8 * ISO_SCALE_Y, 0, 0, Math.PI*2);
        ctx.fill();
        ctx.filter = 'none';
    }

    // ... (Keep existing Cloud/Projectile/Terrain logic as they don't affect grid alignment) ...
    private drawCloudTexture(ctx: CanvasRenderingContext2D, r: number, color: string) {
        const grad = ctx.createRadialGradient(0, 0, 0, 0, 0, r);
        grad.addColorStop(0, color);
        grad.addColorStop(0.7, color);
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        const count = 5;
        for(let i=0; i<count; i++) {
            const angle = (i / count) * Math.PI * 2;
            const dist = r * 0.3;
            const size = r * 0.6;
            const x = Math.cos(angle) * dist;
            const y = Math.sin(angle) * dist * ISO_SCALE_Y; // Squash clouds too
            ctx.beginPath(); ctx.arc(x, y, size, 0, Math.PI*2); ctx.fill();
        }
        ctx.beginPath(); ctx.arc(0, 0, r * 0.5, 0, Math.PI*2); ctx.fill();
    }

    public getTerrainDetail(type: string, color: string, variant: number): HTMLCanvasElement {
        const vIdx = variant % 4;
        const key = `TERRAIN_${type}_${color}_${vIdx}`;
        if (this.cache.has(key)) return this.cache.get(key)!;

        const size = HEX_SIZE * 2; 
        const { canvas, ctx } = createCanvas(size, size);
        const cx = size / 2;
        const cy = size / 2;

        ctx.translate(cx, cy);
        // Note: Terrain details are drawn flat then projected, OR drawn pre-projected.
        // Here we draw pre-projected to save render calls.
        ctx.scale(1, ISO_SCALE_Y); 

        const rnd = (offset: number) => {
            const v = Math.sin(vIdx * 999 + offset) * 1000;
            return v - Math.floor(v);
        };

        ctx.fillStyle = color;
        ctx.globalAlpha = type === 'VOID' ? 0.1 : 0.3;

        // Simple Detail Logic
        for(let i=0; i<5; i++) {
            const px = (rnd(i*2) - 0.5) * HEX_SIZE * 1.2;
            const py = (rnd(i*2+1) - 0.5) * HEX_SIZE * 1.2;
            if (px*px + py*py > (HEX_SIZE*0.7)**2) continue;
            ctx.beginPath();
            ctx.arc(px, py, 1.5 + rnd(i*3), 0, Math.PI*2);
            ctx.fill();
        }

        this.cache.set(key, canvas);
        return canvas;
    }

    // Proxy methods for other assets
    public generateProjectileSprite(visual: string, color: string): HTMLCanvasElement {
        const key = `PROJ_${visual}_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        ctx.translate(64, 32);
        switch (visual) {
            case 'HEX_DART': ProjectilePainter.drawImperialSniper(ctx, color); break;
            case 'CRYSTAL': ProjectilePainter.drawImperialCrystal(ctx, color); break;
            case 'ORB': ProjectilePainter.drawImperialOrb(ctx, color); break;
            case 'BOLT': ProjectilePainter.drawCovenantBolt(ctx, color); break;
            case 'AXE': ProjectilePainter.drawCovenantAxe(ctx, color); break;
            case 'FIREBALL': ProjectilePainter.drawCovenantFireball(ctx, color); break;
            case 'BOMB': ProjectilePainter.drawBomb(ctx, color); break;
            default: ProjectilePainter.drawCovenantBolt(ctx, color); break;
        }
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateGlowOrb(color: string): HTMLCanvasElement { return this.getTexture('ATMOSPHERE', color); }
    public generateCracks(color: string): HTMLCanvasElement { return this.getTexture('CRACKS', color); }

    public generateFogCloud(color: string): HTMLCanvasElement {
        const key = `FOG_CLOUD_${color}`;
        if (this.cache.has(key)) return this.cache.get(key)!;
        const { canvas, ctx } = createCanvas(128, 64);
        const grad = ctx.createRadialGradient(64, 32, 0, 64, 32, 64);
        grad.addColorStop(0, color); 
        grad.addColorStop(1, 'transparent');
        ctx.fillStyle = grad;
        ctx.beginPath(); ctx.ellipse(64, 32, 40, 25, 0, 0, Math.PI*2); ctx.fill();
        this.cache.set(key, canvas);
        return canvas;
    }

    public generateBlastZone(color: string): HTMLCanvasElement {
        return this.getTexture('SHOCKWAVE', color); 
    }
}

export const VFXFactory = new VFXTextureCache();

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../utils/HexGeometry";
import { VFXFactory } from "../VFXFactory";

export const VolumePainter = {

    /**
     * Draws the hatching texture.
     * Texture IS ALREADY ISO-SCALED by VFXFactory.
     * DO NOT apply scale here.
     */
    drawHatch(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('WARNING_HATCH', color);
        // Size match: Texture is 128px. Hex Radius 36 -> Width ~72.
        // We draw slightly larger to cover stroke width.
        const size = radius * 2.2; 

        ctx.save();
        ctx.translate(x, y);
        // NO SCALE HERE - Texture contains the perspective

        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'source-over'; 

        ctx.drawImage(texture, -size/2, -size/2, size, size);

        ctx.restore();
    },

    /**
     * Draws a 3D Prism using exact vertices from HexGeometry.
     */
    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING'
    ) {
        const topY = y - height;

        ctx.save();

        // 1. Get Vertices (Relative to (0,0), ISO Scaled)
        const verts = HexGeometry.getVertices(radius, true);
        const indices = [5, 0, 1]; // Front facing walls for Standard ISO

        // 2. Draw Side Walls (Quads)
        for (const i of indices) {
            const j = (i + 1) % 6;

            // World coordinates derived from relative verts
            const x1 = x + verts[i].x;
            const y1 = y + verts[i].y; // Bottom

            const x2 = x + verts[j].x;
            const y2 = y + verts[j].y; // Bottom

            // Wall Geometry: (x1,y1) -> (x2,y2) -> (x2, y2-height) -> (x1, y1-height)

            const grad = ctx.createLinearGradient(0, topY, 0, y);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; 

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.lineTo(x2, y2 - height); 
            ctx.lineTo(x1, y1 - height);
            ctx.closePath();
            ctx.fill();

            // Side Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x1, y1 - height);
            ctx.stroke();

            if (i === 1) { // Draw rightmost edge
                 ctx.beginPath(); ctx.moveTo(x2, y2); ctx.lineTo(x2, y2 - height); ctx.stroke();
            }
        }

        // 3. Draw Top Face
        if (style === 'HATCHED_WARNING') {
            this.drawHatch(ctx, x, topY, radius, '#ffffff', opacity);

            ctx.strokeStyle = color;
            ctx.lineWidth = 2;
            ctx.globalAlpha = 1.0;
            HexGeometry.traceHex(ctx, x, topY, radius, true);
            ctx.stroke();

        } else {
            // Solid/Gradient Top
            ctx.fillStyle = color;
            ctx.globalAlpha = opacity * 0.3;
            HexGeometry.traceHex(ctx, x, topY, radius, true);
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1.5;
            ctx.globalAlpha = 1.0;
            HexGeometry.traceHex(ctx, x, topY, radius, true);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; 

        ctx.save();
        ctx.translate(x, y);
        // Texture is already ISO
        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';

        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        HexGeometry.traceHex(ctx, x, y, radius, true);
        ctx.stroke();

        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number
    ) {
        // Simple extrusion for ice/crystal floors
        const topY = y - height;
        const verts = HexGeometry.getVertices(radius, true);
        const indices = [5, 0, 1];

        ctx.save();
        ctx.globalAlpha = opacity;

        for (const i of indices) {
            const j = (i + 1) % 6;
            const x1 = x + verts[i].x;
            const y1 = y + verts[i].y;
            const x2 = x + verts[j].x;
            const y2 = y + verts[j].y;

            const grad = ctx.createLinearGradient(0, topY, 0, y);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(x1, y1 - height);
            ctx.lineTo(x2, y2 - height);
            ctx.lineTo(x2, y2);
            ctx.lineTo(x1, y1);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        HexGeometry.traceHex(ctx, x, topY, radius, true);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { VolumePainter } from "../../graphics/painters/VolumePainter";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { CAST_VISUALS } from "../../../data/vfx/cast_visuals";
import { VFXFactory } from "../../graphics/VFXFactory";

export const ZoneRenderer = {

    /**
     * Renders zone effects relative to a SINGLE TILE.
     * This function is only called for valid tiles in the grid.
     */
    drawZone(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Center of the specific tile
        size: number,
        color: string,
        visualTag: string, 
        progress: number, 
        globalTime: number,
        dist: number,     
        maxRadius: number 
    ) {
        const isWarning = visualTag === 'AOE_WARNING';
        const isUlt = visualTag === 'ULT';

        const styleKey = isWarning ? 'AOE_WARNING' : (visualTag === 'ULT' ? 'ULT' : (visualTag === 'ACTIVE' ? 'ACTIVE' : 'BASIC'));
        const def = CAST_VISUALS[styleKey] || CAST_VISUALS['BASIC'];

        ctx.save();

        // --- 1. WAVE LOGIC ---
        const currentExpansion = progress * (maxRadius + 0.5); 
        const normDist = dist; 

        const isInsideWave = normDist <= currentExpansion;
        const isWaveEdge = Math.abs(normDist - currentExpansion) < 0.8;

        // --- 2. PULSE ---
        const pulse = isWarning 
            ? (0.5 + Math.abs(Math.sin(globalTime * 15)) * 0.5) 
            : (1.0 + Math.sin(globalTime * def.pulseSpeed) * 0.1);

        if (def.blendMode) ctx.globalCompositeOperation = def.blendMode;

        // A. TILE FILL (Individual Hex Highlight)
        if (isInsideWave || isWarning) {

            if (isWarning) {
                // Danger: Hatched Top Only
                VolumePainter.drawHatch(ctx, x, y, size, '#ffffff', 0.3 + pulse * 0.4);

                // Border
                ctx.strokeStyle = color;
                ctx.lineWidth = 2;
                HexGeometry.traceHex(ctx, x, y, size, true);
                ctx.stroke();
            } 
            else if (isUlt) {
                // Ult: 3D extrusion
                VolumePainter.draw3DPrism(ctx, x, y, size, 12, color, 0.25 * pulse, 'SOLID');
            }
            else {
                // Basic/Active: Texture Overlay
                const opacity = def.fillOpacityBase * pulse * (0.5 + progress * 0.5);
                const texture = VFXFactory.getTexture('ZONE_BASE', color);
                const drawSize = size * 2.2; 

                ctx.translate(x, y);
                // NO SCALE HERE - Texture is ISO
                ctx.globalAlpha = opacity;
                ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
                ctx.translate(-x, -y);
            }
        }

        // B. WAVE EDGE (Ripple)
        if (isWaveEdge) {
            const edgeOpacity = def.fillOpacityMax * pulse;
            const texture = VFXFactory.getTexture('ZONE_RIPPLE', color);
            const drawSize = size * 2.2;

            ctx.translate(x, y);
            ctx.globalAlpha = edgeOpacity;
            ctx.drawImage(texture, -drawSize/2, -drawSize/2, drawSize, drawSize);
            ctx.translate(-x, -y);
        }

        // C. BORDER (Edge Tiles)
        const isBorderTile = Math.abs(dist - maxRadius) < 0.5;
        if ((isWarning || isUlt) && isBorderTile) {
            const borderAlpha = Math.max(0, Math.min(1, (progress * 3) - 0.5)) * 0.6;

            ctx.strokeStyle = color;
            ctx.lineWidth = isWarning ? 3 : 1.5; 
            ctx.globalAlpha = borderAlpha;

            if (isWarning) ctx.setLineDash([5, 5]);

            HexGeometry.traceHex(ctx, x, y, size * 0.9, true);
            ctx.stroke();

            ctx.setLineDash([]);
        }

        ctx.restore();
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { HEX_SIZE } from "../../../constants";

interface ZoneInfo {
    type: 'CAST';
    color: string;
    visual: string; 
    progress: number;
    centerQ: number;
    centerR: number;
    radius: number;
    dist: number;
}

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face Y
        size: number,

        // State Props
        specialStatus: string | undefined, 
        zoneInfo: ZoneInfo | undefined,    

        // Lighting
        lightColor: string | null,
        lightIntensity: number,

        // Interactive
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        // Metadata
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        // Performance: Use cached path if standard size
        const isStandard = Math.abs(size - HEX_SIZE) < 0.01;
        const hexPath = isStandard ? HexGeometry.getStandardPath() : null;

        const fillHex = (color: string, alpha: number) => {
            ctx.fillStyle = color;
            ctx.globalAlpha = alpha;
            if (hexPath) {
                ctx.translate(x, y);
                ctx.fill(hexPath);
                ctx.translate(-x, -y);
            } else {
                HexGeometry.traceHex(ctx, x, y, size, true);
                ctx.fill();
            }
        };

        const strokeHex = (color: string, width: number, alpha: number) => {
            ctx.strokeStyle = color;
            ctx.lineWidth = width;
            ctx.globalAlpha = alpha;
            if (hexPath) {
                ctx.translate(x, y);
                ctx.stroke(hexPath);
                ctx.translate(-x, -y);
            } else {
                HexGeometry.traceHex(ctx, x, y, size, true);
                ctx.stroke();
            }
        };

        // --- LAYER 1: HAZARDS ---
        if (hazard) {
            HazardPainter.draw(ctx, x, y, hazard, globalTime);
        }

        // --- LAYER 2: UNIT STATUS FLOOR ---
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.globalCompositeOperation = 'source-over';
                fillHex(def.floorColor, def.floorOpacity || 0.5);
                ctx.restore();
            }
        }

        // --- LAYER 3: CAST ZONES ---
        if (zoneInfo) {
            ZoneRenderer.drawZone(
                ctx, x, y, size,
                zoneInfo.color,
                zoneInfo.visual,
                zoneInfo.progress,
                globalTime,
                zoneInfo.dist,
                zoneInfo.radius
            );
        }

        // --- LAYER 4: DYNAMIC LIGHTING ---
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen'; 
            fillHex(lightColor, Math.min(0.5, lightIntensity * 0.4));
            ctx.restore();
        }

        // --- LAYER 5: INTERACTIVE HIGHLIGHTS ---
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.globalCompositeOperation = 'screen';

            // Valid Move Range
            if (isRange) { 
                fillHex(rangeColor, 0.2);
                strokeHex(rangeColor, 2, 0.5);
            }

            // Hover
            if (isHover) { 
                fillHex('#ffffff', 0.2);
                strokeHex('#ffffff', 2, 0.8);
            }

            // Unit Position Ring
            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, x, y, size * 0.9, true);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

