import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

export const TerrainRenderer = {

    /**
     * Renders a terrain block in Immediate Mode (Real-time vector drawing).
     * No caching, ensuring crisp edges and dynamic lighting.
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        const topY = -height; // Local Y coordinate for the top face

        ctx.save();
        ctx.translate(x, y); // Move to the base center of the tile

        // --- 1. PREPARE GEOMETRY ---
        // Get vertices for base (Radius 1.0, unscaled) to multiply manually for speed
        const verts = HexGeometry.getFlatVertices(size); 
        const isoScale = ISO_SCALE_Y;

        // --- 2. DRAW SIDE WALLS (The Pillar) ---
        // Only draw sides if height > 0
        if (height > 0) {
            // Front-facing sides (Indices 0->1, 1->2, 2->3 etc... depending on rotation)
            // For standard pointy top hex in our ISO view, front faces are typically indices 0, 1, 5
            // But we simply draw the full extrusion for robustness, relying on painter's algo.

            // Actually, simplified: Draw a full path for the "Wall"
            // Since we draw back-to-front, we only really need to draw the visible front faces (0, 1, 5) 
            // OR simply draw the full block if simpler.

            const sideGradient = ctx.createLinearGradient(0, topY, 0, 0);
            sideGradient.addColorStop(0, theme.sideLight);
            sideGradient.addColorStop(1, theme.sideDark);

            ctx.fillStyle = sideGradient;

            // Draw 3 Front Faces (Optimization: Don't draw back faces, they are occluded)
            const frontIndices = [5, 0, 1]; // The bottom-facing edges in screen space

            ctx.beginPath();
            for (const i of frontIndices) {
                const j = (i + 1) % 6;
                const v1 = verts[i];
                const v2 = verts[j];

                // Project to ISO
                const x1 = v1.x; const y1 = v1.y * isoScale;
                const x2 = v2.x; const y2 = v2.y * isoScale;

                ctx.moveTo(x1, topY + y1); // Top Edge Start
                ctx.lineTo(x2, topY + y2); // Top Edge End
                ctx.lineTo(x2, y2);        // Bottom Edge End
                ctx.lineTo(x1, y1);        // Bottom Edge Start
            }
            ctx.closePath();
            ctx.fill();

            // Side Edges (Stroke) for definition
            ctx.strokeStyle = theme.sideDark;
            ctx.lineWidth = 0.5;
            ctx.stroke();
        }

        // --- 3. DRAW TOP FACE (The Platform) ---
        // Top Face Gradient
        const topGrad = ctx.createLinearGradient(-size, topY - size, size, topY + size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        const v0 = verts[0];
        ctx.moveTo(v0.x, topY + v0.y * isoScale);
        for (let i = 1; i < 6; i++) {
            const v = verts[i];
            ctx.lineTo(v.x, topY + v.y * isoScale);
        }
        ctx.closePath();
        ctx.fill();

        // --- 4. RIM HIGHLIGHT (Bevel Effect) ---
        // Crisp white/bright line on the top edges
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.6;
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        // --- 5. SURFACE DETAIL (Immediate Mode) ---
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, topY, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            // Simple circuit lines directly
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, topY); ctx.lineTo(10, topY);
            ctx.moveTo(0, topY - 10); ctx.lineTo(0, topY + 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        // Optional: Draw simple vector details (grass tufts, pebbles)
        // Kept separate to draw AFTER overlays if needed, or before.
        // Currently empty to keep style clean, or can delegate to SurfacePainter.
        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, cx, cy, type, detailColor, seed);
            }
        }
    }
};

