export const ZoneRenderer = {

    /**
     * Renders zone effects on a SPECIFIC TILE.
     * Calculated based on distance from the Zone Center.
     */
    drawTileZoneEffect(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Tile center
        size: number,
        distToCenter: number, // Distance from this tile to zone origin (in hex units)
        zoneRadius: number,
        color: string,
        progress: number, // 0.0 to 1.0 (Cast progress)
        isEnemy: boolean
    ) {
        ctx.save();
        ctx.translate(x, y);

        // --- PHYSICS OF THE WAVE ---
        // Wave expands from 0 to Radius
        const currentWaveRadius = progress * (zoneRadius + 0.5);

        // Calculate "Wave Presence" on this specific tile
        // 1.0 = Right on the wave edge, 0.0 = Far away
        const distDiff = Math.abs(distToCenter - currentWaveRadius);
        const waveWidth = 1.5; // Width of the ripple band in hex units

        let waveIntensity = 0;
        if (distDiff < waveWidth) {
            // Cosine curve for smooth ripple peak
            waveIntensity = (Math.cos((distDiff / waveWidth) * Math.PI) + 1) * 0.5;
        }

        // Fill Logic: Are we "Inside" the expanded zone?
        const isInside = distToCenter < currentWaveRadius;

        // --- DRAWING ---
        const drawColor = isEnemy ? '#ef4444' : color;

        // 1. Base Fill (If inside or Enemy Warning)
        // Enemy zones always show full area faintly so you know where NOT to stand
        let baseAlpha = 0;
        if (isEnemy) baseAlpha = 0.2; // Constant warning
        if (isInside && !isEnemy) baseAlpha = 0.15; // Friendly fill

        if (baseAlpha > 0) {
            ctx.fillStyle = drawColor;
            ctx.globalAlpha = baseAlpha;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true);
            ctx.fill();
        }

        // 2. The Ripple (Wavefront)
        if (waveIntensity > 0.05) {
            ctx.strokeStyle = drawColor;
            ctx.lineWidth = 2 + waveIntensity * 2; // Thicker at peak
            ctx.globalAlpha = waveIntensity;

            // Pulse size slightly for visual pop
            const pulseSize = size * (0.9 + waveIntensity * 0.1);

            HexGeometry.traceHex(ctx, 0, 0, pulseSize, true);
            ctx.stroke();

            // Add a second inner line for "High Tech" feel
            ctx.lineWidth = 1;
            HexGeometry.traceHex(ctx, 0, 0, pulseSize * 0.7, true);
            ctx.stroke();
        }

        // 3. Border (Static perimeter)
        if (isEnemy || isInside) {
            const isBorder = Math.abs(distToCenter - zoneRadius) < 0.5;
            if (isBorder) {
                ctx.strokeStyle = drawColor;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.5;
                if (isEnemy) ctx.setLineDash([4, 4]);
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.stroke();
                ctx.setLineDash([]);
            }
        }

        ctx.restore();
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { HEX_SIZE } from "../../../constants";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexMath } from "../../math/HexMath";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face Y
        size: number,

        // State Props
        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    

        // Lighting
        lightColor: string | null,
        lightIntensity: number,

        // Interactive
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        // Metadata
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        // --- LAYER 1: HAZARDS ---
        if (hazard) {
            HazardPainter.draw(ctx, x, y, hazard, globalTime);
        }

        // --- LAYER 2: UNIT STATUS FLOOR (e.g. Rooted, Frozen) ---
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, y);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.fill();
                ctx.restore();
            }
        }

        // --- LAYER 3: UNIFIED ZONE RIPPLE ---
        if (zoneInfo) {
            // Calculate distance from this tile to the zone center
            const dist = HexMath.distance({q, r}, {q: zoneInfo.q, r: zoneInfo.r});

            // Render PER TILE effect
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, y, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy
            );
        }

        // --- LAYER 4: DYNAMIC LIGHTING ---
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.6, lightIntensity * 0.5);
            HexGeometry.traceHex(ctx, 0, 0, size, true);
            ctx.fill();
            ctx.restore();
        }

        // --- LAYER 5: INTERACTIVE HIGHLIGHTS ---
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen';

            // Valid Move Range
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.15;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true);
                ctx.fill();

                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true);
                ctx.stroke();
            }

            // Hover Cursor
            if (isHover) { 
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.fill();

                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.9;
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.stroke();
            }

            // Unit Position Ring
            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache";
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 0; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    // Transient Sets for faster lookup during render loop
    private _unitPresence = new Set<string>();
    private _unitVisualStatus = new Map<string, string>();

    public submit(
        cache: GridCache, // Kept for interface compatibility but we bypass the list
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull if map is effectively gone
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        // 1. Pre-calc Unit Presence (Optimization)
        this._unitPresence.clear();
        this._unitVisualStatus.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = `${a.q},${a.r}`;
                this._unitPresence.add(key);
                if (a.visualStatus !== 'NONE') this._unitVisualStatus.set(key, a.visualStatus);
            }
        }

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 2. Iterate Valid Map Keys ONLY
        // This is the core fix for "Void Drawing". We only iterate what exists in the logic.
        const keys = Array.from(engine.map.mapKeys);
        const len = keys.length;

        for (let i = 0; i < len; i++) {
            const key = keys[i];
            const [q, r] = key.split(',').map(Number);

            // Recalculate position (Immediate Mode - no stale cache)
            const px = HexUtils.toPx(q, r, engine.mapConfig).x;
            const py = HexUtils.toPx(q, r, engine.mapConfig).y;
            const h = engine.map.getTerrainHeight(q, r);

            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            // Visual Ground Top Y = (BaseY - Height + Transition)
            const visualBaseY = py + offset;

            // Cull off-screen transition elements
            if (Math.abs(offset) > 1200) continue;

            const sortY = py; // Stable sort key based on logic ground position

            // A. Obstacles
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; 
                op.z = OBSTACLE_Z_INDEX;
                op.tx = px; 
                op.ty = visualBaseY - h - OBSTACLE_ANCHOR_Y; // Anchor to top of block
                op.ttype = obstacleType;
            }

            // B. Zones (Delegated to ZoneSystem)
            const zoneInfo = engine.zones.getZoneAt(q, r);

            // C. Interactive Highlights
            let isRange = false;
            let rangeColor = '';
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    isRange = true; 
                    rangeColor = hoveredSkill.color; 
                }
            }

            const isHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            const hasUnit = !engine.isRunning && this._unitPresence.has(key);
            const hazard = engine.hazards.getHazardAt(q, r);

            // D. Projectile Lights
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }

            // E. Create Terrain Op
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; 

            op.tx = px; 
            op.ty = visualBaseY; 
            op.th = h;

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = zoneInfo; 
            op.oHazard = hazard;
            op.oLightCol = lightColor; op.oLightInt = Math.min(1, lightIntensity);
            op.oRange = isRange; op.oRangeCol = rangeColor;
            op.oHover = isHover; op.oHasUnit = hasUnit;
            op.time = globalTime;
        }
    }
}

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../utils/HexGeometry";
import { VFXFactory } from "../VFXFactory";

export const VolumePainter = {

    /**
     * Draws a 3D Prism using exact vertices from HexGeometry.
     */
    draw3DPrism(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number,
        style: 'SOLID' | 'GRADIENT_FADE' | 'HATCHED_WARNING'
    ) {
        const topY = y - height;

        ctx.save();
        ctx.translate(x, y); // Center base

        // 1. Get Vertices (Relative to (0,0), ISO Scaled)
        const verts = HexGeometry.getVertices(radius, true);
        const indices = [5, 0, 1]; // Front facing walls

        // 2. Draw Side Walls (Quads)
        for (const i of indices) {
            const j = (i + 1) % 6;

            const v1 = verts[i];
            const v2 = verts[j];

            // Wall Geometry: Bottom is 0, Top is -height
            const grad = ctx.createLinearGradient(0, -height, 0, 0);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent'); 

            ctx.fillStyle = grad;
            ctx.globalAlpha = opacity * 0.5; 

            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y);           // Bottom Left
            ctx.lineTo(v2.x, v2.y);           // Bottom Right
            ctx.lineTo(v2.x, v2.y - height);  // Top Right
            ctx.lineTo(v1.x, v1.y - height);  // Top Left
            ctx.closePath();
            ctx.fill();

            // Side Edges
            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.globalAlpha = opacity;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y);
            ctx.lineTo(v1.x, v1.y - height);
            ctx.stroke();

            if (i === 1) { // Draw rightmost edge
                 ctx.beginPath(); ctx.moveTo(v2.x, v2.y); ctx.lineTo(v2.x, v2.y - height); ctx.stroke();
            }
        }

        // 3. Draw Top Face
        ctx.translate(0, -height);

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.3;
        HexGeometry.traceHex(ctx, 0, 0, radius, true);
        ctx.fill();

        ctx.strokeStyle = color;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 1.0;
        HexGeometry.traceHex(ctx, 0, 0, radius, true);
        ctx.stroke();

        ctx.restore();
    },

    drawVolumetricHex(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number
    ) {
        const texture = VFXFactory.getTexture('ATMOSPHERE', color);
        const size = radius * 2.8; 

        ctx.save();
        ctx.translate(x, y);
        // Texture is already ISO
        ctx.globalAlpha = opacity;
        ctx.globalCompositeOperation = 'screen';
        ctx.drawImage(texture, -size/2, -size/2, size, size);
        ctx.restore();
    },

    drawHexRipple(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        color: string,
        opacity: number,
        width: number
    ) {
        ctx.save();
        ctx.globalAlpha = opacity;
        ctx.strokeStyle = color;
        ctx.lineWidth = width;
        ctx.lineCap = 'round';

        ctx.shadowColor = color;
        ctx.shadowBlur = width * 1.5;

        HexGeometry.traceHex(ctx, x, y, radius, true);
        ctx.stroke();

        ctx.lineWidth = width * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.shadowBlur = 0;
        ctx.stroke();

        ctx.restore();
    },

    drawExtrusion(
        ctx: CanvasRenderingContext2D,
        x: number, y: number,
        radius: number,
        height: number,
        color: string,
        opacity: number
    ) {
        // Simple extrusion for ice/crystal floors
        const verts = HexGeometry.getVertices(radius, true);
        const indices = [5, 0, 1];

        ctx.save();
        ctx.translate(x, y);
        ctx.globalAlpha = opacity;

        for (const i of indices) {
            const j = (i + 1) % 6;
            const v1 = verts[i];
            const v2 = verts[j];

            const grad = ctx.createLinearGradient(0, -height, 0, 0);
            grad.addColorStop(0, color);
            grad.addColorStop(1, 'transparent');

            ctx.fillStyle = grad;
            ctx.beginPath();
            ctx.moveTo(v1.x, v1.y - height);
            ctx.lineTo(v2.x, v2.y - height);
            ctx.lineTo(v2.x, v2.y);
            ctx.lineTo(v1.x, v1.y);
            ctx.closePath();
            ctx.fill();

            ctx.strokeStyle = color;
            ctx.lineWidth = 1;
            ctx.stroke();
        }

        ctx.fillStyle = color;
        ctx.globalAlpha = opacity * 0.6;
        HexGeometry.traceHex(ctx, 0, -height, radius, true);
        ctx.fill();

        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = opacity;
        ctx.stroke();

        ctx.restore();
    }
};

import { HEX_SIZE, BLOCK_HEIGHT, ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

export const TerrainRenderer = {

    /**
     * Renders a terrain block in Immediate Mode (Real-time vector drawing).
     * No caching, ensuring crisp edges and dynamic lighting.
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        const topY = -height; // Local Y coordinate for the top face

        ctx.save();
        ctx.translate(x, y); // Move to the base center of the tile

        // --- 1. PREPARE GEOMETRY ---
        // Get vertices for base (Radius 1.0, unscaled) to multiply manually for speed
        const verts = HexGeometry.getVertices(size, false); 
        const isoScale = ISO_SCALE_Y;

        // --- 2. DRAW SIDE WALLS (The Pillar) ---
        // Only draw sides if height > 0
        if (height > 0) {
            // Front-facing sides (Indices 0->1, 1->2, 2->3 etc... depending on rotation)
            // For standard pointy top hex in our ISO view, front faces are typically indices 0, 1, 5
            // But we simply draw the full extrusion for robustness, relying on painter's algo.

            // Actually, simplified: Draw a full path for the "Wall"
            // Since we draw back-to-front, we only really need to draw the visible front faces (0, 1, 5) 
            // OR simply draw the full block if simpler.

            const sideGradient = ctx.createLinearGradient(0, topY, 0, 0);
            sideGradient.addColorStop(0, theme.sideLight);
            sideGradient.addColorStop(1, theme.sideDark);

            ctx.fillStyle = sideGradient;

            // Draw 3 Front Faces (Optimization: Don't draw back faces, they are occluded)
            const frontIndices = [5, 0, 1]; // The bottom-facing edges in screen space

            ctx.beginPath();
            for (const i of frontIndices) {
                const j = (i + 1) % 6;
                const v1 = verts[i];
                const v2 = verts[j];

                // Project to ISO
                const x1 = v1.x; const y1 = v1.y * isoScale;
                const x2 = v2.x; const y2 = v2.y * isoScale;

                ctx.moveTo(x1, topY + y1); // Top Edge Start
                ctx.lineTo(x2, topY + y2); // Top Edge End
                ctx.lineTo(x2, y2);        // Bottom Edge End
                ctx.lineTo(x1, y1);        // Bottom Edge Start
            }
            ctx.closePath();
            ctx.fill();

            // Side Edges (Stroke) for definition
            ctx.strokeStyle = theme.sideDark;
            ctx.lineWidth = 0.5;
            ctx.stroke();
        }

        // --- 3. DRAW TOP FACE (The Platform) ---
        // Top Face Gradient
        const topGrad = ctx.createLinearGradient(-size, topY - size, size, topY + size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        const v0 = verts[0];
        ctx.moveTo(v0.x, topY + v0.y * isoScale);
        for (let i = 1; i < 6; i++) {
            const v = verts[i];
            ctx.lineTo(v.x, topY + v.y * isoScale);
        }
        ctx.closePath();
        ctx.fill();

        // --- 4. RIM HIGHLIGHT (Bevel Effect) ---
        // Crisp white/bright line on the top edges
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.globalAlpha = 0.6;
        ctx.stroke();
        ctx.globalAlpha = 1.0;

        // --- 5. SURFACE DETAIL (Immediate Mode) ---
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, topY, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            // Simple circuit lines directly
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, topY); ctx.lineTo(10, topY);
            ctx.moveTo(0, topY - 10); ctx.lineTo(0, topY + 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        cx: number, cy: number, 
        q: number, r: number, 
        type: string, 
        detailColor: string
    ) {
        // Optional: Draw simple vector details (grass tufts, pebbles)
        // Kept separate to draw AFTER overlays if needed, or before.
        // Currently empty to keep style clean, or can delegate to SurfacePainter.
        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, cx, cy, type, detailColor, seed);
            }
        }
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";

const OBSTACLE_HALF_WIDTH = 40;

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        // 4. Camera Transform
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        // Cache terrain lookup function for this frame
        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        // Collect Grid
        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        // Collect VFX (with culling)
        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        // Collect Units (Optimized Pre-calculation)
        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place (Strictly logical Y for stability)
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            // PIXEL SNAPPING: Strictly align all translation anchors to integer coordinates to avoid sub-pixel blur
            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    TerrainRenderer.drawBlock(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime
                    );
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY - op.th, op.tq, op.tr, op.ttype, op.tdetail);
                    GridOverlays.drawOverlays(
                        ctx, snapX, snapY - op.th, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    ctx.drawImage(sprite, snapX - OBSTACLE_HALF_WIDTH, snapY);
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);

                        if (p.targetX !== undefined && p.targetY !== undefined) {
                            // Relativize target
                            const origTx = p.targetX;
                            const origTy = p.targetY;
                            p.targetX = origTx - snapX;
                            p.targetY = (origTy - (p.targetZ || 0)) - snapY;
                            ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                            p.targetX = origTx;
                            p.targetY = origTy;
                        } else {
                            ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                        }
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        // 6. Occlusion Pass (Silhouettes)
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(
                    ctx, agent, 
                    terrainHeightFunc, 
                    globalTime,
                    engine.mapConfig
                );
            });
            ctx.restore();
        }

        // 7. STATUS LAYER PASS
        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime);

        // 8. Top VFX (Particles above everything)
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        // 9. Post Processing
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        // 10. HUD Layer (Screen Space)
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);

        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);

        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }
}

import { Hex, Point, Cube } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

/**
 * Cube Coordinate interface (x + y + z = 0)
 */
export { Cube };

// Constants for Isometric Projection (Pointy Top)
// Angle 30 degrees for width/height ratio
const SQRT3 = Math.sqrt(3);

export const HexMath = {

    // --- COORDINATE SYSTEMS ---

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    // --- PROJECTION CORE (THE SOURCE OF TRUTH) ---

    /**
     * Converts Hex(q, r) to Screen Pixel(x, y).
     * @returns The CENTER POINT of the hexagon's BASE (Ground Level).
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number): Point {
        // Standard Pointy Top Hex to Pixel conversion
        const x = (SQRT3 * q + SQRT3 / 2 * r) * HEX_SIZE;
        const y = (3 / 2 * r) * HEX_SIZE;

        // Apply ISO Squash (2.5D Projection)
        // We only scale Y to simulate the viewing angle
        return {
            x: x + offsetX,
            y: (y * ISO_SCALE_Y) + offsetY
        };
    },

    /**
     * Converts Screen Pixel(x, y) to Fractional Hex.
     * Inverse of hexToPixel.
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y; // Un-squash

        const q = (SQRT3 / 3 * dx - 1 / 3 * dy) / HEX_SIZE;
        const r = (2 / 3 * dy) / HEX_SIZE;

        return { q, r };
    },

    // --- GEOMETRY UTILS ---

    distance(a: Hex, b: Hex): number {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    lerp(a: Hex, b: Hex, t: number): Hex {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        const cubeLerp = {
            x: ac.x + (bc.x - ac.x) * t,
            y: ac.y + (bc.y - ac.y) * t,
            z: ac.z + (bc.z - ac.z) * t
        };
        return HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp));
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = HexMath.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp)));
        }
        return results;
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    ring(center: Hex, radius: number): Hex[] {
        const results: Hex[] = [];
        if (radius === 0) return [center];
        let curr = HexMath.axialToCube({ q: center.q, r: center.r - radius });
        const directions = [{x:1, y:-1, z:0}, {x:1, y:0, z:-1}, {x:0, y:1, z:-1}, {x:-1, y:1, z:0}, {x:-1, y:0, z:1}, {x:0, y:-1, z:1}];
        for (let i = 0; i < 6; i++) {
            for (let j = 0; j < radius; j++) {
                results.push(HexMath.cubeToAxial(curr));
                curr.x += directions[i].x;
                curr.y += directions[i].y;
                curr.z += directions[i].z;
            }
        }
        return results;
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

export const TerrainRenderer = {

    /**
     * Renders a solid 2.5D hexagonal prism (The Block).
     * @param x Screen X of the base center
     * @param y Screen Y of the base center (Ground Level)
     * @param size Hex radius
     * @param height Vertical extrusion amount (Positive value)
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Pre-calc visual coordinates
        const topOffset = -height; // Y axis goes down, so height moves Up (Negative Y)
        const vertices = HexGeometry.getVertices(size, true); // Get 6 points relative to (0,0)

        ctx.save();
        ctx.translate(x, y);

        // --- 1. DRAW SIDE WALLS (The Base) ---
        // Only draw the front-facing walls (Indices 0, 1, 5 for pointy top iso)
        // Vertices order is usually starts at 30deg (Bottom Right)

        // Define faces by vertex indices [start, end]
        // 0-1 (Bottom Right), 1-2 (Bottom), 2-3 (Bottom Left) -> These are front facing?
        // Let's rely on standard Pointy Top geometry:
        // P0 (Bottom Right), P1 (Bottom), P2 (Bottom Left), P3 (Top Left), P4 (Top), P5 (Top Right)
        // Wait, HexGeometry.BASE_VERTICES starts at 75deg (30+45). 
        // Let's just draw the "Lower Half" path.

        if (height > 0) {
            // Draw a continuous strip for the visible sides to avoid seams
            const frontIndices = [5, 0, 1, 2]; 
            // We need to fill the quad formed by (v[i], v[i]+up)

            // Side Wall Gradient (Fake Lighting)
            // Left faces are lit, Right faces are shadowed

            // Face 1 (Left-ish): Index 1-2
            this.drawSideFace(ctx, vertices, 1, 2, topOffset, theme.sideLight);

            // Face 2 (Right-ish): Index 0-1
            this.drawSideFace(ctx, vertices, 0, 1, topOffset, theme.sideDark);

            // Face 3 (Far Right): Index 5-0
            this.drawSideFace(ctx, vertices, 5, 0, topOffset, theme.sideDark);
        }

        // --- 2. DRAW TOP FACE (The Surface) ---
        ctx.translate(0, topOffset);

        // Gradient Top
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // --- 3. EDGE HIGHLIGHT (The Bevel) ---
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // --- 4. SURFACE DETAILS ---
        // Special renderers for Liquid/Void
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            // Circuit pattern
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        // Bottom Edge
        ctx.moveTo(verts[i1].x, verts[i1].y);
        ctx.lineTo(verts[i2].x, verts[i2].y);
        // Up to Top Edge
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        // Seam fix line
        ctx.strokeStyle = 'rgba(0,0,0,0.1)';
        ctx.lineWidth = 0.5;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, // Base coords
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // Details sit on top face
        const visualY = baseY - height;

        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache"; // Kept for type signature, but largely bypassed
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 0; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    private _unitVisualStatus = new Map<string, string>();
    private _unitPresence = new Set<string>();

    public submit(
        cache: GridCache, 
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull global transition
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Status (Optimized Lookup)
        this._unitVisualStatus.clear();
        this._unitPresence.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = HexUtils.key(a);
                this._unitVisualStatus.set(key, a.visualStatus);
                this._unitPresence.add(key);
            }
        }

        // 2. ITERATE MAP KEYS DIRECTLY (No Void Drawing)
        // Convert Set iterator to loop
        const mapKeys = Array.from(engine.map.mapKeys);

        for (const key of mapKeys) {
            const [q, r] = key.split(',').map(Number);

            // MATH: Single source of truth for Position
            const pos = HexMath.hexToPixel(q, r, engine.mapConfig.offsetX, engine.mapConfig.offsetY);
            const px = pos.x;
            const py = pos.y;
            const h = engine.map.getTerrainHeight(q, r);

            // Transition Offset (Visual Only)
            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1200) continue; // Cull far off-screen

            // SORT KEY: Use the Base Y (py) + Offset
            // This ensures objects on the same "row" sort correctly regardless of height.
            const sortY = py + offset;

            // A. Obstacles
            // Obstacles sit ON TOP of the terrain block.
            // Visual Y = BaseY - Height - ObstacleAnchor
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; // Sorts with the tile
                op.z = OBSTACLE_Z_INDEX; // Slight bias above floor decals
                op.tx = px; 
                op.ty = py + offset - h; // Anchor to top of block
                op.ttype = obstacleType;
            }

            // B. Terrain Block
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; // Base layer

            op.tx = px;
            op.ty = sortY; // The base of the column
            op.th = h;     // The height to extrude up

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // C. Overlays (Zones, Hazards)
            // Passed as data, renderer handles drawing them on the Top Face
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = engine.zones.getZoneAt(q, r);
            op.oHazard = engine.hazards.getHazardAt(q, r);
            op.oHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            op.oHasUnit = this._unitPresence.has(key);

            // D. Lighting / Range (Logic)
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);

            // Interactive Range
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    op.oRange = true; 
                    op.oRangeCol = hoveredSkill.color; 
                }
            }

            op.time = globalTime;
        }
    }
}

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";

const OBSTACLE_HALF_WIDTH = 40;

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        // 4. Camera Transform
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        // Collect Grid
        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        // Collect VFX
        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        // Collect Units
        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Draw Solid Block
                    TerrainRenderer.drawBlock(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime
                    );

                    // Draw Details on Top Face (Y - Height)
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);

                    // Draw Overlays on Top Face
                    GridOverlays.drawOverlays(
                        ctx, snapX, visualTopY, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    // Obstacles anchor bottom-center to ty
                    ctx.drawImage(sprite, snapX - OBSTACLE_HALF_WIDTH, snapY - 100); // 100 is approx height of obstacle asset
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        // 6. Occlusion & Status Layers
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        // 9. Post Processing
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        // 10. HUD Layer
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);

        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }
}

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import { HexMath } from "../../math/HexMath";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y (Base of the tile unit is standing on)
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // 1. Interpolate Ground Position (Lerp if moving)
        // Use HexMath for consistency
        let logicalX = 0;
        let logicalY = 0;
        let terrainH = 0;

        if (agent.isMoving && agent.path.length > 0) {
            const startPx = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY);
            const nextHex = agent.path[0];
            const endPx = HexMath.hexToPixel(nextHex.q, nextHex.r, mapConfig.offsetX, mapConfig.offsetY);

            // Re-calculate lerp to ensure it matches motion engine visual exactly
            logicalX = startPx.x + (endPx.x - startPx.x) * agent.moveProgress;
            logicalY = startPx.y + (endPx.y - startPx.y) * agent.moveProgress;

            const startH = getTerrainHeight(agent.q, agent.r);
            const endH = getTerrainHeight(nextHex.q, nextHex.r);
            terrainH = startH + (endH - startH) * agent.moveProgress;
        } else {
            const pos = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY);
            logicalX = pos.x;
            logicalY = pos.y;
            terrainH = getTerrainHeight(agent.q, agent.r);
        }

        // Apply visual physics offsets
        const visualX = logicalX + agent.physics.x;
        const visualY = logicalY + agent.physics.y; // This is the GROUND Y used for sorting
        const visualZ = terrainH + agent.physics.z; // Total Height

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}

import { Hex, Point, Cube } from "../../types";
import { HEX_SIZE, ISO_SCALE_Y } from "../../constants";

/**
 * Cube Coordinate interface (x + y + z = 0)
 */
export { Cube };

// Constants for Isometric Projection (Pointy Top)
const SQRT3 = Math.sqrt(3);

export const HexMath = {

    // --- COORDINATE SYSTEMS ---

    axialToCube(h: Hex): Cube {
        return { x: h.q, z: h.r, y: -h.q - h.r };
    },

    cubeToAxial(c: Cube): Hex {
        return { q: c.x, r: c.z };
    },

    cubeRound(frac: Cube): Cube {
        let q = Math.round(frac.x);
        let r = Math.round(frac.z);
        let s = Math.round(frac.y);

        const q_diff = Math.abs(q - frac.x);
        const r_diff = Math.abs(r - frac.z);
        const s_diff = Math.abs(s - frac.y);

        if (q_diff > r_diff && q_diff > s_diff) {
            q = -r - s;
        } else if (r_diff > s_diff) {
            r = -q - s;
        } else {
            s = -q - r;
        }
        return { x: q, y: s, z: r };
    },

    // --- PROJECTION CORE (THE SOURCE OF TRUTH) ---

    /**
     * Converts Hex(q, r) to Screen Pixel(x, y).
     * @returns The CENTER POINT of the hexagon's BASE (Ground Level).
     */
    hexToPixel(q: number, r: number, offsetX: number, offsetY: number): Point {
        // Standard Pointy Top Hex to Pixel conversion
        const x = (SQRT3 * q + SQRT3 / 2 * r) * HEX_SIZE;
        const y = (3 / 2 * r) * HEX_SIZE;

        // Apply ISO Squash (2.5D Projection)
        // We only scale Y to simulate the viewing angle
        return {
            x: x + offsetX,
            y: (y * ISO_SCALE_Y) + offsetY
        };
    },

    /**
     * Converts Screen Pixel(x, y) to Fractional Hex.
     * Inverse of hexToPixel.
     */
    pixelToHex(x: number, y: number, offsetX: number, offsetY: number): Hex {
        const dx = x - offsetX;
        const dy = (y - offsetY) / ISO_SCALE_Y; // Un-squash

        const q = (SQRT3 / 3 * dx - 1 / 3 * dy) / HEX_SIZE;
        const r = (2 / 3 * dy) / HEX_SIZE;

        return { q, r };
    },

    // --- GEOMETRY UTILS ---

    distance(a: Hex, b: Hex): number {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        return Math.max(Math.abs(ac.x - bc.x), Math.abs(ac.y - bc.y), Math.abs(ac.z - bc.z));
    },

    lerp(a: Hex, b: Hex, t: number): Hex {
        const ac = HexMath.axialToCube(a);
        const bc = HexMath.axialToCube(b);
        const cubeLerp = {
            x: ac.x + (bc.x - ac.x) * t,
            y: ac.y + (bc.y - ac.y) * t,
            z: ac.z + (bc.z - ac.z) * t
        };
        return HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp));
    },

    line(a: Hex, b: Hex): Hex[] {
        const N = HexMath.distance(a, b);
        const results: Hex[] = [];
        const ac = { x: a.q + 1e-6, z: a.r + 1e-6, y: -a.q - a.r - 2e-6 };
        const bc = { x: b.q + 1e-6, z: b.r + 1e-6, y: -b.q - b.r - 2e-6 };
        for (let i = 0; i <= N; i++) {
            const t = N === 0 ? 0.0 : i / N;
            const cubeLerp = {
                x: ac.x + (bc.x - ac.x) * t,
                y: ac.y + (bc.y - ac.y) * t,
                z: ac.z + (bc.z - ac.z) * t
            };
            results.push(HexMath.cubeToAxial(HexMath.cubeRound(cubeLerp)));
        }
        return results;
    },

    range(center: Hex, n: number): Hex[] {
        const results: Hex[] = [];
        for (let q = -n; q <= n; q++) {
            for (let r = Math.max(-n, -q - n); r <= Math.min(n, -q + n); r++) {
                results.push({ q: center.q + q, r: center.r + r });
            }
        }
        return results;
    },

    ring(center: Hex, radius: number): Hex[] {
        const results: Hex[] = [];
        if (radius === 0) return [center];
        let curr = HexMath.axialToCube({ q: center.q, r: center.r - radius });
        const directions = [{x:1, y:-1, z:0}, {x:1, y:0, z:-1}, {x:0, y:1, z:-1}, {x:-1, y:1, z:0}, {x:-1, y:0, z:1}, {x:0, y:-1, z:1}];
        for (let i = 0; i < 6; i++) {
            for (let j = 0; j < radius; j++) {
                results.push(HexMath.cubeToAxial(curr));
                curr.x += directions[i].x;
                curr.y += directions[i].y;
                curr.z += directions[i].z;
            }
        }
        return results;
    }
};

import { ISO_SCALE_Y } from "../../../constants";
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { SurfacePainter } from "../../graphics/painters/SurfacePainter";

export const TerrainRenderer = {

    /**
     * Renders a solid 2.5D hexagonal prism (The Block).
     * @param x Screen X of the base center
     * @param y Screen Y of the base center (Ground Level)
     * @param size Hex radius
     * @param height Vertical extrusion amount (Positive value)
     */
    drawBlock(
        ctx: CanvasRenderingContext2D, 
        x: number, y: number, 
        size: number, height: number, 
        theme: any,
        type: string,
        globalTime: number
    ) {
        // Pre-calc visual coordinates
        const topOffset = -height; // Y axis goes down, so height moves Up (Negative Y)

        // Vertices relative to (0,0) center
        const vertices = HexGeometry.getVertices(size, true); 

        ctx.save();
        ctx.translate(x, y);

        // --- 1. DRAW SIDE WALLS (The Pedestal) ---
        // Only draw if there is height. 
        // We draw the "Front" faces (Indices 0, 1, 5 correspond to Bottom-Right, Bottom, Bottom-Left usually)
        // But HexGeometry starts at 30+45 deg? Let's assume standard indices for front-facing.
        // In standard flat-top/pointy-top conversion, visible faces are usually 0, 1, 2 or 5, 0, 1.

        if (height > 0) {
            // Draw a continuous strip for the visible sides
            // Vertices order: 0 (BR), 1 (B), 2 (BL), 3 (TL), 4 (T), 5 (TR)

            // Side Wall Gradient (Fake Lighting: Left is Lit, Right is Dark)

            // Left Face (Index 1-2)
            this.drawSideFace(ctx, vertices, 1, 2, topOffset, theme.sideLight);

            // Right Face (Index 0-1)
            this.drawSideFace(ctx, vertices, 0, 1, topOffset, theme.sideDark);

            // Far Right Face (Index 5-0) - Optional depending on angle, usually visible
            this.drawSideFace(ctx, vertices, 5, 0, topOffset, theme.sideDark);
        }

        // --- 2. DRAW TOP FACE (The Platform) ---
        ctx.translate(0, topOffset);

        // Gradient Top
        const topGrad = ctx.createLinearGradient(-size, -size, size, size);
        topGrad.addColorStop(0, theme.rim); // Light source top-left
        topGrad.addColorStop(0.5, theme.top);
        topGrad.addColorStop(1, theme.sideDark); // Shadow bottom-right

        ctx.fillStyle = topGrad;

        ctx.beginPath();
        ctx.moveTo(vertices[0].x, vertices[0].y);
        for (let i = 1; i < 6; i++) {
            ctx.lineTo(vertices[i].x, vertices[i].y);
        }
        ctx.closePath();
        ctx.fill();

        // --- 3. EDGE HIGHLIGHT (The Bevel) ---
        ctx.strokeStyle = theme.rim;
        ctx.lineWidth = 1.5;
        ctx.stroke();

        // --- 4. SURFACE DETAILS ---
        // Special renderers for Liquid/Void
        if (type === 'MAGMA') {
            SurfacePainter.drawLiquid(ctx, 0, 0, '#ef4444', globalTime, 1.0);
        } else if (type === 'VOID') {
            // Circuit pattern
            ctx.strokeStyle = '#334155';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(-10, 0); ctx.lineTo(10, 0);
            ctx.moveTo(0, -10); ctx.lineTo(0, 10);
            ctx.stroke();
        }

        ctx.restore();
    },

    drawSideFace(ctx: CanvasRenderingContext2D, verts: {x:number, y:number}[], i1: number, i2: number, topOffset: number, color: string) {
        ctx.fillStyle = color;
        ctx.beginPath();
        // Bottom Edge
        ctx.moveTo(verts[i1].x, verts[i1].y);
        ctx.lineTo(verts[i2].x, verts[i2].y);
        // Up to Top Edge
        ctx.lineTo(verts[i2].x, verts[i2].y + topOffset);
        ctx.lineTo(verts[i1].x, verts[i1].y + topOffset);
        ctx.closePath();
        ctx.fill();

        // Seam fix line
        ctx.strokeStyle = 'rgba(0,0,0,0.1)';
        ctx.lineWidth = 0.5;
        ctx.stroke();
    },

    drawTerrainDetail(
        ctx: CanvasRenderingContext2D, 
        baseX: number, baseY: number, // Base coords
        height: number,
        type: string, 
        detailColor: string,
        q: number, r: number
    ) {
        // Details sit on top face
        const visualY = baseY - height;

        if (type === 'FOREST') {
            const seed = Math.abs(Math.sin(q * 12.9898 + r * 78.233));
            if (seed > 0.6) {
                SurfacePainter.drawDetailTexture(ctx, baseX, visualY, type, detailColor, seed);
            }
        }
    }
};

import { GameEngine, Agent } from "../../game";
import { GridCache } from "./GridCache"; 
import { RenderList, RenderOpType } from "../../renderers/RenderList";
import { Hex, Skill, Projectile } from "../../../types";
import { TERRAIN_THEMES, HEX_SIZE } from "../../../constants";
import { HexUtils, getTransitionOffset } from "../../utils";
import { HexMath } from "../../math/HexMath";

const OBSTACLE_Z_INDEX = 10;
const OBSTACLE_ANCHOR_Y = 0; 
const PROJ_LIGHT_RADIUS_SQ = 1600;

export class GridRenderStrategy {

    private _unitVisualStatus = new Map<string, string>();
    private _unitPresence = new Set<string>();

    public submit(
        cache: GridCache, // Kept for interface compatibility but we bypass the list
        renderList: RenderList,
        engine: GameEngine, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null, 
        highlightAgent: Agent | null, 
        projectiles: Projectile[],
        transitionT: number,      
        transitionPhase: 'IN' | 'OUT' | 'IDLE',
        globalTime: number
    ) {
        // Cull global transition
        if (transitionPhase === 'OUT' && transitionT > 0.95) return;

        const scene = engine.currentScene;
        const theme = TERRAIN_THEMES[scene.textureType] || TERRAIN_THEMES['VOID'];

        // 1. Pre-calc Unit Status (Optimized Lookup)
        this._unitVisualStatus.clear();
        this._unitPresence.clear();
        for (const a of engine.agents) {
            if (a.hp > 0) {
                const key = HexUtils.key(a);
                this._unitVisualStatus.set(key, a.visualStatus);
                this._unitPresence.add(key);
            }
        }

        // 2. ITERATE MAP KEYS DIRECTLY (Source of Truth)
        // Convert Set iterator to array for loop
        const mapKeys = Array.from(engine.map.mapKeys);

        for (const key of mapKeys) {
            const [q, r] = key.split(',').map(Number);

            // MATH: Single source of truth for Position
            const pos = HexMath.hexToPixel(q, r, engine.mapConfig.offsetX, engine.mapConfig.offsetY);
            const px = pos.x;
            const py = pos.y;
            const h = engine.map.getTerrainHeight(q, r);

            // Transition Offset (Visual Only)
            const offset = getTransitionOffset(px, py, engine.mapConfig, transitionT, transitionPhase);
            if (Math.abs(offset) > 1200) continue; // Cull far off-screen

            // SORT KEY: Use the Base Y (py) + Offset
            // This ensures objects on the same "row" sort correctly regardless of height.
            // Objects "behind" (smaller Y) draw first.
            const sortY = py + offset;

            // A. Obstacles
            // Obstacles sit ON TOP of the terrain block.
            // Visual Y = BaseY - Height - ObstacleAnchor
            const obstacleType = engine.obstacles.get(key);
            if (obstacleType) {
                const op = renderList.next();
                op.type = RenderOpType.OBSTACLE;
                op.y = sortY; // Sorts with the tile
                op.z = OBSTACLE_Z_INDEX; 
                op.tx = px; 
                op.ty = py + offset - h; // Anchor to top of block
                op.ttype = obstacleType;
            }

            // B. Terrain Block
            const op = renderList.next();
            op.type = RenderOpType.TERRAIN;
            op.y = sortY; 
            op.z = 0; // Base layer

            op.tx = px;
            op.ty = sortY; // The base of the column
            op.th = h;     // The height to extrude up

            op.tsize = HEX_SIZE;
            op.ttheme = theme;
            op.ttype = scene.textureType;
            op.tdetail = theme.detail;
            op.tq = q; op.tr = r;

            // C. Overlays (Zones, Hazards)
            // Passed as data, renderer handles drawing them on the Top Face
            op.oStatus = this._unitVisualStatus.get(key);
            op.oDanger = engine.zones.getZoneAt(q, r);
            op.oHazard = engine.hazards.getHazardAt(q, r);
            op.oHover = hoveredHex ? (hoveredHex.q === q && hoveredHex.r === r) : false;
            op.oHasUnit = this._unitPresence.has(key);

            // D. Lighting / Range (Logic)
            let lightColor = null;
            let lightIntensity = 0;
            for (const p of projectiles) {
                const distSq = (p.x - px)**2 + (p.y - py)**2;
                if (distSq < PROJ_LIGHT_RADIUS_SQ) {
                    lightColor = p.skill.color;
                    lightIntensity += (1 - Math.sqrt(distSq) / 40);
                }
            }
            op.oLightCol = lightColor;
            op.oLightInt = Math.min(1, lightIntensity);

            // Interactive Range
            if (hoveredSkill && highlightAgent) {
                const agentH = engine.map.getTerrainHeight(highlightAgent.q, highlightAgent.r);
                const deltaH = agentH - h;
                const bonus = Math.max(0, Math.floor(deltaH / 24)); 
                const dist = HexMath.distance({q, r}, {q: highlightAgent.q, r: highlightAgent.r});

                if (dist <= hoveredSkill.range + bonus) { 
                    op.oRange = true; 
                    op.oRangeCol = hoveredSkill.color; 
                }
            }

            op.time = globalTime;
        }
    }
}

import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { ISO_SCALE_Y } from "../../../constants";

export const ZoneRenderer = {

    /**
     * Renders zone effects on a SPECIFIC TILE.
     * Calculated based on distance from the Zone Center.
     */
    drawTileZoneEffect(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Tile center
        size: number,
        distToCenter: number, // Distance from this tile to zone origin (in hex units)
        zoneRadius: number,
        color: string,
        progress: number, // 0.0 to 1.0 (Cast progress)
        isEnemy: boolean
    ) {
        ctx.save();
        ctx.translate(x, y);

        // --- PHYSICS OF THE WAVE ---
        // Wave expands from 0 to Radius
        const currentWaveRadius = progress * (zoneRadius + 0.5);

        // Calculate "Wave Presence" on this specific tile
        // 1.0 = Right on the wave edge, 0.0 = Far away
        const distDiff = Math.abs(distToCenter - currentWaveRadius);
        const waveWidth = 1.5; // Width of the ripple band in hex units

        let waveIntensity = 0;
        if (distDiff < waveWidth) {
            // Cosine curve for smooth ripple peak
            waveIntensity = (Math.cos((distDiff / waveWidth) * Math.PI) + 1) * 0.5;
        }

        // Fill Logic: Are we "Inside" the expanded zone?
        const isInside = distToCenter < currentWaveRadius;

        // --- DRAWING ---
        const drawColor = isEnemy ? '#ef4444' : color;

        // 1. Base Fill (If inside or Enemy Warning)
        // Enemy zones always show full area faintly so you know where NOT to stand
        let baseAlpha = 0;
        if (isEnemy) baseAlpha = 0.2; // Constant warning
        if (isInside && !isEnemy) baseAlpha = 0.15; // Friendly fill

        if (baseAlpha > 0) {
            ctx.fillStyle = drawColor;
            ctx.globalAlpha = baseAlpha;
            HexGeometry.traceHex(ctx, 0, 0, size * 0.95, true);
            ctx.fill();
        }

        // 2. The Ripple (Wavefront)
        if (waveIntensity > 0.05) {
            ctx.strokeStyle = drawColor;
            ctx.lineWidth = 2 + waveIntensity * 2; // Thicker at peak
            ctx.globalAlpha = waveIntensity;

            // Pulse size slightly for visual pop
            const pulseSize = size * (0.9 + waveIntensity * 0.1);

            HexGeometry.traceHex(ctx, 0, 0, pulseSize, true);
            ctx.stroke();

            // Add a second inner line for "High Tech" feel
            ctx.lineWidth = 1;
            HexGeometry.traceHex(ctx, 0, 0, pulseSize * 0.7, true);
            ctx.stroke();
        }

        // 3. Border (Static perimeter)
        if (isEnemy || isInside) {
            const isBorder = Math.abs(distToCenter - zoneRadius) < 0.5;
            if (isBorder) {
                ctx.strokeStyle = drawColor;
                ctx.lineWidth = 1;
                ctx.globalAlpha = 0.5;
                if (isEnemy) ctx.setLineDash([4, 4]);
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.stroke();
                ctx.setLineDash([]);
            }
        }

        ctx.restore();
    }
};

import { ZoneRenderer } from "./ZoneRenderer";
import { HazardPainter } from "./painters/HazardPainter"; 
import { HexGeometry } from "../../graphics/utils/HexGeometry";
import { GroundHazard } from "../../../types";
import { STATUS_VISUALS } from "../../../data/vfx/status_visuals";
import { HEX_SIZE } from "../../../constants";
import { ActiveZone } from "../../systems/ZoneSystem";
import { HexMath } from "../../math/HexMath";

export const GridOverlays = {

    drawOverlays(
        ctx: CanvasRenderingContext2D,
        x: number, y: number, // Visual Top Face Y
        size: number,

        // State Props
        specialStatus: string | undefined, 
        zoneInfo: ActiveZone | undefined,    

        // Lighting
        lightColor: string | null,
        lightIntensity: number,

        // Interactive
        isRange: boolean,
        rangeColor: string,
        isHover: boolean,
        hasUnit: boolean,

        // Metadata
        q: number, r: number,
        globalTime: number,
        hazard: GroundHazard | undefined
    ) {
        // --- LAYER 1: HAZARDS ---
        if (hazard) {
            HazardPainter.draw(ctx, x, y, hazard, globalTime);
        }

        // --- LAYER 2: UNIT STATUS FLOOR (e.g. Rooted, Frozen) ---
        if (specialStatus && specialStatus !== 'NONE') {
            const def = STATUS_VISUALS[specialStatus];
            if (def && def.floorColor) {
                ctx.save();
                ctx.translate(x, y);
                ctx.fillStyle = def.floorColor;
                ctx.globalAlpha = def.floorOpacity || 0.5;
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.fill();
                ctx.restore();
            }
        }

        // --- LAYER 3: UNIFIED ZONE RIPPLE ---
        if (zoneInfo) {
            // Calculate distance from this tile to the zone center
            const dist = HexMath.distance({q, r}, {q: zoneInfo.q, r: zoneInfo.r});

            // Render PER TILE effect
            ZoneRenderer.drawTileZoneEffect(
                ctx, x, y, size,
                dist,
                zoneInfo.radius,
                zoneInfo.color,
                zoneInfo.progress,
                zoneInfo.isEnemy
            );
        }

        // --- LAYER 4: DYNAMIC LIGHTING ---
        if (lightColor && lightIntensity > 0) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen'; 
            ctx.fillStyle = lightColor;
            ctx.globalAlpha = Math.min(0.6, lightIntensity * 0.5);
            HexGeometry.traceHex(ctx, 0, 0, size, true);
            ctx.fill();
            ctx.restore();
        }

        // --- LAYER 5: INTERACTIVE HIGHLIGHTS ---
        if (isRange || isHover || hasUnit) {
            ctx.save();
            ctx.translate(x, y);
            ctx.globalCompositeOperation = 'screen';

            // Valid Move Range
            if (isRange) { 
                ctx.fillStyle = rangeColor;
                ctx.globalAlpha = 0.15;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true);
                ctx.fill();

                ctx.strokeStyle = rangeColor;
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.4;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true);
                ctx.stroke();
            }

            // Hover Cursor
            if (isHover) { 
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = 0.2;
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.fill();

                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 2;
                ctx.globalAlpha = 0.9;
                HexGeometry.traceHex(ctx, 0, 0, size, true);
                ctx.stroke();
            }

            // Unit Position Ring
            if (hasUnit && !isHover && !zoneInfo) {
                ctx.strokeStyle = '#ffffff';
                ctx.lineWidth = 1.5;
                ctx.globalAlpha = 0.3;
                HexGeometry.traceHex(ctx, 0, 0, size * 0.9, true);
                ctx.stroke();
            }

            ctx.restore();
        }
    }
};

import { Agent, GameEngine, VICTORY_PHASE_DURATION } from "../game";
import { Camera, GameRenderer } from "../renderer"; 
import { Hex, Skill } from "../../types";
import { HexUtils } from "../utils";

// Sub-renderers
import { BackgroundRenderer } from "./background";
import { TacticalRenderer } from "./tactical";
import { HUDRenderer } from "./HUDRenderer";
import { PostProcessor } from "./PostProcessor"; 
import { RenderList, RenderOpType } from "./RenderList";
import { ProjectileDrawer } from "./ProjectileDrawer";

// Painters
import { TerrainRenderer } from "./grid/TerrainRenderer";
import { GridOverlays } from "./grid/GridOverlays";
import { ParticleRenderer } from "../systems/vfx/renderers/ParticleRenderer";
import { SpriteManager } from "../sprites";
import { AssetManager } from "../assets";

const OBSTACLE_HALF_WIDTH = 40;

export class RenderPipeline {
    private renderer: GameRenderer;

    private backgroundRenderer: BackgroundRenderer;
    private tacticalRenderer: TacticalRenderer;
    private hudRenderer: HUDRenderer;
    private postProcessor: PostProcessor;
    private renderList: RenderList;

    private transitionT: number = 0;
    private transitionPhase: 'IN' | 'OUT' | 'IDLE' = 'IDLE';

    constructor(renderer: GameRenderer) {
        this.renderer = renderer;
        this.backgroundRenderer = new BackgroundRenderer();
        this.tacticalRenderer = new TacticalRenderer();
        this.hudRenderer = new HUDRenderer();
        this.postProcessor = new PostProcessor();
        this.renderList = new RenderList();
    }

    public setTransition(t: number, phase: 'IN' | 'OUT' | 'IDLE') {
        this.transitionT = t;
        this.transitionPhase = phase;
    }

    public update(dt: number, engine: GameEngine) {
        this.tacticalRenderer.update(dt, engine);
    }

    public draw(
        ctx: CanvasRenderingContext2D, 
        engine: GameEngine, 
        camera: Camera, 
        highlight: Agent | null, 
        fps: number, 
        hoveredHex: Hex | null, 
        hoveredSkill: Skill | null,
        globalTime: number
    ): void {
        const physicalWidth = ctx.canvas.width;
        const physicalHeight = ctx.canvas.height;

        if (physicalWidth === 0 || physicalHeight === 0) return;

        const dpr = window.devicePixelRatio || 1;
        const logicalWidth = physicalWidth / dpr;
        const logicalHeight = physicalHeight / dpr;

        const scene = engine.currentScene;

        // 1. Reset & Clear
        ctx.resetTransform();
        ctx.clearRect(0, 0, physicalWidth, physicalHeight);

        // 2. Apply Global Scale
        ctx.scale(dpr, dpr);

        // 3. Background
        this.backgroundRenderer.draw(ctx, logicalWidth, logicalHeight, scene, engine.mapConfig, globalTime);

        // 4. Camera Transform
        ctx.save();
        this.renderer.camera.sync(camera); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        // 5. MAIN PASS: Collect and Sort Renderables
        this.renderList.reset();

        const terrainHeightFunc = (q: number, r: number) => this.renderer.grid.getTerrainHeight(q, r, engine);

        // Collect Grid
        this.renderer.grid.submitRenderables(
            this.renderList,
            engine, hoveredHex, hoveredSkill, highlight, 
            engine.projectiles,
            this.transitionT, this.transitionPhase,
            globalTime
        );

        // Collect VFX
        this.renderer.vfxRenderer.submitRenderables(
            this.renderList,
            engine,
            this.renderer.vfx,
            terrainHeightFunc,
            engine.mapConfig,
            this.transitionT,
            this.transitionPhase,
            { width: logicalWidth, height: logicalHeight, camera } 
        );

        // Collect Units
        this.renderer.unit.submitRenderables(
            this.renderList,
            engine.agents, 
            terrainHeightFunc, 
            globalTime, 
            highlight, 
            engine.mapConfig
        );

        // Sort In-Place
        this.renderList.sort();

        // Execute Draws
        for (let i = 0; i < this.renderList.count; i++) {
            const op = this.renderList.ops[i];

            const snapX = Math.round(op.tx);
            const snapY = Math.round(op.ty);

            switch (op.type) {
                case RenderOpType.TERRAIN:
                    // Draw Solid Block
                    TerrainRenderer.drawBlock(
                        ctx, snapX, snapY, op.tsize, op.th, op.ttheme, op.ttype, globalTime
                    );

                    // Draw Details on Top Face (Y - Height)
                    const visualTopY = snapY - op.th;
                    TerrainRenderer.drawTerrainDetail(ctx, snapX, snapY, op.th, op.ttype, op.tdetail, op.tq, op.tr);

                    // Draw Overlays on Top Face
                    GridOverlays.drawOverlays(
                        ctx, snapX, visualTopY, op.tsize,
                        op.oStatus, op.oDanger,
                        op.oLightCol, op.oLightInt,
                        op.oRange, op.oRangeCol, op.oHover, op.oHasUnit,
                        op.tq, op.tr, op.time,
                        op.oHazard
                    );
                    break;

                case RenderOpType.OBSTACLE:
                    const sprite = SpriteManager.getObstacleSprite(op.ttype);
                    // Obstacles anchor bottom-center to ty
                    ctx.drawImage(sprite, snapX - OBSTACLE_HALF_WIDTH, snapY - 100); // 100 is approx height of obstacle asset
                    break;

                case RenderOpType.UNIT:
                    if (op.agent) {
                        this.renderer.unit.drawAssembly(ctx, op.agent, snapX, snapY, op.th, op.time, op.uSelected, op.uSilhouette);
                    }
                    break;

                case RenderOpType.DECAL:
                    const dImg = AssetManager.getBlastZone(op.dColor);
                    ctx.save();
                    ctx.translate(snapX, snapY);
                    ctx.scale(op.dScale, op.dScale);
                    ctx.globalAlpha = Math.min(1, op.dLife);
                    ctx.drawImage(dImg, -64, -32, 128, 64);
                    ctx.restore();
                    break;

                case RenderOpType.VFX:
                    if (op.particle) {
                        const p = op.particle;
                        ctx.save();
                        ctx.translate(snapX, snapY);
                        ParticleRenderer.drawSingleParticle(ctx, p, 0, 0, op.vProgress, op.vChaos);
                        ctx.restore();
                    }
                    break;

                case RenderOpType.PROJECTILE:
                    ProjectileDrawer.draw(ctx, op, globalTime);
                    break;
            }
        }

        // 6. Occlusion & Status Layers
        const occludedAgents = this.renderer.grid.getOccludedAgents(engine);
        if (occludedAgents.length > 0) {
            ctx.save();
            occludedAgents.forEach(agent => {
                this.renderer.unit.drawSilhouette(ctx, agent, terrainHeightFunc, globalTime, engine.mapConfig);
            });
            ctx.restore();
        }

        this.renderer.statusOrchestrator.draw(ctx, engine.agents, globalTime);
        this.renderer.vfxRenderer.drawTopLayerParticles(ctx, this.renderer.vfx, scene, engine.mapConfig, this.transitionT, this.transitionPhase);

        ctx.restore(); 

        // 9. Post Processing
        let transitionAberration = 0;
        if (this.transitionPhase !== 'IDLE') {
            transitionAberration = 4 * this.transitionT * (1 - this.transitionT) * 0.5;
        }

        this.postProcessor.apply(ctx, physicalWidth, physicalHeight, this.renderer.camera.getTrauma(), transitionAberration);

        // 10. HUD Layer
        ctx.save(); 
        this.renderer.camera.applyTransform(ctx, logicalWidth, logicalHeight);

        this.tacticalRenderer.drawOverlay(ctx, engine, highlight, this.renderer.grid, globalTime);
        this.hudRenderer.draw(ctx, this.renderer.hud, engine.agents, terrainHeightFunc, engine.mapConfig, highlight, globalTime);

        ctx.restore(); 

        if (engine.directorTargetId) {
            this.tacticalRenderer.drawHUD(ctx, engine, logicalWidth, logicalHeight, camera, globalTime);
        } 

        this.tacticalRenderer.drawDebug(ctx, fps);

        let blurAmount = 0;
        if (engine.isFinishing) {
            blurAmount = 1.0 - (engine.victoryTimer / VICTORY_PHASE_DURATION);
        } else if (engine.winningTeam !== null) {
            blurAmount = 1.0;
        }

        if (this.transitionPhase === 'OUT') blurAmount = 1.0; 
        else if (this.transitionPhase === 'IN') blurAmount = 1.0 - this.transitionT;

        if (blurAmount > 0) {
            this.postProcessor.applyFinishBlur(ctx, physicalWidth, physicalHeight, Math.max(0, Math.min(1, blurAmount)));
        }
    }
}

import { Agent } from "../../game";
import { MovementType } from "../../../types";
import { HexUtils, MapConfig } from "../../utils";
import { UNIT_BODY_OFFSET } from "../../../constants";
import { HexMath } from "../../math/HexMath";

export interface UnitVisualState {
    agent: Agent;

    // Position (Screen Space / Render Space)
    x: number;
    y: number; // Ground Y (Base of the tile unit is standing on)
    z: number; // Height (Terrain + Physics)

    // Derived
    terrainHeight: number;
    scale: number;
    isSilhouette: boolean;
    isSelected: boolean;

    // Flags
    isDead: boolean;
    isVisible: boolean;
}

export class UnitVisualProcessor {

    public static process(
        agent: Agent, 
        getTerrainHeight: (q: number, r: number) => number,
        mapConfig: MapConfig,
        highlightAgent: Agent | null
    ): UnitVisualState {

        const isDead = agent.hp <= 0;

        // 1. Interpolate Ground Position (Lerp if moving)
        // Use HexMath for consistency
        let logicalX = 0;
        let logicalY = 0;
        let terrainH = 0;

        if (agent.isMoving && agent.path.length > 0) {
            const startPx = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY);
            const nextHex = agent.path[0];
            const endPx = HexMath.hexToPixel(nextHex.q, nextHex.r, mapConfig.offsetX, mapConfig.offsetY);

            // Re-calculate lerp to ensure it matches motion engine visual exactly
            logicalX = startPx.x + (endPx.x - startPx.x) * agent.moveProgress;
            logicalY = startPx.y + (endPx.y - startPx.y) * agent.moveProgress;

            const startH = getTerrainHeight(agent.q, agent.r);
            const endH = getTerrainHeight(nextHex.q, nextHex.r);
            terrainH = startH + (endH - startH) * agent.moveProgress;
        } else {
            const pos = HexMath.hexToPixel(agent.q, agent.r, mapConfig.offsetX, mapConfig.offsetY);
            logicalX = pos.x;
            logicalY = pos.y;
            terrainH = getTerrainHeight(agent.q, agent.r);
        }

        // Apply visual physics offsets
        const visualX = logicalX + agent.physics.x;
        const visualY = logicalY + agent.physics.y; // This is the GROUND Y used for sorting
        const visualZ = terrainH + agent.physics.z; // Total Height

        const isSelected = (agent === highlightAgent);

        return {
            agent,
            x: visualX,
            y: visualY,
            z: visualZ,
            terrainHeight: terrainH,
            scale: 1.0, 
            isSilhouette: false,
            isSelected,
            isDead,
            isVisible: !agent.fullyDead
        };
    }
}
